final_template:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSQSServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "notification_queue" {
  description             = "Customer-managed KMS key for the notificationQueue SQS queue"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "notification_queue" {
  name          = "alias/notificationQueue"
  target_key_id = aws_kms_key.notification_queue.key_id
}

resource "aws_sqs_queue" "notification_queue" {
  name                              = "notificationQueue"
  delay_seconds                     = 0
  max_message_size                  = 2048
  visibility_timeout_seconds        = 30
  message_retention_seconds         = 345600
  kms_master_key_id                 = aws_kms_key.notification_queue.arn
  kms_data_key_reuse_period_seconds = 300
}

data "aws_iam_policy_document" "notification_queue_policy" {
  statement {
    sid    = "AllowCurrentAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
    ]

    resources = [aws_sqs_queue.notification_queue.arn]
  }
}

resource "aws_sqs_queue_policy" "notification_queue" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.notification_queue_policy.json
}

output "queue_url" {
  description = "URL of the notificationQueue SQS queue"
  value       = aws_sqs_queue.notification_queue.id
}

output "queue_arn" {
  description = "ARN of the notificationQueue SQS queue"
  value       = aws_sqs_queue.notification_queue.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the queue"
  value       = aws_kms_key.notification_queue.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

provider "aws" {}

variable "framework_name" {
  description = "Name and description for the AWS Backup framework."
  type        = string
  default     = "benchmark"
}

variable "tag_key" {
  description = "Tag key applied to the AWS Backup framework."
  type        = string
  default     = "BenchmarkTag"
}

resource "null_resource" "this" {}

resource "aws_backup_framework" "this" {
  name        = var.framework_name
  description = var.framework_name

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = ["EBS"]
    }
  }

  tags = {
    (var.tag_key) = null_resource.this.id
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the KMS key into"
  type        = string
  default     = "us-east-1"
}

# WARNING: This key policy grants kms:* to every AWS principal ("*").
# Intended strictly for isolated test environments. Do not use in production.
resource "aws_kms_key" "this" {
  description              = "Symmetric KMS key for general encryption/decryption (testing)"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days  = 10
  enable_key_rotation      = false
  is_enabled               = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "permissive-test-key-policy"
    Statement = [
      {
        Sid    = "AllowAllActionsFromAnyAWSPrincipal"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "this" {
  name          = "alias/bar"
  target_key_id = aws_kms_key.this.key_id
}

output "kms_key_id" {
  description = "ID of the KMS key"
  value       = aws_kms_key.this.key_id
}

output "kms_key_arn" {
  description = "ARN of the KMS key"
  value       = aws_kms_key.this.arn
}

output "kms_alias_name" {
  description = "Alias of the KMS key"
  value       = aws_kms_alias.this.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Allow inbound HTTP from anywhere to the ALB; egress restricted to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "alb"
  }
}

resource "aws_vpc_security_group_ingress_rule" "alb_http_in" {
  security_group_id = aws_security_group.alb.id
  description       = "HTTP from anywhere"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_egress_rule" "alb_vpc_out" {
  security_group_id = aws_security_group.alb.id
  description       = "All outbound traffic within the VPC"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Allow inbound HTTP only from the ALB security group; egress restricted to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "allow_alb"
  }
}

resource "aws_vpc_security_group_ingress_rule" "allow_alb_http_in" {
  security_group_id            = aws_security_group.allow_alb.id
  description                  = "HTTP from the ALB security group"
  ip_protocol                  = "tcp"
  from_port                    = 80
  to_port                      = 80
  referenced_security_group_id = aws_security_group.alb.id
}

resource "aws_vpc_security_group_egress_rule" "allow_alb_vpc_out" {
  security_group_id = aws_security_group.allow_alb.id
  description       = "All outbound traffic within the VPC"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "alb_security_group_id" {
  description = "ID of the ALB security group"
  value       = aws_security_group.alb.id
}

output "allow_alb_security_group_id" {
  description = "ID of the backend security group that allows traffic from the ALB"
  value       = aws_security_group.allow_alb.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM execution role for the Lambda function."
  type        = string
  default     = "lambda-vpc-efs-execution-role"
}

variable "tags" {
  description = "Tags to apply to the IAM role."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution" {
  name               = var.role_name
  description        = "Execution role for a Lambda function running in a VPC with access to Amazon EFS."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "vpc_access_execution" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

resource "aws_iam_role_policy_attachment" "efs_client_full_access" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

output "lambda_execution_role_arn" {
  description = "ARN of the Lambda execution role."
  value       = aws_iam_role.lambda_execution.arn
}

output "lambda_execution_role_name" {
  description = "Name of the Lambda execution role."
  value       = aws_iam_role.lambda_execution.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "instance_id" {
  description = "ID of the EC2 instance to associate with the Elastic IP. Leave empty to allocate the EIP without attaching it."
  type        = string
  default     = ""
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "main" {
  domain   = "vpc"
  instance = var.instance_id != "" ? var.instance_id : null

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "main-eip"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "eip_public_ip" {
  description = "Public IP address of the Elastic IP"
  value       = aws_eip.main.public_ip
}

output "eip_allocation_id" {
  description = "Allocation ID of the Elastic IP"
  value       = aws_eip.main.allocation_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the test networking environment into"
  type        = string
  default     = "us-east-1"
}

variable "environment_name" {
  description = "Name prefix applied to all resources"
  type        = string
  default     = "test-env"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name        = "${var.environment_name}-vpc"
    Environment = var.environment_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment_name}-igw"
    Environment = var.environment_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment_name}-public-subnet"
    Environment = var.environment_name
    Tier        = "public"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment_name}-private-subnet"
    Environment = var.environment_name
    Tier        = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment_name}-public-rt"
    Environment = var.environment_name
  }
}

resource "aws_route" "public_ipv4_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_default" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the VPC"
  value       = aws_vpc.main.ipv6_cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the test buckets."
  type        = string
  default     = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  count_bucket_suffixes = ["bucket3", "bucket4"]

  map_buckets = {
    bucket101 = {
      purpose = "test-map-1"
    }
    bucket102 = {
      purpose = "test-map-2"
    }
  }

  list_buckets = ["bucket103", "bucket104"]

  all_bucket_keys = concat(
    ["bucket2"],
    local.count_bucket_suffixes,
    keys(local.map_buckets),
    local.list_buckets,
  )

  all_bucket_ids = merge(
    { bucket2 = aws_s3_bucket.bucket2.id },
    { for idx, suffix in local.count_bucket_suffixes : suffix => aws_s3_bucket.counted[idx].id },
    { for k, b in aws_s3_bucket.from_map : k => b.id },
    { for k, b in aws_s3_bucket.from_list : k => b.id },
  )

  common_tags = {
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "s3" {
  description             = "Shared customer-managed KMS key for test S3 buckets"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.account_id}-test-s3-buckets"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket" "bucket2" {
  bucket        = "${local.account_id}-bucket2"
  force_destroy = true

  tags = merge(local.common_tags, { Name = "${local.account_id}-bucket2" })
}

resource "aws_s3_bucket" "counted" {
  count = length(local.count_bucket_suffixes)

  bucket        = "${local.account_id}-${local.count_bucket_suffixes[count.index]}"
  force_destroy = true

  tags = merge(local.common_tags, { Name = "${local.account_id}-${local.count_bucket_suffixes[count.index]}" })
}

resource "aws_s3_bucket" "from_map" {
  for_each = local.map_buckets

  bucket        = "${local.account_id}-${each.key}"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name    = "${local.account_id}-${each.key}"
    Purpose = each.value.purpose
  })
}

resource "aws_s3_bucket" "from_list" {
  for_each = toset(local.list_buckets)

  bucket        = "${local.account_id}-${each.value}"
  force_destroy = true

  tags = merge(local.common_tags, { Name = "${local.account_id}-${each.value}" })
}

resource "aws_s3_bucket_public_access_block" "all" {
  for_each = toset(local.all_bucket_keys)

  bucket = local.all_bucket_ids[each.key]

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "all" {
  for_each = toset(local.all_bucket_keys)

  bucket = local.all_bucket_ids[each.key]

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

output "account_id" {
  description = "AWS account ID used as the bucket name prefix."
  value       = local.account_id
}

output "kms_key_arn" {
  description = "ARN of the shared customer-managed KMS key."
  value       = aws_kms_key.s3.arn
}

output "bucket_names" {
  description = "Map of bucket suffix to full bucket name."
  value       = local.all_bucket_ids
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "eu-west-2"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowBudgetsToUseKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "budget" {
  description         = "KMS key for budget SNS topic"
  enable_key_rotation = true
  policy              = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_kms_alias" "budget" {
  name          = "alias/budget"
  target_key_id = aws_kms_key.budget.key_id
}

resource "aws_sns_topic" "budget" {
  name              = "budget"
  kms_master_key_id = aws_kms_key.budget.arn
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid       = "AllowBudgetsToPublish"
    effect    = "Allow"
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.budget.arn]

    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "budget" {
  arn    = aws_sns_topic.budget.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic_subscription" "sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = "+447828835419"
}

resource "aws_budgets_budget" "budget" {
  name              = "budget"
  budget_type       = "COST"
  limit_amount      = "25.0"
  limit_unit        = "USD"
  time_period_start = "2021-07-01_00:00"
