provider "aws" {}

variable "bucket_name" {
  description = "Name of the S3 bucket used for benchmarking."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value of the Name tag applied to resources."
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects."
  type        = bool
  default     = true
}

resource "aws_kms_key" "benchmark" {
  description             = "Customer-managed KMS key for ${var.bucket_name} default encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = var.name_tag
  }
}

resource "aws_kms_alias" "benchmark" {
  name          = "alias/${var.bucket_name}"
  target_key_id = aws_kms_key.benchmark.key_id
}

resource "aws_s3_bucket" "benchmark" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.benchmark.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# NOTE: This disables account-wide S3 public access protections for ALL buckets
# in the account, not just the benchmark bucket. Only the bucket-level block above
# protects this bucket; other buckets may become publicly exposable.
resource "aws_s3_account_public_access_block" "account" {
  block_public_acls       = false
  ignore_public_acls      = false
  block_public_policy     = false
  restrict_public_buckets = false
}

output "bucket_id" {
  value = aws_s3_bucket.benchmark.id
}

output "bucket_arn" {
  value = aws_s3_bucket.benchmark.arn
}

output "kms_key_arn" {
  value = aws_kms_key.benchmark.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "base_name" {
  description = "Base name used to construct the CloudTrail log bucket name."
  type        = string
  default     = "benchmark"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_name = "${var.base_name}-cloudtrail-${data.aws_region.current.name}"
}

data "aws_iam_policy_document" "cloudtrail_kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "Customer-managed KMS key for ${local.bucket_name} CloudTrail log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudtrail_kms.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

output "cloudtrail_bucket_name" {
  description = "Name of the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail.id
}

output "cloudtrail_bucket_arn" {
  description = "ARN of the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail.arn
}

output "cloudtrail_kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for bucket encryption."
  value       = aws_kms_key.cloudtrail.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "app_name" {
  description = "Human-readable application name"
  type        = string
  default     = "Trilium Notes"
}

variable "app" {
  description = "Short application identifier used in resource names"
  type        = string
  default     = "trilium"
}

variable "module" {
  description = "Module identifier used in resource names"
  type        = string
  default     = "log"
}

variable "stage" {
  description = "Deployment stage"
  type        = string
  default     = "production"
}

variable "log_retention" {
  description = "Number of days to retain log events in the log groups"
  type        = number
  default     = 120
}

locals {
  name_prefix = "cwlg-${join("-", [var.app, var.module, var.stage])}"

  app_log_group_name   = "${local.name_prefix}-app"
  proxy_log_group_name = "${local.name_prefix}-proxy"
}

provider "aws" {
  default_tags {
    tags = {
      App    = var.app_name
      Module = var.module
      Stage  = var.stage
    }
  }
}

resource "aws_cloudwatch_log_group" "app" {
  name              = local.app_log_group_name
  retention_in_days = var.log_retention

  tags = {
    Name = local.app_log_group_name
  }
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = local.proxy_log_group_name
  retention_in_days = var.log_retention

  tags = {
    Name = local.proxy_log_group_name
  }
}

output "app_log_group_name" {
  description = "Name of the application CloudWatch log group"
  value       = aws_cloudwatch_log_group.app.name
}

output "app_log_group_arn" {
  description = "ARN of the application CloudWatch log group"
  value       = aws_cloudwatch_log_group.app.arn
}

output "proxy_log_group_name" {
  description = "Name of the reverse proxy CloudWatch log group"
  value       = aws_cloudwatch_log_group.proxy.name
}

output "proxy_log_group_arn" {
  description = "ARN of the reverse proxy CloudWatch log group"
  value       = aws_cloudwatch_log_group.proxy.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_efs_file_system" "test" {
  creation_token = "cloudrail-test"
  encrypted      = true
}

resource "aws_ecs_task_definition" "test" {
  family = "cloudrail-test-encryption"

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
        }
      ]
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true
      portMappings = [
        {
          containerPort = 443
          hostPort      = 443
        }
      ]
    }
  ])

  volume {
    name = "service-storage"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.test.id
      root_directory          = "/opt/data"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
    }
  }
}

