terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "key_prefix" {
  description = "Prefix for the AWS key pair name"
  type        = string
  default     = "key"
}

resource "random_pet" "key_suffix" {
  length = 2
}

resource "tls_private_key" "ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "ssh" {
  key_name   = "${var.key_prefix}-${random_pet.key_suffix.id}"
  public_key = tls_private_key.ssh.public_key_openssh

  provisioner "local-exec" {
    command = <<-EOT
      echo '${tls_private_key.ssh.private_key_pem}' > ../${self.key_name}.pem
      chmod 600 ../${self.key_name}.pem
    EOT
  }
}

output "key_pair_name" {
  value = aws_key_pair.ssh.key_name
}

