  }

  statement {
    sid    = "AllowEventBridgeUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "incident_response" {
  description             = "Customer-managed KMS key for the incident-response SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms_key.json

  tags = {
    Name = "incident-response-sns-key"
  }
}

resource "aws_kms_alias" "incident_response" {
  name          = "alias/incident-response-sns"
  target_key_id = aws_kms_key.incident_response.key_id
}

resource "aws_sns_topic" "incident_response" {
  name              = "incident-response"
  kms_master_key_id = aws_kms_key.incident_response.arn

  tags = {
    Name    = "incident-response"
    Purpose = "Operational notifications"
  }
}

data "aws_iam_policy_document" "incident_response_topic" {
  policy_id = "__default_policy_ID"

  statement {
    sid    = "__default_statement_ID"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "SNS:Subscribe",
      "SNS:SetTopicAttributes",
      "SNS:RemovePermission",
      "SNS:Receive",
      "SNS:Publish",
      "SNS:ListSubscriptionsByTopic",
      "SNS:GetTopicAttributes",
      "SNS:DeleteTopic",
      "SNS:AddPermission",
    ]

    resources = [aws_sns_topic.incident_response.arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAWSEvents"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.incident_response.arn]
  }
}

resource "aws_sns_topic_policy" "incident_response" {
  arn    = aws_sns_topic.incident_response.arn
  policy = data.aws_iam_policy_document.incident_response_topic.json
}

output "sns_topic_arn" {
  description = "ARN of the incident-response SNS topic."
  value       = aws_sns_topic.incident_response.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the SNS topic."
  value       = aws_kms_key.incident_response.arn
}

