  name        = "allow_all"
  description = "Allow ALL traffic"

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the state backend resources."
  type        = string
  default     = "us-east-1"
}

variable "state_bucket_name" {
  description = "Globally unique name of the S3 bucket used to store Terraform state."
  type        = string
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "terraform-remote-state"
  }
}

resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed KMS key for Terraform state bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = var.tags
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state"
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = var.tags
}

output "state_bucket_name" {
  description = "Name of the S3 bucket holding Terraform state."
  value       = aws_s3_bucket.terraform_state.id
}

output "state_bucket_arn" {
  description = "ARN of the S3 bucket holding Terraform state."
  value       = aws_s3_bucket.terraform_state.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used to encrypt Terraform state."
  value       = aws_kms_key.terraform_state.arn
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.terraform_lock.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "regions" {
  description = "List of AWS regions in which the PowerScale node runtime may assign private IP addresses to network interfaces."
  type        = list(string)
  default     = ["*"]
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  name_prefix = "${local.account_id}-powerscale-node-runtime"

  network_interface_arns = [
    for region in var.regions :
    "arn:${data.aws_partition.current.partition}:ec2:${region}:${local.account_id}:network-interface/*"
  ]
}

data "aws_iam_policy_document" "node_runtime" {
  statement {
    sid       = "AssignPrivateIpAddresses"
    effect    = "Allow"
    actions   = ["ec2:AssignPrivateIpAddresses"]
    resources = local.network_interface_arns
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "node_runtime" {
  name        = "${local.name_prefix}-policy"
  description = "Permissions for PowerScale node runtime operations"
  policy      = data.aws_iam_policy_document.node_runtime.json
}

resource "aws_iam_role" "node_runtime" {
  name               = "${local.name_prefix}-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "node_runtime" {
  role       = aws_iam_role.node_runtime.name
  policy_arn = aws_iam_policy.node_runtime.arn
}

resource "aws_iam_instance_profile" "node_runtime" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.node_runtime.name
}

output "iam_policy_arn" {
  value = aws_iam_policy.node_runtime.arn
}

output "iam_role_arn" {
  value = aws_iam_role.node_runtime.arn
}

output "instance_profile_name" {
  value = aws_iam_instance_profile.node_runtime.name
}

output "instance_profile_arn" {
  value = aws_iam_instance_profile.node_runtime.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "192.168.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr)) && tonumber(split("/", var.vpc_cidr)[1]) <= 22
    error_message = "vpc_cidr must be a valid IPv4 CIDR block with a prefix length of /22 or larger to fit four /24 subnets."
  }
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "tiered-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  subnet_newbits = 24 - tonumber(split("/", var.vpc_cidr)[1])

  subnets = {
    web = {
      index  = 0
      az_idx = 0
    }
    app = {
      index  = 1
      az_idx = 1
    }
    db = {
      index  = 2
      az_idx = 2
    }
    mgmt = {
      index  = 3
      az_idx = 0
    }
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "tier" {
  for_each = local.subnets

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.subnet_newbits, each.value.index)
  availability_zone = local.azs[each.value.az_idx]

  tags = {
    Name = "${var.vpc_name}-${each.key}"
    Tier = each.key
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "Map of tier name to subnet ID"
  value       = { for k, s in aws_subnet.tier : k => s.id }
}

output "subnet_cidr_blocks" {
  description = "Map of tier name to subnet CIDR block"
  value       = { for k, s in aws_subnet.tier : k => s.cidr_block }
}

output "subnet_availability_zones" {
  description = "Map of tier name to subnet availability zone"
  value       = { for k, s in aws_subnet.tier : k => s.availability_zone }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "name" {
  description = "Name of the IAM role and instance profile."
  type        = string
}

variable "path" {
  description = "Path for the IAM role and instance profile."
  type        = string
  default     = "/"
}

variable "description" {
  description = "Description of the IAM role."
  type        = string
  default     = "IAM role for EC2 instances"
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role."
  type        = number
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of a permissions boundary policy to attach to the role."
  type        = string
  default     = null
}

variable "managed_policy_arns" {
  description = "Set of managed IAM policy ARNs to attach to the role. Use the token '{partition}' to have the current AWS partition substituted (e.g. arn:{partition}:iam::aws:policy/AmazonSSMManagedInstanceCore)."
  type        = set(string)
  default     = []
}

variable "inline_policies" {
  description = "Map of inline policy names to JSON policy documents to embed in the role."
  type        = map(string)
  default     = {}
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

locals {
  managed_policy_arns = toset([
    for arn in var.managed_policy_arns :
    replace(arn, "{partition}", data.aws_partition.current.partition)
  ])
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "this" {
  name                  = var.name
  path                  = var.path
  description           = var.description
  assume_role_policy    = data.aws_iam_policy_document.assume_role.json
  max_session_duration  = var.max_session_duration
  permissions_boundary  = var.permissions_boundary_arn
  force_detach_policies = true

  tags = var.tags
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.this.id
  policy = each.value
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = local.managed_policy_arns

  role       = aws_iam_role.this.name
  policy_arn = each.value
}

resource "aws_iam_instance_profile" "this" {
  name = var.name
  path = var.path
  role = aws_iam_role.this.name

  tags = var.tags
}

output "role_name" {
  description = "Name of the IAM role."
  value       = aws_iam_role.this.name
}

output "role_arn" {
  description = "ARN of the IAM role."
  value       = aws_iam_role.this.arn
}

output "role_unique_id" {
  description = "Unique ID of the IAM role."
  value       = aws_iam_role.this.unique_id
}

output "instance_profile_name" {
  description = "Name of the IAM instance profile."
  value       = aws_iam_instance_profile.this.name
}

output "instance_profile_arn" {
  description = "ARN of the IAM instance profile."
  value       = aws_iam_instance_profile.this.arn
}

output "ec2_service_principal" {
  description = "Partition-specific EC2 service principal used in the trust policy."
  value       = "ec2.${data.aws_partition.current.dns_suffix}"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the VPC into"
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the cluster used for naming and tagging resources"
  type        = string
  default     = "Fast-App"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "az_count" {
  description = "Number of availability zones to spread subnets across"
  type        = number
  default     = 3

  validation {
    condition     = var.az_count >= 2
    error_message = "az_count must be at least 2 to span multiple availability zones."
  }
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  public_subnet_cidrs  = [for i in range(var.az_count) : cidrsubnet(var.vpc_cidr, 8, i)]
  private_subnet_cidrs = [for i in range(var.az_count) : cidrsubnet(var.vpc_cidr, 8, i + 100)]

  common_tags = {
    Cluster   = var.cluster_name
    ManagedBy = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count             = var.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = var.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = var.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "availability_zones" {
  description = "Availability zones used by the subnets"
  value       = local.azs
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "grafana_workspace_name" {
  description = "Name of the AWS Managed Grafana workspace that will use this role."
  type        = string
  default     = "Grafana"
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs (monitoring accounts) allowed to assume the Grafana data source role."
  type        = list(string)

  validation {
    condition     = length(var.monitoring_account_ids) > 0 && alltrue([for id in var.monitoring_account_ids : can(regex("^[0-9]{12}$", id))])
    error_message = "monitoring_account_ids must contain at least one valid 12-digit AWS account ID."
  }
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Purpose   = "GrafanaDataSourceAccess"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  role_name   = "${var.grafana_workspace_name}-DataSourceRole"
  policy_name = "${var.grafana_workspace_name}-PrometheusCloudWatchQueryPolicy"

  monitoring_account_root_arns = [
    for id in var.monitoring_account_ids : "arn:${data.aws_partition.current.partition}:iam::${id}:root"
  ]
}

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    sid     = "AllowMonitoringAccountsToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = local.monitoring_account_root_arns
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = var.monitoring_account_ids
    }
  }

  statement {
    sid     = "AllowGrafanaServiceFromMonitoringAccounts"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = var.monitoring_account_ids
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values = [
        for id in var.monitoring_account_ids : "arn:${data.aws_partition.current.partition}:grafana:*:${id}:/workspaces/*"
      ]
    }
  }
}

resource "aws_iam_role" "grafana" {
  name               = local.role_name
  description        = "Role assumed by the ${var.grafana_workspace_name} AWS Managed Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch metrics."
  assume_role_policy = data.aws_iam_policy_document.grafana_assume_role.json
  max_session_duration = 3600

  tags = merge(var.tags, {
    Name             = local.role_name
    GrafanaWorkspace = var.grafana_workspace_name
  })
}

data "aws_iam_policy_document" "grafana_query" {
  statement {
    sid    = "AllowPrometheusQuery"
    effect = "Allow"
    actions = [
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace",
      "aps:QueryMetrics",
      "aps:GetLabels",
      "aps:GetSeries",
      "aps:GetMetricMetadata"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchMetricsRead"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarmsForMetric",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:ListMetrics",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:GetInsightRuleReport"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchSupportingReads"
    effect = "Allow"
    actions = [
      "ec2:DescribeTags",
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
      "tag:GetResources"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_query" {
  name        = local.policy_name
  description = "Allows the ${var.grafana_workspace_name} Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch metrics."
  policy      = data.aws_iam_policy_document.grafana_query.json

  tags = merge(var.tags, {
    Name             = local.policy_name
    GrafanaWorkspace = var.grafana_workspace_name
  })
}

resource "aws_iam_role_policy_attachment" "grafana_query" {
  role       = aws_iam_role.grafana.name
  policy_arn = aws_iam_policy.grafana_query.arn
}

output "grafana_role_arn" {
  description = "ARN of the IAM role to configure as the data source role in the Grafana workspace."
  value       = aws_iam_role.grafana.arn
}

output "grafana_role_name" {
  description = "Name of the IAM role for the Grafana workspace."
  value       = aws_iam_role.grafana.name
}

output "grafana_query_policy_arn" {
  description = "ARN of the custom policy granting Prometheus and CloudWatch query access."
  value       = aws_iam_policy.grafana_query.arn
}

output "account_id" {
  description = "AWS account ID in which the role was created."
  value       = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to resource Name tags"
  type        = string
  default     = "test"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name_prefix}-private-a"
    Tier = "private"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name_prefix}-private-b"
    Tier = "private"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "subnet_a_id" {
  description = "ID of the first private subnet"
  value       = aws_subnet.private_a.id
}

output "subnet_b_id" {
  description = "ID of the second private subnet"
  value       = aws_subnet.private_b.id
}

output "subnet_a_cidr" {
  description = "CIDR block of the first private subnet"
  value       = aws_subnet.private_a.cidr_block
}

output "subnet_b_cidr" {
  description = "CIDR block of the second private subnet"
  value       = aws_subnet.private_b.cidr_block
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = [aws_subnet.private_a.id, aws_subnet.private_b.id]
}

output "private_subnet_cidrs" {
  description = "List of private subnet CIDR blocks"
  value       = [aws_subnet.private_a.cidr_block, aws_subnet.private_b.cidr_block]
}

output "public_subnet_ids" {
  description = "List of public subnet IDs (mirrors the private subnets for testing)"
  value       = [aws_subnet.private_a.id, aws_subnet.private_b.id]
}

output "public_subnet_cidrs" {
  description = "List of public subnet CIDR blocks (mirrors the private subnets for testing)"
  value       = [aws_subnet.private_a.cidr_block, aws_subnet.private_b.cidr_block]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "eu-west-2"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "development"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.101.0/24", "10.0.102.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = "trade-tariff-development-vpc"
  azs  = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Environment = var.environment
    Project     = "trade-tariff"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.name
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH and outbound traffic within the VPC CIDR"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.this.cidr_block]
  }

  egress {
    description = "All outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.this.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "allow-ssh"
  })
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.this.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = aws_nat_gateway.this.id
}

output "nat_public_ip" {
  description = "Public IP of the NAT gateway"
  value       = aws_eip.nat.public_ip
}

output "allow_ssh_security_group_id" {
  description = "ID of the allow-ssh security group"
  value       = aws_security_group.allow_ssh.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "repository_name" {
  description = "Name of the ECR repository."
  type        = string
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the repository. Must be MUTABLE or IMMUTABLE."
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either MUTABLE or IMMUTABLE."
  }
}

variable "scan_on_push" {
  description = "Whether images are scanned for vulnerabilities after being pushed."
  type        = bool
  default     = true
}

variable "force_delete" {
  description = "If true, deletes the repository even if it contains images."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of a customer-managed KMS key for repository encryption. If null, AES256 encryption is used."
  type        = string
  default     = null
}

variable "pull_principal_arns" {
  description = "List of AWS principal ARNs allowed to pull images. If empty, no repository policy is created."
  type        = list(string)
  default     = []
}

variable "lifecycle_policy" {
  description = "Optional lifecycle policy JSON document. If null, no lifecycle policy is created."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to the repository."
  type        = map(string)
  default     = {}
}

locals {
  encryption_type  = var.kms_key_arn != null ? "KMS" : "AES256"
  create_policy    = length(var.pull_principal_arns) > 0
  create_lifecycle = var.lifecycle_policy != null
}

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.force_delete

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = local.encryption_type
    kms_key         = var.kms_key_arn
  }

  tags = var.tags
}

data "aws_iam_policy_document" "pull" {
  count = local.create_policy ? 1 : 0

  statement {
    sid    = "AllowPull"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.pull_principal_arns
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  count = local.create_policy ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.pull[0].json
}

resource "aws_ecr_lifecycle_policy" "this" {
  count = local.create_lifecycle ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "repository_name" {
  description = "Name of the ECR repository."
  value       = aws_ecr_repository.this.name
}

output "repository_url" {
  description = "URL of the ECR repository."
  value       = aws_ecr_repository.this.repository_url
}

output "registry_id" {
  description = "Registry ID where the repository was created."
  value       = aws_ecr_repository.this.registry_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region in which to create the SQS queue."
  type        = string
  default     = "us-east-1"
}

variable "namespace" {
  description = "Namespace, typically an abbreviation of the organization name."
  type        = string
  default     = null
}

variable "environment" {
  description = "Environment, e.g. 'uw2', 'us-west-2', or 'prod'."
  type        = string
  default     = null
}

variable "stage" {
  description = "Stage, e.g. 'prod', 'staging', 'dev'."
  type        = string
  default     = null
}

variable "name" {
  description = "Base name of the SQS queue."
  type        = string
}

variable "attributes" {
  description = "Additional attributes appended to the generated ID."
  type        = list(string)
  default     = []
}

variable "delimiter" {
  description = "Delimiter used between ID elements."
  type        = string
  default     = "-"
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "enabled" {
  description = "Set to false to prevent the module from creating any resources."
  type        = bool
  default     = true
}

variable "fifo_queue" {
  description = "Whether to create a FIFO queue. If true, '.fifo' is appended to the queue name."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the 'messageGroup' or 'queue' level (FIFO only)."
  type        = string
  default     = null

  validation {
    condition     = var.deduplication_scope == null || contains(["messageGroup", "queue"], coalesce(var.deduplication_scope, "queue"))
    error_message = "deduplication_scope must be one of 'messageGroup' or 'queue'."
  }
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO throughput quota applies to the entire queue or per message group ('perQueue' or 'perMessageGroupId')."
  type        = string
  default     = null

  validation {
    condition     = var.fifo_throughput_limit == null || contains(["perQueue", "perMessageGroupId"], coalesce(var.fifo_throughput_limit, "perQueue"))
    error_message = "fifo_throughput_limit must be one of 'perQueue' or 'perMessageGroupId'."
  }
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue, in seconds (0-43200)."
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "Number of seconds SQS retains a message (60-1209600)."
  type        = number
  default     = 345600
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024-262144)."
  type        = number
  default     = 262144
}

variable "delay_seconds" {
  description = "Time in seconds that delivery of all messages in the queue is delayed (0-900)."
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  description = "Time for which a ReceiveMessage call waits for a message to arrive (long polling), 0-20."
  type        = number
  default     = 0
}

variable "sqs_managed_sse_enabled" {
  description = "Enable server-side encryption with SQS-owned keys. Ignored when kms_master_key_id is set."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ID of an AWS-managed or customer-managed KMS key for SQS encryption."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time, in seconds, SQS can reuse a data key (60-86400)."
  type        = number
  default     = 300
}

variable "create_queue_policy" {
  description = "Whether to attach an access policy granting the specified principal permission to send messages."
  type        = bool
  default     = false
}

variable "sender_principal_type" {
  description = "Type of the principal allowed to send messages (e.g. 'AWS' or 'Service')."
  type        = string
  default     = "AWS"
}

variable "sender_principal_identifiers" {
  description = "List of principal identifiers (ARNs, account IDs, or service principals) allowed to send messages."
  type        = list(string)
  default     = []
}

variable "sender_source_arns" {
  description = "Optional list of source ARNs to restrict sending via the aws:SourceArn condition."
  type        = list(string)
  default     = []
}

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled     = var.enabled
  namespace   = var.namespace
  environment = var.environment
  stage       = var.stage
  name        = var.name
  attributes  = var.attributes
  delimiter   = var.delimiter
  tags        = var.tags
}

locals {
  enabled       = module.label.enabled
  queue_name    = var.fifo_queue ? "${module.label.id}.fifo" : module.label.id
  create_policy = local.enabled && var.create_queue_policy && length(var.sender_principal_identifiers) > 0
}

resource "aws_sqs_queue" "this" {
  count = local.enabled ? 1 : 0

  name = local.queue_name

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null

  tags = module.label.tags
}

data "aws_iam_policy_document" "queue_policy" {
  count = local.create_policy ? 1 : 0

  statement {
    sid       = "AllowSendMessage"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this[0].arn]

    principals {
      type        = var.sender_principal_type
      identifiers = var.sender_principal_identifiers
    }

    dynamic "condition" {
      for_each = length(var.sender_source_arns) > 0 ? [1] : []

      content {
        test     = "ArnEquals"
        variable = "aws:SourceArn"
        values   = var.sender_source_arns
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.create_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

output "queue_id" {
  description = "URL of the SQS queue."
  value       = one(aws_sqs_queue.this[*].id)
}

output "queue_url" {
  description = "URL of the SQS queue."
  value       = one(aws_sqs_queue.this[*].url)
}

output "queue_arn" {
  description = "ARN of the SQS queue."
  value       = one(aws_sqs_queue.this[*].arn)
}

output "queue_name" {
  description = "Name of the SQS queue."
  value       = one(aws_sqs_queue.this[*].name)
}

output "queue_policy" {
  description = "JSON access policy attached to the queue, if any."
  value       = one(data.aws_iam_policy_document.queue_policy[*].json)
}

output "tags" {
  description = "Tags applied to the queue."
  value       = module.label.tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0"
    }
  }
}

variable "create" {
  description = "Whether to create the Aurora DSQL cluster"
  type        = bool
  default     = true
}

variable "region" {
  description = "AWS region in which to create the cluster. Defaults to the provider region when null"
  type        = string
  default     = null
}

variable "deletion_protection_enabled" {
  description = "Whether deletion protection is enabled on the cluster"
  type        = bool
  default     = true
}

variable "kms_encryption_key" {
  description = "ARN of a customer managed KMS key used to encrypt the cluster, or AWS_OWNED_KMS_KEY to use an AWS owned key"
  type        = string
  default     = "AWS_OWNED_KMS_KEY"

  validation {
    condition     = var.kms_encryption_key == "AWS_OWNED_KMS_KEY" || can(regex("^arn:aws[a-zA-Z-]*:kms:", var.kms_encryption_key))
    error_message = "kms_encryption_key must be AWS_OWNED_KMS_KEY or a valid KMS key ARN."
  }
}

variable "force_destroy" {
  description = "Whether to disable deletion protection and destroy the cluster on terraform destroy"
  type        = bool
  default     = false
}

variable "witness_region" {
  description = "Witness region for multi-region cluster properties. When null, the cluster is single-region"
  type        = string
  default     = null
}

variable "create_cluster_peering" {
  description = "Whether to create a peering relationship between this cluster and the clusters in peered_clusters"
  type        = bool
  default     = false
}

variable "peered_clusters" {
  description = "List of DSQL cluster ARNs to peer with this cluster"
  type        = list(string)
  default     = []
}

variable "peering_witness_region" {
  description = "Witness region for the cluster peering. Defaults to witness_region when null"
  type        = string
  default     = null
}

variable "peering_timeouts_create" {
  description = "Timeout for the cluster peering create operation"
  type        = string
  default     = "30m"
}

variable "tags" {
  description = "Tags to apply to the cluster"
  type        = map(string)
  default     = {}
}

locals {
  create_peering = var.create && var.create_cluster_peering && length(var.peered_clusters) > 0
}

resource "aws_dsql_cluster" "this" {
  count = var.create ? 1 : 0

  region                      = var.region
  deletion_protection_enabled = var.deletion_protection_enabled
  kms_encryption_key          = var.kms_encryption_key
  force_destroy               = var.force_destroy

  dynamic "multi_region_properties" {
    for_each = var.witness_region != null ? [var.witness_region] : []

    content {
      witness_region = multi_region_properties.value
    }
  }

  tags = var.tags
}

resource "aws_dsql_cluster_peering" "this" {
  count = local.create_peering ? 1 : 0

  region         = var.region
  identifier     = aws_dsql_cluster.this[0].identifier
  clusters       = var.peered_clusters
  witness_region = coalesce(var.peering_witness_region, var.witness_region)

  timeouts {
    create = var.peering_timeouts_create
  }
}

output "arn" {
  description = "ARN of the cluster"
  value       = try(aws_dsql_cluster.this[0].arn, null)
}

output "identifier" {
  description = "Identifier of the cluster"
  value       = try(aws_dsql_cluster.this[0].identifier, null)
}

output "encryption_details" {
  description = "Encryption configuration details of the cluster"
  value       = try(aws_dsql_cluster.this[0].encryption_details, null)
}

output "vpc_endpoint_service_name" {
  description = "VPC endpoint service name of the cluster"
  value       = try(aws_dsql_cluster.this[0].vpc_endpoint_service_name, null)
}

output "multi_region_properties" {
  description = "Multi-region properties of the cluster"
  value       = try(aws_dsql_cluster.this[0].multi_region_properties, null)
}

output "peering_id" {
  description = "Identifier of the cluster peering"
  value       = try(aws_dsql_cluster_peering.this[0].identifier, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket."
  type        = string
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled on the bucket. Can only be set at bucket creation."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Whether to delete all objects so the bucket can be destroyed without error. Defaults to false to prevent accidental deletion of non-empty buckets."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period, in days, before the KMS key is deleted."
  type        = number
  default     = 30
}

variable "bucket_policies" {
  description = "Map of custom bucket policy objects. All provided policies are merged into the single bucket policy. Statement SIDs must be unique across all policies. If a statement's resources list is empty, it defaults to the bucket and all of its objects."
  type = map(object({
    policy_id = optional(string)
    version   = optional(string, "2012-10-17")
    statements = list(object({
      sid       = string
      actions   = list(string)
      effect    = optional(string, "Allow")
      resources = optional(list(string), [])
      principals = optional(list(object({
        type        = string
        identifiers = list(string)
      })), [])
    }))
  }))
  default = {}

  validation {
    condition = alltrue(flatten([
      for p in values(var.bucket_policies) : [
        for s in p.statements : contains(["Allow", "Deny"], s.effect)
      ]
    ]))
    error_message = "Each statement effect must be either \"Allow\" or \"Deny\"."
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  create_bucket_policy = length(var.bucket_policies) > 0
  default_resources = [
    aws_s3_bucket.this.arn,
    "${aws_s3_bucket.this.arn}/*",
  ]
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "this" {
  description             = "Customer-managed KMS key for default encryption of S3 bucket ${var.bucket_name}"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/s3-${var.bucket_name}"
  target_key_id = aws_kms_key.this.key_id
}

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "custom" {
  for_each = var.bucket_policies

  policy_id = each.value.policy_id
  version   = each.value.version

  dynamic "statement" {
    for_each = each.value.statements

    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = length(statement.value.resources) > 0 ? statement.value.resources : local.default_resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
    }
  }
}

data "aws_iam_policy_document" "combined" {
  count = local.create_bucket_policy ? 1 : 0

  source_policy_documents = [
    for k in sort(keys(data.aws_iam_policy_document.custom)) : data.aws_iam_policy_document.custom[k].json
  ]
}

resource "aws_s3_bucket_policy" "this" {
  count  = local.create_bucket_policy ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined[0].json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this,
  ]
}

output "bucket_id" {
  description = "Name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "Regional domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for default bucket encryption."
  value       = aws_kms_key.this.arn
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key."
  value       = aws_kms_alias.this.name
}

output "bucket_policy_json" {
  description = "Combined bucket policy JSON, or null if no policies were provided."
  value       = local.create_bucket_policy ? data.aws_iam_policy_document.combined[0].json : null
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.30"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Controls whether any resources are created (main toggle)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

# Topic

variable "name" {
  description = "The name of the SNS topic. A `.fifo` suffix is appended automatically for FIFO topics"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether `name` is used as a prefix rather than the exact topic name"
  type        = bool
  default     = false
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Boolean indicating whether or not to enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK"
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "The SNS delivery policy (JSON)"
  type        = string
  default     = null
}

variable "signature_version" {
  description = "If SignatureVersion should be 1 (SHA1) or 2 (SHA256)"
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of the topic. Valid values: `PassThrough`, `Active`"
  type        = string
  default     = null
}

variable "archive_policy" {
  description = "The message archive policy for FIFO topics (JSON)"
  type        = string
  default     = null
}

# Delivery status feedback

variable "create_feedback_role" {
  description = "Determines whether an IAM role is created for SNS delivery status logging to CloudWatch Logs. When created, it is used as the default success/failure feedback role"
  type        = bool
  default     = false
}

variable "feedback_role_name" {
  description = "Name of the delivery feedback IAM role. Defaults to `<topic name>-sns-feedback`"
  type        = string
  default     = null
}

variable "feedback_role_permissions_boundary" {
  description = "ARN of the policy used to set the permissions boundary for the feedback IAM role"
  type        = string
  default     = null
}

variable "application_feedback" {
  description = "Map of application platform delivery feedback settings: `success_role_arn`, `failure_role_arn`, `success_sample_rate`"
  type = object({
    success_role_arn    = optional(string)
    failure_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "firehose_feedback" {
  description = "Map of Kinesis Data Firehose delivery feedback settings: `success_role_arn`, `failure_role_arn`, `success_sample_rate`"
  type = object({
    success_role_arn    = optional(string)
    failure_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "http_feedback" {
  description = "Map of HTTP(S) delivery feedback settings: `success_role_arn`, `failure_role_arn`, `success_sample_rate`"
  type = object({
    success_role_arn    = optional(string)
    failure_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "lambda_feedback" {
  description = "Map of Lambda delivery feedback settings: `success_role_arn`, `failure_role_arn`, `success_sample_rate`"
  type = object({
    success_role_arn    = optional(string)
    failure_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "sqs_feedback" {
  description = "Map of SQS delivery feedback settings: `success_role_arn`, `failure_role_arn`, `success_sample_rate`"
  type = object({
    success_role_arn    = optional(string)
    failure_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

# Topic policy

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is created"
  type        = bool
  default     = true
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to include the default owner-access statement in the topic policy"
  type        = bool
  default     = true
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. In merging, statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statements for a custom topic policy"
  type = map(object({
    sid           = optional(string)
    effect        = optional(string, "Allow")
    actions       = optional(list(string))
    not_actions   = optional(list(string))
    resources     = optional(list(string))
    not_resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = {}
}

variable "topic_policy" {
  description = "An externally created, fully-formed JSON topic policy. When set, it is used instead of the generated policy document"
  type        = string
  default     = null
}

# Subscriptions

variable "create_subscription" {
  description = "Determines whether topic subscriptions are created"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscription definitions to create"
  type = map(object({
    protocol                        = string
    endpoint                        = string
    confirmation_timeout_in_minutes = optional(number)
    delivery_policy                 = optional(string)
    endpoint_auto_confirms          = optional(bool)
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    raw_message_delivery            = optional(bool)
    redrive_policy                  = optional(string)
    replay_policy                   = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

################################################################################
# Locals & Data
################################################################################

data "aws_caller_identity" "current" {
  count = var.create ? 1 : 0
}

data "aws_partition" "current" {
  count = var.create ? 1 : 0
}

locals {
  base_name   = var.name != null ? trimsuffix(var.name, ".fifo") : null
  topic_name  = var.use_name_prefix || local.base_name == null ? null : (var.fifo_topic ? "${local.base_name}.fifo" : local.base_name)
  name_prefix = var.use_name_prefix && local.base_name != null ? "${local.base_name}-" : null

  create_feedback_role = var.create && var.create_feedback_role
  feedback_role_arn    = try(aws_iam_role.feedback[0].arn, null)
  feedback_role_name   = coalesce(var.feedback_role_name, "${coalesce(local.base_name, "sns")}-sns-feedback")

  account_id = try(data.aws_caller_identity.current[0].account_id, "")
  partition  = try(data.aws_partition.current[0].partition, "aws")
}

################################################################################
# Delivery Feedback IAM Role
################################################################################

data "aws_iam_policy_document" "feedback_assume" {
  count = local.create_feedback_role ? 1 : 0

  statement {
    sid     = "SNSAssumeRole"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "feedback" {
  count = local.create_feedback_role ? 1 : 0

  statement {
    sid = "CloudWatchLogsDeliveryStatus"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutMetricFilter",
      "logs:PutRetentionPolicy",
    ]
    resources = ["arn:${local.partition}:logs:*:${local.account_id}:log-group:sns/*"]
  }
}

resource "aws_iam_role" "feedback" {
  count = local.create_feedback_role ? 1 : 0

  name                 = local.feedback_role_name
  assume_role_policy   = data.aws_iam_policy_document.feedback_assume[0].json
  permissions_boundary = var.feedback_role_permissions_boundary

  tags = var.tags
}

resource "aws_iam_role_policy" "feedback" {
  count = local.create_feedback_role ? 1 : 0

  name   = "${local.feedback_role_name}-logs"
  role   = aws_iam_role.feedback[0].id
  policy = data.aws_iam_policy_document.feedback[0].json
}

################################################################################
# Topic
################################################################################

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = local.topic_name
  name_prefix = local.name_prefix

  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  kms_master_key_id           = var.kms_master_key_id
  delivery_policy             = var.delivery_policy
  signature_version           = var.signature_version
  tracing_config              = var.tracing_config
  archive_policy              = var.fifo_topic ? var.archive_policy : null

  application_success_feedback_role_arn    = try(coalesce(var.application_feedback.success_role_arn, local.feedback_role_arn), null)
  application_failure_feedback_role_arn    = try(coalesce(var.application_feedback.failure_role_arn, local.feedback_role_arn), null)
  application_success_feedback_sample_rate = var.application_feedback.success_sample_rate

  firehose_success_feedback_role_arn    = try(coalesce(var.firehose_feedback.success_role_arn, local.feedback_role_arn), null)
  firehose_failure_feedback_role_arn    = try(coalesce(var.firehose_feedback.failure_role_arn, local.feedback_role_arn), null)
  firehose_success_feedback_sample_rate = var.firehose_feedback.success_sample_rate

  http_success_feedback_role_arn    = try(coalesce(var.http_feedback.success_role_arn, local.feedback_role_arn), null)
  http_failure_feedback_role_arn    = try(coalesce(var.http_feedback.failure_role_arn, local.feedback_role_arn), null)
  http_success_feedback_sample_rate = var.http_feedback.success_sample_rate

  lambda_success_feedback_role_arn    = try(coalesce(var.lambda_feedback.success_role_arn, local.feedback_role_arn), null)
  lambda_failure_feedback_role_arn    = try(coalesce(var.lambda_feedback.failure_role_arn, local.feedback_role_arn), null)
  lambda_success_feedback_sample_rate = var.lambda_feedback.success_sample_rate

  sqs_success_feedback_role_arn    = try(coalesce(var.sqs_feedback.success_role_arn, local.feedback_role_arn), null)
  sqs_failure_feedback_role_arn    = try(coalesce(var.sqs_feedback.failure_role_arn, local.feedback_role_arn), null)
  sqs_success_feedback_sample_rate = var.sqs_feedback.success_sample_rate

  tags = var.tags

  depends_on = [aws_iam_role_policy.feedback]
}

################################################################################
# Topic Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy && var.topic_policy == null ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid = "__default_statement_ID"
      actions = [
        "sns:Subscribe",
        "sns:SetTopicAttributes",
        "sns:RemovePermission",
        "sns:Publish",
        "sns:ListSubscriptionsByTopic",
        "sns:GetTopicAttributes",
        "sns:DeleteTopic",
        "sns:AddPermission",
      ]
      effect    = "Allow"
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"
        values   = [local.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid           = try(coalesce(statement.value.sid, statement.key), statement.key)
      effect        = statement.value.effect
      actions       = statement.value.actions
      not_actions   = statement.value.not_actions
      resources     = coalesce(statement.value.resources, statement.value.not_resources == null ? [aws_sns_topic.this[0].arn] : null, [])
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.topic_policy != null ? var.topic_policy : data.aws_iam_policy_document.this[0].json
}

################################################################################
# Subscriptions
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create && var.create_subscription ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn
  protocol  = each.value.protocol
  endpoint  = each.value.endpoint

  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  delivery_policy                 = each.value.delivery_policy
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  raw_message_delivery            = each.value.raw_message_delivery
  redrive_policy                  = each.value.redrive_policy
  replay_policy                   = each.value.replay_policy
  subscription_role_arn           = each.value.subscription_role_arn
}

################################################################################
# Outputs
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_beginning_archive_time" {
  description = "The oldest timestamp at which a FIFO topic subscriber can start a replay"
  value       = try(aws_sns_topic.this[0].beginning_archive_time, null)
}

output "topic_policy" {
  description = "The JSON policy applied to the SNS topic"
  value       = try(aws_sns_topic_policy.this[0].policy, null)
}

output "feedback_role_arn" {
  description = "The ARN of the delivery status feedback IAM role"
  value       = local.feedback_role_arn
}

output "subscriptions" {
  description = "Map of subscriptions created and their attributes"
  value       = aws_sns_topic_subscription.this
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ansible-vpc"
  }
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id     = aws_vpc.ansible_vpc.id
  cidr_block = "10.0.0.0/24"

  tags = {
    Name = "ansible-vpc-private-subnet-1"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-public-subnet-1"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-igw"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "ansible-vpc-public-rt"
  }
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-private-rt"
  }
}

resource "aws_route_table_association" "public_subnet_1" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table_association" "private_subnet_1" {
  subnet_id      = aws_subnet.private_subnet_1.id
  route_table_id = aws_route_table.private_rt.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix used for tagging resources."
  type        = string
  default     = "central"
}

variable "create_transit_gateway" {
  description = "Whether to create a new Transit Gateway. If false, existing_transit_gateway_id must be provided."
  type        = bool
  default     = true
}

variable "existing_transit_gateway_id" {
  description = "ID of an existing Transit Gateway to attach VPCs to when create_transit_gateway is false."
  type        = string
  default     = null

  validation {
    condition     = var.existing_transit_gateway_id == null || can(regex("^tgw-[0-9a-f]+$", var.existing_transit_gateway_id))
    error_message = "existing_transit_gateway_id must be a valid Transit Gateway ID (tgw-xxxxxxxx)."
  }
}

variable "amazon_side_asn" {
  description = "Private ASN for the Amazon side of a BGP session."
  type        = number
  default     = 64512
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachment requests are automatically accepted."
  type        = string
  default     = "disable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be 'enable' or 'disable'."
  }
}

variable "default_route_table_association" {
  description = "Whether attachments are automatically associated with the default route table."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.default_route_table_association)
    error_message = "default_route_table_association must be 'enable' or 'disable'."
  }
}

variable "default_route_table_propagation" {
  description = "Whether attachments automatically propagate routes to the default route table."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.default_route_table_propagation)
    error_message = "default_route_table_propagation must be 'enable' or 'disable'."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled on the Transit Gateway."
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled."
  type        = string
  default     = "enable"
}

variable "vpc_attachments" {
  description = <<-EOT
    Map of VPC attachments keyed by a logical name. Each entry provides the VPC ID
    and the list of subnet IDs (one per AZ) used for the attachment. Optionally,
    supply route table IDs and destination CIDRs to add routes pointing to the TGW.
  EOT
  type = map(object({
    vpc_id                 = string
    subnet_ids             = list(string)
    dns_support            = optional(string, "enable")
    ipv6_support           = optional(string, "disable")
    appliance_mode_support = optional(string, "disable")
    route_table_ids        = optional(list(string), [])
    destination_cidrs      = optional(list(string), [])
    tags                   = optional(map(string), {})
  }))
  default = {}

  validation {
    condition     = alltrue([for k, v in var.vpc_attachments : length(v.subnet_ids) > 0])
    error_message = "Each VPC attachment must include at least one subnet ID."
  }
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

locals {
  transit_gateway_id = var.create_transit_gateway ? aws_ec2_transit_gateway.this[0].id : var.existing_transit_gateway_id

  vpc_routes = merge([
    for att_key, att in var.vpc_attachments : {
      for pair in setproduct(att.route_table_ids, att.destination_cidrs) :
      "${att_key}|${pair[0]}|${pair[1]}" => {
        attachment_key   = att_key
        route_table_id   = pair[0]
        destination_cidr = pair[1]
      }
    }
  ]...)
}

resource "aws_ec2_transit_gateway" "this" {
  count = var.create_transit_gateway ? 1 : 0

  description                     = "${var.name} Transit Gateway"
  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = var.default_route_table_association
  default_route_table_propagation = var.default_route_table_propagation
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support

  tags = merge(var.tags, {
    Name = "${var.name}-tgw"
  })

  lifecycle {
    precondition {
      condition     = var.create_transit_gateway || var.existing_transit_gateway_id != null
      error_message = "existing_transit_gateway_id must be set when create_transit_gateway is false."
    }
  }
}

data "aws_ec2_transit_gateway" "existing" {
  count = var.create_transit_gateway ? 0 : 1
  id    = var.existing_transit_gateway_id
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = var.vpc_attachments

  transit_gateway_id     = local.transit_gateway_id
  vpc_id                 = each.value.vpc_id
  subnet_ids             = each.value.subnet_ids
  dns_support            = each.value.dns_support
  ipv6_support           = each.value.ipv6_support
  appliance_mode_support = each.value.appliance_mode_support

  tags = merge(var.tags, each.value.tags, {
    Name = "${var.name}-tgw-attach-${each.key}"
  })
}

resource "aws_route" "to_tgw" {
  for_each = local.vpc_routes

  route_table_id         = each.value.route_table_id
  destination_cidr_block = each.value.destination_cidr
  transit_gateway_id     = local.transit_gateway_id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

output "transit_gateway_id" {
  description = "ID of the Transit Gateway in use."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "ARN of the Transit Gateway in use."
  value       = var.create_transit_gateway ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.existing[0].arn
}

output "transit_gateway_default_route_table_id" {
  description = "ID of the Transit Gateway default association route table."
  value       = var.create_transit_gateway ? aws_ec2_transit_gateway.this[0].association_default_route_table_id : data.aws_ec2_transit_gateway.existing[0].association_default_route_table_id
}

output "vpc_attachment_ids" {
  description = "Map of VPC attachment keys to Transit Gateway VPC attachment IDs."
  value       = { for k, v in aws_ec2_transit_gateway_vpc_attachment.this : k => v.id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to deploy the resources."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated ECS Fargate VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the ECS Fargate subnet."
  type        = string
  default     = "10.0.0.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "dragondrop_fargate" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dragondrop-compute-ecs-fargate-vpc"
  }
}

resource "aws_subnet" "dragondrop_fargate" {
  vpc_id                  = aws_vpc.dragondrop_fargate.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "dragondrop-compute-ecs-fargate-subnet"
  }
}

resource "aws_internet_gateway" "dragondrop_fargate" {
  vpc_id = aws_vpc.dragondrop_fargate.id

  tags = {
    Name = "dragondrop-compute-ecs-fargate-igw"
  }
}

resource "aws_route_table" "dragondrop_fargate" {
  vpc_id = aws_vpc.dragondrop_fargate.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.dragondrop_fargate.id
  }

  tags = {
    Name = "dragondrop-compute-ecs-fargate-rt"
  }
}

resource "aws_route_table_association" "dragondrop_fargate" {
  subnet_id      = aws_subnet.dragondrop_fargate.id
  route_table_id = aws_route_table.dragondrop_fargate.id
}

resource "aws_security_group" "dragondrop_fargate" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for dragondrop ECS Fargate tasks; egress restricted to the VPC CIDR."
  vpc_id      = aws_vpc.dragondrop_fargate.id

  tags = {
    Name = "dragondrop-compute-ecs-fargate-sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "dragondrop_fargate_vpc_only" {
  security_group_id = aws_security_group.dragondrop_fargate.id
  description       = "Allow all outbound traffic within the VPC CIDR only."
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.dragondrop_fargate.cidr_block
}

output "vpc_id" {
  description = "ID of the dedicated ECS Fargate VPC."
