}

output "subnet_id" {
  description = "ID of the ECS Fargate subnet."
  value       = aws_subnet.dragondrop_fargate.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.dragondrop_fargate.id
}

output "route_table_id" {
  description = "ID of the route table routing default traffic via the internet gateway."
  value       = aws_route_table.dragondrop_fargate.id
}

output "security_group_id" {
  description = "ID of the dragondrop ECS Fargate security group."
  value       = aws_security_group.dragondrop_fargate.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_dynamodb_table" "raw_metrics" {
  name             = "raw_metrics"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "uuid"
  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  attribute {
    name = "uuid"
    type = "S"
  }

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  server_side_encryption {
    enabled = true
  }
}

resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }
}

output "raw_metrics_table_name" {
  value = aws_dynamodb_table.raw_metrics.name
}

output "raw_metrics_stream_arn" {
  value = aws_dynamodb_table.raw_metrics.stream_arn
}

output "aggregate_metrics_table_name" {
  value = aws_dynamodb_table.aggregate_metrics.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "instance_type" {
  description = "EC2 instance size"
  type        = string
  default     = "t3.micro"
}

variable "server_name" {
  description = "Name of the web server"
  type        = string
  default     = "demo"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.server_name}-public-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.server_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "${var.server_name}-web-sg"
  description = "Allow inbound HTTP from anywhere; restrict egress to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.server_name}-web-sg"
  }
}

# NOTE: Because egress is restricted to the VPC CIDR, the instance cannot reach
# public package repositories. The user_data below attempts to install httpd and
# falls back to a minimal Python-based HTTP server on port 80 if installation fails.
resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    if timeout 120 yum install -y httpd; then
      systemctl enable httpd
      systemctl start httpd
      echo "<h1>Hello from ${var.server_name}</h1>" > /var/www/html/index.html
    else
      mkdir -p /opt/web
      echo "<h1>Hello from ${var.server_name}</h1>" > /opt/web/index.html
      cd /opt/web && nohup python -m SimpleHTTPServer 80 >/var/log/web.log 2>&1 &
    fi
  EOF

  tags = {
    Name = var.server_name
  }
}

resource "aws_eip" "web" {
  domain   = "vpc"
  instance = aws_instance.web.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.server_name}-eip"
  }
}

output "instance_id" {
  description = "ID of the EC2 instance"
  value       = aws_instance.web.id
}

output "ami_id" {
  description = "Amazon Linux 2 AMI used"
  value       = data.aws_ami.amazon_linux_2.id
}

output "public_ip" {
  description = "Elastic IP attached to the web server"
  value       = aws_eip.web.public_ip
}

output "web_url" {
  description = "URL of the web server"
  value       = "http://${aws_eip.web.public_ip}"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "sns_kms_key_policy" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer-managed KMS key for SNS topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms_key_policy.json

  tags = {
    Purpose = "sns-messaging-integration-testing"
  }
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-messaging-integration-testing"
  target_key_id = aws_kms_key.sns.key_id
}

resource "aws_sns_topic" "my_topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns.arn

  tags = {
    Purpose = "sns-messaging-integration-testing"
  }
}

resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns.arn

  tags = {
    Purpose = "sns-messaging-integration-testing"
  }
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns.arn

  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 20
        numRetries         = 3
        numMaxDelayRetries = 0
        numNoDelayRetries  = 0
        numMinDelayRetries = 0
        backoffFunction    = "linear"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 1
      }
    }
  })

  tags = {
    Purpose = "sns-messaging-integration-testing"
  }
}

# Shared topic policy: allows all AWS principals full SNS actions on the first topic.
# NOTE: Intentionally permissive for integration testing only; do not use in production.
data "aws_iam_policy_document" "shared_topic_policy" {
  statement {
    sid    = "AllowAllPrincipalsFullSNSAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions   = ["sns:*"]
    resources = [aws_sns_topic.my_topic_with_policy.arn]
  }
}

resource "aws_sns_topic_policy" "my_topic_with_policy" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.shared_topic_policy.json
}

resource "aws_sns_topic_policy" "my_topic_with_policy2" {
  arn    = aws_sns_topic.my_topic_with_policy2.arn
  policy = data.aws_iam_policy_document.shared_topic_policy.json
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for SNS encryption"
  value       = aws_kms_key.sns.arn
}

output "my_topic_with_policy_arn" {
  description = "ARN of my-topic-with-policy"
  value       = aws_sns_topic.my_topic_with_policy.arn
}

output "my_topic_with_policy2_arn" {
  description = "ARN of my-topic-with-policy2"
  value       = aws_sns_topic.my_topic_with_policy2.arn
}

output "user_updates_topic_arn" {
  description = "ARN of user-updates-topic"
  value       = aws_sns_topic.user_updates_topic.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used for naming resources"
  type        = string
  default     = "test"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az = data.aws_availability_zones.available.names[0]

  common_tags = {
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.1.0/24"
  availability_zone       = local.az
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.4.0/24"
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-private-subnet"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_eip" "standalone" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-eip"
  })
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "availability_zone" {
  description = "Availability zone used for both subnets"
  value       = local.az
}

output "elastic_ip_allocation_id" {
  description = "Allocation ID of the standalone Elastic IP"
  value       = aws_eip.standalone.id
}

output "elastic_ip_public_ip" {
  description = "Public IP address of the standalone Elastic IP"
  value       = aws_eip.standalone.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to resource names"
  type        = string
  default     = "app"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.101.0/24", "10.0.102.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Project   = var.name_prefix
    ManagedBy = "terraform"
  }

  public_ingress_ports = {
    http     = 80
    https    = 443
    app      = 3000
    postgres = 5432
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "app" {
  name        = "${var.name_prefix}-app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-app-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "ssh_from_vpc" {
  security_group_id = aws_security_group.app.id
  description       = "SSH from within the VPC"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_ingress_rule" "public" {
  for_each = local.public_ingress_ports

  security_group_id = aws_security_group.app.id
  description       = "Allow ${each.key} (${each.value}) from anywhere"
  ip_protocol       = "tcp"
  from_port         = each.value
  to_port           = each.value
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.app.id
  description       = "Allow all outbound traffic within the VPC only"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "service.local"
  description = "Private DNS namespace for service discovery"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-service-local"
  })
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = aws_nat_gateway.main.id
}

output "security_group_id" {
  description = "ID of the application security group"
  value       = aws_security_group.app.id
}

output "service_discovery_namespace_id" {
  description = "ID of the service.local private DNS namespace"
  value       = aws_service_discovery_private_dns_namespace.main.id
}

output "service_discovery_namespace_arn" {
  description = "ARN of the service.local private DNS namespace"
  value       = aws_service_discovery_private_dns_namespace.main.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the backup resources into."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used for naming backup resources."
  type        = string
  default     = "benchmark"
}

variable "backup_schedule" {
  description = "Cron expression for the backup rule schedule."
  type        = string
  default     = "cron(0 5 ? * * *)"
}

variable "backup_retention_days" {
  description = "Number of days to retain recovery points (must be between 7 and 90)."
  type        = number
  default     = 30

  validation {
    condition     = var.backup_retention_days >= 7 && var.backup_retention_days <= 90
    error_message = "backup_retention_days must be between 7 and 90."
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "backup_kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAWSBackupUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "backup" {
  description             = "KMS key for AWS Backup vault encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms.json

  tags = {
    Name = "${var.name_prefix}-backup-kms-key"
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.name_prefix}-backup-vault"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "this" {
  name        = "${var.name_prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name = "${var.name_prefix}-backup-vault"
  }
}

resource "aws_backup_vault_lock_configuration" "this" {
  backup_vault_name  = aws_backup_vault.this.name
  min_retention_days = 7
  max_retention_days = 90
}

resource "aws_backup_plan" "this" {
  name = "${var.name_prefix}-backup-plan"

  rule {
    rule_name         = "${var.name_prefix}-daily-backup-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_schedule
    start_window      = 60
    completion_window = 180

    lifecycle {
      delete_after = var.backup_retention_days
    }

    recovery_point_tags = {
      CreatedBy = "aws-backup"
      Plan      = "${var.name_prefix}-backup-plan"
    }
  }

  tags = {
    Name = "${var.name_prefix}-backup-plan"
  }

  depends_on = [aws_backup_vault_lock_configuration.this]
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${var.name_prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "${var.name_prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_backup_selection" "tagged" {
  name         = "${var.name_prefix}-tagged-selection"
  plan_id      = aws_backup_plan.this.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "benchmark-backup"
    value = "true"
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restore,
  ]
}

output "backup_vault_arn" {
  description = "ARN of the backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_plan_id" {
  description = "ID of the backup plan."
  value       = aws_backup_plan.this.id
}

output "backup_selection_id" {
  description = "ID of the backup selection."
  value       = aws_backup_selection.tagged.id
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt the backup vault."
  value       = aws_kms_key.backup.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used for naming all resources"
  type        = string
  default     = "myapp"
}

resource "aws_cognito_user_pool" "this" {
  name = "${var.name_prefix}-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = false
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 5
      max_length = 2048
    }
  }
}

resource "aws_cognito_user_pool_client" "this" {
  name         = "${var.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret               = false
  prevent_user_existence_errors = "ENABLED"

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

resource "aws_cognito_identity_pool" "this" {
  identity_pool_name               = "${var.name_prefix}_identity_pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.this.id
    provider_name           = aws_cognito_user_pool.this.endpoint
    server_side_token_check = false
  }
}

data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "${var.name_prefix}-cognito-authenticated"
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json
}

data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "${var.name_prefix}-cognito-authenticated-policy"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated_permissions.json
}

resource "aws_cognito_identity_pool_roles_attachment" "this" {
  identity_pool_id = aws_cognito_identity_pool.this.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

output "user_pool_id" {
  description = "ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.this.id
}

output "user_pool_client_id" {
  description = "ID of the Cognito User Pool app client"
  value       = aws_cognito_user_pool_client.this.id
}

output "identity_pool_id" {
  description = "ID of the Cognito Identity Pool"
  value       = aws_cognito_identity_pool.this.id
}

output "authenticated_role_arn" {
  description = "ARN of the IAM role assumed by authenticated identities"
  value       = aws_iam_role.authenticated.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the test VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the test subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "dns_servers" {
  description = "Public DNS servers for the DHCP options set"
  type        = list(string)
  default     = ["8.8.8.8", "8.8.4.4"]
}

resource "aws_vpc" "test" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

resource "aws_subnet" "test" {
  vpc_id                  = aws_vpc.test.id
  cidr_block              = var.subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "test-subnet"
  }
}

resource "aws_internet_gateway" "test" {
  vpc_id = aws_vpc.test.id

  tags = {
    Name = "test-igw"
  }
}

resource "aws_eip" "test" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.test]

  tags = {
    Name = "test-eip"
  }
}

resource "aws_vpc_dhcp_options" "test" {
  domain_name_servers = var.dns_servers

  tags = {
    Name = "test-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "test" {
  vpc_id          = aws_vpc.test.id
  dhcp_options_id = aws_vpc_dhcp_options.test.id
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.test.id

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.test.cidr_block]
  }

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.test.cidr_block]
  }

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.test.cidr_block]
  }

  egress {
    description = "All traffic to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.test.cidr_block]
  }

  tags = {
    Name = "test-default-sg"
  }
}

output "vpc_id" {
  value = aws_vpc.test.id
}

output "subnet_id" {
  value = aws_subnet.test.id
}

output "internet_gateway_id" {
  value = aws_internet_gateway.test.id
}

output "eip_public_ip" {
  value = aws_eip.test.public_ip
}

output "dhcp_options_id" {
  value = aws_vpc_dhcp_options.test.id
}

output "default_security_group_id" {
  value = aws_default_security_group.default.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "stage_name" {
  description = "API Gateway stage name"
  type        = string
  default     = "prod"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# KMS key for SNS topic encryption
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "sns_kms_key" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSNSServiceUse"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowApiGatewayRoleUse"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.apigw_sns.arn]
    }
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer-managed KMS key for the event-topic SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms_key.json
}

resource "aws_kms_alias" "sns" {
  name          = "alias/event-topic-sns"
  target_key_id = aws_kms_key.sns.key_id
}

# -----------------------------------------------------------------------------
# SNS topic
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "event_topic" {
  name              = "event-topic"
  kms_master_key_id = aws_kms_key.sns.arn
}

# -----------------------------------------------------------------------------
# IAM role for API Gateway to publish to SNS
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_sns" {
  name               = "apigateway-event-topic-publish-role"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

data "aws_iam_policy_document" "apigw_sns_publish" {
  statement {
    sid       = "AllowPublishToEventTopic"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "AllowUseOfTopicKmsKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = [aws_kms_key.sns.arn]
  }
}

resource "aws_iam_role_policy" "apigw_sns_publish" {
  name   = "publish-to-event-topic"
  role   = aws_iam_role.apigw_sns.id
  policy = data.aws_iam_policy_document.apigw_sns_publish.json
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "events" {
  name        = "event-topic-api"
  description = "REST API that publishes POST requests to the event-topic SNS topic"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  parent_id   = aws_api_gateway_rest_api.events.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "post_events" {
  rest_api_id   = aws_api_gateway_rest_api.events.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "post_events_sns" {
  rest_api_id             = aws_api_gateway_rest_api.events.id
  resource_id             = aws_api_gateway_resource.events.id
  http_method             = aws_api_gateway_method.post_events.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${local.partition}:apigateway:${var.aws_region}:sns:path//"
  credentials             = aws_iam_role.apigw_sns.arn
  passthrough_behavior    = "NEVER"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }

  depends_on = [aws_iam_role_policy.apigw_sns_publish]
}

resource "aws_api_gateway_method_response" "post_events_200" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_method_response" "post_events_400" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = "400"

  response_models = {
    "application/json" = "Error"
  }
}

resource "aws_api_gateway_method_response" "post_events_500" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = "500"

  response_models = {
    "application/json" = "Error"
  }
}

resource "aws_api_gateway_integration_response" "post_events_200" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = aws_api_gateway_method_response.post_events_200.status_code

  selection_pattern = "2\\d{2}"

  response_templates = {
    "application/json" = "{\"message\": \"Event published\", \"messageId\": \"$input.path('$.PublishResponse.PublishResult.MessageId')\"}"
  }

  depends_on = [aws_api_gateway_integration.post_events_sns]
}

resource "aws_api_gateway_integration_response" "post_events_400" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = aws_api_gateway_method_response.post_events_400.status_code

  selection_pattern = "4\\d{2}"

  response_templates = {
    "application/json" = "{\"message\": \"Bad request\"}"
  }

  depends_on = [aws_api_gateway_integration.post_events_sns]
}

resource "aws_api_gateway_integration_response" "post_events_500" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = aws_api_gateway_method_response.post_events_500.status_code

  selection_pattern = "5\\d{2}"

  response_templates = {
    "application/json" = "{\"message\": \"Internal error publishing event\"}"
  }

  depends_on = [aws_api_gateway_integration.post_events_sns]
}

resource "aws_api_gateway_deployment" "events" {
  rest_api_id = aws_api_gateway_rest_api.events.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events.id,
      aws_api_gateway_method.post_events.id,
      aws_api_gateway_integration.post_events_sns.id,
      aws_api_gateway_integration.post_events_sns.request_templates,
      aws_api_gateway_integration_response.post_events_200.id,
      aws_api_gateway_integration_response.post_events_400.id,
      aws_api_gateway_integration_response.post_events_500.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.post_events_sns,
    aws_api_gateway_integration_response.post_events_200,
    aws_api_gateway_integration_response.post_events_400,
    aws_api_gateway_integration_response.post_events_500,
  ]
}

resource "aws_api_gateway_stage" "events" {
  rest_api_id   = aws_api_gateway_rest_api.events.id
  deployment_id = aws_api_gateway_deployment.events.id
  stage_name    = var.stage_name
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "invoke_url" {
  description = "URL to POST events to"
  value       = "${aws_api_gateway_stage.events.invoke_url}/${aws_api_gateway_resource.events.path_part}"
}

output "sns_topic_arn" {
  description = "ARN of the event-topic SNS topic"
  value       = aws_sns_topic.event_topic.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the SNS topic"
  value       = aws_kms_key.sns.arn
}

output "apigateway_role_arn" {
  description = "ARN of the IAM role API Gateway uses to publish to SNS"
  value       = aws_iam_role.apigw_sns.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

provider "aws" {
  region = var.aws_region
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "ntier primary"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.10.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_a = data.aws_availability_zones.available.names[0]
  az_b = data.aws_availability_zones.available.names[1]

  subnets = {
    web  = { cidr = cidrsubnet(var.vpc_cidr, 8, 0), az = local.az_a, public = true }
    app  = { cidr = cidrsubnet(var.vpc_cidr, 8, 1), az = local.az_a, public = false }
    db   = { cidr = cidrsubnet(var.vpc_cidr, 8, 2), az = local.az_a, public = false }
    mgmt = { cidr = cidrsubnet(var.vpc_cidr, 8, 3), az = local.az_a, public = true }
    web2 = { cidr = cidrsubnet(var.vpc_cidr, 8, 4), az = local.az_b, public = true }
    app2 = { cidr = cidrsubnet(var.vpc_cidr, 8, 5), az = local.az_b, public = false }
    db2  = { cidr = cidrsubnet(var.vpc_cidr, 8, 6), az = local.az_b, public = false }
  }

  public_subnets  = { for k, v in local.subnets : k => v if v.public }
  private_subnets = { for k, v in local.subnets : k => v if !v.public }
}

resource "aws_vpc" "ntier" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "ntier" {
  vpc_id = aws_vpc.ntier.id

  tags = {
    Name = "${var.vpc_name} igw"
  }
}

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.ntier.id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = each.value.public

  tags = {
    Name = "${var.vpc_name} ${each.key}"
    Tier = each.key
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier.id
  }

  tags = {
    Name = "${var.vpc_name} public"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ntier.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier.id
  }

  tags = {
    Name = "${var.vpc_name} private"
  }
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  value = aws_vpc.ntier.id
}

output "internet_gateway_id" {
  value = aws_internet_gateway.ntier.id
}

output "subnet_ids" {
  value = { for k, s in aws_subnet.this : k => s.id }
}

output "public_route_table_id" {
  value = aws_route_table.public.id
}

output "private_route_table_id" {
  value = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.61"
    }
  }
}

################################################################################
# Variables - Creation Flags
################################################################################

variable "create" {
  description = "Determines whether any resources will be created (affects all resources)"
  type        = bool
  default     = true
}

variable "create_external" {
  description = "Determines whether an external CMK (externally provided material) will be created or a standard CMK (AWS provided material)"
  type        = bool
  default     = false
}

variable "create_replica" {
  description = "Determines whether a replica standard CMK will be created (AWS provided material)"
  type        = bool
  default     = false
}

variable "create_replica_external" {
  description = "Determines whether a replica external CMK will be created (externally provided material)"
  type        = bool
  default     = false
}

################################################################################
# Variables - Key
################################################################################

variable "bypass_policy_lockout_safety_check" {
  description = "A flag to indicate whether to bypass the key policy lockout safety check. Setting this value to true increases the risk that the KMS key becomes unmanageable"
  type        = bool
  default     = null
}

variable "customer_master_key_spec" {
  description = "Specifies whether the key contains a symmetric key or an asymmetric key pair and the encryption algorithms or signing algorithms that the key supports. Valid values: SYMMETRIC_DEFAULT, RSA_2048, RSA_3072, RSA_4096, HMAC_224, HMAC_256, HMAC_384, HMAC_512, ECC_NIST_P256, ECC_NIST_P384, ECC_NIST_P521, ECC_SECG_P256K1, ML_DSA_44, ML_DSA_65, ML_DSA_87, SM2"
  type        = string
  default     = null
}

variable "custom_key_store_id" {
  description = "ID of the KMS Custom Key Store where the key will be stored instead of KMS (eg CloudHSM)"
  type        = string
  default     = null
}

variable "xks_key_id" {
  description = "Identifies the external key that serves as key material for the KMS key in an external key store"
  type        = string
  default     = null
}

variable "deletion_window_in_days" {
  description = "The waiting period, specified in number of days. After the waiting period ends, AWS KMS deletes the KMS key. If you specify a value, it must be between 7 and 30, inclusive"
  type        = number
  default     = null

  validation {
    condition     = var.deletion_window_in_days == null || try(var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30, false)
    error_message = "deletion_window_in_days must be between 7 and 30, inclusive."
  }
}

variable "description" {
  description = "The description of the key as viewed in AWS console"
  type        = string
  default     = null
}

variable "enable_key_rotation" {
  description = "Specifies whether key rotation is enabled"
  type        = bool
  default     = true
}

variable "rotation_period_in_days" {
  description = "Custom period of time between each rotation date. Must be a number between 90 and 2560 (inclusive)"
  type        = number
  default     = null

  validation {
    condition     = var.rotation_period_in_days == null || try(var.rotation_period_in_days >= 90 && var.rotation_period_in_days <= 2560, false)
    error_message = "rotation_period_in_days must be between 90 and 2560, inclusive."
  }
}

variable "is_enabled" {
  description = "Specifies whether the key is enabled"
  type        = bool
  default     = null
}

variable "key_material_base64" {
  description = "Base64 encoded 256-bit symmetric encryption key material to import. The CMK is permanently associated with this key material. External key only"
  type        = string
  default     = null
  sensitive   = true
}

variable "key_usage" {
  description = "Specifies the intended use of the key. Valid values: ENCRYPT_DECRYPT, SIGN_VERIFY, GENERATE_VERIFY_MAC, KEY_AGREEMENT"
  type        = string
  default     = null
}

variable "multi_region" {
  description = "Indicates whether the KMS key is a multi-Region (true) or regional (false) key"
  type        = bool
  default     = false
}

variable "policy" {
  description = "A valid policy JSON document. When provided, this takes precedence over the generated key policy"
  type        = string
  default     = null
}

variable "valid_to" {
  description = "Time at which the imported key material expires. When the key material expires, AWS KMS deletes the key material and the CMK becomes unusable. If not specified, key material does not expire. Valid values: RFC3339 time string (YYYY-MM-DDTHH:MM:SSZ)"
  type        = string
  default     = null
}

variable "primary_key_arn" {
  description = "The primary key ARN of a multi-region replica key"
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "The primary external key ARN of a multi-region replica external key"
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Policy
################################################################################

variable "enable_default_policy" {
  description = "Specifies whether to enable the default key policy granting the account root full access"
  type        = bool
  default     = true
}

variable "key_owners" {
  description = "A list of IAM ARNs for those who will have full key permissions (`kms:*`)"
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "A list of IAM ARNs for key administrators"
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "A list of IAM ARNs for key users"
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "A list of IAM ARNs for key service users (AWS services integrated with KMS via grants)"
  type        = list(string)
  default     = []
}

variable "key_service_roles_for_autoscaling" {
  description = "A list of IAM ARNs for AWSServiceRoleForAutoScaling roles"
  type        = list(string)
  default     = []
}

variable "key_symmetric_encryption_users" {
  description = "A list of IAM ARNs for key symmetric encryption users"
  type        = list(string)
  default     = []
}

variable "key_hmac_users" {
  description = "A list of IAM ARNs for key HMAC users"
  type        = list(string)
  default     = []
}

variable "key_asymmetric_public_encryption_users" {
  description = "A list of IAM ARNs for key asymmetric public encryption users"
  type        = list(string)
  default     = []
}

variable "key_asymmetric_sign_verify_users" {
  description = "A list of IAM ARNs for key asymmetric sign and verify users"
  type        = list(string)
  default     = []
}

variable "enable_route53_dnssec" {
  description = "Determines whether the KMS policy used for Route53 DNSSEC signing is enabled"
  type        = bool
  default     = false
}

variable "route53_dnssec_sources" {
  description = "A list of maps containing `account_ids` and Route53 `hosted_zone_arn` that will be allowed to sign DNSSEC records. Defaults to the current account and all hosted zones"
  type = list(object({
    account_ids     = optional(list(string))
    hosted_zone_arn = optional(string)
  }))
  default = []
}

variable "source_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. In merging, statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "key_statements" {
  description = "A map of IAM policy statements for custom permission usage"
  type = map(object({
    sid           = optional(string)
    actions       = optional(list(string))
    not_actions   = optional(list(string))
    effect        = optional(string, "Allow")
    resources     = optional(list(string))
    not_resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = {}
}

################################################################################
# Variables - Aliases
################################################################################

variable "aliases" {
  description = "A list of aliases to create. Note - due to the use of `toset()`, values must be static strings and not computed values"
  type        = list(string)
  default     = []
}

variable "computed_aliases" {
  description = "A map of aliases to create. Values provided via the `name` key of the map can be computed from upstream resources"
  type = map(object({
    name = string
  }))
  default = {}
}

variable "aliases_use_name_prefix" {
  description = "Determines whether the alias name is used as a prefix"
  type        = bool
  default     = false
}

################################################################################
# Variables - Grants
################################################################################

variable "grants" {
  description = "A map of grant definitions to create"
  type = map(object({
    name                  = optional(string)
    grantee_principal     = string
    operations            = list(string)
    retiring_principal    = optional(string)
    grant_creation_tokens = optional(list(string))
    retire_on_delete      = optional(bool)
    constraints = optional(list(object({
      encryption_context_equals = optional(map(string))
      encryption_context_subset = optional(map(string))
    })), [])
  }))
  default = {}
}

################################################################################
# Data Sources
################################################################################

data "aws_partition" "current" {
  count = var.create ? 1 : 0
}

data "aws_caller_identity" "current" {
  count = var.create ? 1 : 0
}

################################################################################
# Locals
################################################################################

locals {
  account_id = try(data.aws_caller_identity.current[0].account_id, "")
  partition  = try(data.aws_partition.current[0].partition, "")

  create_standard         = var.create && !var.create_external && !var.create_replica && !var.create_replica_external
  create_external         = var.create && var.create_external && !var.create_replica && !var.create_replica_external
  create_replica          = var.create && var.create_replica && !var.create_external && !var.create_replica_external
  create_replica_external = var.create && var.create_replica_external && !var.create_external && !var.create_replica

  key_policy = var.policy != null ? var.policy : try(data.aws_iam_policy_document.this[0].json, null)

  route53_dnssec_sources = length(var.route53_dnssec_sources) > 0 ? var.route53_dnssec_sources : [
    {
      account_ids     = null
      hosted_zone_arn = null
    }
  ]

  aliases = merge(
    { for alias in toset(var.aliases) : alias => { name = alias } },
    var.computed_aliases,
  )

  key_arn = try(
    aws_kms_key.this[0].arn,
    aws_kms_external_key.this[0].arn,
    aws_kms_replica_key.this[0].arn,
    aws_kms_replica_external_key.this[0].arn,
    null,
  )

  key_id = try(
    aws_kms_key.this[0].key_id,
    aws_kms_external_key.this[0].id,
    aws_kms_replica_key.this[0].key_id,
    aws_kms_replica_external_key.this[0].key_id,
    null,
  )
}

check "mutually_exclusive_key_types" {
  assert {
    condition     = length([for flag in [var.create_external, var.create_replica, var.create_replica_external] : flag if flag]) <= 1
    error_message = "Only one of create_external, create_replica, or create_replica_external may be set to true."
  }
}

################################################################################
# Standard Key (AWS provided key material)
################################################################################

resource "aws_kms_key" "this" {
  count = local.create_standard ? 1 : 0

  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  customer_master_key_spec           = var.customer_master_key_spec
  custom_key_store_id                = var.custom_key_store_id
  xks_key_id                         = var.xks_key_id
  deletion_window_in_days            = var.deletion_window_in_days
  description                        = var.description
  enable_key_rotation                = var.enable_key_rotation
  rotation_period_in_days            = var.enable_key_rotation ? var.rotation_period_in_days : null
  is_enabled                         = var.is_enabled
  key_usage                          = var.key_usage
  multi_region                       = var.multi_region
  policy                             = local.key_policy

  tags = var.tags
}

################################################################################
# External Key (externally provided key material)
################################################################################

resource "aws_kms_external_key" "this" {
  count = local.create_external ? 1 : 0

  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  deletion_window_in_days            = var.deletion_window_in_days
  description                        = var.description
  enabled                            = var.is_enabled
  key_material_base64                = var.key_material_base64
  multi_region                       = var.multi_region
  policy                             = local.key_policy
  valid_to                           = var.valid_to

  tags = var.tags
}

################################################################################
# Replica Key (AWS provided key material)
################################################################################

resource "aws_kms_replica_key" "this" {
  count = local.create_replica ? 1 : 0

  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  deletion_window_in_days            = var.deletion_window_in_days
  description                        = var.description
  enabled                            = var.is_enabled
  primary_key_arn                    = var.primary_key_arn
  policy                             = local.key_policy

  tags = var.tags

  lifecycle {
    precondition {
      condition     = var.primary_key_arn != null
      error_message = "primary_key_arn must be provided when create_replica is true."
    }
  }
}

################################################################################
# Replica External Key (externally provided key material)
################################################################################

resource "aws_kms_replica_external_key" "this" {
  count = local.create_replica_external ? 1 : 0

  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  deletion_window_in_days            = var.deletion_window_in_days
  description                        = var.description
  enabled                            = var.is_enabled
  key_material_base64                = var.key_material_base64
  primary_key_arn                    = var.primary_external_key_arn
  policy                             = local.key_policy
  valid_to                           = var.valid_to

  tags = var.tags

  lifecycle {
    precondition {
      condition     = var.primary_external_key_arn != null
      error_message = "primary_external_key_arn must be provided when create_replica_external is true."
    }
  }
}

################################################################################
# Key Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.policy == null ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  # Default policy - account wide access to all key operations
  dynamic "statement" {
    for_each = var.enable_default_policy ? [1] : []

    content {
      sid       = "Default"
      actions   = ["kms:*"]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
      }
    }
  }

  # Key owner - all key operations
  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []

    content {
      sid       = "KeyOwner"
      actions   = ["kms:*"]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_owners
      }
    }
  }

  # Key administrators
  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []

    content {
      sid = "KeyAdministration"
      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion",
        "kms:ReplicateKey",
        "kms:ImportKeyMaterial",
        "kms:RotateKeyOnDemand",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
    }
  }

  # Key users
  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []

    content {
      sid = "KeyUsage"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
    }
  }

  # Key service users
  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []

    content {
      sid = "KeyServiceUsage"
      actions = [
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:RevokeGrant",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_service_users
      }

      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  # Key service roles for Auto Scaling - encryption usage
  dynamic "statement" {
    for_each = length(var.key_service_roles_for_autoscaling) > 0 ? [1] : []

    content {
      sid = "KeyServiceRolesASG"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_service_roles_for_autoscaling
      }
    }
  }

  # Key service roles for Auto Scaling - persistent volume attachment
  dynamic "statement" {
    for_each = length(var.key_service_roles_for_autoscaling) > 0 ? [1] : []

    content {
      sid       = "KeyServiceRolesASGPersistentVol"
      actions   = ["kms:CreateGrant"]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_service_roles_for_autoscaling
      }

      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  # Key symmetric encryption users
  dynamic "statement" {
    for_each = length(var.key_symmetric_encryption_users) > 0 ? [1] : []

    content {
      sid = "KeySymmetricEncryption"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_symmetric_encryption_users
      }
    }
  }

  # Key HMAC users
  dynamic "statement" {
    for_each = length(var.key_hmac_users) > 0 ? [1] : []

    content {
      sid = "KeyHMAC"
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac",
        "kms:DescribeKey",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_hmac_users
      }
    }
  }

  # Key asymmetric public encryption users
  dynamic "statement" {
    for_each = length(var.key_asymmetric_public_encryption_users) > 0 ? [1] : []

    content {
      sid = "KeyAsymmetricPublicEncryption"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:DescribeKey",
        "kms:GetPublicKey",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_public_encryption_users
      }
    }
  }

  # Key asymmetric sign/verify users
  dynamic "statement" {
    for_each = length(var.key_asymmetric_sign_verify_users) > 0 ? [1] : []

    content {
      sid = "KeyAsymmetricSignVerify"
      actions = [
        "kms:Sign",
        "kms:Verify",
        "kms:DescribeKey",
        "kms:GetPublicKey",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = var.key_asymmetric_sign_verify_users
      }
    }
  }

  # Route53 DNSSEC signing service
  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? local.route53_dnssec_sources : []

    content {
      sid = "Route53DnssecService${statement.key}"
      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign",
      ]
      resources = ["*"]

      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = coalesce(statement.value.account_ids, [local.account_id])
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = [coalesce(statement.value.hosted_zone_arn, "arn:${local.partition}:route53:::hostedzone/*")]
      }
    }
  }

  # Route53 DNSSEC grant creation for AWS resources
  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? local.route53_dnssec_sources : []

    content {
      sid       = "Route53DnssecGrant${statement.key}"
      actions   = ["kms:CreateGrant"]
      resources = ["*"]

      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }

      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = coalesce(statement.value.account_ids, [local.account_id])
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = [coalesce(statement.value.hosted_zone_arn, "arn:${local.partition}:route53:::hostedzone/*")]
      }
    }
  }

  # Custom statements
  dynamic "statement" {
    for_each = var.key_statements

    content {
      sid           = coalesce(statement.value.sid, statement.key)
      actions       = statement.value.actions
      not_actions   = statement.value.not_actions
      effect        = statement.value.effect
      resources     = statement.value.resources
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

################################################################################
# Aliases
################################################################################

resource "aws_kms_alias" "this" {
  for_each = var.create ? local.aliases : {}

  name          = var.aliases_use_name_prefix ? null : "alias/${trimprefix(each.value.name, "alias/")}"
  name_prefix   = var.aliases_use_name_prefix ? "alias/${trimprefix(each.value.name, "alias/")}-" : null
  target_key_id = local.key_id
}

################################################################################
# Grants
################################################################################

resource "aws_kms_grant" "this" {
  for_each = var.create ? var.grants : {}

  name                  = coalesce(each.value.name, each.key)
  key_id                = local.key_id
  grantee_principal     = each.value.grantee_principal
  operations            = each.value.operations
  retiring_principal    = each.value.retiring_principal
  grant_creation_tokens = each.value.grant_creation_tokens
  retire_on_delete      = each.value.retire_on_delete

  dynamic "constraints" {
    for_each = each.value.constraints

    content {
      encryption_context_equals = constraints.value.encryption_context_equals
      encryption_context_subset = constraints.value.encryption_context_subset
    }
  }
}

################################################################################
# Outputs
################################################################################

output "key_arn" {
  description = "The Amazon Resource Name (ARN) of the key"
  value       = local.key_arn
}

output "key_id" {
  description = "The globally unique identifier for the key"
  value       = local.key_id
}

output "key_policy" {
  description = "The IAM resource policy set on the key"
  value = try(
    aws_kms_key.this[0].policy,
    aws_kms_external_key.this[0].policy,
    aws_kms_replica_key.this[0].policy,
    aws_kms_replica_external_key.this[0].policy,
    null,
  )
}

output "external_key_expiration_model" {
  description = "Whether the key material expires. Empty when pending key material import, otherwise `KEY_MATERIAL_EXPIRES` or `KEY_MATERIAL_DOES_NOT_EXPIRE`"
  value       = try(aws_kms_external_key.this[0].expiration_model, aws_kms_replica_external_key.this[0].expiration_model, null)
}

output "external_key_state" {
  description = "The state of the CMK"
  value       = try(aws_kms_external_key.this[0].key_state, aws_kms_replica_external_key.this[0].key_state, null)
}

output "external_key_usage" {
  description = "The cryptographic operations for which you can use the CMK"
  value       = try(aws_kms_external_key.this[0].key_usage, aws_kms_replica_external_key.this[0].key_usage, null)
}

output "aliases" {
  description = "A map of aliases created and their attributes"
  value       = aws_kms_alias.this
}

output "grants" {
  description = "A map of grants created and their attributes"
  value       = aws_kms_grant.this
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name of the SNS topic. For FIFO topics, '.fifo' is appended automatically if missing."
  type        = string
}

variable "display_name" {
  description = "Display name for the SNS topic."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

# Encryption

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key for SNS topic encryption."
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "ARN or alias of an existing KMS key to use for SNS encryption. Ignored when create_kms_key is true. Falls back to alias/aws/sns when null."
  type        = string
  default     = null
}

# Topic policy

variable "create_topic_policy" {
  description = "Whether to attach a custom SNS topic policy."
  type        = bool
  default     = false
}

variable "topic_policy" {
  description = "JSON string of the SNS topic policy. Required when create_topic_policy is true."
  type        = string
  default     = null
}

# FIFO

variable "fifo_topic" {
  description = "Whether the SNS topic is a FIFO topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

# Delivery feedback - Application

variable "application_success_feedback_role_arn" {
  description = "IAM role ARN permitted to write successful Application delivery logs to CloudWatch."
  type        = string
  default     = null
}

variable "application_success_feedback_sample_rate" {
  description = "Percentage (0-100) of successful Application deliveries to sample."
  type        = number
  default     = null
}

variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN permitted to write failed Application delivery logs to CloudWatch."
  type        = string
  default     = null
}

# Delivery feedback - HTTP

variable "http_success_feedback_role_arn" {
  description = "IAM role ARN permitted to write successful HTTP delivery logs to CloudWatch."
  type        = string
  default     = null
}

variable "http_success_feedback_sample_rate" {
  description = "Percentage (0-100) of successful HTTP deliveries to sample."
  type        = number
  default     = null
}

variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN permitted to write failed HTTP delivery logs to CloudWatch."
  type        = string
  default     = null
}

# Delivery feedback - Lambda

variable "lambda_success_feedback_role_arn" {
  description = "IAM role ARN permitted to write successful Lambda delivery logs to CloudWatch."
  type        = string
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  description = "Percentage (0-100) of successful Lambda deliveries to sample."
  type        = number
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN permitted to write failed Lambda delivery logs to CloudWatch."
  type        = string
  default     = null
}

# Delivery feedback - SQS

variable "sqs_success_feedback_role_arn" {
  description = "IAM role ARN permitted to write successful SQS delivery logs to CloudWatch."
  type        = string
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  description = "Percentage (0-100) of successful SQS deliveries to sample."
  type        = number
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN permitted to write failed SQS delivery logs to CloudWatch."
  type        = string
  default     = null
}

# Delivery feedback - Firehose

variable "firehose_success_feedback_role_arn" {
  description = "IAM role ARN permitted to write successful Firehose delivery logs to CloudWatch."
  type        = string
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  description = "Percentage (0-100) of successful Firehose deliveries to sample."
  type        = number
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN permitted to write failed Firehose delivery logs to CloudWatch."
  type        = string
  default     = null
}

# Subscriptions

variable "subscriptions" {
  description = "Map of SNS subscriptions to create, keyed by an arbitrary identifier."
  type = map(object({
    endpoint               = string
    protocol               = string
    endpoint_auto_confirms = optional(bool, false)
    raw_message_delivery   = optional(bool, false)
    filter_policy          = optional(string)
    filter_policy_scope    = optional(string)
    redrive_policy         = optional(string)
    subscription_role_arn  = optional(string)
  }))
  default = {}
}

################################################################################
# Data sources & locals
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  topic_name = var.fifo_topic && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name

  # KMS alias names may only contain alphanumerics, '/', '_' and '-'
  kms_alias_name = "alias/sns/${replace(local.topic_name, "/[^a-zA-Z0-9/_-]/", "-")}"

  kms_master_key_id = (
    var.create_kms_key ? aws_kms_key.this[0].arn :
    var.kms_master_key_id != null ? var.kms_master_key_id :
    "alias/aws/sns"
  )
}

################################################################################
# KMS
################################################################################

data "aws_iam_policy_document" "kms" {
  count = var.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }
}

resource "aws_kms_key" "this" {
  count = var.create_kms_key ? 1 : 0

  description             = "KMS key for SNS topic ${local.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = var.tags
}

resource "aws_kms_alias" "this" {
  count = var.create_kms_key ? 1 : 0

  name          = local.kms_alias_name
  target_key_id = aws_kms_key.this[0].key_id
}

################################################################################
# SNS Topic
################################################################################

resource "aws_sns_topic" "this" {
  name         = local.topic_name
  display_name = var.display_name

  kms_master_key_id = local.kms_master_key_id

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null

  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn

  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn

  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn

  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn

  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn

  tags = var.tags

  lifecycle {
    precondition {
      condition     = !var.create_topic_policy || var.topic_policy != null
      error_message = "topic_policy must be provided when create_topic_policy is true."
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this.arn
  policy = var.topic_policy
}

################################################################################
# Subscriptions
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn = aws_sns_topic.this.arn
  endpoint  = each.value.endpoint
  protocol  = each.value.protocol

  endpoint_auto_confirms = each.value.endpoint_auto_confirms
  raw_message_delivery   = each.value.raw_message_delivery
  filter_policy          = each.value.filter_policy
  filter_policy_scope    = each.value.filter_policy != null ? each.value.filter_policy_scope : null
  redrive_policy         = each.value.redrive_policy
  subscription_role_arn  = each.value.subscription_role_arn
}

################################################################################
# Outputs
################################################################################

output "sns_topic_arn" {
  description = "ARN of the SNS topic."
  value       = aws_sns_topic.this.arn
}

output "sns_topic_name" {
  description = "Name of the SNS topic."
  value       = aws_sns_topic.this.name
}

output "kms_master_key_id" {
  description = "KMS key identifier used for SNS server-side encryption."
  value       = local.kms_master_key_id
}

output "kms_key_arn" {
  description = "ARN of the created KMS key, if any."
  value       = try(aws_kms_key.this[0].arn, null)
}

output "kms_alias_name" {
  description = "Alias of the created KMS key, if any."
  value       = try(aws_kms_alias.this[0].name, null)
}

output "subscription_arns" {
  description = "Map of subscription keys to subscription ARNs."
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "create_group" {
  description = "Whether to create the IAM developer group"
  type        = bool
  default     = true
}

variable "create_group_policy" {
  description = "Whether to create the IAM read-only and S3 read/write access policy"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Whether to attach the IAM read-only and S3 policy to the group"
  type        = bool
  default     = true
}

variable "create_users" {
  description = "Whether to create the IAM users"
  type        = bool
  default     = true
}

variable "create_ec2_screenshot_policy" {
  description = "Whether to create the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachments" {
  description = "Whether to attach the EC2 console screenshot policy to each user"
  type        = bool
  default     = true
}

variable "create_group_membership" {
  description = "Whether to add the created users to the developer group"
  type        = bool
  default     = true
}

variable "create_instance_role" {
  description = "Whether to create the EC2 instance role"
  type        = bool
  default     = true
}

variable "group_name" {
  description = "Name of the IAM developer group"
  type        = string
  default     = "developers"
}

variable "group_path" {
  description = "Path for the IAM developer group"
  type        = string
  default     = "/"
}

variable "users" {
  description = "List of IAM users to create"
  type = list(object({
    name = string
    path = optional(string, "/")
    tags = optional(map(string), {})
  }))
  default = [
    {
      name = "jack"
      tags = {
        user_created_by = "terraform"
      }
    },
    {
      name = "jones"
      tags = {
        user_created_by = "terraform"
      }
    }
  ]
}

variable "group_policy_name" {
  description = "Name of the IAM read-only and S3 read/write access policy"
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "group_policy_description" {
  description = "Description of the IAM read-only and S3 read/write access policy"
  type        = string
  default     = "Provides read-only access to IAM and read/write access to S3 objects"
}

variable "group_policy_statements" {
  description = "Statements for the IAM read-only and S3 read/write access policy"
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = list(string)
  }))
  default = [
    {
      sid    = "IAMReadOnly"
      effect = "Allow"
      actions = [
        "iam:Get*",
        "iam:List*",
        "iam:GenerateCredentialReport",
        "iam:GenerateServiceLastAccessedDetails",
        "iam:SimulateCustomPolicy",
        "iam:SimulatePrincipalPolicy"
      ]
      resources = ["*"]
    },
    {
      sid    = "S3ObjectReadWrite"
      effect = "Allow"
      actions = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:ListBucket"
      ]
      resources = ["*"]
    }
  ]
}

variable "ec2_screenshot_policy_name" {
  description = "Name of the EC2 console screenshot policy"
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "ec2_screenshot_policy_description" {
  description = "Description of the EC2 console screenshot policy"
  type        = string
  default     = "Allows retrieving EC2 instance console screenshots"
}

variable "instance_role_name" {
  description = "Name of the EC2 instance role"
  type        = string
  default     = "instance_role"
}

variable "instance_role_policy_arn" {
  description = "ARN of the managed policy to attach to the EC2 instance role"
  type        = string
  default     = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

variable "tags" {
  description = "Common tags applied to taggable resources"
  type        = map(string)
  default     = {}
}

locals {
  users_map = { for u in var.users : u.name => u }

  group_name = var.create_group ? aws_iam_group.developers[0].name : var.group_name

  user_names = var.create_users ? { for k, u in aws_iam_user.this : k => u.name } : { for k, u in local.users_map : k => u.name }
}

resource "aws_iam_group" "developers" {
  count = var.create_group ? 1 : 0

  name = var.group_name
  path = var.group_path
}

data "aws_iam_policy_document" "group_policy" {
  count = var.create_group_policy ? 1 : 0

  dynamic "statement" {
    for_each = var.group_policy_statements

    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
    }
  }
}

resource "aws_iam_policy" "group_policy" {
  count = var.create_group_policy ? 1 : 0

  name        = var.group_policy_name
  description = var.group_policy_description
  policy      = data.aws_iam_policy_document.group_policy[0].json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developers" {
  count = var.create_group_policy_attachment && var.create_group_policy ? 1 : 0

  group      = local.group_name
  policy_arn = aws_iam_policy.group_policy[0].arn
}

resource "aws_iam_user" "this" {
  for_each = var.create_users ? local.users_map : {}

  name = each.value.name
  path = each.value.path
  tags = merge(var.tags, each.value.tags)
}

data "aws_iam_policy_document" "ec2_screenshot" {
  count = var.create_ec2_screenshot_policy ? 1 : 0

  statement {
    sid       = "EC2GetConsoleScreenshot"
    effect    = "Allow"
    actions   = ["ec2:GetConsoleScreenshot"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_screenshot" {
  count = var.create_ec2_screenshot_policy ? 1 : 0

  name        = var.ec2_screenshot_policy_name
  description = var.ec2_screenshot_policy_description
  policy      = data.aws_iam_policy_document.ec2_screenshot[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "ec2_screenshot" {
  for_each = var.create_user_policy_attachments && var.create_ec2_screenshot_policy ? local.user_names : {}

  user       = each.value
  policy_arn = aws_iam_policy.ec2_screenshot[0].arn
}

resource "aws_iam_user_group_membership" "developers" {
  for_each = var.create_group_membership ? local.user_names : {}

  user   = each.value
  groups = [local.group_name]
}

data "aws_iam_policy_document" "instance_assume_role" {
  count = var.create_instance_role ? 1 : 0

  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance_role" {
  count = var.create_instance_role ? 1 : 0

  name               = var.instance_role_name
  assume_role_policy = data.aws_iam_policy_document.instance_assume_role[0].json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "instance_role" {
  count = var.create_instance_role ? 1 : 0

  role       = aws_iam_role.instance_role[0].name
  policy_arn = var.instance_role_policy_arn
}

resource "aws_iam_instance_profile" "instance_role" {
  count = var.create_instance_role ? 1 : 0

  name = var.instance_role_name
  role = aws_iam_role.instance_role[0].name
  tags = var.tags
}

output "group_name" {
  description = "Name of the IAM developer group"
  value       = try(aws_iam_group.developers[0].name, null)
}

output "group_arn" {
  description = "ARN of the IAM developer group"
  value       = try(aws_iam_group.developers[0].arn, null)
}

output "group_policy_arn" {
  description = "ARN of the IAM read-only and S3 read/write access policy"
  value       = try(aws_iam_policy.group_policy[0].arn, null)
}

output "user_arns" {
  description = "Map of IAM user names to ARNs"
  value       = { for k, u in aws_iam_user.this : k => u.arn }
}

output "ec2_screenshot_policy_arn" {
  description = "ARN of the EC2 console screenshot policy"
  value       = try(aws_iam_policy.ec2_screenshot[0].arn, null)
}

output "instance_role_arn" {
  description = "ARN of the EC2 instance role"
  value       = try(aws_iam_role.instance_role[0].arn, null)
}

output "instance_profile_name" {
  description = "Name of the EC2 instance profile"
  value       = try(aws_iam_instance_profile.instance_role[0].name, null)
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = local.region
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  name   = "multi-cluster-vpc"
  region = "us-west-2"

  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)

  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

################################################################################
# VPC
################################################################################

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 4, k)]
  public_subnets  = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 8, k + 48)]

  enable_nat_gateway = true
  single_nat_gateway = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

################################################################################
# Cross-cluster Security Groups
################################################################################

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Allow communication from cluster2 SG to cluster1 SG"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster1_additional_sg"
  })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Allow communication from cluster1 SG to cluster2 SG"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster2_additional_sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all traffic from cluster2"

  tags = local.tags
}

resource "aws_vpc_security_group_egress_rule" "cluster1_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all traffic to cluster2"

  tags = local.tags
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all traffic from cluster1"

  tags = local.tags
}

resource "aws_vpc_security_group_egress_rule" "cluster2_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
  description                  = "Allow all traffic to cluster1"

  tags = local.tags
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = module.vpc.vpc_id
}

output "private_subnets" {
  description = "List of IDs of private subnets"
  value       = module.vpc.private_subnets
}

output "public_subnets" {
  description = "List of IDs of public subnets"
  value       = module.vpc.public_subnets
}

output "cluster1_additional_sg_id" {
  description = "ID of the cluster1 additional security group"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "ID of the cluster2 additional security group"
  value       = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes supported as an alias for this user pool"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to be auto-verified"
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject"
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "Multi-factor authentication configuration (OFF, ON, OPTIONAL)"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message"
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Verification message template configuration"
  type        = map(string)
  default = {
    default_email_option  = "CONFIRM_WITH_LINK"
    email_message_by_link = "Please click the link below to verify your email address. {##Verify Email##}"
    email_subject_by_link = "Your verification link"
  }
}

variable "sms_configuration" {
  description = "SMS configuration map"
  type        = map(string)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  description = "Account recovery mechanisms"
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_email"
      priority = 2
    },
    {
      name     = "verified_phone_number"
      priority = 1
    }
  ]
}

variable "invite_message_template" {
  description = "Invite message templates"
  type        = map(string)
  default = {
    email_message = "Your username is {username} and temporary password is {####}."
    email_subject = "Your temporary password"
    sms_message   = "Your username is {username} and temporary password is {####}."
  }
}

variable "allow_admin_create_user_only" {
  description = "Only allow administrators to create users"
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Enable software token MFA"
  type        = bool
  default     = true
}

variable "case_sensitive" {
  description = "Whether username case sensitivity is applied"
  type        = bool
  default     = null
}

variable "challenge_required_on_new_device" {
  description = "Whether a challenge is required on a new device"
  type        = bool
  default     = null
}

variable "device_only_remembered_on_user_prompt" {
  description = "Whether a device is only remembered on user prompt"
  type        = bool
  default     = null
}

variable "lambda_config" {
  description = "Lambda trigger configuration. Supports custom_email_sender = { lambda_arn, lambda_version } together with kms_key_id"
  type        = any
  default     = {}
}

variable "schema" {
  description = "Custom schema attribute definitions"
  type        = any
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      mutable             = true
      required            = true
    }
  ]
}

variable "client_names" {
  description = "List of user pool client app names"
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Whether to generate a client secret"
  type        = bool
  default     = false
}

variable "client_access_token_validity" {
  description = "Access token validity"
  type        = number
  default     = 120
}

variable "client_id_token_validity" {
  description = "ID token validity"
  type        = number
  default     = 120
}

variable "client_refresh_token_validity" {
  description = "Refresh token validity"
  type        = number
  default     = 7
}

variable "client_token_validity_units" {
  description = "Units for token validities"
  type        = map(string)
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "client_allowed_oauth_flows_user_pool_client" {
  description = "Whether the client is allowed to follow the OAuth protocol"
  type        = bool
  default     = false
}

variable "client_enable_token_revocation" {
  description = "Enable token revocation for the client"
  type        = bool
  default     = true
}

variable "client_explicit_auth_flows" {
  description = "Explicit authentication flows"
  type        = list(string)
  default     = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "client_prevent_user_existence_errors" {
  description = "Prevent user existence errors setting (LEGACY or ENABLED)"
  type        = string
  default     = "LEGACY"
}

variable "client_read_attributes" {
  description = "Attributes the client can read"
  type        = list(string)
  default     = []
}

variable "client_write_attributes" {
  description = "Attributes the client can write"
  type        = list(string)
  default     = []
}

variable "client_callback_urls" {
  description = "Allowed callback URLs"
  type        = list(string)
  default     = []
}

variable "client_logout_urls" {
  description = "Allowed logout URLs"
  type        = list(string)
  default     = []
}

variable "client_allowed_oauth_flows" {
  description = "Allowed OAuth flows"
  type        = list(string)
  default     = []
}

variable "client_allowed_oauth_scopes" {
  description = "Allowed OAuth scopes"
  type        = list(string)
  default     = []
}

variable "client_supported_identity_providers" {
  description = "Supported identity providers"
  type        = list(string)
  default     = []
}

variable "user_group_name" {
  description = "Name of the user group; group is created only when non-empty"
  type        = string
  default     = ""
}

variable "user_group_description" {
  description = "Description of the user group"
  type        = string
  default     = ""
}

variable "user_group_precedence" {
  description = "Precedence of the user group"
  type        = number
  default     = 0
}

variable "user_group_role_arn" {
  description = "IAM role ARN for the user group"
  type        = string
  default     = ""
}

variable "domain" {
  description = "Cognito User Pool domain; created only when non-empty"
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "ACM certificate ARN for a custom domain"
  type        = string
  default     = ""
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias record for the domain"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to the user pool"
  type        = map(string)
  default     = {}
}

locals {
  sms_configuration_enabled = lookup(var.sms_configuration, "external_id", "") != "" && lookup(var.sms_configuration, "sns_caller_arn", "") != ""

  device_configuration_enabled = var.challenge_required_on_new_device != null || var.device_only_remembered_on_user_prompt != null

  schema_with_constraints = [
    for s in var.schema : s
    if try(s.min_length, null) != null || try(s.max_length, null) != null
  ]

  schema_without_constraints = [
    for s in var.schema : s
    if try(s.min_length, null) == null && try(s.max_length, null) == null
  ]
}

resource "aws_cognito_user_pool" "pool" {
  name = var.pool_name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  verification_message_template {
    default_email_option  = lookup(var.verification_message_template, "default_email_option", "CONFIRM_WITH_LINK")
    email_message_by_link = lookup(var.verification_message_template, "email_message_by_link", null)
    email_subject_by_link = lookup(var.verification_message_template, "email_subject_by_link", null)
  }

  dynamic "sms_configuration" {
    for_each = local.sms_configuration_enabled ? [var.sms_configuration] : []
    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
    }
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms
      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.allow_admin_create_user_only

    invite_message_template {
      email_message = lookup(var.invite_message_template, "email_message", null)
      email_subject = lookup(var.invite_message_template, "email_subject", null)
      sms_message   = lookup(var.invite_message_template, "sms_message", null)
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [true] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive != null ? [var.case_sensitive] : []
    content {
      case_sensitive = username_configuration.value
    }
  }

  dynamic "device_configuration" {
    for_each = local.device_configuration_enabled ? [true] : []
    content {
      challenge_required_on_new_device      = var.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_config) > 0 ? [var.lambda_config] : []
    content {
      create_auth_challenge          = lookup(lambda_config.value, "create_auth_challenge", null)
      custom_message                 = lookup(lambda_config.value, "custom_message", null)
      define_auth_challenge          = lookup(lambda_config.value, "define_auth_challenge", null)
      post_authentication            = lookup(lambda_config.value, "post_authentication", null)
      post_confirmation              = lookup(lambda_config.value, "post_confirmation", null)
      pre_authentication             = lookup(lambda_config.value, "pre_authentication", null)
      pre_sign_up                    = lookup(lambda_config.value, "pre_sign_up", null)
      pre_token_generation           = lookup(lambda_config.value, "pre_token_generation", null)
      user_migration                 = lookup(lambda_config.value, "user_migration", null)
      verify_auth_challenge_response = lookup(lambda_config.value, "verify_auth_challenge_response", null)
      kms_key_id                     = lookup(lambda_config.value, "kms_key_id", null)

      dynamic "custom_email_sender" {
        for_each = lookup(lambda_config.value, "custom_email_sender", null) != null ? [lambda_config.value.custom_email_sender] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = custom_email_sender.value.lambda_version
        }
      }
    }
  }

  dynamic "schema" {
    for_each = local.schema_without_constraints
    content {
      name                     = schema.value.name
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = try(schema.value.developer_only_attribute, null)
      mutable                  = try(schema.value.mutable, null)
      required                 = try(schema.value.required, null)
    }
  }

  dynamic "schema" {
    for_each = local.schema_with_constraints
    content {
      name                     = schema.value.name
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = try(schema.value.developer_only_attribute, null)
      mutable                  = try(schema.value.mutable, null)
      required                 = try(schema.value.required, null)

      string_attribute_constraints {
        min_length = try(schema.value.min_length, null)
        max_length = try(schema.value.max_length, null)
      }
    }
  }

  tags = var.tags

  lifecycle {
    ignore_changes = [estimated_number_of_users]
  }
}

resource "aws_cognito_user_pool_client" "client" {
  for_each = toset(var.client_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret        = var.client_generate_secret
  access_token_validity  = var.client_access_token_validity
  id_token_validity      = var.client_id_token_validity
  refresh_token_validity = var.client_refresh_token_validity

  token_validity_units {
    access_token  = lookup(var.client_token_validity_units, "access_token", "minutes")
    id_token      = lookup(var.client_token_validity_units, "id_token", "minutes")
    refresh_token = lookup(var.client_token_validity_units, "refresh_token", "days")
  }

  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.client_enable_token_revocation
  explicit_auth_flows                  = var.client_explicit_auth_flows
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors

  read_attributes              = var.client_read_attributes
  write_attributes             = var.client_write_attributes
  callback_urls                = var.client_callback_urls
  logout_urls                  = var.client_logout_urls
  allowed_oauth_flows          = var.client_allowed_oauth_flows
  allowed_oauth_scopes         = var.client_allowed_oauth_scopes
  supported_identity_providers = var.client_supported_identity_providers
}

resource "aws_cognito_user_group" "group" {
  count = var.user_group_name != "" ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.pool.id
  description  = var.user_group_description != "" ? var.user_group_description : null
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn != "" ? var.user_group_role_arn : null
}

resource "aws_cognito_user_pool_domain" "domain" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.pool.id
  certificate_arn = var.domain_certificate_arn != "" ? var.domain_certificate_arn : null
}

resource "aws_route53_record" "domain" {
  count = var.create_route53_record && var.route53_zone_id != "" && var.domain != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = aws_cognito_user_pool_domain.domain[0].domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

output "user_pool_id" {
  description = "ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.id
}

output "user_pool_arn" {
  description = "ARN of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.arn
}

output "user_pool_endpoint" {
  description = "Endpoint of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.endpoint
}

output "client_ids" {
  description = "Map of client names to client IDs"
  value       = { for name, client in aws_cognito_user_pool_client.client : name => client.id }
}

output "client_secrets" {
  description = "Map of client names to client secrets"
  value       = { for name, client in aws_cognito_user_pool_client.client : name => client.client_secret }
  sensitive   = true
}

output "user_group_name" {
  description = "Name of the Cognito user group"
  value       = try(aws_cognito_user_group.group[0].name, null)
}

output "domain_cloudfront_distribution" {
  description = "CloudFront distribution backing the user pool domain"
  value       = try(aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn, null)
}

output "route53_record_fqdn" {
  description = "FQDN of the Route 53 alias record"
  value       = try(aws_route53_record.domain[0].fqdn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_name" {
  description = "Identifier of the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 pool from which the Elastic IP is allocated"
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr_block" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_availability_zone" {
  description = "Availability zone for Subnet A (defaults to the first AZ in the region)"
  type        = string
  default     = null
}

variable "subnet_a_map_public_ip_on_launch" {
  description = "Whether instances launched in Subnet A receive a public IP"
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_cidr_block" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_availability_zone" {
  description = "Availability zone for Subnet B (defaults to the second AZ in the region)"
  type        = string
  default     = null
}

variable "subnet_b_map_public_ip_on_launch" {
  description = "Whether instances launched in Subnet B receive a public IP"
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_cidr_block" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_availability_zone" {
  description = "Availability zone for Subnet C (defaults to the third AZ in the region)"
  type        = string
  default     = null
}

variable "subnet_c_map_public_ip_on_launch" {
  description = "Whether instances launched in Subnet C receive a public IP"
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  subnet_a_az = coalesce(var.subnet_a_availability_zone, data.aws_availability_zones.available.names[0])
  subnet_b_az = coalesce(var.subnet_b_availability_zone, data.aws_availability_zones.available.names[1])
  subnet_c_az = coalesce(var.subnet_c_availability_zone, data.aws_availability_zones.available.names[2])
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr_block
  availability_zone       = local.subnet_a_az
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name       = var.subnet_a_name
    Identifier = var.public_subnet_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr_block
  availability_zone       = local.subnet_b_az
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr_block
  availability_zone       = local.subnet_c_az
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = {
    Name = "${var.nat_gateway_name}-EIP"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Custom security group allowing egress only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr_block]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway"
  value       = aws_nat_gateway.main.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "vault_name" {
  description = "Name of the AWS Backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "tags" {
  description = "Optional tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "backup_tag_key" {
  description = "Tag key used to select resources for backup"
  type        = string
  default     = "backup"
}

variable "daily_schedule" {
  description = "Cron schedule for the daily backup rule"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "daily_enable_continuous_backup" {
  description = "Enable continuous backup for the daily backup rule"
  type        = bool
  default     = false
}

variable "weekly_schedule" {
  description = "Cron schedule for the weekly backup rule"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule for the monthly backup rule"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "enable_notifications" {
  description = "Whether to configure backup vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for backup vault notifications"
  type        = string
  default     = null

  validation {
    condition     = var.sns_topic_arn == null || can(regex("^arn:aws[a-zA-Z-]*:sns:", var.sns_topic_arn))
    error_message = "sns_topic_arn must be a valid SNS topic ARN."
  }
}

variable "backup_vault_events" {
  description = "List of backup vault events to send notifications for"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED",
  ]
}

data "aws_partition" "current" {}

resource "aws_kms_key" "backup" {
  description             = "KMS key for AWS Backup vault ${var.vault_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.vault_name}"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "this" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.tags
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${var.vault_name}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "daily" {
  name = "${var.vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.this.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.daily_enable_continuous_backup

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  tags = var.tags
}

resource "aws_backup_plan" "weekly" {
  name = "${var.vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = 31
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  tags = var.tags
}

resource "aws_backup_plan" "monthly" {
  name = "${var.vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = 366
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  condition {
    string_like {
      key   = "aws:ResourceTag/${var.backup_tag_key}"
      value = "daily"
    }
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  condition {
    string_like {
      key   = "aws:ResourceTag/${var.backup_tag_key}"
      value = "weekly"
    }
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  condition {
    string_like {
      key   = "aws:ResourceTag/${var.backup_tag_key}"
      value = "monthly"
    }
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events

  lifecycle {
    precondition {
      condition     = var.sns_topic_arn != null
      error_message = "sns_topic_arn must be set when enable_notifications is true."
    }
  }
}

output "backup_vault_arn" {
  value = aws_backup_vault.this.arn
}

output "backup_vault_name" {
  value = aws_backup_vault.this.name
}

output "kms_key_arn" {
  value = aws_kms_key.backup.arn
}

output "backup_role_arn" {
  value = aws_iam_role.backup.arn
}

output "backup_plan_ids" {
  value = {
    daily   = aws_backup_plan.daily.id
    weekly  = aws_backup_plan.weekly.id
    monthly = aws_backup_plan.monthly.id
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag used for resource naming"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, {
    Name   = "${var.env}-vpc"
    Region = data.aws_region.current.name
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.env}-igw"
  })
}

resource "aws_subnet" "public_subnets" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.env}-public-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "public_subnets" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-public-subnets"
  })
}

resource "aws_route_table_association" "public_routes" {
  count          = length(aws_subnet.public_subnets)
  route_table_id = aws_route_table.public_subnets.id
  subnet_id      = aws_subnet.public_subnets[count.index].id
}

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-eip-${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "nat" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public_subnets[count.index % length(aws_subnet.public_subnets)].id

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-gw-${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_subnet" "private_subnets" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]

  tags = merge(var.common_tags, {
    Name = "${var.env}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "private_subnets" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-private-subnets-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private_routes" {
  count          = length(aws_subnet.private_subnets)
  route_table_id = aws_route_table.private_subnets[count.index].id
  subnet_id      = aws_subnet.private_subnets[count.index].id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_cidr" {
  value = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  value = aws_subnet.public_subnets[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private_subnets[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.nat[*].id
}

output "nat_eip_public_ips" {
  value = aws_eip.nat[*].public_ip
}

variable "create_eks" {
  description = "Whether to create the EKS cluster"
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "Authentication mode for the EKS cluster"
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "control_plane_subnet_ids" {
  description = "Subnet IDs for the EKS control plane ENIs"
  type        = list(string)
  default     = []
}

variable "subnet_ids" {
  description = "Subnet IDs used when control_plane_subnet_ids is empty"
  type        = list(string)
  default     = []
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name     = var.cluster_name
  version  = var.cluster_version
  role_arn = aws_iam_role.eks_cluster.arn

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  vpc_config {
    subnet_ids = coalescelist(var.control_plane_subnet_ids, var.subnet_ids)
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {}

data "aws_caller_identity" "current" {}

locals {
  iam_path = "/system/"

  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountId  = data.aws_caller_identity.current.account_id
    UserId     = data.aws_caller_identity.current.user_id
  }
}

data "aws_iam_policy_document" "cicd_user_policy" {
  statement {
    sid    = "CodeBuildCodeCommitCloudWatchEventsLogsReadOnly"
    effect = "Allow"

    actions = [
      "codebuild:BatchGet*",
      "codebuild:GetResourcePolicy",
      "codebuild:List*",
      "codebuild:DescribeTestCases",
      "codebuild:DescribeCodeCoverages",
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:ListBranches",
      "codecommit:ListRepositories",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics",
      "events:DescribeRule",
      "events:ListTargetsByRule",
      "events:ListRuleNamesByTarget",
      "events:ListRules",
      "logs:GetLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:FilterLogEvents",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CodeStarConnectionsUserAccess"
    effect = "Allow"

    actions = [
      "codestar-connections:ListConnections",
      "codestar-connections:GetConnection",
    ]

    resources = ["arn:aws:codestar-connections:*:*:connection/*"]
  }

  statement {
    sid    = "CodeStarNotificationsPowerUserAccess"
    effect = "Allow"

    actions = [
      "codestar-notifications:DescribeNotificationRule",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "codestar-notifications:NotificationsForResource"
      values   = ["arn:aws:codebuild:*"]
    }
  }

  statement {
    sid    = "CodeStarNotificationsListAccess"
    effect = "Allow"

    actions = [
      "codestar-notifications:ListNotificationRules",
      "codestar-notifications:ListEventTypes",
      "codestar-notifications:ListTargets",
    ]

    resources = ["*"]
  }
}

# Development

resource "aws_iam_user" "dev_user" {
  name = "DevUser-rwwise.dev"
  path = local.iam_path
  tags = local.common_tags
}

resource "aws_iam_access_key" "dev_user" {
  user   = aws_iam_user.dev_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "dev_cicd_user_policy" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev_user.name
  policy = data.aws_iam_policy_document.cicd_user_policy.json
}

# Testing

resource "aws_iam_user" "test_user" {
  name = "TestUser-rwwise.dev"
  path = local.iam_path
  tags = local.common_tags
}

resource "aws_iam_access_key" "test_user" {
  user   = aws_iam_user.test_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "test_cicd_user_policy" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test_user.name
  policy = data.aws_iam_policy_document.cicd_user_policy.json
}

# Production

resource "aws_iam_user" "prod_user" {
  name = "ProdUser-rwwise.dev"
  path = local.iam_path
  tags = local.common_tags
}

resource "aws_iam_access_key" "prod_user" {
  user   = aws_iam_user.prod_user.name
  status = "Active"
}

resource "aws_iam_user_policy" "prod_cicd_user_policy" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod_user.name
  policy = data.aws_iam_policy_document.cicd_user_policy.json
}

# Outputs

output "dev_user_arn" {
  value = aws_iam_user.dev_user.arn
}

output "dev_user_access_key_id" {
  value = aws_iam_access_key.dev_user.id
}

output "dev_user_secret_access_key" {
  value     = aws_iam_access_key.dev_user.secret
  sensitive = true
}

output "test_user_arn" {
  value = aws_iam_user.test_user.arn
}

output "test_user_access_key_id" {
  value = aws_iam_access_key.test_user.id
}

output "test_user_secret_access_key" {
  value     = aws_iam_access_key.test_user.secret
  sensitive = true
}

output "prod_user_arn" {
  value = aws_iam_user.prod_user.arn
}

output "prod_user_access_key_id" {
  value = aws_iam_access_key.prod_user.id
}

output "prod_user_secret_access_key" {
  value     = aws_iam_access_key.prod_user.secret
  sensitive = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "name" {
  description = "Name of the event processing module. Falls back to \"default\" when null or empty."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "Event bus configuration."
  type = object({
    event_source_name = optional(string, null)
  })
  default = {}

  validation {
    condition     = var.bus != null
    error_message = "The bus variable must not be null."
  }
}

variable "rules" {
  description = "List of EventBridge rules to create."
  type = list(object({
    name                = string
    description         = optional(string, null)
    event_pattern       = optional(string, null)
    schedule_expression = optional(string, null)
  }))
  default = []

  validation {
    condition     = var.rules != null
    error_message = "The rules variable must not be null."
  }
}

variable "targets" {
  description = "List of EventBridge targets to create."
  type = list(object({
    rule      = string
    arn       = string
    target_id = optional(string, null)
  }))
  default = []

  validation {
    condition     = var.targets != null
    error_message = "The targets variable must not be null."
  }
}

data "aws_partition" "current" {}

# Default naming: fall back to "default" when name is null or empty
locals {
  name = var.name == null ? "default" : (trimspace(var.name) == "" ? "default" : var.name)

  create_bus     = local.name != "default"
  event_bus_name = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null

  rules = { for rule in var.rules : rule.name => rule }

  targets = {
    for idx, target in var.targets :
    "${target.rule}-${idx}" => merge(target, { index = idx })
  }
}

resource "aws_cloudwatch_event_bus" "this" {
  count = local.create_bus ? 1 : 0

  name              = local.name
  event_source_name = var.bus.event_source_name
  tags              = var.tags
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.rules

  name                = each.value.name
  description         = each.value.description
  event_pattern       = each.value.event_pattern
  schedule_expression = each.value.schedule_expression
  event_bus_name      = local.event_bus_name
  tags                = var.tags
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

data "aws_iam_policy_document" "invoke_targets" {
  statement {
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "states:StartExecution",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "invoke" {
  name               = "${local.name}-invoke"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "invoke_targets" {
  name   = "${local.name}-invoke-targets"
  role   = aws_iam_role.invoke.id
  policy = data.aws_iam_policy_document.invoke_targets.json
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = local.targets

  rule           = each.value.rule
  arn            = each.value.arn
  target_id      = each.value.target_id
  event_bus_name = local.event_bus_name
  role_arn       = length(regexall("stateMachine", each.value.arn)) > 0 ? aws_iam_role.invoke.arn : null

  depends_on = [aws_cloudwatch_event_rule.this]
}

output "event_bus_name" {
  description = "Name of the custom event bus, or null if the default bus is used."
  value       = local.event_bus_name
}

output "event_bus_arn" {
  description = "ARN of the custom event bus, or null if the default bus is used."
  value       = local.create_bus ? aws_cloudwatch_event_bus.this[0].arn : null
}

output "rule_arns" {
  description = "Map of rule names to ARNs."
  value       = { for k, r in aws_cloudwatch_event_rule.this : k => r.arn }
}

output "invoke_role_arn" {
  description = "ARN of the IAM role used by EventBridge to invoke targets."
  value       = aws_iam_role.invoke.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "name" {
  description = "Name value used to build resource names and the Job tag."
  type        = string
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN used to encrypt the backup vault."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON access policy document for the backup vault. Leave empty to skip."
  type        = string
  default     = ""
}

variable "schedule" {
  description = "CRON expression for the backup rule schedule."
  type        = string
  default     = "cron(0 5 ? * * *)"
}

variable "start_window" {
  description = "Minutes after a backup is scheduled before it is canceled if it has not started."
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Minutes after a backup starts before it is canceled if it has not completed."
  type        = number
  default     = 120
}

variable "cold_storage_after" {
  description = "Days after creation that a recovery point is moved to cold storage."
  type        = number
  default     = 30
}

variable "delete_after" {
  description = "Days after creation that a recovery point is deleted."
  type        = number
  default     = 120
}

variable "destination_vault_arns" {
  description = "Map of copy destinations. Keys are labels, values are destination backup vault ARNs."
  type        = map(string)
  default     = {}
}

variable "selection_tag_type" {
  description = "Operation type used for tag-based resource selection."
  type        = string
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  description = "Tag key used for resource selection."
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value used for resource selection."
  type        = string
  default     = "true"
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN for vault event notifications. Leave empty to skip."
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "Backup vault events that trigger notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

locals {
  job_tag = "${var.name}-backup"
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name_prefix        = "aws-backup-"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = {
    Job = local.job_tag
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_vault" "this" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.kms_key_arn

  tags = {
    Job = local.job_tag
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_plan" "this" {
  name = "plan-${var.name}-backup"

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    dynamic "copy_action" {
      for_each = var.destination_vault_arns

      content {
        destination_vault_arn = copy_action.value

        lifecycle {
          cold_storage_after = var.cold_storage_after
          delete_after       = var.delete_after
        }
      }
    }
  }

  tags = {
    Job = local.job_tag
  }
}

resource "aws_backup_selection" "this" {
  name         = "selection-${var.name}-backup"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id

  condition {}

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_vault_notifications" "this" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_vault_arn" {
  description = "ARN of the backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_vault_name" {
  description = "Name of the backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_plan_id" {
  description = "ID of the backup plan."
  value       = aws_backup_plan.this.id
}

output "backup_selection_id" {
  description = "ID of the backup selection."
  value       = aws_backup_selection.this.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to look up when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name of the Transit Gateway. Used for the Name tag on creation and as a tag:Name filter on lookup."
  type        = string
  default     = null
}

variable "description" {
  description = "Description of the Transit Gateway."
  type        = string
  default     = null
}

variable "asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachment requests are automatically accepted."
  type        = bool
  default     = false
}

variable "dns_support" {
  description = "Whether DNS support is enabled."
  type        = bool
  default     = true
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled."
  type        = bool
  default     = true
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "All entries in transit_gateway_cidr_blocks must be valid IPv4 or IPv6 CIDR blocks."
  }
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up."
  type = map(object({
    create     = optional(bool, true)
    name       = optional(string)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals (account IDs, OU ARNs, or organization ARNs) to share the Transit Gateway with via RAM."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name of the RAM resource share. Defaults to the Transit Gateway name."
  type        = string
  default     = null
}

locals {
  name_tag = var.name != null ? { Name = var.name } : {}

  transit_gateway = var.create ? aws_ec2_transit_gateway.this[0] : data.aws_ec2_transit_gateway.this[0]

  route_tables = {
    for k, v in var.route_tables : k => merge(v, {
      resolved_name = coalesce(v.name, var.name, k)
    })
  }

  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id },
  )

  ram_share_name = coalesce(var.ram_resource_share_name, var.name, "transit-gateway")
}

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description                     = var.description
  amazon_side_asn                 = var.asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments ? "enable" : "disable"
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.dns_support ? "enable" : "disable"
  vpn_ecmp_support                = var.vpn_ecmp_support ? "enable" : "disable"
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = merge(local.name_tag, var.tags)
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null && var.name != null ? [var.name] : []

    content {
      name   = "tag:Name"
      values = [filter.value]
    }
  }
}

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in local.route_tables : k => v if v.create }

  transit_gateway_id = local.transit_gateway.id

  tags = merge(
    { Name = each.value.resolved_name },
    var.tags,
    each.value.local_tags,
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in local.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway.id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.resolved_name]
  }
}

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge({ Name = local.ram_share_name }, var.tags)
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.transit_gateway.arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

output "id" {
  description = "ID of the Transit Gateway."
  value       = local.transit_gateway.id
}

output "arn" {
  description = "ARN of the Transit Gateway."
  value       = local.transit_gateway.arn
}

output "route_table_ids" {
  description = "Map of route table keys to Transit Gateway route table IDs."
  value       = local.route_table_ids
}

output "ram_resource_share_arn" {
  description = "ARN of the RAM resource share, if created."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the backup architecture into"
  type        = string
  default     = "us-east-1"
}

# -----------------------------------------------------------------------------
# Shared KMS key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "backup" {
  description             = "Shared KMS key for AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "backup" {
  name          = "alias/aws-backup-tiered"
  target_key_id = aws_kms_key.backup.key_id
}

# -----------------------------------------------------------------------------
# IAM role for AWS Backup
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "Bronze_Backup_Role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restores" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# -----------------------------------------------------------------------------
# Bronze tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restores,
  ]
}

# -----------------------------------------------------------------------------
# Silver tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restores,
  ]
}

# -----------------------------------------------------------------------------
# Gold tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restores,
  ]
}

# -----------------------------------------------------------------------------
# Premium tier
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restores,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "kms_key_arn" {
  value = aws_kms_key.backup.arn
}

output "backup_role_arn" {
  value = aws_iam_role.backup.arn
}

output "backup_vault_arns" {
  value = {
    bronze  = aws_backup_vault.bronze.arn
    silver  = aws_backup_vault.silver.arn
    gold    = aws_backup_vault.gold.arn
    premium = aws_backup_vault.premium.arn
  }
}

output "backup_plan_ids" {
  value = {
    bronze  = aws_backup_plan.bronze.id
    silver  = aws_backup_plan.silver.id
    gold    = aws_backup_plan.gold.id
    premium = aws_backup_plan.premium.id
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the Prisma Cloud IAM role"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Whether to grant remediation (read-write) permissions"
  type        = bool
  default     = false
}

provider "aws" {
  region = var.aws_region
}

resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::188619942792:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.external_id.result]
    }
  }
}

resource "aws_iam_role" "prisma_cloud" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

data "aws_iam_policy_document" "read_only" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET",
      "cognito-identity:ListTagsForResource",
      "cognito-idp:ListTagsForResource",
      "ecr:DescribeImages",
      "ecr:GetLifecyclePolicy",
      "elasticbeanstalk:ListTagsForResource",
      "elasticfilesystem:DescribeTags",
      "glacier:GetVaultLock",
      "glacier:ListTagsForVault",
      "glue:GetSecurityConfigurations",
      "logs:GetLogEvents",
      "mq:listBrokers",
      "mq:describeBroker",
      "ram:GetResourceShares",
      "secretsmanager:DescribeSecret",
      "ssm:GetParameters",
      "ssm:ListTagsForResource",
      "sqs:SendMessage",
      "elasticmapreduce:ListSecurityConfigurations",
      "sns:listSubscriptions",
      "wafv2:ListResourcesForWebACL",
      "wafv2:ListWebACLs",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud.id
  policy = data.aws_iam_policy_document.read_only.json
}

data "aws_iam_policy_document" "remediation" {
  statement {
    effect = "Allow"
    actions = [
      "iam:UpdateAccountPasswordPolicy",
      "ec2:ModifyImageAttribute",
      "rds:ModifyDBSnapshotAttribute",
      "s3:PutBucketAcl",
      "ec2:RevokeSecurityGroupIngress",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.id
  policy = data.aws_iam_policy_document.remediation.json
}

output "role_arn" {
  description = "ARN of the Prisma Cloud IAM role"
  value       = aws_iam_role.prisma_cloud.arn
}

output "external_id" {
  description = "External ID required to assume the role"
  value       = random_string.external_id.result
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Allow SSH from within the VPC and HTTP from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "development-be-sg"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.25"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Determines whether resources will be created (affects all resources)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

# Topic

variable "name" {
  description = "The name of the SNS topic to create"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether `name` is used as a prefix"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Boolean indicating whether or not to enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "The SNS delivery policy (JSON)"
  type        = string
  default     = null
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK"
  type        = string
  default     = null
}

variable "signature_version" {
  description = "If SignatureVersion should be 1 (SHA1) or 2 (SHA256). Ignored for FIFO topics"
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: `PassThrough`, `Active`"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

# Feedback

variable "application_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback for the application protocol"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "firehose_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback for the Firehose protocol"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "http_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback for the HTTP protocol"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "lambda_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback for the Lambda protocol"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "sqs_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback for the SQS protocol"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

# Topic Policy

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is created"
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "An externally created fully-formed AWS policy as JSON. Used when `create_topic_policy` is false"
  type        = string
  default     = null
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. In merging, statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to enable the default topic policy. Defaults to `true`"
  type        = bool
  default     = true
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statements for custom permission usage"
  type = map(object({
    sid           = optional(string)
    actions       = optional(list(string))
    not_actions   = optional(list(string))
    effect        = optional(string, "Allow")
    resources     = optional(list(string))
    not_resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = {}
}

# Subscriptions

variable "create_subscription" {
  description = "Determines whether an SNS subscription is created"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscription definitions to create"
  type = map(object({
    confirmation_timeout_in_minutes = optional(number)
    delivery_policy                 = optional(string)
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool)
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    protocol                        = string
    raw_message_delivery            = optional(bool)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

# Data Protection Policy

variable "data_protection_policy" {
  description = "A map of data protection policy statements (JSON). Not supported for FIFO topics"
  type        = string
  default     = null
}

################################################################################
# Data
################################################################################

data "aws_caller_identity" "current" {
  count = var.create ? 1 : 0
}

################################################################################
# Topic
################################################################################

locals {
  name = var.name != null && var.fifo_topic ? "${trimsuffix(var.name, ".fifo")}.fifo" : var.name
}

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : local.name
  name_prefix = var.use_name_prefix ? var.name : null

  application_failure_feedback_role_arn    = var.application_feedback.failure_role_arn
  application_success_feedback_role_arn    = var.application_feedback.success_role_arn
  application_success_feedback_sample_rate = var.application_feedback.success_sample_rate

  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic

  firehose_failure_feedback_role_arn    = var.firehose_feedback.failure_role_arn
  firehose_success_feedback_role_arn    = var.firehose_feedback.success_role_arn
  firehose_success_feedback_sample_rate = var.firehose_feedback.success_sample_rate

  http_failure_feedback_role_arn    = var.http_feedback.failure_role_arn
  http_success_feedback_role_arn    = var.http_feedback.success_role_arn
  http_success_feedback_sample_rate = var.http_feedback.success_sample_rate

  kms_master_key_id = var.kms_master_key_id

  lambda_failure_feedback_role_arn    = var.lambda_feedback.failure_role_arn
  lambda_success_feedback_role_arn    = var.lambda_feedback.success_role_arn
  lambda_success_feedback_sample_rate = var.lambda_feedback.success_sample_rate

  policy            = var.create_topic_policy ? null : var.topic_policy
  signature_version = var.fifo_topic ? null : var.signature_version

  sqs_failure_feedback_role_arn    = var.sqs_feedback.failure_role_arn
  sqs_success_feedback_role_arn    = var.sqs_feedback.success_role_arn
  sqs_success_feedback_sample_rate = var.sqs_feedback.success_sample_rate

  tracing_config = var.tracing_config

  tags = var.tags
}

################################################################################
# Topic Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid = "__default_statement_ID"
      actions = [
        "sns:Subscribe",
        "sns:SetTopicAttributes",
        "sns:RemovePermission",
        "sns:Publish",
        "sns:ListSubscriptionsByTopic",
        "sns:GetTopicAttributes",
        "sns:DeleteTopic",
        "sns:AddPermission",
      ]
      effect    = "Allow"
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"
        values   = [data.aws_caller_identity.current[0].account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid           = try(coalesce(statement.value.sid, statement.key), statement.key)
      actions       = statement.value.actions
      not_actions   = statement.value.not_actions
      effect        = statement.value.effect
      resources     = coalesce(statement.value.resources, statement.value.not_resources == null ? [aws_sns_topic.this[0].arn] : null, [])
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Subscription(s)
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = { for k, v in var.subscriptions : k => v if var.create && var.create_subscription }

  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  delivery_policy                 = each.value.delivery_policy
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  protocol                        = each.value.protocol
  raw_message_delivery            = each.value.raw_message_delivery
  redrive_policy                  = each.value.redrive_policy
  subscription_role_arn           = each.value.subscription_role_arn
  topic_arn                       = aws_sns_topic.this[0].arn
}

################################################################################
# Data Protection Policy
################################################################################

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

################################################################################
# Outputs
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS Account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_beginning_archive_time" {
  description = "The oldest timestamp at which a FIFO topic subscriber can start a replay"
  value       = try(aws_sns_topic.this[0].beginning_archive_time, null)
}

output "subscriptions" {
  description = "Map of subscriptions created and their attributes"
  value       = aws_sns_topic_subscription.this
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "bucket_name" {
  description = "Name of the S3 bucket. If null, a name of the form corebucket-<random hex> is generated."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, an extra random string suffix is appended to the resolved bucket name."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Who pays for requests and data transfer. Either BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"

  validation {
    condition     = contains(["BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be either \"BucketOwner\" or \"Requester\"."
  }
}

variable "encryption" {
  description = "Enable default server-side encryption (always aws:kms)."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing KMS key for SSE-KMS. If empty, the module creates a rotating customer-managed key."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket (requires versioning and the mfa variable)."
  type        = bool
  default     = false
}

variable "mfa" {
  description = "Concatenation of the authentication device serial number, a space, and the value displayed on the device. Required when mfa_delete is true."
  type        = string
  default     = null
  sensitive   = true
}

variable "acl" {
  description = "Canned ACL to apply to the bucket. Ignored when grants are supplied."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of ACL grants. Mutually exclusive with acl."
  type = list(object({
    id          = optional(string)
    uri         = optional(string)
    type        = string
    permissions = list(string)
  }))
  default = []
}

variable "policy" {
  description = "JSON bucket policy document."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status. One of Enabled, Suspended, or null to leave unmanaged."
  type        = string
  default     = null

  validation {
    condition     = var.transfer_acceleration == null || contains(["Enabled", "Suspended"], coalesce(var.transfer_acceleration, "Enabled"))
    error_message = "transfer_acceleration must be \"Enabled\", \"Suspended\", or null."
  }
}

variable "logging_bucket" {
  description = "Name of the target bucket for server access logs. Logging is disabled when null."
  type        = string
  default     = null
}

variable "logging_prefix" {
  description = "Key prefix for server access log objects."
  type        = string
  default     = ""
}

variable "website_index_document" {
  description = "Index document suffix for static website hosting."
  type        = string
  default     = null
}

variable "website_error_document" {
  description = "Error document key for static website hosting."
  type        = string
  default     = null
}

variable "website_redirect_all" {
  description = "Redirect all website requests to another host. Mutually exclusive with index/error documents."
  type = object({
    host_name = string
    protocol  = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules."
  type = list(object({
    id                                     = string
    enabled                                = optional(bool, true)
    prefix                                 = optional(string)
    tags                                   = optional(map(string), {})
    expiration_days                        = optional(number)
    expired_object_delete_marker           = optional(bool)
    noncurrent_version_expiration_days     = optional(number)
    abort_incomplete_multipart_upload_days = optional(number)
    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])
    noncurrent_version_transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Object lock configuration. When non-null, object lock is enabled on the bucket. mode may be null to enable object lock without a default retention rule."
  type = object({
    mode  = optional(string)
    days  = optional(number)
    years = optional(number)
  })
  default = null

  validation {
    condition = (
      var.object_lock_configuration == null ||
      try(var.object_lock_configuration.mode, null) == null ||
      contains(["COMPLIANCE", "GOVERNANCE"], try(var.object_lock_configuration.mode, ""))
    )
    error_message = "object_lock_configuration.mode must be \"COMPLIANCE\" or \"GOVERNANCE\"."
  }

  validation {
    condition = (
      var.object_lock_configuration == null ||
      try(var.object_lock_configuration.mode, null) == null ||
      ((try(var.object_lock_configuration.days, null) == null) != (try(var.object_lock_configuration.years, null) == null))
    )
    error_message = "When an object lock mode is set, exactly one of days or years must be specified."
  }
}

variable "replication_role" {
  description = "ARN of an existing IAM role for replication. If null and replication_rules are supplied, a role is created."
  type        = string
  default     = null
}

variable "replication_rules" {
  description = "List of cross-region replication rules."
  type = list(object({
    id                        = string
    priority                  = optional(number)
    status                    = optional(string, "Enabled")
    prefix                    = optional(string)
    tags                      = optional(map(string), {})
    delete_marker_replication = optional(bool, false)
    destination_bucket        = string
    destination_storage_class = optional(string)
    destination_account_id    = optional(string)
    replica_kms_key_id        = optional(string)
  }))
  default = []
}

################################################################################
# Naming
################################################################################

resource "random_id" "bucket" {
  count       = var.bucket_name == null ? 1 : 0
  byte_length = 4
}

resource "random_string" "suffix" {
  count   = var.prefix ? 1 : 0
  length  = 8
  upper   = false
  special = false
}

locals {
  base_bucket_name = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket[0].hex}"
  bucket_name      = var.prefix ? "${local.base_bucket_name}-${random_string.suffix[0].result}" : local.base_bucket_name

  create_kms_key = var.encryption && var.kms_key == ""
  kms_key_arn    = var.encryption ? (var.kms_key != "" ? var.kms_key : aws_kms_key.this[0].arn) : null

  object_lock_enabled = var.object_lock_configuration != null
  object_lock_rule    = local.object_lock_enabled ? try(var.object_lock_configuration.mode, null) != null : false

  replication_enabled     = length(var.replication_rules) > 0
  create_replication_role = local.replication_enabled && var.replication_role == null
  replication_role_arn    = local.replication_enabled ? (var.replication_role != null ? var.replication_role : aws_iam_role.replication[0].arn) : null

  versioning_enabled = var.versioning || local.replication_enabled || local.object_lock_enabled

  website_enabled = var.website_index_document != null || var.website_redirect_all != null

  acl_enabled = var.acl != null || length(var.grants) > 0

  replica_kms_key_ids = distinct(compact([for r in var.replication_rules : r.replica_kms_key_id]))
}

################################################################################
# KMS
################################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "KMS key for S3 bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = var.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/s3-${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = local.object_lock_enabled

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = local.acl_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

data "aws_canonical_user_id" "current" {}

resource "aws_s3_bucket_acl" "this" {
  count  = local.acl_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  acl = length(var.grants) == 0 ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = flatten([
          for g in var.grants : [
            for p in g.permissions : {
              id         = g.id
              uri        = g.uri
              type       = g.type
              permission = p
            }
          ]
        ])

        content {
          permission = grant.value.permission

          grantee {
            type = grant.value.type
            id   = grant.value.id
            uri  = grant.value.uri
          }
        }
      }

      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_versioning" "this" {
  count  = local.versioning_enabled || var.mfa_delete ? 1 : 0
  bucket = aws_s3_bucket.this.id
  mfa    = var.mfa_delete ? var.mfa : null

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.transfer_acceleration != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = var.logging_prefix
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = local.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all != null ? [var.website_redirect_all] : []

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = redirect_all_requests_to.value.protocol
    }
  }

  dynamic "index_document" {
    for_each = var.website_redirect_all == null && var.website_index_document != null ? [var.website_index_document] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website_redirect_all == null && var.website_error_document != null ? [var.website_error_document] : []

    content {
      key = error_document.value
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        prefix = length(rule.value.tags) == 0 ? coalesce(rule.value.prefix, "") : null

        dynamic "and" {
          for_each = length(rule.value.tags) > 0 ? [1] : []

          content {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null || rule.value.expired_object_delete_marker != null ? [1] : []

        content {
          days                         = rule.value.expiration_days
          expired_object_delete_marker = rule.value.expiration_days == null ? rule.value.expired_object_delete_marker : null
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [rule.value.noncurrent_version_expiration_days] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.object_lock_rule ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = try(var.object_lock_configuration.days, null)
      years = try(var.object_lock_configuration.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Replication
################################################################################

data "aws_iam_policy_document" "replication_assume" {
  count = local.create_replication_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name               = "CoreS3ReplicationRole_${local.bucket_name}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume[0].json

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_replication_role ? 1 : 0

  statement {
    sid    = "SourceBucket"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "SourceObjects"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold",
    ]
    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    sid    = "DestinationObjects"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]
    resources = distinct([for r in var.replication_rules : "${r.destination_bucket}/*"])
  }

  dynamic "statement" {
    for_each = local.kms_key_arn != null ? [local.kms_key_arn] : []

    content {
      sid       = "SourceKmsDecrypt"
      effect    = "Allow"
      actions   = ["kms:Decrypt"]
      resources = [statement.value]
    }
  }

  dynamic "statement" {
    for_each = length(local.replica_kms_key_ids) > 0 ? [local.replica_kms_key_ids] : []

    content {
      sid       = "DestinationKmsEncrypt"
      effect    = "Allow"
      actions   = ["kms:Encrypt", "kms:GenerateDataKey"]
      resources = statement.value
    }
  }
}

resource "aws_iam_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name   = "CoreS3ReplicationPolicy_${local.bucket_name}"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_replication_role ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = local.replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      filter {
        prefix = length(rule.value.tags) == 0 ? coalesce(rule.value.prefix, "") : null

        dynamic "and" {
          for_each = length(rule.value.tags) > 0 ? [1] : []

          content {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.replica_kms_key_id != null ? [1] : []

        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }

      destination {
        bucket        = rule.value.destination_bucket
        storage_class = rule.value.destination_storage_class
        account       = rule.value.destination_account_id

        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_key_id != null ? [rule.value.replica_kms_key_id] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "access_control_translation" {
          for_each = rule.value.destination_account_id != null ? [1] : []

          content {
            owner = "Destination"
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_iam_role_policy_attachment.replication,
  ]
}

################################################################################
# Outputs
################################################################################

output "bucket_id" {
  description = "Name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Bucket region-specific domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for bucket encryption."
  value       = local.kms_key_arn
}

output "website_endpoint" {
  description = "Website endpoint, if website hosting is configured."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "replication_role_arn" {
  description = "ARN of the IAM role used for replication."
  value       = local.replication_role_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

variable "random_suffix" {
  description = "Whether to append a random lowercase alphanumeric suffix to resource names."
  type        = bool
  default     = true
}

variable "random_suffix_length" {
  description = "Length of the random suffix."
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name" {
  description = "Base name of the IAM user."
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name of the IAM policy."
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload the local image file to the S3 bucket."
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Name of the local image file in the execution directory."
  type        = string
  default     = "my-file.qcow2"
}

variable "create_folder" {
  description = "Whether to prefix the uploaded object key with s3_folder."
  type        = bool
  default     = true
}

variable "s3_folder" {
  description = "Folder (key prefix) for the uploaded image."
  type        = string
  default     = "my-folder"
}

variable "create_iam_user" {
  description = "Whether to create the IAM user, access key, and read-only policy."
  type        = bool
  default     = true
}

resource "random_string" "suffix" {
  count = var.random_suffix ? 1 : 0

  length  = var.random_suffix_length
  special = false
  upper   = false
  lower   = true
  numeric = true
}

locals {
  suffix          = var.random_suffix ? "-${random_string.suffix[0].result}" : ""
  bucket_name     = "${var.bucket_name}${local.suffix}"
  iam_user_name   = "${var.iam_user_name}${local.suffix}"
  iam_policy_name = "${var.iam_policy_name}${local.suffix}"
  image_key       = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

resource "aws_kms_key" "s3" {
  description             = "Customer-managed KMS key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = "${local.bucket_name}-kms"
  }
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.bucket_name}-s3"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket" "datastore" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "datastore" {
  bucket = aws_s3_bucket.datastore.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "datastore" {
  bucket = aws_s3_bucket.datastore.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_object" "image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.datastore.id
  key    = local.image_key
  source = "${path.cwd}/${var.image_filename}"
  etag   = filemd5("${path.cwd}/${var.image_filename}")

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.datastore,
    aws_s3_bucket_public_access_block.datastore,
  ]
}

resource "aws_iam_user" "s3_user" {
  count = var.create_iam_user ? 1 : 0

  name          = local.iam_user_name
  path          = "/"
  force_destroy = true

  tags = {
    Name = local.iam_user_name
  }
}

resource "aws_iam_access_key" "s3_user" {
  count = var.create_iam_user ? 1 : 0

  user   = aws_iam_user.s3_user[0].name
  status = "Active"
}

data "aws_iam_policy_document" "s3_read" {
  statement {
    sid       = "ReadObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.datastore.arn}/*"]
  }

  statement {
    sid       = "ListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.datastore.arn]
  }

  # Required to read objects encrypted with the customer-managed KMS key.
  statement {
    sid       = "DecryptObjects"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.s3.arn]
  }
}

resource "aws_iam_policy" "s3_read" {
  count = var.create_iam_user ? 1 : 0

  name        = local.iam_policy_name
  path        = "/"
  description = "Read-only access to S3 bucket ${local.bucket_name}"
  policy      = data.aws_iam_policy_document.s3_read.json
}

resource "aws_iam_user_policy_attachment" "s3_read" {
  count = var.create_iam_user ? 1 : 0

  user       = aws_iam_user.s3_user[0].name
  policy_arn = aws_iam_policy.s3_read[0].arn
}

output "bucket_name" {
  description = "Resolved S3 bucket name."
  value       = aws_s3_bucket.datastore.id
}

output "bucket_arn" {
  description = "S3 bucket ARN."
  value       = aws_s3_bucket.datastore.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for bucket encryption."
  value       = aws_kms_key.s3.arn
}

output "image_key" {
  description = "S3 key of the uploaded image, if uploaded."
  value       = var.upload_image ? aws_s3_object.image[0].key : null
}

output "iam_user_name" {
  description = "Name of the IAM user, if created."
  value       = var.create_iam_user ? aws_iam_user.s3_user[0].name : null
}

output "iam_access_key_id" {
  description = "Access key ID for the IAM user, if created."
  value       = var.create_iam_user ? aws_iam_access_key.s3_user[0].id : null
}

output "iam_secret_access_key" {
  description = "Secret access key for the IAM user, if created."
  value       = var.create_iam_user ? aws_iam_access_key.s3_user[0].secret : null
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "eu-central-1"
}

variable "default_tags" {
  description = "Default tags applied to all resources via the provider"
  type        = map(string)
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC"
  type        = string
  default     = "10.14.0.0/16"
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.default_tags
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}"
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
  az_count    = length(local.azs)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name                     = "${local.name_prefix}-public-${local.azs[count.index]}"
    "kubernetes.io/role/elb" = "1"
  }
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = local.azs[count.index]
  cidr_block        = cidrsubnet(var.vpc_cidr, 4, count.index + local.az_count)

  tags = {
    Name                              = "${local.name_prefix}-private-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name_prefix}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  description = "ID of the main VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = aws_nat_gateway.main.id
}

output "nat_public_ip" {
  description = "Public IP of the NAT gateway"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region in which to create the bucket."
  type        = string
  default     = "us-east-1"
}

variable "create_bucket" {
  description = "Controls whether the S3 bucket and related resources should be created."
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the bucket. If omitted, Terraform assigns a random unique name (or uses bucket_prefix)."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned ACL to apply. Ignored when grant is set."
  type        = string
  default     = "private"
}

variable "grant" {
  description = "List of ACL policy grants. Each item: { type, permission, id, uri, email }."
  type        = any
  default     = []
}

variable "owner" {
  description = "Bucket owner for the ACL access control policy. Map with id (and optional display_name)."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket so it can be destroyed without error."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to assign to the bucket and related resources."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration state of the bucket. Valid values: Enabled, Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Who pays for download and request fees. Valid values: BucketOwner, Requester."
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter."
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Static website hosting configuration: index_document, error_document, redirect_all_requests_to, routing_rules."
  type        = any
  default     = {}
}

variable "cors_rule" {
  description = "List of CORS rules."
  type        = any
  default     = []
}

variable "versioning" {
  description = "Versioning configuration: enabled/status, mfa_delete, mfa."
  type        = any
  default     = {}
}

variable "logging" {
  description = "Access logging configuration: target_bucket, target_prefix, target_grant, target_object_key_format."
  type        = any
  default     = {}
}

variable "lifecycle_rule" {
  description = "List of object lifecycle rules."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration: role and rules."
  type        = any
  default     = {}
}

variable "server_side_encryption_configuration" {
  description = "Server-side encryption configuration. When empty, a customer-managed KMS key is created and used."
  type        = any
  default     = {}
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object Lock configuration: { token, rule = { default_retention = { mode, days, years } } }."
  type        = any
  default     = {}
}

variable "attach_elb_log_delivery_policy" {
  description = "Whether to attach a policy allowing Classic ELB log delivery."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Whether to attach a policy allowing ALB/NLB log delivery."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Whether to attach a policy denying non-SSL transport."
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Whether to attach the custom bucket policy supplied in policy."
  type        = bool
  default     = false
}

variable "policy" {
  description = "Custom bucket policy JSON document."
  type        = string
  default     = null
}

variable "attach_public_policy" {
  description = "Whether to manage the S3 public access block for this bucket."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

################################################################################
# Locals and data sources
################################################################################

locals {
  create_bucket = var.create_bucket

  create_kms_key = local.create_bucket && length(keys(var.server_side_encryption_configuration)) == 0

  create_acl = local.create_bucket && (var.acl != null || length(var.grant) > 0) && !(var.control_object_ownership && var.object_ownership == "BucketOwnerEnforced")

  attach_policy = local.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    var.attach_policy
  )

  sse_rule = try(var.server_side_encryption_configuration.rule, {})
}

data "aws_canonical_user_id" "this" {}

data "aws_elb_service_account" "this" {
  count = local.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket              = var.bucket
  bucket_prefix       = var.bucket == null ? var.bucket_prefix : null
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

################################################################################
# Ownership controls and ACL
################################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = length(var.grant) == 0 ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grant) > 0 ? [true] : []

    content {
      dynamic "grant" {
        for_each = var.grant

        content {
          permission = grant.value.permission

          grantee {
            type          = grant.value.type
            id            = try(grant.value.id, null)
            uri           = try(grant.value.uri, null)
            email_address = try(grant.value.email, null)
          }
        }
      }

      owner {
        id           = try(var.owner["id"], data.aws_canonical_user_id.this.id)
        display_name = try(var.owner["display_name"], null)
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

################################################################################
# Acceleration and request payment
################################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = title(lower(var.acceleration_status))
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = lower(var.request_payer) == "requester" ? "Requester" : "BucketOwner"
}

################################################################################
# Website
################################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(keys(var.website)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) == null ? [] : [var.website.index_document]

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) == null ? [] : [var.website.error_document]

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) == null ? [] : [var.website.redirect_all_requests_to]

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  routing_rules = can(tostring(var.website.routing_rules)) ? var.website.routing_rules : null

  dynamic "routing_rule" {
    for_each = can(tostring(var.website.routing_rules)) ? [] : try(flatten([var.website.routing_rules]), [])

    content {
      dynamic "condition" {
        for_each = try(routing_rule.value.condition, null) == null ? [] : [routing_rule.value.condition]

        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

################################################################################
# CORS
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule

    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

################################################################################
# Versioning
################################################################################

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(keys(var.versioning)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  mfa    = try(var.versioning.mfa, null)

  versioning_configuration {
    status = try(
      var.versioning.enabled ? "Enabled" : "Suspended",
      tobool(var.versioning.status) ? "Enabled" : "Suspended",
      title(lower(var.versioning.status))
    )

    mfa_delete = try(
      tobool(var.versioning.mfa_delete) ? "Enabled" : "Disabled",
      title(lower(var.versioning.mfa_delete)),
      null
    )
  }
}

################################################################################
# Access logging
################################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(keys(var.logging)) > 0 ? 1 : 0

  bucket        = aws_s3_bucket.this[0].id
  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, "")

  dynamic "target_grant" {
    for_each = try(var.logging.target_grant, [])

    content {
      permission = target_grant.value.permission

      grantee {
        type          = target_grant.value.type
        id            = try(target_grant.value.id, null)
        uri           = try(target_grant.value.uri, null)
        email_address = try(target_grant.value.email, null)
      }
    }
  }

  dynamic "target_object_key_format" {
    for_each = try(var.logging.target_object_key_format, null) == null ? [] : [var.logging.target_object_key_format]

    content {
      dynamic "partitioned_prefix" {
        for_each = try(target_object_key_format.value.partitioned_prefix, null) == null ? [] : [target_object_key_format.value.partitioned_prefix]

        content {
          partition_date_source = try(partitioned_prefix.value.partition_date_source, "EventTime")
        }
      }

      dynamic "simple_prefix" {
        for_each = try(target_object_key_format.value.simple_prefix, null) == null ? [] : [true]

        content {}
      }
    }
  }
}

################################################################################
# Lifecycle
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = (
          length(try(rule.value.filter.tags, {})) > 0 ||
          try(rule.value.filter.object_size_greater_than, null) != null ||
          try(rule.value.filter.object_size_less_than, null) != null
        ) ? [] : [try(rule.value.filter, {})]

        content {
          prefix = try(filter.value.prefix, try(rule.value.prefix, null))
        }
      }

      dynamic "filter" {
        for_each = (
          length(try(rule.value.filter.tags, {})) > 0 ||
          try(rule.value.filter.object_size_greater_than, null) != null ||
          try(rule.value.filter.object_size_less_than, null) != null
        ) ? [rule.value.filter] : []

        content {
          and {
            prefix                   = try(filter.value.prefix, null)
            tags                     = try(filter.value.tags, null)
            object_size_greater_than = try(filter.value.object_size_greater_than, null)
            object_size_less_than    = try(filter.value.object_size_less_than, null)
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) == null ? [] : [rule.value.abort_incomplete_multipart_upload_days]

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) == null ? [] : [rule.value.expiration]

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(flatten([rule.value.transition]), [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) == null ? [] : [rule.value.noncurrent_version_expiration]

        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, noncurrent_version_expiration.value.days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(flatten([rule.value.noncurrent_version_transition]), [])

        content {
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, noncurrent_version_transition.value.days, null)
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Cross-region replication
################################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && length(keys(var.replication_configuration)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role

  dynamic "rule" {
    for_each = var.replication_configuration.rules

    content {
      id       = try(rule.value.id, null)
      priority = try(rule.value.priority, null)
      prefix   = try(rule.value.filter, null) == null ? try(rule.value.prefix, null) : null
      status = try(
        tobool(rule.value.status) ? "Enabled" : "Disabled",
        title(lower(rule.value.status)),
        "Enabled"
      )

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) == null ? [] : [rule.value.delete_marker_replication]

        content {
          status = try(tobool(delete_marker_replication.value), false) ? "Enabled" : "Disabled"
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.filter, null) == null ? [] : [rule.value.filter]

        content {
          prefix = length(try(filter.value.tags, {})) == 0 ? try(filter.value.prefix, null) : null

          dynamic "and" {
            for_each = length(try(filter.value.tags, {})) > 0 ? [true] : []

            content {
              prefix = try(filter.value.prefix, null)
              tags   = filter.value.tags
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account_id, null)

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation, null) == null ? [] : [rule.value.destination.access_control_translation]

          content {
            owner = title(lower(access_control_translation.value.owner))
          }
        }

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) == null ? [] : [rule.value.destination.replica_kms_key_id]

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) == null ? [] : [rule.value.destination.replication_time]

          content {
            status = try(tobool(replication_time.value.status) ? "Enabled" : "Disabled", title(lower(replication_time.value.status)), "Enabled")

            time {
              minutes = try(replication_time.value.minutes, 15)
            }
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) == null ? [] : [rule.value.destination.metrics]

          content {
            status = try(tobool(metrics.value.status) ? "Enabled" : "Disabled", title(lower(metrics.value.status)), "Enabled")

            event_threshold {
              minutes = try(metrics.value.minutes, 15)
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) == null ? [] : [rule.value.source_selection_criteria]

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) == null ? [] : [source_selection_criteria.value.sse_kms_encrypted_objects]

            content {
              status = try(tobool(sse_kms_encrypted_objects.value.enabled), false) ? "Enabled" : "Disabled"
            }
          }

          dynamic "replica_modifications" {
            for_each = try(source_selection_criteria.value.replica_modifications, null) == null ? [] : [source_selection_criteria.value.replica_modifications]

            content {
              status = try(tobool(replica_modifications.value.enabled), false) ? "Enabled" : "Disabled"
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Server-side encryption
################################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "KMS key for default SSE-KMS encryption of S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = var.tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    bucket_key_enabled = local.create_kms_key ? true : try(local.sse_rule.bucket_key_enabled, null)

    apply_server_side_encryption_by_default {
      sse_algorithm     = local.create_kms_key ? "aws:kms" : local.sse_rule.apply_server_side_encryption_by_default.sse_algorithm
      kms_master_key_id = local.create_kms_key ? aws_kms_key.this[0].arn : try(local.sse_rule.apply_server_side_encryption_by_default.kms_master_key_id, null)
    }
  }
}

################################################################################
# Object Lock
################################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_enabled && try(var.object_lock_configuration.rule.default_retention, null) != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  token  = try(var.object_lock_configuration.token, null)

  rule {
    default_retention {
      mode  = var.object_lock_configuration.rule.default_retention.mode
      days  = try(var.object_lock_configuration.rule.default_retention.days, null)
      years = try(var.object_lock_configuration.rule.default_retention.years, null)
    }
  }
}

################################################################################
# Bucket policy
################################################################################

data "aws_iam_policy_document" "elb_log_delivery" {
  count = local.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid     = "ELBLogDelivery"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.this[0].arn]
    }

    resources = ["${aws_s3_bucket.this[0].arn}/*"]
  }
}

data "aws_iam_policy_document" "lb_log_delivery" {
  count = local.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid     = "AWSLogDeliveryWrite"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    principals {
      type = "Service"
      identifiers = [
        "delivery.logs.amazonaws.com",
        "logdelivery.elasticloadbalancing.amazonaws.com",
      ]
    }

    resources = ["${aws_s3_bucket.this[0].arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid     = "AWSLogDeliveryAclCheck"
    effect  = "Allow"
    actions = ["s3:GetBucketAcl"]

    principals {
      type = "Service"
      identifiers = [
        "delivery.logs.amazonaws.com",
        "logdelivery.elasticloadbalancing.amazonaws.com",
      ]
    }

    resources = [aws_s3_bucket.this[0].arn]
  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = local.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "combined" {
  count = local.attach_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_policy && var.policy != null ? var.policy : "",
  ])
}

resource "aws_s3_bucket_policy" "this" {
  count = local.attach_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# Public access block
################################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket && var.attach_public_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

################################################################################
# Outputs
################################################################################

output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = try(aws_s3_bucket.this[0].id, "")
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket."
  value       = try(aws_s3_bucket.this[0].arn, "")
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name."
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, "")
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = try(aws_s3_bucket.this[0].bucket_regional_domain_name, "")
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 hosted zone ID for this bucket's region."
  value       = try(aws_s3_bucket.this[0].hosted_zone_id, "")
}

output "s3_bucket_region" {
  description = "The AWS region this bucket resides in."
  value       = try(aws_s3_bucket.this[0].region, "")
}

output "s3_bucket_website_endpoint" {
  description = "The website endpoint, if the bucket is configured with a website."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, "")
}

output "s3_bucket_website_domain" {
  description = "The domain of the website endpoint, if the bucket is configured with a website."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_domain, "")
}

output "s3_bucket_policy" {
  description = "The policy attached to the bucket."
  value       = try(aws_s3_bucket_policy.this[0].policy, "")
}

output "kms_key_arn" {
  description = "ARN of the module-managed KMS key used for default bucket encryption."
  value       = try(aws_kms_key.this[0].arn, "")
}

output "kms_key_id" {
  description = "ID of the module-managed KMS key used for default bucket encryption."
  value       = try(aws_kms_key.this[0].key_id, "")
}

terraform {
  required_version = ">= 0.14.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.awsRegion
}

############################ Variables ############################

variable "projectPrefix" {
  type        = string
  default     = "f5-dcec"
  description = "projectPrefix name for tagging"
}

variable "resourceOwner" {
  type        = string
  default     = "f5-user"
  description = "Owner of the deployment for tagging purposes"
}

variable "buildSuffix" {
  type        = string
  default     = "YY"
  description = "Suffix to append to resource names for uniqueness"
}

variable "map_public_ip_on_launch" {
  type        = bool
  default     = false
  description = "Whether instances launched in public subnets receive a public IP"
}

variable "awsRegion" {
  type        = string
  default     = "us-east-1"
  description = "AWS region"
}

variable "awsAz1" {
  type        = string
  default     = null
  description = "Availability zone 1; defaults to the first available AZ in the region"
}

variable "awsAz2" {
  type        = string
  default     = null
  description = "Availability zone 2; defaults to the second available AZ in the region"
}

variable "vpcMainCidr" {
  type        = string
  default     = "10.1.0.0/16"
  description = "CIDR block for the main VPC"
}

variable "vpcMainSubPubACidr" {
  type        = string
  default     = "10.1.10.0/24"
  description = "CIDR block for public subnet A"
}

variable "vpcMainSubPubBCidr" {
  type        = string
  default     = "10.1.110.0/24"
  description = "CIDR block for public subnet B"
}

variable "vpcMainSubMgmtACidr" {
  type        = string
  default     = "10.1.1.0/24"
  description = "CIDR block for management subnet A"
}

variable "vpcMainSubMgmtBCidr" {
  type        = string
  default     = "10.1.101.0/24"
  description = "CIDR block for management subnet B"
}

variable "vpcMainSubPrivACidr" {
  type        = string
  default     = "10.1.20.0/24"
  description = "CIDR block for private subnet A"
}

variable "vpcMainSubPrivBCidr" {
  type        = string
  default     = "10.1.120.0/24"
  description = "CIDR block for private subnet B"
}

############################ Locals ############################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  awsAz1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  # Per requirement: when awsAz2 is specified, it falls back to referencing awsAz1
  awsAz2 = var.awsAz2 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
}

############################ VPC ############################

resource "aws_vpc" "vpcMain" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name  = "${var.projectPrefix}-vpcMain-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

############################ Subnets ############################

resource "aws_subnet" "vpcMainSubPubA" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.awsAz1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPubB" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.awsAz2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

############################ Internet Gateway ############################

resource "aws_internet_gateway" "vpcMainIgw" {
  vpc_id = aws_vpc.vpcMain.id

  tags = {
    Name  = "${var.projectPrefix}-vpcMainIgw-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

############################ Route Table ############################

resource "aws_route_table" "vpcMainRtb" {
  vpc_id = aws_vpc.vpcMain.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpcMainIgw.id
  }

  tags = {
    Name  = "${var.projectPrefix}-vpcMainRtb-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_main_route_table_association" "vpcMainRtbAssoc" {
  vpc_id         = aws_vpc.vpcMain.id
  route_table_id = aws_route_table.vpcMainRtb.id
}

############################ Outputs ############################

output "vpcMainId" {
  value = aws_vpc.vpcMain.id
}

output "vpcMainSubPubAId" {
  value = aws_subnet.vpcMainSubPubA.id
}

output "vpcMainSubPubBId" {
  value = aws_subnet.vpcMainSubPubB.id
}

output "vpcMainSubMgmtAId" {
  value = aws_subnet.vpcMainSubMgmtA.id
}

output "vpcMainSubMgmtBId" {
  value = aws_subnet.vpcMainSubMgmtB.id
}

output "vpcMainSubPrivAId" {
  value = aws_subnet.vpcMainSubPrivA.id
}

output "vpcMainSubPrivBId" {
  value = aws_subnet.vpcMainSubPrivB.id
}

output "vpcMainIgwId" {
  value = aws_internet_gateway.vpcMainIgw.id
}

output "vpcMainRtbId" {
  value = aws_route_table.vpcMainRtb.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "resource_name" {
  description = "Name used for all named resources."
  type        = string
  default     = "benchmark"
}

variable "resource_count" {
  description = "Number of path-based listener rules to create."
  type        = number
  default     = 1

  validation {
    condition     = var.resource_count >= 0
    error_message = "resource_count must be zero or greater."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_subnet" "this" {
  count = length(local.azs)

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.resource_name}-${count.index}"
  }
}

resource "aws_security_group" "alb" {
  name        = var.resource_name
  description = "Allow all traffic within the VPC CIDR"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "All traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic to within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = var.resource_name
  }
}

resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "this" {
  private_key_pem = tls_private_key.this.private_key_pem

  subject {
    common_name  = "${var.resource_name}.internal"
    organization = var.resource_name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "this" {
  private_key      = tls_private_key.this.private_key_pem
  certificate_body = tls_self_signed_cert.this.cert_pem

  tags = {
    Name = var.resource_name
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "this" {
  name                       = var.resource_name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.this[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_target_group" "this" {
  name        = var.resource_name
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.this.id
  target_type = "instance"

  health_check {
    enabled             = true
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.this.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-3-2021-06"
  certificate_arn   = aws_acm_certificate.this.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_listener_rule" "static" {
  count = var.resource_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.resource_name}-${count.index}"
  }
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "subnet_ids" {
  value = aws_subnet.this[*].id
}

output "alb_arn" {
  value = aws_lb.this.arn
}

output "alb_dns_name" {
  value = aws_lb.this.dns_name
}

output "target_group_arn" {
  value = aws_lb_target_group.this.arn
}

output "https_listener_arn" {
  value = aws_lb_listener.https.arn
}

output "listener_rule_arns" {
  value = aws_lb_listener_rule.static[*].arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy the CloudTrail resources into"
  type        = string
  default     = "us-east-1"
}

variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "management_trail"
}

variable "is_organization_trail" {
  description = "Whether the trail is an AWS Organizations trail"
  type        = bool
  default     = false
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group that receives CloudTrail events"
  type        = string
  default     = "cloudtrail_logs"
}

variable "enable_kms_encryption" {
  description = "Whether to create and use a customer managed KMS key for CloudTrail and the log bucket"
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias for the CloudTrail KMS key"
  type        = string
  default     = "alias/cloudtrail_key"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id    = data.aws_caller_identity.current.account_id
  partition     = data.aws_partition.current.partition
  region        = data.aws_region.current.name
  trail_arn     = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"
  kms_key_arn   = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null
  bucket_name   = "cloudtrail-bucket-${random_string.bucket_suffix.result}"
  root_arn      = "arn:${local.partition}:iam::${local.account_id}:root"
  cloudtrail_ec = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"
}

################################################################################
# KMS
################################################################################

data "aws_iam_policy_document" "kms" {
  count = var.enable_kms_encryption ? 1 : 0

  statement {
    sid       = "EnableRootAndCallerAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type = "AWS"
      identifiers = distinct([
        local.root_arn,
        data.aws_caller_identity.current.arn,
      ])
    }
  }

  statement {
    sid       = "AllowCloudTrailToEncryptLogs"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey*"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = [local.cloudtrail_ec]
    }
  }

  statement {
    sid       = "AllowCloudTrailToDescribeKey"
    effect    = "Allow"
    actions   = ["kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowS3ToUseKeyForBucketEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowAccountToDecryptLogFiles"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:ReEncryptFrom",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = [local.cloudtrail_ec]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "Customer managed key for CloudTrail logs and the CloudTrail S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

################################################################################
# S3 bucket
################################################################################

resource "random_string" "bucket_suffix" {
  length  = 12
  special = false
  upper   = false
  lower   = false
  numeric = true
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket = local.bucket_name
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = var.enable_kms_encryption
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

################################################################################
# CloudWatch Logs
################################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 0
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid    = "AWSCloudTrailCreateLogStreamAndPutLogEvents"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch.json
}

################################################################################
# CloudTrail
################################################################################

resource "aws_cloudtrail" "this" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  is_multi_region_trail         = true
  include_global_service_events = true
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = local.kms_key_arn

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch.arn

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_s3_bucket_server_side_encryption_configuration.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch,
  ]
}

################################################################################
# Outputs
################################################################################

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail"
  value       = aws_cloudtrail.this.arn
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket receiving CloudTrail logs"
  value       = aws_s3_bucket.cloudtrail.id
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch Log Group receiving CloudTrail events"
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "kms_key_arn" {
  description = "ARN of the CloudTrail KMS key (null when KMS encryption is disabled)"
  value       = local.kms_key_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "namespace" {
  description = "Optional namespace prefix for the repository name."
  type        = string
  default     = ""
}

variable "name" {
  description = "Repository name. When null or empty, a petname is generated (frigga naming)."
  type        = string
  default     = "ecr"
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the repository. Must be MUTABLE or IMMUTABLE."
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either \"MUTABLE\" or \"IMMUTABLE\"."
  }
}

variable "scan_on_push" {
  description = "Whether images are scanned after being pushed to the repository."
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "Lifecycle policy JSON document. No lifecycle policy is created when null."
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "Additional AWS account IDs granted read access to the repository."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags to apply to resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_pet" "name" {
  count = var.name == null || var.name == "" ? 1 : 0

  length    = 2
  separator = "-"
}

locals {
  base_name = var.name == null || var.name == "" ? random_pet.name[0].id : var.name

  namespace = var.namespace == null ? "" : var.namespace

  name = local.namespace == "" ? local.base_name : "${local.namespace}/${local.base_name}"

  # IAM policy names may not contain "/", so flatten the repository path.
  policy_name_prefix = replace(local.name, "/", "-")

  account_ids = distinct(concat([data.aws_caller_identity.current.account_id], var.trusted_accounts))

  tags = merge(
    var.tags,
    {
      "terraform.io" = "managed"
      "Name"         = local.name
    }
  )
}

resource "aws_ecr_repository" "this" {
  name                 = local.name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = local.tags
}

resource "aws_ecr_lifecycle_policy" "this" {
  count = var.lifecycle_policy != null ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

data "aws_iam_policy_document" "read" {
  statement {
    sid    = "ECRRead"
    effect = "Allow"

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]

    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "read" {
  name        = "${local.policy_name_prefix}-ecr-read"
  description = "Read access to the ${local.name} ECR repository."
  policy      = data.aws_iam_policy_document.read.json

  tags = local.tags
}

data "aws_iam_policy_document" "write" {
  statement {
    sid    = "ECRWrite"
    effect = "Allow"

    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload",
    ]

    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "write" {
  name        = "${local.policy_name_prefix}-ecr-write"
  description = "Write access to the ${local.name} ECR repository."
  policy      = data.aws_iam_policy_document.write.json

  tags = local.tags
}

data "aws_iam_policy_document" "repository" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [for id in local.account_ids : "arn:${data.aws_partition.current.partition}:iam::${id}:root"]
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.repository.json
}

output "repository_name" {
  description = "Name of the ECR repository."
  value       = aws_ecr_repository.this.name
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "repository_url" {
  description = "URL of the ECR repository."
  value       = aws_ecr_repository.this.repository_url
}

output "read_policy_arn" {
  description = "ARN of the IAM read policy."
  value       = aws_iam_policy.read.arn
}

output "write_policy_arn" {
  description = "ARN of the IAM write policy."
  value       = aws_iam_policy.write.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix applied to all resources"
  type        = string
  default     = "multi-tier"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "az_count" {
  description = "Number of availability zones to spread subnets across"
  type        = number
  default     = 2

  validation {
    condition     = var.az_count >= 1
    error_message = "az_count must be at least 1."
  }
}

variable "enable_public_subnets" {
  description = "Create public subnets, Internet Gateway, public route table and security group"
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Create NAT tier subnets"
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Create private tier subnets"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags applied to all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = slice(
    data.aws_availability_zones.available.names,
    0,
    min(var.az_count, length(data.aws_availability_zones.available.names))
  )
  az_count = length(local.az_names)

  public_subnet_count  = var.enable_public_subnets ? local.az_count : 0
  nat_subnet_count     = var.enable_nat_subnets ? local.az_count : 0
  private_subnet_count = var.enable_private_subnets ? local.az_count : 0

  total_subnet_count = local.public_subnet_count + local.nat_subnet_count + local.private_subnet_count

  # Number of additional bits needed to fit every active subnet into the VPC CIDR
  subnet_newbits = ceil(log(max(local.total_subnet_count, 2), 2))

  public_offset  = 0
  nat_offset     = local.public_subnet_count
  private_offset = local.public_subnet_count + local.nat_subnet_count

  public_subnet_cidrs = [
    for i in range(local.public_subnet_count) :
    cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.public_offset + i)
  ]

  nat_subnet_cidrs = [
    for i in range(local.nat_subnet_count) :
    cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.nat_offset + i)
  ]

  private_subnet_cidrs = [
    for i in range(local.private_subnet_count) :
    cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.private_offset + i)
  ]
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${var.name}-vpc"
  })
}

# Public tier

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.tags, {
    Name = "${var.name}-public-${local.az_names[count.index]}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "this" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "${var.name}-igw"
  })
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "${var.name}-public-sg"
  description = "Security group for public tier"
  vpc_id      = aws_vpc.this.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.name}-public-sg"
  })
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[0].id
  }

  route {
    cidr_block = aws_vpc.this.cidr_block
    gateway_id = "local"
  }

  tags = merge(var.tags, {
    Name = "${var.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# NAT tier

resource "aws_subnet" "nat" {
  count = local.nat_subnet_count

  vpc_id            = aws_vpc.this.id
  cidr_block        = local.nat_subnet_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(var.tags, {
    Name = "${var.name}-nat-${local.az_names[count.index]}"
    Tier = "nat"
  })
}

# Private tier

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.this.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(var.tags, {
    Name = "${var.name}-private-${local.az_names[count.index]}"
    Tier = "private"
  })
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "availability_zones" {
  description = "Availability zones used for subnets"
  value       = local.az_names
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "nat_subnet_ids" {
  description = "IDs of the NAT tier subnets"
  value       = aws_subnet.nat[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway (null if public subnets disabled)"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "public_security_group_id" {
  description = "ID of the public security group (null if public subnets disabled)"
  value       = try(aws_security_group.public[0].id, null)
}

output "public_route_table_id" {
  description = "ID of the public route table (null if public subnets disabled)"
  value       = try(aws_route_table.public[0].id, null)
}

output "subnet_cidrs" {
  description = "Calculated CIDR blocks per tier"
  value = {
    public  = local.public_subnet_cidrs
    nat     = local.nat_subnet_cidrs
    private = local.private_subnet_cidrs
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "project" {
  description = "Project name used for tagging and naming"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones for subnets; if empty, the first available zones in the region are used"
  type        = list(string)
  default     = []
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_name" {
  description = "EC2 key pair name for SSH access to the bastion"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "Instance type for the SSH bastion host"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Whether the bastion instance is EBS optimized"
  type        = bool
  default     = false
}

variable "bastion_allowed_cidrs" {
  description = "CIDR blocks allowed to SSH into the bastion"
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

variable "vpc_tags" {
  description = "Additional tags for the VPC"
  type        = map(string)
  default     = {}
}

variable "subnet_tags" {
  description = "Additional tags for subnets"
  type        = map(string)
  default     = {}
}

variable "bastion_tags" {
  description = "Additional tags for the bastion host"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(
    data.aws_availability_zones.available.names,
    0,
    max(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs))
  )

  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, var.vpc_tags, {
    Name = var.vpc_name
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "demogwInternet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "demoPublicRouteTable"
  })
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, var.subnet_tags, {
    Name = "${var.project}-${var.environment}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, var.subnet_tags, {
    Name = "${var.project}-${var.environment}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}PrivateRouteTable"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "bastion" {
  name        = "${var.project}-${var.environment}-bastion-sg"
  description = "Allow SSH access to bastion host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.bastion_allowed_cidrs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-bastion-sg"
  })
}

resource "aws_instance" "bastion" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = var.bastion_instance_type
  key_name                    = var.key_name
  subnet_id                   = aws_subnet.public[0].id
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  ebs_optimized               = var.ebs_optimized
  associate_public_ip_address = false

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(local.common_tags, var.bastion_tags, {
    Name = "${var.project}-${var.environment}-bastion"
  })
}

resource "aws_eip" "bastion" {
  domain   = "vpc"
  instance = aws_instance.bastion.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-bastion-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  value = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  value = aws_route_table.public.id
}

output "bastion_security_group_id" {
  value = aws_security_group.bastion.id
}

output "bastion_public_ip" {
  value = aws_eip.bastion.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "primary_region" {
  description = "Primary AWS region where RDS databases and the primary backup vault reside."
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Secondary AWS region for cross-region backup copies."
  type        = string
  default     = "us-west-2"
}

variable "name_prefix" {
  description = "Prefix applied to the names of all created resources."
  type        = string
  default     = "rds-backup"
}

variable "enable_daily_backup" {
  description = "Whether to create the daily backup plan."
  type        = bool
  default     = true
}

variable "enable_cross_account_copy" {
  description = "Whether to copy recovery points to a vault in another AWS account."
  type        = bool
  default     = true
}

variable "cross_account_destination_account_id" {
  description = "AWS account ID that receives cross-account backup copies."
  type        = string
  default     = "433568766270"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.cross_account_destination_account_id))
    error_message = "cross_account_destination_account_id must be a 12-digit AWS account ID."
  }
}

variable "cross_account_destination_region" {
  description = "Region of the destination vault in the cross-account target. Defaults to the primary region when null."
  type        = string
  default     = null
}

variable "cross_account_destination_vault_name" {
  description = "Name of the pre-existing backup vault in the destination account. The vault's access policy must allow backup:CopyIntoBackupVault from this account."
  type        = string
  default     = "rds-backup-cross-account-vault"
}

variable "excluded_rds_arns" {
  description = "List of RDS instance or cluster ARNs to exclude from backups."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  cross_account_region = coalesce(var.cross_account_destination_region, var.primary_region)

  cross_account_vault_arn = "arn:${local.partition}:backup:${local.cross_account_region}:${var.cross_account_destination_account_id}:backup-vault:${var.cross_account_destination_vault_name}"

  all_backup_plans = {
    daily = {
      schedule       = "cron(0 2 * * ? *)"
      retention_days = 7
      enabled        = var.enable_daily_backup
    }
    weekly = {
      schedule       = "cron(0 2 ? * SAT *)"
      retention_days = 30
      enabled        = true
    }
    monthly = {
      schedule       = "cron(0 3 1 * ? *)"
      retention_days = 365
      enabled        = true
    }
    yearly = {
      schedule       = "cron(0 4 1 1 ? *)"
      retention_days = 2555
      enabled        = true
    }
  }

  backup_plans = { for k, v in local.all_backup_plans : k => v if v.enabled }

  rds_resource_arns = [
    "arn:${local.partition}:rds:*:${local.account_id}:db:*",
    "arn:${local.partition}:rds:*:${local.account_id}:cluster:*",
  ]

  common_tags = merge(
    {
      ManagedBy = "Terraform"
      Purpose   = "RDS-Backup"
    },
    var.tags,
  )
}

# -----------------------------------------------------------------------------
# KMS keys
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAWSBackupUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.backup.arn]
    }
  }

  statement {
    sid    = "AllowCrossAccountDestinationUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${var.cross_account_destination_account_id}:root"]
    }
  }
}

resource "aws_kms_key" "primary" {
  description             = "KMS key for AWS Backup vault (${var.primary_region})"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms.json

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-primary-kms" })
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${var.name_prefix}-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "secondary" {
  provider = aws.secondary

  description             = "KMS key for AWS Backup vault (${var.secondary_region})"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms.json

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-secondary-kms" })
}

resource "aws_kms_alias" "secondary" {
  provider = aws.secondary

  name          = "alias/${var.name_prefix}-secondary"
  target_key_id = aws_kms_key.secondary.key_id
}

# -----------------------------------------------------------------------------
# Backup vaults
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "primary" {
  name        = "${var.name_prefix}-primary-vault"
  kms_key_arn = aws_kms_key.primary.arn

  tags = local.common_tags
}

resource "aws_backup_vault" "secondary" {
  provider = aws.secondary

  name        = "${var.name_prefix}-secondary-vault"
  kms_key_arn = aws_kms_key.secondary.arn

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# IAM role for AWS Backup
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${var.name_prefix}-service-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# -----------------------------------------------------------------------------
# Backup plans
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "rds" {
  for_each = local.backup_plans

  name = "${var.name_prefix}-${each.key}"

  rule {
    rule_name         = "${var.name_prefix}-${each.key}-rule"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = each.value.schedule
    start_window      = 60
    completion_window = 360

    lifecycle {
      delete_after = each.value.retention_days
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn

      lifecycle {
        delete_after = each.value.retention_days
      }
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []

      content {
        destination_vault_arn = local.cross_account_vault_arn

        lifecycle {
          delete_after = each.value.retention_days
        }
      }
    }

    recovery_point_tags = merge(local.common_tags, { BackupFrequency = each.key })
  }

  tags = merge(local.common_tags, { BackupFrequency = each.key })
}

resource "aws_backup_selection" "rds" {
  for_each = local.backup_plans

  name         = "${var.name_prefix}-${each.key}-rds"
  plan_id      = aws_backup_plan.rds[each.key].id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = local.rds_resource_arns
  not_resources = var.excluded_rds_arns

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restore,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "primary_backup_vault_arn" {
  description = "ARN of the primary backup vault."
  value       = aws_backup_vault.primary.arn
}

output "secondary_backup_vault_arn" {
  description = "ARN of the cross-region backup vault."
  value       = aws_backup_vault.secondary.arn
}

output "cross_account_backup_vault_arn" {
  description = "ARN of the cross-account destination vault (null when disabled)."
  value       = var.enable_cross_account_copy ? local.cross_account_vault_arn : null
}

output "backup_plan_ids" {
  description = "Map of backup plan frequency to plan ID."
  value       = { for k, v in aws_backup_plan.rds : k => v.id }
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "primary_kms_key_arn" {
  description = "ARN of the KMS key encrypting the primary vault."
  value       = aws_kms_key.primary.arn
}

output "secondary_kms_key_arn" {
  description = "ARN of the KMS key encrypting the secondary vault."
  value       = aws_kms_key.secondary.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the provider"
  type        = string
  default     = "us-east-1"
}

variable "allow_users_to_change_password" {
  description = "Whether IAM users are allowed to change their own password"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their password has expired"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Number of days that a user password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum length to require for user passwords"
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that users are prevented from reusing"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether to require lowercase characters in user passwords"
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether to require uppercase characters in user passwords"
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether to require numbers in user passwords"
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether to require symbols in user passwords"
  type        = bool
  default     = true
}

resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

data "aws_iam_policy_document" "developpers" {
  statement {
    sid       = "AllowEc2RdsOnDevResources"
    effect    = "Allow"
    actions   = ["ec2:*", "rds:*"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["dev"]
    }
  }
}

data "aws_iam_policy_document" "prod_users" {
  statement {
    sid       = "AllowEc2RdsOnProdResources"
    effect    = "Allow"
    actions   = ["ec2:*", "rds:*"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["preprod", "prod"]
    }
  }
}

data "aws_iam_policy_document" "administrators" {
  statement {
    sid         = "AllowAllExceptIamOrgAccountOnNonHighSecurity"
    effect      = "Allow"
    not_actions = ["iam:*", "organizations:*", "account:*"]
    resources   = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceTag/security"
      values   = ["high"]
    }
  }

  statement {
    sid    = "AllowSelectedIamOrgAccountActions"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole",
      "iam:DeleteServiceLinkedRole",
      "iam:ListRoles",
      "organizations:DescribeOrganization",
      "account:ListRegions",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "developpers" {
  name        = "developpers_policy"
  description = "Full EC2 and RDS access on resources tagged env=dev"
  policy      = data.aws_iam_policy_document.developpers.json
}

resource "aws_iam_policy" "prod_users" {
  name        = "prod_users_policy"
  description = "Full EC2 and RDS access on resources tagged env=preprod or env=prod"
  policy      = data.aws_iam_policy_document.prod_users.json
}

resource "aws_iam_policy" "administrators" {
  name        = "administrators_policy"
  description = "Broad access excluding IAM, Organizations and Account on non high-security resources"
  policy      = data.aws_iam_policy_document.administrators.json
}

resource "aws_iam_group_policy_attachment" "developpers" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers.arn
}

resource "aws_iam_group_policy_attachment" "prod_users" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users.arn
}

resource "aws_iam_group_policy_attachment" "administrators" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators.arn
}

output "group_names" {
  description = "Names of the IAM groups created"
  value = {
    administrators = aws_iam_group.administrators.name
    developpers    = aws_iam_group.developpers.name
    prod_users     = aws_iam_group.prod_users.name
  }
}

output "policy_arns" {
  description = "ARNs of the custom IAM policies created"
  value = {
    administrators = aws_iam_policy.administrators.arn
    developpers    = aws_iam_policy.developpers.arn
    prod_users     = aws_iam_policy.prod_users.arn
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix applied to all resources"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "main_cidr_block" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound network ACL rules applied to the private subnets"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 1024
      to_port     = 65535
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound network ACL rules applied to the private subnets"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.main_cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = "${var.name}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-private-${data.aws_availability_zones.available.names[count.index]}"
  }
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name}-private-rt-${data.aws_availability_zones.available.names[count.index]}"
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"

  tags = {
    Name = "${var.name}-s3-endpoint"
  }
}

resource "aws_vpc_endpoint_route_table_association" "private_s3" {
  count = 2

  vpc_endpoint_id = aws_vpc_endpoint.s3.id
  route_table_id  = aws_route_table.private[count.index].id
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.name}-private-nacl"
  }
}

resource "aws_network_acl_rule" "private_inbound" {
  count = length(var.public_inbound_acl_rules)

  network_acl_id = aws_network_acl.private.id
  egress         = false
  rule_number    = tonumber(var.public_inbound_acl_rules[count.index]["rule_number"])
  rule_action    = var.public_inbound_acl_rules[count.index]["rule_action"]
  from_port      = tonumber(var.public_inbound_acl_rules[count.index]["from_port"])
  to_port        = tonumber(var.public_inbound_acl_rules[count.index]["to_port"])
  protocol       = var.public_inbound_acl_rules[count.index]["protocol"]
  cidr_block     = var.public_inbound_acl_rules[count.index]["cidr_block"]
}

resource "aws_network_acl_rule" "private_outbound" {
  count = length(var.public_outbound_acl_rules)

  network_acl_id = aws_network_acl.private.id
  egress         = true
  rule_number    = tonumber(var.public_outbound_acl_rules[count.index]["rule_number"])
  rule_action    = var.public_outbound_acl_rules[count.index]["rule_action"]
  from_port      = tonumber(var.public_outbound_acl_rules[count.index]["from_port"])
  to_port        = tonumber(var.public_outbound_acl_rules[count.index]["to_port"])
  protocol       = var.public_outbound_acl_rules[count.index]["protocol"]
  cidr_block     = var.public_outbound_acl_rules[count.index]["cidr_block"]
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "private_route_table_ids" {
  description = "IDs of the private route tables"
  value       = aws_route_table.private[*].id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "private_network_acl_id" {
  description = "ID of the network ACL associated with the private subnets"
  value       = aws_network_acl.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Cloud Posse null-label context
################################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled             = var.enabled
  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  additional_tag_map  = var.additional_tag_map
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_key_case      = var.label_key_case
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  labels_as_tags      = var.labels_as_tags

  context = var.context
}

variable "context" {
  type = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = null
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    labels_as_tags      = ["unset"]
  }
  description = <<-EOT
    Single object for setting entire context at once.
    See description of individual variables for details.
    Leave string and numeric variables as `null` to use default value.
    Individual variable settings (non-null) override settings in context object,
    except for attributes, tags, and additional_tag_map, which are merged.
  EOT

  validation {
    condition     = lookup(var.context, "label_key_case", null) == null ? true : contains(["lower", "title", "upper"], var.context["label_key_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }

  validation {
    condition     = lookup(var.context, "label_value_case", null) == null ? true : contains(["lower", "title", "upper", "none"], var.context["label_value_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "enabled" {
  type        = bool
  default     = null
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name, e.g. 'eg' or 'cp', to help ensure generated IDs are globally unique"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element _(Rarely used, not included by default)_. A customer identifier, indicating who this instance of a resource is for"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region e.g. 'uw2', 'us-west-2', OR role 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'source', 'build', 'test', 'deploy', 'release'"
}

variable "name" {
  type        = string
  default     = null
  description = "ID element. Usually the component or solution name, e.g. 'app' or 'jenkins'"
}

variable "delimiter" {
  type        = string
  default     = null
  description = "Delimiter to be used between ID elements. Defaults to `-` (hyphen)."
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "ID element. Additional attributes (e.g. `workers` or `cluster`) to add to `id`, in the order they appear in the list."
}

variable "labels_as_tags" {
  type        = set(string)
  default     = ["default"]
  description = "Set of labels (ID elements) to include as tags in the `tags` output."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags (e.g. `{'BusinessUnit': 'XYZ'}`)."
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = "Additional key-value pairs to add to each map in `tags_as_list_of_maps`."
}

variable "label_order" {
  type        = list(string)
  default     = null
  description = "The order in which the labels (ID elements) appear in the `id`."
}

variable "regex_replace_chars" {
  type        = string
  default     = null
  description = "Terraform regular expression (regex) string. Characters matching the regex will be removed from the ID elements."
}

variable "id_length_limit" {
  type        = number
  default     = null
  description = "Limit `id` to this many characters (minimum 6). Set to `0` for unlimited length."

  validation {
    condition     = var.id_length_limit == null ? true : var.id_length_limit >= 6 || var.id_length_limit == 0
    error_message = "The id_length_limit must be >= 6 if supplied (not null), or 0 for unlimited length."
  }
}

variable "label_key_case" {
  type        = string
  default     = null
  description = "Controls the letter case of the `tags` keys (label names) for tags generated by this module."

  validation {
    condition     = var.label_key_case == null ? true : contains(["lower", "title", "upper"], var.label_key_case)
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }
}

variable "label_value_case" {
  type        = string
  default     = null
  description = "Controls the letter case of ID elements (labels) as included in `id`."

  validation {
    condition     = var.label_value_case == null ? true : contains(["lower", "title", "upper", "none"], var.label_value_case)
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "descriptor_formats" {
  type        = any
  default     = {}
  description = "Describe additional descriptors to be output in the `descriptors` output map."
}

################################################################################
# VPC variables
################################################################################

variable "ipv4_primary_cidr_block" {
  type        = string
  default     = "11.0.0.0/16"
  description = <<-EOT
    The primary IPv4 CIDR block for the VPC.
    Ignored when `ipv4_primary_cidr_block_association` is set to use an IPAM pool.
    EOT
}

variable "ipv4_primary_cidr_block_association" {
  type = object({
    ipv4_ipam_pool_id   = string
    ipv4_netmask_length = number
  })
  default     = null
  description = <<-EOT
    Configuration of the VPC's primary IPv4 CIDR block via IPAM. Conflicts with `ipv4_primary_cidr_block`.
    One of `ipv4_primary_cidr_block` or `ipv4_primary_cidr_block_association` must be set.
    EOT
}

variable "ipv4_additional_cidr_block_associations" {
  type = map(object({
    ipv4_cidr_block     = string
    ipv4_ipam_pool_id   = string
    ipv4_netmask_length = number
  }))
  default     = {}
  description = <<-EOT
    IPv4 CIDR blocks to assign to the VPC.
    `ipv4_cidr_block` can be set explicitly, or set to `null` with the CIDR block derived from `ipv4_ipam_pool_id` using `ipv4_netmask_length`.
    Map keys must be known at `plan` time and are only used to track changes.
    EOT
}

variable "ipv4_cidr_block_association_timeouts" {
  type = object({
    create = string
    delete = string
  })
  default     = null
  description = "Timeouts (in `go` duration format) for creating and destroying IPv4 CIDR block associations"
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  default     = true
  description = "When `true`, assign an AWS-generated /56 IPv6 CIDR block to the VPC. Conflicts with `ipv6_primary_cidr_block_association`."
}

variable "ipv6_primary_cidr_block_association" {
  type = object({
    ipv6_cidr_block     = string
    ipv6_ipam_pool_id   = string
    ipv6_netmask_length = number
  })
  default     = null
  description = <<-EOT
    Primary IPv6 CIDR block to assign to the VPC via IPAM. Conflicts with `assign_generated_ipv6_cidr_block`.
    `ipv6_cidr_block` can be set explicitly, or set to `null` with the CIDR block derived from `ipv6_ipam_pool_id` using `ipv6_netmask_length`.
    EOT
}

variable "ipv6_additional_cidr_block_associations" {
  type = map(object({
    ipv6_cidr_block     = string
    ipv6_ipam_pool_id   = string
    ipv6_netmask_length = number
  }))
  default     = {}
  description = <<-EOT
    IPv6 CIDR blocks to assign to the VPC (in addition to the autogenerated one).
    `ipv6_cidr_block` can be set explicitly, or set to `null` with the CIDR block derived from `ipv6_ipam_pool_id` using `ipv6_netmask_length`.
    Map keys must be known at `plan` time and are only used to track changes.
    EOT
}

variable "ipv6_cidr_block_association_timeouts" {
  type = object({
    create = string
    delete = string
  })
  default     = null
  description = "Timeouts (in `go` duration format) for creating and destroying IPv6 CIDR block associations"
}

variable "instance_tenancy" {
  type        = string
  default     = "default"
  description = "A tenancy option for instances launched into the VPC"

  validation {
    condition     = contains(["default", "dedicated", "host"], var.instance_tenancy)
    error_message = "Instance tenancy must be one of \"default\", \"dedicated\", or \"host\"."
  }
}

variable "dns_hostnames_enabled" {
  type        = bool
  default     = true
  description = "Set `true` to enable [DNS hostnames](https://docs.aws.amazon.com/vpc/latest/userguide/vpc-dns.html#vpc-dns-hostnames) in the VPC"
}

variable "dns_support_enabled" {
  type        = bool
  default     = true
  description = "Set `true` to enable DNS resolution in the VPC through the Amazon provided DNS server"
}

variable "default_security_group_deny_all" {
  type        = bool
  default     = true
  description = <<-EOT
    When `true`, manage the default security group and remove all rules, disabling all ingress and egress.
    When `false`, do not manage the default security group, allowing it to be managed by another component.
    EOT
}

variable "default_route_table_no_routes" {
  type        = bool
  default     = false
  description = <<-EOT
    When `true`, manage the default route table and remove all routes, disabling all ingress and egress.
    When `false`, do not mange the default route table, allowing it to be managed by another component.
    Conflicts with Terraform resource `aws_main_route_table_association`.
    EOT
}

variable "default_network_acl_deny_all" {
  type        = bool
  default     = false
  description = <<-EOT
    When `true`, manage the default network acl and remove all rules, disabling all ingress and egress.
    When `false`, do not mange the default networking acl, allowing it to be managed by another component.
    EOT
}

variable "internet_gateway_enabled" {
  type        = bool
  default     = true
  description = "Set `true` to create an Internet Gateway for the VPC"
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  default     = false
  description = "Set `true` to create an IPv4-only Internet Gateway for the VPC"
}

################################################################################
# Locals
################################################################################

locals {
  enabled = module.this.enabled

  ipv4_primary_ipam = var.ipv4_primary_cidr_block_association != null
  ipv6_primary_ipam = var.ipv6_primary_cidr_block_association != null

  # An IPAM-provided IPv6 primary block is mutually exclusive with an AWS-generated one
  assign_generated_ipv6_cidr_block = local.ipv6_primary_ipam ? false : var.assign_generated_ipv6_cidr_block
  ipv6_enabled                     = local.assign_generated_ipv6_cidr_block || local.ipv6_primary_ipam

  default_security_group_managed = local.enabled && var.default_security_group_deny_all
  default_route_table_managed    = local.enabled && var.default_route_table_no_routes
  default_network_acl_managed    = local.enabled && var.default_network_acl_deny_all

  internet_gateway_enabled                  = local.enabled && var.internet_gateway_enabled
  ipv6_egress_only_internet_gateway_enabled = local.enabled && local.ipv6_enabled && var.ipv6_egress_only_internet_gateway_enabled

  ipv4_additional_cidr_block_associations = local.enabled ? var.ipv4_additional_cidr_block_associations : {}
  ipv6_additional_cidr_block_associations = local.enabled ? var.ipv6_additional_cidr_block_associations : {}

  ipv4_cidr_block_association_timeouts = var.ipv4_cidr_block_association_timeouts == null ? [] : [var.ipv4_cidr_block_association_timeouts]
  ipv6_cidr_block_association_timeouts = var.ipv6_cidr_block_association_timeouts == null ? [] : [var.ipv6_cidr_block_association_timeouts]
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "default" {
  count = local.enabled ? 1 : 0

  # IPv4
  cidr_block          = local.ipv4_primary_ipam ? null : var.ipv4_primary_cidr_block
  ipv4_ipam_pool_id   = try(var.ipv4_primary_cidr_block_association.ipv4_ipam_pool_id, null)
  ipv4_netmask_length = try(var.ipv4_primary_cidr_block_association.ipv4_netmask_length, null)

  # IPv6
  assign_generated_ipv6_cidr_block = local.assign_generated_ipv6_cidr_block
  ipv6_cidr_block                  = try(var.ipv6_primary_cidr_block_association.ipv6_cidr_block, null)
  ipv6_ipam_pool_id                = try(var.ipv6_primary_cidr_block_association.ipv6_ipam_pool_id, null)
  ipv6_netmask_length              = try(var.ipv6_primary_cidr_block_association.ipv6_netmask_length, null)

  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.dns_hostnames_enabled
  enable_dns_support   = var.dns_support_enabled

  tags = module.this.tags

  lifecycle {
    precondition {
      condition     = local.ipv4_primary_ipam || var.ipv4_primary_cidr_block != null
      error_message = "One of `ipv4_primary_cidr_block` or `ipv4_primary_cidr_block_association` must be set."
    }
  }
}

resource "aws_vpc_ipv4_cidr_block_association" "default" {
  for_each = local.ipv4_additional_cidr_block_associations

  vpc_id              = aws_vpc.default[0].id
  cidr_block          = each.value.ipv4_cidr_block
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_netmask_length

  dynamic "timeouts" {
    for_each = local.ipv4_cidr_block_association_timeouts
    content {
      create = timeouts.value.create
      delete = timeouts.value.delete
    }
  }
}

resource "aws_vpc_ipv6_cidr_block_association" "default" {
  for_each = local.ipv6_additional_cidr_block_associations

  vpc_id              = aws_vpc.default[0].id
  ipv6_cidr_block     = each.value.ipv6_cidr_block
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_netmask_length

  dynamic "timeouts" {
    for_each = local.ipv6_cidr_block_association_timeouts
    content {
      create = timeouts.value.create
      delete = timeouts.value.delete
    }
  }
}

################################################################################
# Default resource adoption
################################################################################

# Adopting the default security group without any ingress/egress blocks removes all rules
resource "aws_default_security_group" "default" {
  count = local.default_security_group_managed ? 1 : 0

  vpc_id = aws_vpc.default[0].id

  tags = merge(module.this.tags, { Name = "Default Security Group" })
}

# Adopting the default route table with an empty route list removes all routes
resource "aws_default_route_table" "default" {
  count = local.default_route_table_managed ? 1 : 0

  default_route_table_id = aws_vpc.default[0].default_route_table_id
  route                  = []

  tags = module.this.tags
}

# Adopting the default network ACL without any ingress/egress blocks removes all rules
resource "aws_default_network_acl" "default" {
  count = local.default_network_acl_managed ? 1 : 0

  default_network_acl_id = aws_vpc.default[0].default_network_acl_id

  tags = module.this.tags

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

################################################################################
# Internet gateways
################################################################################

resource "aws_internet_gateway" "default" {
  count = local.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.default[0].id

  tags = module.this.tags
}

resource "aws_egress_only_internet_gateway" "default" {
  count = local.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.default[0].id

  tags = module.this.tags
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = one(aws_vpc.default[*].id)
}

output "vpc_arn" {
  description = "The ARN of the VPC"
  value       = one(aws_vpc.default[*].arn)
}

output "vpc_cidr_block" {
  description = "The primary IPv4 CIDR block of the VPC"
  value       = one(aws_vpc.default[*].cidr_block)
}

output "vpc_ipv6_cidr_block" {
  description = "The primary IPv6 CIDR block of the VPC"
  value       = one(aws_vpc.default[*].ipv6_cidr_block)
}

output "vpc_ipv6_association_id" {
  description = "The association ID for the primary IPv6 CIDR block"
  value       = one(aws_vpc.default[*].ipv6_association_id)
}

output "additional_cidr_blocks" {
  description = "A list of the additional IPv4 CIDR blocks associated with the VPC"
  value       = [for k, v in aws_vpc_ipv4_cidr_block_association.default : v.cidr_block]
}

output "additional_cidr_blocks_to_association_ids" {
  description = "A map of the additional IPv4 CIDR blocks to VPC CIDR association IDs"
  value       = { for k, v in aws_vpc_ipv4_cidr_block_association.default : v.cidr_block => v.id }
}

output "additional_ipv6_cidr_blocks" {
  description = "A list of the additional IPv6 CIDR blocks associated with the VPC"
  value       = [for k, v in aws_vpc_ipv6_cidr_block_association.default : v.ipv6_cidr_block]
}

output "additional_ipv6_cidr_blocks_to_association_ids" {
  description = "A map of the additional IPv6 CIDR blocks to VPC CIDR association IDs"
  value       = { for k, v in aws_vpc_ipv6_cidr_block_association.default : v.ipv6_cidr_block => v.id }
}

output "vpc_main_route_table_id" {
  description = "The ID of the main route table associated with this VPC"
  value       = one(aws_vpc.default[*].main_route_table_id)
}

output "vpc_default_network_acl_id" {
  description = "The ID of the network ACL created by default on VPC creation"
  value       = one(aws_vpc.default[*].default_network_acl_id)
}

output "vpc_default_security_group_id" {
  description = "The ID of the security group created by default on VPC creation"
  value       = one(aws_vpc.default[*].default_security_group_id)
}

output "vpc_default_route_table_id" {
  description = "The ID of the route table created by default on VPC creation"
  value       = one(aws_vpc.default[*].default_route_table_id)
}

output "igw_id" {
  description = "The ID of the Internet Gateway"
  value       = one(aws_internet_gateway.default[*].id)
}

output "ipv6_egress_only_igw_id" {
  description = "The ID of the egress-only Internet Gateway"
  value       = one(aws_egress_only_internet_gateway.default[*].id)
}

output "ipv6_cidr_block_network_border_group" {
  description = "The IPv6 Network Border Group Zone name"
  value       = one(aws_vpc.default[*].ipv6_cidr_block_network_border_group)
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "username" {
  description = "Name of the IAM user for infrastructure deployment"
  type        = string
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  description = "Name of the IAM group"
  type        = string
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  description = "Name of the IAM group membership"
  type        = string
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  description = "Value of the ProjectTag tag applied to resources"
  type        = string
  default     = "my-vpn-tag"
}

variable "policy_path" {
  description = "Path for IAM policies"
  type        = string
  default     = "/my_vpn_infra/"
}

locals {
  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_user" "this" {
  name          = var.username
  force_destroy = true
  tags          = local.tags
}

resource "aws_iam_access_key" "this" {
  user   = aws_iam_user.this.name
  status = "Active"
}

resource "aws_iam_group" "this" {
  name = var.group_name
}

resource "aws_iam_group_membership" "this" {
  name  = var.membership_name
  group = aws_iam_group.this.name
  users = [aws_iam_user.this.name]
}

resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Basic identity access"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sts:GetCallerIdentity"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "EC2 resource creation permissions"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "EC2 read permissions"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses",
          "ec2:DescribeAddressesAttribute",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeImages",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstances",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeRegions",
          "ec2:DescribeReplaceRootVolumeTasks",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeVpcClassicLink",
          "ec2:DescribeVpcClassicLinkDnsSupport",
          "ec2:DescribeVpcs",
          "ec2:GetConsoleOutput"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "EC2 modification and association permissions"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:AssociateAddress",
          "ec2:AssociateRouteTable",
          "ec2:AttachInternetGateway",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyVpcAttribute",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:ReplaceRoute",
          "ec2:ReplaceRouteTableAssociation",
          "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
          "ec2:UpdateSecurityGroupRuleDescriptionsIngress",
          "ec2:ImportKeyPair"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "EC2 deletion and detachment permissions"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DeleteKeyPair",
          "ec2:DeleteVpc",
          "ec2:DeleteSubnet",
          "ec2:DeleteInternetGateway",
          "ec2:DeleteRoute",
          "ec2:DeleteRouteTable",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteTags",
          "ec2:DetachInternetGateway",
          "ec2:DisassociateAddress",
          "ec2:DisassociateRouteTable",
          "ec2:ReleaseAddress",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "EC2 instance lifecycle permissions"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "Terraform S3 backend and DynamoDB state lock access"
  tags        = local.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      }
    ]
  })
}

locals {
  group_policies = {
    basic_policy             = aws_iam_policy.basic_policy.arn
    create_policy            = aws_iam_policy.create_policy.arn
    read_policy              = aws_iam_policy.read_policy.arn
    update_policy            = aws_iam_policy.update_policy.arn
    delete_policy            = aws_iam_policy.delete_policy.arn
    instance_policy          = aws_iam_policy.instance_policy.arn
    terraform_backend_access = aws_iam_policy.terraform_backend_access.arn
  }
}

resource "aws_iam_group_policy_attachment" "this" {
  for_each   = local.group_policies
  group      = aws_iam_group.this.name
  policy_arn = each.value
}

output "user_name" {
  value = aws_iam_user.this.name
}

output "access_key_id" {
  value = aws_iam_access_key.this.id
}

output "secret_access_key" {
  value     = aws_iam_access_key.this.secret
  sensitive = true
}

output "group_name" {
  value = aws_iam_group.this.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC to use. Leave empty to create a new VPC."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment prefix used for resource naming"
  type        = string
  default     = "DEV"
}

variable "main_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "craete_private_subnet" {
  description = "Whether to create private subnets, a private route table, and a NAT Gateway"
  type        = bool
  default     = false
}

variable "eip_associate_with_private_ip" {
  description = "Private IP address to associate with the Elastic IP"
  type        = string
  default     = "10.0.0.5"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  create_vpc = var.existing_vpc_id == ""
  vpc_id     = local.create_vpc ? aws_vpc.main[0].id : var.existing_vpc_id
  azs        = slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.main_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name        = "${var.environment}-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment}-public-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${var.environment}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = var.craete_private_subnet ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name        = "${var.environment}-private-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "private"
  }
}

resource "aws_eip" "nat" {
  count = var.craete_private_subnet ? 1 : 0

  domain                    = "vpc"
  associate_with_private_ip = var.eip_associate_with_private_ip

  tags = {
    Name        = "${var.environment}-nat-eip"
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = var.craete_private_subnet ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = "${var.environment}-nat-gw"
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = var.craete_private_subnet ? 1 : 0

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name        = "${var.environment}-private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private" {
  count = var.craete_private_subnet ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = var.craete_private_subnet ? aws_nat_gateway.main[0].id : null
}

output "nat_eip_public_ip" {
  description = "Public IP of the NAT gateway Elastic IP"
  value       = var.craete_private_subnet ? aws_eip.nat[0].public_ip : null
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Whether to create SQS queue resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SQS queue. The .fifo suffix is managed automatically for FIFO queues"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Whether to use `name` as a prefix (name_prefix) instead of an exact name"
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = null
}

variable "deduplication_scope" {
  description = "Whether message deduplication occurs at the message group or queue level (`messageGroup` or `queue`)"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Whether the FIFO throughput quota applies to the entire queue or per message group (`perQueue` or `perMessageGroupId`)"
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "Time in seconds that delivery of all messages in the queue will be delayed (0-900)"
  type        = number
  default     = null
}

variable "max_message_size" {
  description = "Limit of how many bytes a message can contain before SQS rejects it (1024-262144)"
  type        = number
  default     = null
}

variable "message_retention_seconds" {
  description = "Number of seconds SQS retains a message (60-1209600)"
  type        = number
  default     = null
}

variable "receive_wait_time_seconds" {
  description = "Time for which a ReceiveMessage call will wait for a message to arrive (long polling) before returning (0-20)"
  type        = number
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the queue in seconds (0-43200)"
  type        = number
  default     = null
}

variable "kms_master_key_id" {
  description = "ID of an AWS-managed or custom CMK for SQS. When omitted, SQS managed SSE is used"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time in seconds for which SQS can reuse a data key before calling KMS again (60-86400)"
  type        = number
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys. Only applied when `kms_master_key_id` is not set"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A mapping of tags to assign to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Queue Policy Variables
################################################################################

variable "create_queue_policy" {
  description = "Whether to create an SQS queue policy"
  type        = bool
  default     = false
}

variable "source_queue_policy_documents" {
  description = "List of IAM policy documents (JSON strings) that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_queue_policy_documents" {
  description = "List of IAM policy documents (JSON strings) that are merged together into the exported document. Statements with the same `sid` override earlier ones"
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "A map of IAM policy statements for a custom queue policy. `resources` defaults to the queue ARN when unspecified"
  type        = any
  default     = {}
}

################################################################################
# Dead Letter Queue Variables
################################################################################

variable "create_dlq" {
  description = "Whether to create an SQS dead-letter queue"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Name of the dead-letter queue. Defaults to `<name>-dlq`"
  type        = string
  default     = null
}

variable "dlq_content_based_deduplication" {
  description = "Enables content-based deduplication for the FIFO dead-letter queue"
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Whether message deduplication occurs at the message group or queue level for the dead-letter queue"
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Time in seconds that delivery of all messages in the dead-letter queue will be delayed"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Number of seconds SQS retains a message in the dead-letter queue"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Long polling wait time for the dead-letter queue"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Visibility timeout for the dead-letter queue in seconds"
  type        = number
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "KMS key ID for the dead-letter queue. Falls back to `kms_master_key_id`"
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Data key reuse period for the dead-letter queue. Falls back to `kms_data_key_reuse_period_seconds`"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Whether SQS managed SSE is enabled for the dead-letter queue. Falls back to `sqs_managed_sse_enabled`"
  type        = bool
  default     = null
}

variable "redrive_policy" {
  description = "Additional redrive policy settings for the main queue. `maxReceiveCount` defaults to 5 and `deadLetterTargetArn` is set to the dead-letter queue ARN"
  type        = any
  default     = {}
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to create a redrive allow policy on the dead-letter queue restricting redrive to the main queue"
  type        = bool
  default     = true
}

variable "dlq_tags" {
  description = "A mapping of additional tags to assign to the dead-letter queue"
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  name = try(trimsuffix(var.name, ".fifo"), "")

  dlq_base_name = try(trimsuffix(coalesce(var.dlq_name, "${local.name}-dlq"), ".fifo"), "")

  dlq_kms_master_key_id = try(coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id), null)
  dlq_kms_data_key_reuse_period_seconds = try(
    coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds),
    null
  )
  dlq_sqs_managed_sse_enabled = coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled)
}

################################################################################
# Queue
################################################################################

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : (var.fifo_queue ? "${local.name}.fifo" : local.name)
  name_prefix = var.use_name_prefix ? "${local.name}-" : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.content_based_deduplication
  deduplication_scope         = var.deduplication_scope
  fifo_throughput_limit       = var.fifo_throughput_limit

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled

  tags = var.tags
}

################################################################################
# Queue Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, statement.key)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null) != null || try(statement.value.not_resources, null) != null ? try(statement.value.resources, null) : [aws_sqs_queue.this[0].arn]
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, statement.value.condition, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Dead Letter Queue
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = var.use_name_prefix ? null : (var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name)
  name_prefix = var.use_name_prefix ? "${local.dlq_base_name}-" : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.dlq_content_based_deduplication
  deduplication_scope         = var.dlq_deduplication_scope

  delay_seconds              = var.dlq_delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.dlq_message_retention_seconds
  receive_wait_time_seconds  = var.dlq_receive_wait_time_seconds
  visibility_timeout_seconds = var.dlq_visibility_timeout_seconds

  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : local.dlq_sqs_managed_sse_enabled

  tags = merge(var.tags, var.dlq_tags)
}

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(
    merge(
      { maxReceiveCount = 5 },
      var.redrive_policy,
      { deadLetterTargetArn = aws_sqs_queue.dlq[0].arn }
    )
  )
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

################################################################################
# Outputs
################################################################################

output "queue_id" {
  description = "The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "Same as `queue_id`: the URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dead_letter_queue_id" {
  description = "The URL for the created dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "The ARN of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "Same as `dead_letter_queue_id`: the URL for the created dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "The name of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  users = {
    loadbalancer  = ["test", "test2", "test3", "test4"]
    loadbalancer2 = ["test2", "test22", "test23", "test24"]
    loadbalancer3 = ["test3", "test32", "test33", "test34"]
  }

  user_policies = merge([
    for user, policies in local.users : {
      for policy in policies : "${user}-${policy}" => {
        user   = user
        policy = policy
      }
    }
  ]...)
}

resource "aws_iam_user" "lb" {
  for_each = local.users

  name = each.key
  path = "/system/"
}

resource "aws_iam_access_key" "lb" {
  for_each = aws_iam_user.lb

  user   = each.value.name
  status = "Active"
}

data "aws_iam_policy_document" "ec2_describe" {
  statement {
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

resource "aws_iam_user_policy" "lb" {
  for_each = local.user_policies

  name   = each.value.policy
  user   = aws_iam_user.lb[each.value.user].name
  policy = data.aws_iam_policy_document.ec2_describe.json
}

output "access_key_ids" {
  value = { for k, v in aws_iam_access_key.lb : k => v.id }
}

output "secret_access_keys" {
  value     = { for k, v in aws_iam_access_key.lb : k => v.secret }
  sensitive = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "backup_name" {
  description = "Name used for the backup vault and related resources."
  type        = string
}

variable "account_type" {
  description = "Type of account this vault is deployed to: 'workload' or 'backup'."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN used to encrypt the backup vault."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON policy document to attach to the backup vault."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention period in days for the vault lock. When set, a vault lock is configured."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention period in days for the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional number of days before the vault lock becomes immutable (compliance mode)."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to enable SNS notifications for backup vault events."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN that receives backup vault notifications."
  type        = string
  default     = null
}

variable "backup_vault_events" {
  description = "List of backup vault events that trigger notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "rule_schedule" {
  description = "CRON expression for the backup rule schedule."
  type        = string
  default     = "cron(0 5 ? * * *)"
}

variable "recovery_point_tags" {
  description = "Tags applied to recovery points created by the backup plan."
  type        = map(string)
  default     = {}
}

variable "copy_actions" {
  description = "List of cross-region or cross-account copy actions for the backup rule."
  type = list(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number)
    delete_after          = optional(number)
  }))
  default = []
}

variable "selection_resources" {
  description = "Optional list of explicit resource ARNs to include in an additional backup selection."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  is_workload = var.account_type == "workload"
}

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn
  tags        = var.tags
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

data "aws_iam_policy_document" "backup_assume_role" {
  count = local.is_workload ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name_prefix        = "aws-backup-"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role[0].json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name           = "rule-${var.backup_name}-backup"
    target_vault_name   = aws_backup_vault.this.name
    schedule            = var.rule_schedule
    start_window        = 60
    completion_window   = 120
    recovery_point_tags = var.recovery_point_tags

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.copy_actions

      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.cold_storage_after != null || copy_action.value.delete_after != null ? [1] : []

          content {
            cold_storage_after = copy_action.value.cold_storage_after
            delete_after       = copy_action.value.delete_after
          }
        }
      }
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "tag_based" {
  count = local.is_workload ? 1 : 0

  name         = "selection-${var.backup_name}-tags"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resource_based" {
  count = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0

  name         = "selection-${var.backup_name}-resources"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources
}

output "backup_vault_name" {
  description = "Name of the backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_vault_arn" {
  description = "ARN of the backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_plan_id" {
  description = "ID of the backup plan (workload accounts only)."
  value       = local.is_workload ? aws_backup_plan.this[0].id : null
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup (workload accounts only)."
  value       = local.is_workload ? aws_iam_role.backup[0].arn : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy the AWS Config stack into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name for resources. Falls back to a generated petname when null or empty."
  type        = string
  default     = "config"
  nullable    = true
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# Naming convention
################################################################################

module "naming" {
  source = "./modules/naming"

  name = var.name
}

locals {
  name       = module.naming.name
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  config_rules = {
    "cloudtrail-enabled" = {
      source_identifier           = "CLOUD_TRAIL_ENABLED"
      maximum_execution_frequency = "TwentyFour_Hours"
      input_parameters            = null
      compliance_resource_types   = []
    }
    "iam-pw-policy" = {
      source_identifier           = "IAM_PASSWORD_POLICY"
      maximum_execution_frequency = "TwentyFour_Hours"
      input_parameters            = null
      compliance_resource_types   = []
    }
    "ec2-vpc" = {
      source_identifier           = "INSTANCES_IN_VPC"
      maximum_execution_frequency = null
      input_parameters            = null
      compliance_resource_types   = []
    }
    "root-mfa-enabled" = {
      source_identifier           = "ROOT_ACCOUNT_MFA_ENABLED"
      maximum_execution_frequency = "TwentyFour_Hours"
      input_parameters            = null
      compliance_resource_types   = []
    }
    "acm-expiration-check" = {
      source_identifier           = "ACM_CERTIFICATE_EXPIRATION_CHECK"
      maximum_execution_frequency = "TwentyFour_Hours"
      input_parameters            = null
      compliance_resource_types   = []
    }
    "ebs-inuse-check" = {
      source_identifier           = "EC2_VOLUME_INUSE_CHECK"
      maximum_execution_frequency = null
      input_parameters            = null
      compliance_resource_types   = []
    }
    "ec2-imdsv2-check" = {
      source_identifier           = "EC2_IMDSV2_CHECK"
      maximum_execution_frequency = null
      input_parameters            = null
      compliance_resource_types   = []
    }
    "rds-encrypted" = {
      source_identifier           = "RDS_STORAGE_ENCRYPTED"
      maximum_execution_frequency = null
      input_parameters            = null
      compliance_resource_types   = []
    }
    "rds-private" = {
      source_identifier           = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
      maximum_execution_frequency = null
      input_parameters            = null
      compliance_resource_types   = []
    }
    "rds-private-snapshots" = {
      source_identifier           = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
      maximum_execution_frequency = null
      input_parameters            = null
      compliance_resource_types   = []
    }
    "required-tags" = {
      source_identifier           = "REQUIRED_TAGS"
      maximum_execution_frequency = null
      input_parameters = jsonencode({
        tag1Key = "terraform.io"
        tag2Key = "environment"
      })
      compliance_resource_types = ["AWS::S3::Bucket"]
    }
  }
}

################################################################################
# KMS key for SNS encryption
################################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowConfigServiceUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowConfigRoleUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }
  }
}

resource "aws_kms_key" "sns" {
  description             = "CMK for encrypting the ${local.name} AWS Config SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = var.tags
}

resource "aws_kms_alias" "sns" {
  name          = "alias/${local.name}-sns"
  target_key_id = aws_kms_key.sns.key_id
}

################################################################################
# SNS topic
################################################################################

resource "aws_sns_topic" "config" {
  name              = local.name
  kms_master_key_id = aws_kms_key.sns.arn

  tags = var.tags
}

################################################################################
# S3 snapshot bucket
################################################################################

resource "aws_s3_bucket" "config" {
  bucket_prefix = "${local.name}-snapshots-"
  force_destroy = true

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket = aws_s3_bucket.config.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

################################################################################
# IAM role
################################################################################

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = local.name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "config" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "s3" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.config.arn]
  }

  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject", "s3:PutObjectAcl"]
    resources = ["${aws_s3_bucket.config.arn}/awsconfig/records/AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringLike"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_iam_role_policy" "s3" {
  name   = "${local.name}-s3"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.s3.json
}

data "aws_iam_policy_document" "sns" {
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = [aws_kms_key.sns.arn]
  }
}

resource "aws_iam_role_policy" "sns" {
  name   = "${local.name}-sns"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.sns.json
}

################################################################################
# AWS Config recorder & delivery channel
################################################################################

resource "aws_config_configuration_recorder" "this" {
  name     = local.name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "this" {
  name           = local.name
  s3_bucket_name = aws_s3_bucket.config.id
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_config_configuration_recorder.this,
    aws_iam_role_policy.s3,
    aws_iam_role_policy.sns,
  ]
}

resource "aws_config_configuration_recorder_status" "this" {
  name       = aws_config_configuration_recorder.this.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.this]
}

################################################################################
# AWS Config managed rules
################################################################################

resource "aws_config_config_rule" "this" {
  for_each = local.config_rules

  name                        = each.key
  maximum_execution_frequency = each.value.maximum_execution_frequency
  input_parameters            = each.value.input_parameters

  source {
    owner             = "AWS"
    source_identifier = each.value.source_identifier
  }

  dynamic "scope" {
    for_each = length(each.value.compliance_resource_types) > 0 ? [1] : []

    content {
      compliance_resource_types = each.value.compliance_resource_types
    }
  }

  tags = var.tags

  depends_on = [aws_config_configuration_recorder_status.this]
}

################################################################################
# Outputs
################################################################################

output "config_role_arn" {
  value = aws_iam_role.config.arn
}

output "config_bucket" {
  value = aws_s3_bucket.config.id
}

output "config_sns_topic_arn" {
  value = aws_sns_topic.config.arn
}

output "config_kms_key_arn" {
  value = aws_kms_key.sns.arn
}

output "config_rule_arns" {
  value = { for k, r in aws_config_config_rule.this : k => r.arn }
}

################################################################################
# modules/naming/main.tf  (place in ./modules/naming/main.tf)
################################################################################
#
# terraform {
#   required_providers {
#     random = {
#       source  = "hashicorp/random"
#       version = ">= 3.5"
#     }
#   }
# }
#
# variable "name" {
#   description = "Requested name. A petname is generated when null or empty."
#   type        = string
#   default     = "config"
#   nullable    = true
# }
#
# resource "random_pet" "this" {
#   length = 2
# }
#
# output "name" {
#   value = var.name == null || trimspace(coalesce(var.name, "")) == "" ? random_pet.this.id : var.name
# }

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

locals {
  project = "BJIT DevOps Task"
  author  = "Ariful Islam"
  name    = "bjit"

  common_tags = {
    Project = local.project
    Author  = local.author
  }

  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-subnet-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-subnet-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt-${local.azs[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-s3-endpoint"
  })
}

resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Allow HTTP/HTTPS (80-443) from anywhere to the API server ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP to HTTPS range"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

resource "aws_security_group" "mariadb" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "Allow MySQL/MariaDB from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL/MariaDB"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Allow Redis from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-redis-SG"
  })
}

resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "Allow API (8080) and SSH from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "API server"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-SG"
  })
}

resource "aws_security_group" "file_server" {
  name        = "bjit-file-server-SG"
  description = "Allow file server (8081) and SSH from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "File server"
    from_port   = 8081
    to_port     = 8081
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-file-server-SG"
  })
}

resource "aws_security_group" "public_ssh" {
  name        = "bjit-public-ssh-SG"
  description = "Allow SSH from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-ssh-SG"
  })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "public_route_table_id" {
  value = aws_route_table.public.id
}

output "private_route_table_ids" {
  value = aws_route_table.private[*].id
}

output "s3_vpc_endpoint_id" {
  value = aws_vpc_endpoint.s3.id
}

output "security_group_ids" {
  value = {
    alb         = aws_security_group.alb.id
    mariadb     = aws_security_group.mariadb.id
    redis       = aws_security_group.redis.id
    api_server  = aws_security_group.api_server.id
    file_server = aws_security_group.file_server.id
    public_ssh  = aws_security_group.public_ssh.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "base_name" {
  description = "Prefix used for naming all resources"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "Optional list of CIDR blocks for private subnets; when null, no private tier is created"
  type        = list(string)
  default     = null
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  private_enabled = var.subnet_private_cidrs != null
  private_cidrs   = local.private_enabled ? var.subnet_private_cidrs : []

  # Interface endpoints allow only one subnet per AZ, so prefer the private tier when present.
  endpoint_subnet_ids = local.private_enabled ? aws_subnet.private[*].id : aws_subnet.public[*].id
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count = length(var.subnet_public_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  availability_zone       = element(data.aws_availability_zones.available.names, count.index + 1)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.base_name}-public-${count.index}"
    Tier = "public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.subnet_public_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = length(local.private_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = element(data.aws_availability_zones.available.names, count.index + 1)

  tags = {
    Name = "${var.base_name}-private-${count.index}"
    Tier = "private"
  }
}

resource "aws_eip" "nat" {
  count = local.private_enabled ? length(var.subnet_public_cidrs) : 0

  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.private_enabled ? length(var.subnet_public_cidrs) : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.base_name}-nat-${count.index}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = length(local.private_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index % length(aws_nat_gateway.main)].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count = length(local.private_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.base_name}-s3-public-endpoint"
  }
}

resource "aws_vpc_endpoint" "s3_private" {
  count = local.private_enabled ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-private-endpoint"
  }
}

resource "aws_security_group" "ecr" {
  name        = "${var.base_name}-ecr-endpoints"
  description = "Allow HTTPS to ECR interface endpoints from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from public subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  dynamic "ingress" {
    for_each = local.private_enabled ? [1] : []

    content {
      description = "HTTPS from private subnets"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = local.private_cidrs
    }
  }

  egress {
    description = "All traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.base_name}-ecr-sg"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.ecr.id]

  tags = {
    Name = "${var.base_name}-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.ecr.id]

  tags = {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.main[*].id
}

output "ecr_security_group_id" {
  value = aws_security_group.ecr.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "pub_sub_1_cidr" {
  description = "CIDR block for public subnet 1"
  type        = string
  default     = "10.0.1.0/24"
}

variable "pub_sub_2_cidr" {
  description = "CIDR block for public subnet 2"
  type        = string
  default     = "10.0.2.0/24"
}

variable "pvt_sub_1_cidr" {
  description = "CIDR block for private subnet 1"
  type        = string
  default     = "10.0.3.0/24"
}

variable "pvt_sub_2_cidr" {
  description = "CIDR block for private subnet 2"
  type        = string
  default     = "10.0.4.0/24"
}

variable "admin_ssh_cidr" {
  description = "CIDR range permitted to SSH into the public tier (placeholder admin range)"
  type        = string
  default     = "203.0.113.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "project-vpc"
  }
}

resource "aws_subnet" "pub_sub_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pub_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "pub-sub-1"
  }
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pub_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "pub-sub-2"
  }
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pvt_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-1"
  }
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pvt_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-2"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "T-igw"
  }
}

resource "aws_route_table" "pub_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-1"
  }
}

resource "aws_route_table" "pub_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-2"
  }
}

resource "aws_route_table_association" "pub_sub_1" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.pub_rt_1.id
}

resource "aws_route_table_association" "pub_sub_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.pub_rt_2.id
}

resource "aws_eip" "nat_1" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_eip" "nat_2" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat_1" {
  allocation_id = aws_eip.nat_1.id
  subnet_id     = aws_subnet.pub_sub_1.id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat_2" {
  allocation_id = aws_eip.nat_2.id
  subnet_id     = aws_subnet.pub_sub_2.id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "pvt_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table" "pvt_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_sub_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.pvt_rt_1.id
}

resource "aws_route_table_association" "pvt_sub_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.pvt_rt_2.id
}

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public tier: HTTP/HTTPS from anywhere, SSH from admin range"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "allow_tls"
  }
}

resource "aws_vpc_security_group_ingress_rule" "pub_http" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "HTTP from anywhere"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_ingress_rule" "pub_https" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "HTTPS from anywhere"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_ingress_rule" "pub_ssh" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "SSH from admin range"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = var.admin_ssh_cidr
}

resource "aws_vpc_security_group_egress_rule" "pub_egress_vpc" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "All traffic to VPC CIDR only"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private tier: traffic only from/to public security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "pvt-seg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "pvt_http" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "HTTP from public SG"
  ip_protocol                  = "tcp"
  from_port                    = 80
  to_port                      = 80
  referenced_security_group_id = aws_security_group.allow_tls.id
}

resource "aws_vpc_security_group_ingress_rule" "pvt_https" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "HTTPS from public SG"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.allow_tls.id
}

resource "aws_vpc_security_group_ingress_rule" "pvt_ssh" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "SSH from public SG"
  ip_protocol                  = "tcp"
  from_port                    = 22
  to_port                      = 22
  referenced_security_group_id = aws_security_group.allow_tls.id
}

resource "aws_vpc_security_group_ingress_rule" "pvt_postgres" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "PostgreSQL from public SG"
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  referenced_security_group_id = aws_security_group.allow_tls.id
}

resource "aws_vpc_security_group_egress_rule" "pvt_egress_pub_sg" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "All traffic to public SG only"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.allow_tls.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = [aws_subnet.pub_sub_1.id, aws_subnet.pub_sub_2.id]
}

output "private_subnet_ids" {
  value = [aws_subnet.pvt_sub_1.id, aws_subnet.pvt_sub_2.id]
}

output "nat_gateway_ids" {
  value = [aws_nat_gateway.nat_1.id, aws_nat_gateway.nat_2.id]
}

output "public_security_group_id" {
  value = aws_security_group.allow_tls.id
}

output "private_security_group_id" {
  value = aws_security_group.pvt_seg.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# DynamoDB
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }
}

# ---------------------------------------------------------------------------
# IAM role used by API Gateway to call DynamoDB
# ---------------------------------------------------------------------------

resource "aws_iam_role" "apigw_dynamodb" {
  name = "apigw-dynamodb-terraform-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "apigateway.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb" {
  name = "apigw-dynamodb-terraform-policy"
  role = aws_iam_role.apigw_dynamodb.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# API Gateway account-level CloudWatch role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "apigw_cloudwatch" {
  name = "apigw-dynamodb-terraform-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "apigateway.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch" {
  role       = aws_iam_role.apigw_cloudwatch.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_cloudwatch]
}

# ---------------------------------------------------------------------------
# REST API
# ---------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "this" {
  name           = "APIGW DynamoDB Serverless Pattern Demo"
  description    = "Direct API Gateway to DynamoDB integration for a pet inventory"
  api_key_source = "HEADER"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# POST /pets -> DynamoDB PutItem

resource "aws_api_gateway_method" "post_pets" {
  rest_api_id      = aws_api_gateway_rest_api.this.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id             = aws_api_gateway_rest_api.this.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${var.region}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb.arn
  passthrough_behavior    = "WHEN_NO_TEMPLATES"

  request_templates = {
    "application/json" = <<-EOT
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "Item": {
          "id": {
            "S": "$context.requestId"
          },
          "PetType": {
            "S": "$input.path('$.PetType')"
          },
          "PetName": {
            "S": "$input.path('$.PetName')"
          },
          "PetPrice": {
            "N": "$input.path('$.PetPrice')"
          },
          "PetBoolean": {
            "BOOL": true
          }
        }
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets_200.status_code

  response_templates = {
    "application/json" = <<-EOT
      {
        "requestId": "$context.requestId"
      }
    EOT
  }

  depends_on = [aws_api_gateway_integration.post_pets]
}

# GET /pets/{PetType} -> DynamoDB Query on PetType-index

resource "aws_api_gateway_method" "get_pet_type" {
  rest_api_id      = aws_api_gateway_rest_api.this.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "get_pet_type" {
  rest_api_id             = aws_api_gateway_rest_api.this.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pet_type.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${var.region}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb.arn
  passthrough_behavior    = "WHEN_NO_TEMPLATES"

  request_parameters = {
    "integration.request.path.PetType" = "method.request.path.PetType"
  }

  request_templates = {
    "application/json" = <<-EOT
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "IndexName": "PetType-index",
        "KeyConditionExpression": "PetType = :v1",
        "ExpressionAttributeValues": {
          ":v1": {
            "S": "$util.urlDecode($input.params('PetType'))"
          }
        }
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "get_pet_type_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pet_type.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_pet_type_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pet_type.http_method
  status_code = aws_api_gateway_method_response.get_pet_type_200.status_code

  response_templates = {
    "application/json" = <<-EOT
      #set($inputRoot = $input.path('$'))
      {
        "pets": [
          #foreach($elem in $inputRoot.Items) {
            "id": "$elem.id.S",
            "PetType": "$elem.PetType.S",
            "PetName": "$elem.PetName.S",
            "PetPrice": "$elem.PetPrice.N"
          }#if($foreach.hasNext),#end
          #end
        ]
      }
    EOT
  }

  depends_on = [aws_api_gateway_integration.get_pet_type]
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "apigw" {
  name_prefix       = "/aws/APIGW/terraform"
  retention_in_days = 7
}

resource "aws_cloudwatch_log_resource_policy" "apigw" {
  policy_name = "apigw-dynamodb-terraform-log-policy-${data.aws_caller_identity.current.account_id}"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowApiGatewayLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = [
            "apigateway.amazonaws.com",
            "delivery.logs.amazonaws.com"
          ]
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.apigw.arn}:*"
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_api_gateway_rest_api.this.arn
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Deployment and stage
# ---------------------------------------------------------------------------

resource "aws_api_gateway_deployment" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.pets.id,
      aws_api_gateway_resource.pet_type.id,
      aws_api_gateway_method.post_pets.id,
      aws_api_gateway_method.get_pet_type.id,
      aws_api_gateway_integration.post_pets.id,
      aws_api_gateway_integration.post_pets.request_templates,
      aws_api_gateway_integration.get_pet_type.id,
      aws_api_gateway_integration.get_pet_type.request_templates,
      aws_api_gateway_integration_response.post_pets_200.response_templates,
      aws_api_gateway_integration_response.get_pet_type_200.response_templates,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.post_pets,
    aws_api_gateway_integration.get_pet_type,
    aws_api_gateway_integration_response.post_pets_200,
    aws_api_gateway_integration_response.get_pet_type_200,
  ]
}

resource "aws_api_gateway_stage" "v1" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  deployment_id = aws_api_gateway_deployment.this.id
  stage_name    = "v1"

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw.arn
    format = jsonencode({
      requestId         = "$context.requestId"
      ip                = "$context.identity.sourceIp"
      requestTime       = "$context.requestTime"
      httpMethod        = "$context.httpMethod"
      resourcePath      = "$context.resourcePath"
      status            = "$context.status"
      protocol          = "$context.protocol"
      responseLength    = "$context.responseLength"
      integrationStatus = "$context.integration.status"
      errorMessage      = "$context.error.message"
    })
  }

  depends_on = [
    aws_api_gateway_account.this,
    aws_cloudwatch_log_resource_policy.apigw,
  ]
}

resource "aws_api_gateway_method_settings" "all" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled = true
    logging_level   = "INFO"
  }

  depends_on = [aws_api_gateway_account.this]
}

# ---------------------------------------------------------------------------
# API key and usage plan
# ---------------------------------------------------------------------------

resource "aws_api_gateway_api_key" "this" {
  name    = "apigw-dynamodb-terraform-api-key"
  enabled = true
}

resource "aws_api_gateway_usage_plan" "this" {
  name = "apigw-dynamodb-terraform-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.this.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "this" {
  key_id        = aws_api_gateway_api_key.this.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.this.id
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "api_endpoint" {
  description = "Invoke URL for the v1 stage"
  value       = aws_api_gateway_stage.v1.invoke_url
}

output "api_key_id" {
  description = "ID of the API key (retrieve value with: aws apigateway get-api-key --api-key <id> --include-value)"
  value       = aws_api_gateway_api_key.this.id
}

output "api_key_value" {
  description = "API key value to send in the x-api-key header"
  value       = aws_api_gateway_api_key.this.value
  sensitive   = true
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.pets.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "name" {
  description = "Name used for naming resources"
  type        = string
  default     = "sadcloud"
}

variable "bucket_acl" {
  description = "Canned ACL applied to the logging bucket"
  type        = string
  default     = "log-delivery-write"
}

variable "no_versioning" {
  description = "Disable versioning on the main bucket"
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "Disable default encryption on the main bucket"
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "Enable static website hosting on the main bucket"
  type        = bool
  default     = false
}

variable "no_logging" {
  description = "Disable access logging and the logging bucket"
  type        = bool
  default     = false
}

variable "allow_cleartext" {
  description = "Attach a policy denying non-SSL requests to the main bucket"
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "Create a public bucket allowing s3:GetObject to everyone"
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "Create a public bucket allowing s3:* to everyone"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

################################################################################
# Main bucket
################################################################################

resource "aws_kms_key" "main" {
  count = var.no_default_encryption ? 0 : 1

  description             = "${var.name} main bucket encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "main" {
  bucket_prefix = var.name
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.no_versioning ? "Suspended" : "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.no_default_encryption ? 0 : 1

  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main[0].arn
    }
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count = var.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket_logging" "main" {
  count = var.no_logging ? 0 : 1

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"

  depends_on = [aws_s3_bucket_acl.logging]
}

data "aws_iam_policy_document" "main_deny_cleartext" {
  count = var.allow_cleartext ? 1 : 0

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  count = var.allow_cleartext ? 1 : 0

  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.main_deny_cleartext[0].json

  depends_on = [aws_s3_bucket_public_access_block.main]
}

################################################################################
# Logging bucket
################################################################################

resource "aws_kms_key" "logging" {
  count = var.no_logging ? 0 : 1

  description             = "${var.name} logging bucket encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "logging" {
  count = var.no_logging ? 0 : 1

  bucket        = "${var.name}-logging"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logging[0].arn
    }
  }
}

################################################################################
# Public read-only (GetObject) bucket
################################################################################

resource "aws_s3_bucket" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket        = "${var.name}-getonly"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

data "aws_iam_policy_document" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  statement {
    sid       = "PublicGetObject"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.getonly[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }
}

resource "aws_s3_bucket_policy" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id
  policy = data.aws_iam_policy_document.getonly[0].json

  depends_on = [aws_s3_bucket_public_access_block.getonly]
}

################################################################################
# Public read-write (s3:*) bucket
################################################################################

resource "aws_s3_bucket" "public" {
  count = var.s3_public ? 1 : 0

  bucket        = "${var.name}-public"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

data "aws_iam_policy_document" "public" {
  count = var.s3_public ? 1 : 0

  statement {
    sid     = "PublicFullAccess"
    effect  = "Allow"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.public[0].arn,
      "${aws_s3_bucket.public[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }
}

resource "aws_s3_bucket_policy" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id
  policy = data.aws_iam_policy_document.public[0].json

  depends_on = [aws_s3_bucket_public_access_block.public]
}

################################################################################
# Outputs
################################################################################

output "main_bucket_id" {
  value = aws_s3_bucket.main.id
}

output "logging_bucket_id" {
  value = var.no_logging ? null : aws_s3_bucket.logging[0].id
}

output "getonly_bucket_id" {
  value = var.s3_getobject_only ? aws_s3_bucket.getonly[0].id : null
}

output "public_bucket_id" {
  value = var.s3_public ? aws_s3_bucket.public[0].id : null
}

output "account_id" {
  value = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  managed_policy_prefix = "arn:${local.partition}:iam::aws:policy/service-role"

  drs_policy_arns = {
    agent             = "${local.managed_policy_prefix}/AWSElasticDisasterRecoveryAgentPolicy"
    failback          = "${local.managed_policy_prefix}/AWSElasticDisasterRecoveryFailbackPolicy"
    conversion_server = "${local.managed_policy_prefix}/AWSElasticDisasterRecoveryConversionServerPolicy"
    recovery_instance = "${local.managed_policy_prefix}/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
    replication       = "${local.managed_policy_prefix}/AWSElasticDisasterRecoveryReplicationServerPolicy"
  }

  ssm_managed_instance_core_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"

  ec2_service_roles = {
    conversion_server = {
      name     = "AWSElasticDisasterRecoveryConversionServerRole"
      policies = [local.drs_policy_arns.conversion_server]
    }
    recovery_instance = {
      name     = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
      policies = [local.drs_policy_arns.recovery_instance]
    }
    replication_server = {
      name     = "AWSElasticDisasterRecoveryReplicationServerRole"
      policies = [local.drs_policy_arns.replication]
    }
    recovery_instance_with_launch_actions = {
      name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
      policies = [
        local.drs_policy_arns.recovery_instance,
        local.ssm_managed_instance_core_arn,
      ]
    }
  }

  ec2_service_role_attachments = merge([
    for role_key, role in local.ec2_service_roles : {
      for policy_arn in role.policies :
      "${role_key}|${policy_arn}" => {
        role_key   = role_key
        policy_arn = policy_arn
      }
    }
  ]...)
}

################################################################################
# DRS-assumed service roles (Agent / Failback)
################################################################################

data "aws_iam_policy_document" "agent_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "failback_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "agent" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.agent_assume_role.json
}

resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = local.drs_policy_arns.agent
}

resource "aws_iam_role" "failback" {
  name               = "AWSElasticDisasterRecoveryFailbackRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.failback_assume_role.json
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = local.drs_policy_arns.failback
}

################################################################################
# EC2-assumed service roles
################################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_service" {
  for_each = local.ec2_service_roles

  name               = each.value.name
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ec2_service" {
  for_each = local.ec2_service_role_attachments

  role       = aws_iam_role.ec2_service[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

################################################################################
# Initializer role
################################################################################

data "aws_iam_policy_document" "initializer_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:userid"
      values   = [data.aws_caller_identity.current.user_id]
    }
  }
}

data "aws_iam_policy_document" "initialize" {
  statement {
    sid       = "DrsInitializeService"
    effect    = "Allow"
    actions   = ["drs:InitializeService"]
    resources = ["*"]
  }

  statement {
    sid    = "InstanceProfileManagement"
    effect = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:GetInstanceProfile",
      "iam:ListInstanceProfilesForRole",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "PassRoleToEc2AndDrs"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ec2.amazonaws.com", "drs.amazonaws.com"]
    }
  }

  statement {
    sid     = "CreateDrsServiceLinkedRole"
    effect  = "Allow"
    actions = ["iam:CreateServiceLinkedRole"]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery",
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  statement {
    sid       = "Ec2FullAccess"
    effect    = "Allow"
    actions   = ["ec2:*"]
    resources = ["*"]
  }

  statement {
    sid       = "AttachDrsManagedPolicies"
    effect    = "Allow"
    actions   = ["iam:AttachRolePolicy"]
    resources = ["*"]

    condition {
      test     = "ArnEquals"
      variable = "iam:PolicyARN"
      values = concat(
        values(local.drs_policy_arns),
        [local.ssm_managed_instance_core_arn],
      )
    }
  }
}

resource "aws_iam_role" "initializer" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.initializer_assume_role.json
}

resource "aws_iam_role_policy" "initialize" {
  name   = "InitializePolicy"
  role   = aws_iam_role.initializer.id
  policy = data.aws_iam_policy_document.initialize.json
}

output "agent_role_arn" {
  value = aws_iam_role.agent.arn
}

output "failback_role_arn" {
  value = aws_iam_role.failback.arn
}

output "ec2_service_role_arns" {
  value = { for k, r in aws_iam_role.ec2_service : r.name => r.arn }
}

output "initializer_role_arn" {
  value = aws_iam_role.initializer.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_count" {
  description = "Number of EC2 instances to launch"
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the instances; defaults to the latest Amazon Linux 2 AMI when empty"
  type        = string
  default     = ""
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  ami_id = var.ami_id != "" ? var.ami_id : data.aws_ami.amazon_linux_2.id
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = {
    Name      = "Private_Subnet_${count.index + 1}"
    Terraform = "true"
  }
}

resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC, HTTP and HTTPS from anywhere; egress restricted to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name      = "Terraform_SG_HTTP_HTTPS_SSH"
    Terraform = "true"
  }
}

resource "aws_instance" "this" {
  count = var.instance_count

  ami                         = local.ami_id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids      = [aws_security_group.allow_ssh_http_https.id]
  associate_public_ip_address = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true

    tags = {
      Name      = "Terraform_EBS_Volume1"
      Terraform = "true"
    }
  }

  tags = {
    Name      = "Terraform_Instance"
    Terraform = "true"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "ID of the security group"
  value       = aws_security_group.allow_ssh_http_https.id
}

output "instance_ids" {
  description = "IDs of the EC2 instances"
  value       = aws_instance.this[*].id
}

output "instance_private_ips" {
  description = "Private IP addresses of the EC2 instances"
  value       = aws_instance.this[*].private_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy IAM resources into."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all IAM roles."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "ecs-deployments"
  }
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Trust policies
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_service_assume" {
  statement {
    sid     = "AllowEcsAndS3Assume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com", "s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume" {
  statement {
    sid     = "AllowEcsTasksAndS3Assume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "autoscale_assume" {
  statement {
    sid     = "AllowAppAutoscalingAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codedeploy_assume" {
  statement {
    sid     = "AllowCodeDeployAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# ecsServiceRole
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ecs_service_role" {
  name               = "ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service_assume.json
  tags               = var.tags
}

data "aws_iam_policy_document" "ecs_task_role_policy" {
  statement {
    sid    = "ElasticLoadBalancing"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:DeregisterTargets",
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:ModifyRule",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2"
    effect = "Allow"
    actions = [
      "ec2:AttachNetworkInterface",
      "ec2:CreateNetworkInterface",
      "ec2:CreateNetworkInterfacePermission",
      "ec2:DeleteNetworkInterface",
      "ec2:DeleteNetworkInterfacePermission",
      "ec2:Describe*",
      "ec2:DetachNetworkInterface",
      "ec2:AuthorizeSecurityGroupIngress",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSM"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath",
      "ssm:DescribeParameters",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SecretsManager"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeDeploy"
    effect = "Allow"
    actions = [
      "codedeploy:CreateApplication",
      "codedeploy:CreateDeployment",
      "codedeploy:CreateDeploymentGroup",
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetDeploymentGroup",
      "codedeploy:GetDeploymentTarget",
      "codedeploy:ListApplications",
      "codedeploy:ListDeploymentGroups",
      "codedeploy:ListDeployments",
      "codedeploy:ListDeploymentTargets",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:StopDeployment",
      "codedeploy:ContinueDeployment",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SNS"
    effect = "Allow"
    actions = [
      "sns:Publish",
      "sns:ListTopics",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatch"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms",
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:DeleteAlarms",
      "cloudwatch:PutMetricData",
      "cloudwatch:GetMetricStatistics",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "Lambda"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "lambda:ListFunctions",
      "lambda:GetFunction",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecsTaskRolePolicy"
  role   = aws_iam_role.ecs_service_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_policy.json
}

# ---------------------------------------------------------------------------
# ecsExecTaskRole
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ecs_exec_task_role" {
  name               = "ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json
  tags               = var.tags
}

data "aws_iam_policy_document" "ecs_exec_role_policy" {
  statement {
    sid    = "ECR"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "ECSDescribe"
    effect    = "Allow"
    actions   = ["ecs:DescribeServices"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SecretsManager"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSM"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name   = "ecsExecRolePolicy"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_exec_role_policy.json
}

data "aws_iam_policy_document" "ecs_additional" {
  statement {
    sid    = "ECSListDescribe"
    effect = "Allow"
    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::*/*"]
  }
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_additional.json
}

# ---------------------------------------------------------------------------
# ecsTaskRole
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ecs_task_role" {
  name               = "ecsTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name   = "ecsTaskRole_additional"
  role   = aws_iam_role.ecs_task_role.id
  policy = data.aws_iam_policy_document.ecs_additional.json
}

# ---------------------------------------------------------------------------
# ecs_autoscale_role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ecs_autoscale_role" {
  name               = "ecs_autoscale_role"
  assume_role_policy = data.aws_iam_policy_document.autoscale_assume.json
  tags               = var.tags
}

data "aws_iam_policy_document" "ecs_autoscale_role_policy" {
  statement {
    sid    = "ECSServiceScaling"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:UpdateService",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchAlarms"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms",
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:DeleteAlarms",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name   = "ecs_autoscale_role_policy"
  role   = aws_iam_role.ecs_autoscale_role.id
  policy = data.aws_iam_policy_document.ecs_autoscale_role_policy.json
}

# ---------------------------------------------------------------------------
# ecs_codedeploy_role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ecs_codedeploy_role" {
  name               = "ecs_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_codedeploy_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy" {
  statement {
    sid    = "ECSTaskSets"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:CreateTaskSet",
      "ecs:UpdateServicePrimaryTaskSet",
      "ecs:DeleteTaskSet",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElasticLoadBalancing"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:ModifyRule",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "Lambda"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatch"
    effect    = "Allow"
    actions   = ["cloudwatch:DescribeAlarms"]
    resources = ["*"]
  }

  statement {
    sid       = "SNS"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }

  statement {
    sid    = "S3"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy.json
}

data "aws_iam_policy_document" "ecs_codedeploy_pass_task" {
  statement {
    sid       = "PassTaskRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_task_role.arn]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_pass_task.json
}

data "aws_iam_policy_document" "ecs_codedeploy_pass_task_exec" {
  statement {
    sid       = "PassTaskExecRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_exec_task_role.arn]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_pass_task_exec.json
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "ecs_service_role_arn" {
  value = aws_iam_role.ecs_service_role.arn
}

output "ecs_exec_task_role_arn" {
  value = aws_iam_role.ecs_exec_task_role.arn
}

output "ecs_task_role_arn" {
  value = aws_iam_role.ecs_task_role.arn
}

output "ecs_autoscale_role_arn" {
  value = aws_iam_role.ecs_autoscale_role.arn
}

output "ecs_codedeploy_role_arn" {
  value = aws_iam_role.ecs_codedeploy_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy the production network into"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  external_subnets = {
    "Subnet0-1a" = { cidr = "10.41.0.0/24", az_index = 0 }
    "Subnet1-1b" = { cidr = "10.41.1.0/24", az_index = 1 }
    "Subnet2-1c" = { cidr = "10.41.2.0/24", az_index = 2 }
    "Subnet3-1d" = { cidr = "10.41.3.0/24", az_index = 3 }
  }

  internal_subnets = {
    "Subnet0-1a" = { cidr = "10.40.0.0/24", az_index = 0 }
    "Subnet1-1b" = { cidr = "10.40.1.0/24", az_index = 1 }
    "Subnet2-1c" = { cidr = "10.40.2.0/24", az_index = 2 }
    "Subnet3-1d" = { cidr = "10.40.3.0/24", az_index = 3 }
  }
}

# ---------------------------------------------------------------------------
# External VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id
}

resource "aws_subnet" "external" {
  for_each = local.external_subnets

  vpc_id            = aws_vpc.external.id
  cidr_block        = each.value.cidr
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  tags = {
    Name = each.key
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External GW"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external" {
  for_each = aws_subnet.external

  subnet_id      = each.value.id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id
  subnet_ids             = [for s in aws_subnet.external : s.id]

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }
}

# ---------------------------------------------------------------------------
# Internal VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "internal" {
  cidr_block       = "10.40.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id
}

resource "aws_subnet" "internal" {
  for_each = local.internal_subnets

  vpc_id            = aws_vpc.internal.id
  cidr_block        = each.value.cidr
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  tags = {
    Name = each.key
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id
  subnet_ids             = [for s in aws_subnet.internal : s.id]

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }
}

output "external_vpc_id" {
  value = aws_vpc.external.id
}

output "internal_vpc_id" {
  value = aws_vpc.internal.id
}

output "external_subnet_ids" {
  value = { for k, s in aws_subnet.external : k => s.id }
}

output "internal_subnet_ids" {
  value = { for k, s in aws_subnet.internal : k => s.id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {}

variable "prefix" {
  description = "Prefix applied to all resource names"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN for the HTTPS listener. A self-signed certificate is generated when null."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional public URL override used for WEBHOOK_URL"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of n8n tasks"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "n8n container image"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider to use (FARGATE or FARGATE_SPOT)"
  type        = string
  default     = "FARGATE_SPOT"

  validation {
    condition     = contains(["FARGATE", "FARGATE_SPOT"], var.fargate_type)
    error_message = "fargate_type must be either FARGATE or FARGATE_SPOT."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  vpc_cidr        = "10.0.0.0/16"
  azs             = slice(data.aws_availability_zones.available.names, 0, 3)
  private_subnets = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnets  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  certificate_arn = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn
  webhook_url     = var.url != null ? var.url : "https://${aws_lb.main.dns_name}/"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-igw"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.private_subnets)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.prefix}-private-${local.azs[count.index]}"
  }
}

resource "aws_subnet" "public" {
  count                   = length(local.public_subnets)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.prefix}-public-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.prefix}-public"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-private"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb-sg"
  description = "n8n load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.prefix}-alb-sg"
  }
}

resource "aws_security_group" "service" {
  name        = "${var.prefix}-service-sg"
  description = "n8n ECS service"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n from load balancer"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.prefix}-service-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs-sg"
  description = "n8n EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.prefix}-efs-sg"
  }
}

# ---------------------------------------------------------------------------
# Certificate
# ---------------------------------------------------------------------------

resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = "${var.prefix}.internal"
    organization = var.prefix
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  tags = {
    Name = "${var.prefix}-self-signed"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Load balancer
# ---------------------------------------------------------------------------

resource "aws_lb" "main" {
  name                       = "${var.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.prefix}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = {
    Name = "${var.prefix}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ---------------------------------------------------------------------------
# EFS
# ---------------------------------------------------------------------------

resource "aws_efs_file_system" "main" {
  encrypted = true

  tags = {
    Name = "${var.prefix}-efs"
  }
}

resource "aws_efs_mount_target" "main" {
  count           = length(aws_subnet.private)
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.prefix}-ap"
  }
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "main" {
  name              = "${var.prefix}-logs"
  retention_in_days = 1
}

# ---------------------------------------------------------------------------
# IAM
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "logs" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "task" {
  name               = "${var.prefix}-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume.json
}

resource "aws_iam_role_policy" "task_logs" {
  name   = "${var.prefix}-task-logs"
  role   = aws_iam_role.task.id
  policy = data.aws_iam_policy_document.logs.json
}

resource "aws_iam_role" "execution" {
  name               = "${var.prefix}-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume.json
}

resource "aws_iam_role_policy" "execution_logs" {
  name   = "${var.prefix}-execution-logs"
  role   = aws_iam_role.execution.id
  policy = data.aws_iam_policy_document.logs.json
}

# ---------------------------------------------------------------------------
# ECS
# ---------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  task_role_arn            = aws_iam_role.task.arn
  execution_role_arn       = aws_iam_role.execution.arn

  volume {
    name = "${var.prefix}-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = var.prefix
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "${var.prefix}-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.main.name
          awslogs-region        = data.aws_region.current.name
          awslogs-stream-prefix = var.prefix
        }
      }
    }
  ])
}

resource "aws_ecs_service" "main" {
  name            = "${var.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.service.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = var.prefix
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
    aws_efs_mount_target.main,
    aws_ecs_cluster_capacity_providers.main,
  ]
}

output "load_balancer_dns_name" {
  value = aws_lb.main.dns_name
}

output "webhook_url" {
  value = local.webhook_url
}

output "efs_file_system_id" {
  value = aws_efs_file_system.main.id
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy the development network into"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr       = "10.32.0.0/20"
  primary_az     = data.aws_availability_zones.available.names[0]
  secondary_az   = data.aws_availability_zones.available.names[1]
  postgres_port  = 5432
  ssh_port       = 22
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "lambda-rds-dev-default-sg"
  }
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.this.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "db_1" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "db_2" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = local.secondary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "lambda" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "bastion" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

# -----------------------------------------------------------------------------
# Internet Gateway and public routing
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "PostgreSQL database access from bastion and lambda functions"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Lambda functions with egress restricted to the VPC"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

resource "aws_security_group" "bastion_host" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Bastion host with SSH from VPC and egress to PostgreSQL only"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

# PostgreSQL DB rules

resource "aws_vpc_security_group_egress_rule" "postgres_db_to_vpc" {
  security_group_id = aws_security_group.postgres_db.id
  description       = "Egress restricted to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = local.vpc_cidr
}

resource "aws_vpc_security_group_ingress_rule" "postgres_db_from_bastion" {
  security_group_id            = aws_security_group.postgres_db.id
  description                  = "PostgreSQL from bastion host"
  ip_protocol                  = "tcp"
  from_port                    = local.postgres_port
  to_port                      = local.postgres_port
  referenced_security_group_id = aws_security_group.bastion_host.id
}

resource "aws_vpc_security_group_ingress_rule" "postgres_db_from_lambda" {
  security_group_id            = aws_security_group.postgres_db.id
  description                  = "PostgreSQL from lambda functions"
  ip_protocol                  = "tcp"
  from_port                    = local.postgres_port
  to_port                      = local.postgres_port
  referenced_security_group_id = aws_security_group.lambda_functions.id
}

# Lambda function rules

resource "aws_vpc_security_group_egress_rule" "lambda_functions_to_vpc" {
  security_group_id = aws_security_group.lambda_functions.id
  description       = "Egress restricted to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = local.vpc_cidr
}

# Bastion host rules

resource "aws_vpc_security_group_ingress_rule" "bastion_host_ssh_from_vpc" {
  security_group_id = aws_security_group.bastion_host.id
  description       = "SSH from within the VPC"
  ip_protocol       = "tcp"
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  cidr_ipv4         = local.vpc_cidr
}

resource "aws_vpc_security_group_egress_rule" "bastion_host_to_postgres_db" {
  security_group_id            = aws_security_group.bastion_host.id
  description                  = "PostgreSQL to database security group only"
  ip_protocol                  = "tcp"
  from_port                    = local.postgres_port
  to_port                      = local.postgres_port
  referenced_security_group_id = aws_security_group.postgres_db.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  value = aws_vpc.this.id
}

output "db_subnet_ids" {
  value = [aws_subnet.db_1.id, aws_subnet.db_2.id]
}

output "lambda_subnet_id" {
  value = aws_subnet.lambda.id
}

output "bastion_subnet_id" {
  value = aws_subnet.bastion.id
}

output "postgres_db_security_group_id" {
  value = aws_security_group.postgres_db.id
}

output "lambda_functions_security_group_id" {
  value = aws_security_group.lambda_functions.id
}

output "bastion_host_security_group_id" {
  value = aws_security_group.bastion_host.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_cidr       = "10.255.0.0/16"
  admin_ssh_cidr = "203.0.113.0/24"

  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = "us-east-1a"

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = "us-east-1e"

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host access for Quasar"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.admin_ssh_cidr]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA Proxy load balancer for Quasar"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD for Quasar"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web from HA Proxy"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes for Quasar"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from Bastion and Jenkins"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    security_groups = [
      aws_security_group.bastion.id,
      aws_security_group.jenkins.id,
    ]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL RDS for Quasar"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "PostgreSQL from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from ETL"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "All traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

output "vpc_id" {
  value = aws_vpc.quasar.id
}

output "rds_subnet_ids" {
  value = [aws_subnet.rds_1a.id, aws_subnet.rds_1e.id]
}

output "security_group_ids" {
  value = {
    bastion    = aws_security_group.bastion.id
    ha_proxy   = aws_security_group.ha_proxy.id
    jenkins    = aws_security_group.jenkins.id
    etl        = aws_security_group.etl.id
    postgresql = aws_security_group.postgresql.id
  }
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables - General
################################################################################

variable "create" {
  description = "Whether to create SQS queue resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable name of the queue. A trailing `.fifo` suffix is stripped and re-applied automatically when `fifo_queue` is true"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Whether to use `name` as a prefix for the queue name"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A mapping of tags to assign to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Queue
################################################################################

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = null
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are `messageGroup` and `queue`"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are `perQueue` and `perMessageGroupId`"
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed. An integer from 0 to 900 (15 minutes)"
  type        = number
  default     = null
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it. An integer from 1024 bytes (1 KiB) up to 262144 bytes (256 KiB)"
  type        = number
  default     = null
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message. Integer representing seconds, from 60 (1 minute) to 1209600 (14 days)"
  type        = number
  default     = null
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling) before returning. An integer from 0 to 20 (seconds)"
  type        = number
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue. An integer from 0 to 43200 (12 hours)"
  type        = number
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys. Ignored when `kms_master_key_id` is set"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again. An integer representing seconds, between 60 seconds (1 minute) and 86,400 seconds (24 hours)"
  type        = number
  default     = null
}

variable "redrive_policy" {
  description = "The JSON policy (as a map) to set up the Dead Letter Queue redrive policy. When `create_dlq` is true, `deadLetterTargetArn` and `maxReceiveCount` are populated automatically and may be overridden here"
  type        = any
  default     = {}
}

variable "redrive_allow_policy" {
  description = "The JSON policy (as a map) to set up the redrive allow policy on the primary queue"
  type        = any
  default     = {}
}

################################################################################
# Variables - Queue Policy
################################################################################

variable "create_queue_policy" {
  description = "Whether to create an SQS queue policy for the primary queue"
  type        = bool
  default     = false
}

variable "source_queue_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_queue_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. In merging, statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "A map of IAM policy statements for a custom queue policy. `resources` defaults to the queue ARN when omitted"
  type        = any
  default     = {}
}

################################################################################
# Variables - Dead Letter Queue
################################################################################

variable "create_dlq" {
  description = "Whether to create an SQS dead-letter queue (DLQ)"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Human-readable name of the dead-letter queue. Defaults to `name` with `dlq_name_suffix` appended"
  type        = string
  default     = null
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the queue name to build the dead-letter queue name when `dlq_name` is not provided"
  type        = string
  default     = "-dlq"
}

variable "dlq_content_based_deduplication" {
  description = "Enables content-based deduplication for the FIFO dead-letter queue. Defaults to `content_based_deduplication`"
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level for the DLQ. Defaults to `deduplication_scope`"
  type        = string
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "FIFO throughput limit for the DLQ. Defaults to `fifo_throughput_limit`"
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the DLQ will be delayed"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message in the DLQ"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call on the DLQ will wait for a message to arrive (long polling)"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "The visibility timeout for the DLQ"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Boolean to enable SQS-managed SSE on the DLQ. Defaults to `sqs_managed_sse_enabled`. Ignored when a KMS key is in use"
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "The ID of a KMS key for the DLQ. Defaults to `kms_master_key_id`"
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period for the DLQ. Defaults to `kms_data_key_reuse_period_seconds`"
  type        = number
  default     = null
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to create a redrive allow policy on the DLQ restricting redrive to the source queue"
  type        = bool
  default     = true
}

variable "dlq_redrive_allow_policy" {
  description = "The JSON policy (as a map) merged into the DLQ redrive allow policy"
  type        = any
  default     = {}
}

variable "dlq_tags" {
  description = "A mapping of additional tags to assign to the DLQ"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Dead Letter Queue Policy
################################################################################

variable "create_dlq_queue_policy" {
  description = "Whether to create an SQS queue policy for the dead-letter queue"
  type        = bool
  default     = false
}

variable "source_dlq_queue_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported DLQ document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_dlq_queue_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported DLQ document. Statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "dlq_queue_policy_statements" {
  description = "A map of IAM policy statements for a custom DLQ policy. `resources` defaults to the DLQ ARN when omitted"
  type        = any
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  name = try(trimsuffix(var.name, ".fifo"), "")

  queue_name        = var.use_name_prefix ? null : (var.fifo_queue ? "${local.name}.fifo" : local.name)
  queue_name_prefix = var.use_name_prefix ? "${local.name}-" : null

  dlq_base_name = try(trimsuffix(coalesce(var.dlq_name, "${local.name}${var.dlq_name_suffix}"), ".fifo"), "")

  dlq_name        = var.use_name_prefix ? null : (var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name)
  dlq_name_prefix = var.use_name_prefix ? "${local.dlq_base_name}-" : null

  dlq_kms_master_key_id = try(coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id), null)
  dlq_sqs_managed_sse   = local.dlq_kms_master_key_id != null ? null : try(coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled), true)
}

################################################################################
# Queue
################################################################################

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled

  # When a DLQ is created, the redrive policy is managed by aws_sqs_queue_redrive_policy
  redrive_policy       = !var.create_dlq && length(var.redrive_policy) > 0 ? jsonencode(var.redrive_policy) : null
  redrive_allow_policy = length(var.redrive_allow_policy) > 0 ? jsonencode(var.redrive_allow_policy) : null

  tags = var.tags

  lifecycle {
    ignore_changes = [redrive_policy]
  }
}

################################################################################
# Queue Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, [aws_sqs_queue.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Redrive Policy
################################################################################

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(merge(
    {
      deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
      maxReceiveCount     = 5
    },
    var.redrive_policy
  ))
}

################################################################################
# Dead Letter Queue
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? try(coalesce(var.dlq_content_based_deduplication, var.content_based_deduplication), null) : null
  deduplication_scope         = var.fifo_queue ? try(coalesce(var.dlq_deduplication_scope, var.deduplication_scope), null) : null
  fifo_throughput_limit       = var.fifo_queue ? try(coalesce(var.dlq_fifo_throughput_limit, var.fifo_throughput_limit), null) : null

  delay_seconds              = try(coalesce(var.dlq_delay_seconds, var.delay_seconds), null)
  max_message_size           = var.max_message_size
  message_retention_seconds  = try(coalesce(var.dlq_message_retention_seconds, var.message_retention_seconds), null)
  receive_wait_time_seconds  = try(coalesce(var.dlq_receive_wait_time_seconds, var.receive_wait_time_seconds), null)
  visibility_timeout_seconds = try(coalesce(var.dlq_visibility_timeout_seconds, var.visibility_timeout_seconds), null)

  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = try(coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds), null)
  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse

  tags = merge(var.tags, var.dlq_tags)

  lifecycle {
    ignore_changes = [redrive_allow_policy]
  }
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  redrive_allow_policy = jsonencode(merge(
    {
      redrivePermission = "byQueue"
      sourceQueueArns   = [aws_sqs_queue.this[0].arn]
    },
    var.dlq_redrive_allow_policy
  ))
}

################################################################################
# Dead Letter Queue Policy
################################################################################

data "aws_iam_policy_document" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.source_dlq_queue_policy_documents
  override_policy_documents = var.override_dlq_queue_policy_documents

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, [aws_sqs_queue.dlq[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = data.aws_iam_policy_document.dlq[0].json
}

################################################################################
# Outputs
################################################################################

output "queue_id" {
  description = "The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "Same as `queue_id`: The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dead_letter_queue_id" {
  description = "The URL for the created dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "The ARN of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "Same as `dead_letter_queue_id`: The URL for the created dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "The name of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 1.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 2.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Controls whether resources should be created"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to assign to resources"
  type        = map(string)
  default     = {}
}

variable "alias_name" {
  description = "Name for the alias"
  type        = string
  default     = ""
}

variable "function_name" {
  description = "The name of the Lambda function to deploy"
  type        = string
  default     = ""
}

variable "current_version" {
  description = "Current version of Lambda function version to deploy (can't be $LATEST)"
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Target version of Lambda function version to deploy"
  type        = string
  default     = ""
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of Lambda function to execute before allow traffic during deployment. This function should be named CodeDeployHook_, to match the managed AWSCodeDeployForLambda policy, unless you're using a custom role"
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of Lambda function to execute after allow traffic during deployment. This function should be named CodeDeployHook_, to match the managed AWSCodeDeployForLambda policy, unless you're using a custom role"
  type        = string
  default     = null
}

variable "interpreter" {
  description = "List of interpreter arguments used to execute deploy script, first arg is path"
  type        = list(string)
  default     = ["/bin/bash", "-c"]
}

variable "description" {
  description = "Description to use for the deployment"
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether to create new AWS CodeDeploy app"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use existing AWS CodeDeploy app"
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of AWS CodeDeploy application"
  type        = string
  default     = ""
}

variable "create_deployment_group" {
  description = "Whether to create new AWS CodeDeploy Deployment Group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use existing AWS CodeDeploy Deployment Group"
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of deployment group to use"
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "Name of deployment config to use"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "auto_rollback_enabled" {
  description = "Indicates whether a defined automatic rollback configuration is currently enabled for this Deployment Group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "List of event types that trigger a rollback. Supported types are DEPLOYMENT_FAILURE and DEPLOYMENT_STOP_ON_ALARM."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_enabled" {
  description = "Indicates whether the alarm configuration is enabled. This option is useful when you want to temporarily deactivate alarm monitoring for a deployment group without having to add the same alarms again later."
  type        = bool
  default     = false
}

variable "alarms" {
  description = "A list of alarms configured for the deployment group. A maximum of 10 alarms can be added to a deployment group."
  type        = list(string)
  default     = []
}

variable "alarm_ignore_poll_alarm_failure" {
  description = "Indicates whether a deployment should continue if information about the current state of alarms cannot be retrieved from CloudWatch."
  type        = bool
  default     = false
}

variable "triggers" {
  description = "Map of triggers which will be notified when event happens. Valid options for event types are DeploymentStart, DeploymentSuccess, DeploymentFailure, DeploymentStop, DeploymentRollback, DeploymentReady (Applies only to replacement instances in a blue/green deployment), InstanceStart, InstanceSuccess, InstanceFailure, InstanceReady. Note that you have to specify CodeDeploy role with sns:Publish permission in order to use triggers."
  type = map(object({
    events     = list(string)
    name       = string
    target_arn = string
  }))
  default = {}
}

variable "aws_cli_command" {
  description = "Command to run as AWS CLI. May include extra arguments like region and profile."
  type        = string
  default     = "aws"
}

variable "save_deploy_script" {
  description = "Save deploy script locally"
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Create the AWS resources and script for CodeDeploy"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Run AWS CLI command to start the deployment"
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Force deployment every time (even when nothing changes)"
  type        = bool
  default     = false
}

variable "wait_deployment_completion" {
  description = "Wait until deployment completes. It can take a lot of time and your terraform process may lock execution for long time."
  type        = bool
  default     = false
}

variable "get_deployment_sleep_timer" {
  description = "Adds additional sleep time to get-deployment command to avoid the service throttling"
  type        = number
  default     = 5
}

variable "create_codedeploy_role" {
  description = "Whether to create new AWS CodeDeploy IAM role"
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "IAM role name to create or use by CodeDeploy"
  type        = string
  default     = ""
}

variable "codedeploy_principals" {
  description = "List of CodeDeploy service principals to allow. The list can include global or regional endpoints."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach Invoke policy to CodeDeploy role when before allow traffic or after allow traffic hooks are defined."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach SNS policy to CodeDeploy role when triggers are defined"
  type        = bool
  default     = false
}

################################################################################
# Locals
################################################################################

locals {
  # AWS CodeDeploy can't deploy when CurrentVersion is "$LATEST"
  current_version = var.current_version == "$LATEST" ? "1" : var.current_version

  app_name              = try(aws_codedeploy_app.this[0].name, var.app_name)
  deployment_group_name = try(aws_codedeploy_deployment_group.this[0].deployment_group_name, var.deployment_group_name)

  codedeploy_role_name = coalesce(var.codedeploy_role_name, "${local.app_name}-codedeploy")
  codedeploy_role_arn  = try(aws_iam_role.codedeploy[0].arn, data.aws_iam_role.codedeploy[0].arn, "")

  hook_arns = [
    for arn in [var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn] : arn
    if arn != null && arn != ""
  ]

  has_hooks = var.before_allow_traffic_hook_arn != null || var.after_allow_traffic_hook_arn != null

  hooks = [
    for k, v in {
      BeforeAllowTraffic = var.before_allow_traffic_hook_arn
      AfterAllowTraffic  = var.after_allow_traffic_hook_arn
    } : { (k) = v } if v != null && v != ""
  ]

  appspec = merge(
    {
      version = "0.0"
      Resources = [
        {
          MyFunction = {
            Type = "AWS::Lambda::Function"
            Properties = {
              Name           = var.function_name
              Alias          = var.alias_name
              CurrentVersion = local.current_version
              TargetVersion  = var.target_version
            }
          }
        }
      ]
    },
    { for k, v in { Hooks = local.hooks } : k => v if length(v) > 0 }
  )

  appspec_content = replace(jsonencode(local.appspec), "\"", "\\\"")
  appspec_sha256  = sha256(jsonencode(local.appspec))

  script = <<EOF
#!/bin/bash

if [ '${var.target_version}' == '${local.current_version}' ]; then
  echo "Skipping deployment because target version (${var.target_version}) is already the current version"
  exit 0
fi

ID=$(${var.aws_cli_command} deploy create-deployment \
    --application-name ${local.app_name} \
    --deployment-group-name ${local.deployment_group_name} \
    --deployment-config-name ${var.deployment_config_name} \
    --description "${var.description}" \
    --revision '{"revisionType": "AppSpecContent", "appSpecContent": {"content": "${local.appspec_content}", "sha256": "${local.appspec_sha256}"}}' \
    --output text \
    --query '[deploymentId]')

%{if var.wait_deployment_completion~}
STATUS=$(${var.aws_cli_command} deploy get-deployment \
    --deployment-id $ID \
    --output text \
    --query '[deploymentInfo.status]')

while [[ $STATUS == "Created" || $STATUS == "InProgress" || $STATUS == "Pending" || $STATUS == "Queued" || $STATUS == "Ready" ]]; do
    echo "Status: $STATUS..."
    SLEEP_TIME=${var.get_deployment_sleep_timer}
    echo "Sleeping for: $SLEEP_TIME seconds"
    sleep $SLEEP_TIME

    STATUS=$(${var.aws_cli_command} deploy get-deployment \
        --deployment-id $ID \
        --output text \
        --query '[deploymentInfo.status]')
done

${var.aws_cli_command} deploy get-deployment --deployment-id $ID

if [[ $STATUS == "Succeeded" ]]; then
    echo "Deployment succeeded."
else
    echo "Deployment failed!"
    exit 1
fi
%{else~}
${var.aws_cli_command} deploy get-deployment --deployment-id $ID
echo "Deployment started, but wait deployment completion is disabled!"
%{endif~}
EOF
}

################################################################################
# CodeDeploy Application & Deployment Group
################################################################################

resource "aws_codedeploy_app" "this" {
  count = var.create && var.create_app && !var.use_existing_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"

  tags = var.tags
}

resource "aws_codedeploy_deployment_group" "this" {
  count = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0

  app_name               = local.app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.alarm_enabled ? [true] : []

    content {
      enabled                   = var.alarm_enabled
      alarms                    = var.alarms
      ignore_poll_alarm_failure = var.alarm_ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.triggers

    content {
      trigger_events     = trigger_configuration.value.events
      trigger_name       = trigger_configuration.value.name
      trigger_target_arn = trigger_configuration.value.target_arn
    }
  }

  tags = var.tags
}

################################################################################
# IAM
################################################################################

data "aws_iam_role" "codedeploy" {
  count = var.create && !var.create_codedeploy_role ? 1 : 0

  name = local.codedeploy_role_name
}

data "aws_iam_policy_document" "assume_role" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name               = local.codedeploy_role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && local.has_hooks ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hook_arns
  }
}

resource "aws_iam_role_policy" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && local.has_hooks ? 1 : 0

  name   = "${local.codedeploy_role_name}-hooks"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.hooks[0].json
}

data "aws_iam_policy_document" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.triggers) > 0 ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [for k, v in var.triggers : v.target_arn]
  }
}

resource "aws_iam_role_policy" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.triggers) > 0 ? 1 : 0

  name   = "${local.codedeploy_role_name}-sns"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.triggers[0].json
}

################################################################################
# Deployment
################################################################################

resource "local_file" "deploy_script" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  filename             = "deploy_script_${local.appspec_sha256}.txt"
  directory_permission = "0755"
  file_permission      = "0644"
  content              = local.script
}

resource "null_resource" "deploy" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    appspec_sha256 = local.appspec_sha256
    force_deploy   = var.force_deploy ? uuid() : "false"
  }

  provisioner "local-exec" {
    command     = local.script
    interpreter = var.interpreter
  }

  depends_on = [
    aws_codedeploy_app.this,
    aws_codedeploy_deployment_group.this,
    aws_iam_role_policy_attachment.codedeploy,
    aws_iam_role_policy.hooks,
    aws_iam_role_policy.triggers,
  ]
}

################################################################################
# Outputs
################################################################################

output "codedeploy_app_name" {
  description = "Name of CodeDeploy application"
  value       = local.app_name
}

output "codedeploy_deployment_group_name" {
  description = "CodeDeploy deployment group name"
  value       = local.deployment_group_name
}

output "codedeploy_deployment_group_id" {
  description = "CodeDeploy deployment group id"
  value       = try(aws_codedeploy_deployment_group.this[0].id, "")
}

output "codedeploy_iam_role_name" {
  description = "Name of IAM role used by CodeDeploy"
  value       = try(aws_iam_role.codedeploy[0].name, local.codedeploy_role_name)
}

output "appspec" {
  description = "AppSpec definition"
  value       = local.appspec
}

output "appspec_content" {
  description = "AppSpec escaped content"
  value       = local.appspec_content
}

output "appspec_sha256" {
  description = "SHA256 of AppSpec JSON"
  value       = local.appspec_sha256
}

output "script" {
  description = "Deployment script"
  value       = local.script
}

output "deploy_script" {
  description = "Path to a deployment script"
  value       = try(local_file.deploy_script[0].filename, "")
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.16.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "name_prefix" {
  description = "Prefix for the VPC Name tag and other resource names. A random integer (1-100) is appended."
  type        = string
  default     = "tf-project"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "max_subnet_count" {
  description = "Maximum number of availability zones to randomly select from the region for subnet placement."
  type        = number
  default     = 3

  validation {
    condition     = var.max_subnet_count >= 1
    error_message = "max_subnet_count must be at least 1."
  }
}

variable "web_subnet_cidrs" {
  description = "List of CIDR blocks for the public web tier subnets."
  type        = list(string)
  default     = ["10.16.0.0/20", "10.16.16.0/20", "10.16.32.0/20"]
}

variable "web_subnet_count" {
  description = "Number of web subnets to create (capped by the length of web_subnet_cidrs)."
  type        = number
  default     = 3
}

variable "app_subnet_cidrs" {
  description = "List of CIDR blocks for the private application tier subnets."
  type        = list(string)
  default     = ["10.16.48.0/20", "10.16.64.0/20", "10.16.80.0/20"]
}

variable "app_subnet_count" {
  description = "Number of app subnets to create (capped by the length of app_subnet_cidrs)."
  type        = number
  default     = 3
}

variable "db_subnet_cidrs" {
  description = "List of CIDR blocks for the private database tier subnets."
  type        = list(string)
  default     = ["10.16.96.0/20", "10.16.112.0/20", "10.16.128.0/20"]
}

variable "db_subnet_count" {
  description = "Number of database subnets to create (capped by the length of db_subnet_cidrs)."
  type        = number
  default     = 3
}

variable "reserved_subnet_cidrs" {
  description = "List of CIDR blocks for the private reserved tier subnets."
  type        = list(string)
  default     = ["10.16.144.0/20", "10.16.160.0/20", "10.16.176.0/20"]
}

variable "reserved_subnet_count" {
  description = "Number of reserved subnets to create (capped by the length of reserved_subnet_cidrs)."
  type        = number
  default     = 3
}

variable "create_internet_gateway" {
  description = "Whether to create an internet gateway. It is only created when at least one web subnet exists."
  type        = bool
  default     = true
}

variable "interface_endpoints" {
  description = <<-EOT
    Map of interface VPC endpoints to create. Key is a logical name.
    service_name may be a short name (e.g. "ssm") or a full service name (e.g. "com.amazonaws.us-east-1.ssm").
    subnet_tier selects which private tier hosts the endpoint ENIs: "app", "db", or "reserved".
  EOT
  type = map(object({
    service_name        = string
    private_dns_enabled = optional(bool, true)
    subnet_tier         = optional(string, "app")
    security_group_ids  = optional(list(string), [])
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.interface_endpoints : contains(["app", "db", "reserved"], v.subnet_tier)
    ])
    error_message = "subnet_tier must be one of \"app\", \"db\", or \"reserved\"."
  }
}

variable "gateway_endpoint_service_name" {
  description = "Service for an optional gateway VPC endpoint (e.g. \"s3\", \"dynamodb\", or a full service name). Leave empty to skip."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

resource "random_integer" "suffix" {
  min = 1
  max = 100
}

resource "random_shuffle" "az" {
  input        = data.aws_availability_zones.available.names
  result_count = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
}

locals {
  name = "${var.name_prefix}-${random_integer.suffix.result}"

  web_count      = min(var.web_subnet_count, length(var.web_subnet_cidrs))
  app_count      = min(var.app_subnet_count, length(var.app_subnet_cidrs))
  db_count       = min(var.db_subnet_count, length(var.db_subnet_cidrs))
  reserved_count = min(var.reserved_subnet_count, length(var.reserved_subnet_cidrs))

  private_subnet_count = local.app_count + local.db_count + local.reserved_count
  create_igw           = var.create_internet_gateway && local.web_count > 0
  create_private_rt    = local.private_subnet_count > 0

  azs = random_shuffle.az.result

  gateway_endpoint_service = var.gateway_endpoint_service_name == "" ? "" : (
    length(split(".", var.gateway_endpoint_service_name)) > 1
    ? var.gateway_endpoint_service_name
    : "com.amazonaws.${var.region}.${var.gateway_endpoint_service_name}"
  )

  common_tags = merge(
    {
      Project   = var.name_prefix
      ManagedBy = "terraform"
    },
    var.tags
  )
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(local.common_tags, {
    Name = local.name
  })
}

resource "aws_subnet" "web" {
  count = local.web_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.web_subnet_cidrs[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-web-${count.index + 1}"
    Tier = "web"
  })
}

resource "aws_subnet" "app" {
  count = local.app_count

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.app_subnet_cidrs[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(local.common_tags, {
    Name = "${local.name}-app-${count.index + 1}"
    Tier = "app"
  })
}

resource "aws_subnet" "db" {
  count = local.db_count

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.db_subnet_cidrs[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(local.common_tags, {
    Name = "${local.name}-db-${count.index + 1}"
    Tier = "db"
  })
}

resource "aws_subnet" "reserved" {
  count = local.reserved_count

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.reserved_subnet_cidrs[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(local.common_tags, {
    Name = "${local.name}-reserved-${count.index + 1}"
    Tier = "reserved"
  })
}

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_route_table" "public" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "web" {
  count = local.create_igw ? local.web_count : 0

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = local.create_private_rt ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route_table_association" "app" {
  count = local.app_count

  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "db" {
  count = local.db_count

  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count = local.reserved_count

  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Interface endpoints allow at most one subnet per AZ, so pick the first subnet of each tier per AZ.
locals {
  tier_subnets_by_az = {
    app      = { for az, ids in { for s in aws_subnet.app : s.availability_zone => s.id... } : az => ids[0] }
    db       = { for az, ids in { for s in aws_subnet.db : s.availability_zone => s.id... } : az => ids[0] }
    reserved = { for az, ids in { for s in aws_subnet.reserved : s.availability_zone => s.id... } : az => ids[0] }
  }
}

resource "aws_security_group" "endpoints" {
  count = length(var.interface_endpoints) > 0 ? 1 : 0

  name        = "${local.name}-vpce-sg"
  description = "Allow HTTPS from within the VPC to interface endpoints"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.this.cidr_block]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpce-sg"
  })
}

resource "aws_vpc_endpoint" "interface" {
  for_each = var.interface_endpoints

  vpc_id              = aws_vpc.this.id
  vpc_endpoint_type   = "Interface"
  service_name        = length(split(".", each.value.service_name)) > 1 ? each.value.service_name : "com.amazonaws.${var.region}.${each.value.service_name}"
  private_dns_enabled = each.value.private_dns_enabled
  subnet_ids          = values(local.tier_subnets_by_az[each.value.subnet_tier])
  security_group_ids  = length(each.value.security_group_ids) > 0 ? each.value.security_group_ids : [aws_security_group.endpoints[0].id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-${each.key}-vpce"
  })
}

resource "aws_vpc_endpoint" "gateway" {
  count = local.gateway_endpoint_service != "" ? 1 : 0

  vpc_id            = aws_vpc.this.id
  vpc_endpoint_type = "Gateway"
  service_name      = local.gateway_endpoint_service
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-gateway-vpce"
  })
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.this.id
}

output "vpc_name" {
  description = "Name tag of the VPC."
  value       = local.name
}

output "selected_availability_zones" {
  description = "Randomly shuffled availability zones used for subnet placement."
  value       = local.azs
}

output "web_subnet_ids" {
  description = "IDs of the web subnets."
  value       = aws_subnet.web[*].id
}

output "app_subnet_ids" {
  description = "IDs of the app subnets."
  value       = aws_subnet.app[*].id
}

output "db_subnet_ids" {
  description = "IDs of the database subnets."
  value       = aws_subnet.db[*].id
}

output "reserved_subnet_ids" {
  description = "IDs of the reserved subnets."
  value       = aws_subnet.reserved[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway, if created."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "public_route_table_id" {
  description = "ID of the public route table, if created."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_id" {
  description = "ID of the shared private route table, if created."
  value       = try(aws_route_table.private[0].id, null)
}

output "interface_endpoint_ids" {
  description = "Map of interface VPC endpoint IDs."
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

output "gateway_endpoint_id" {
  description = "ID of the gateway VPC endpoint, if created."
  value       = try(aws_vpc_endpoint.gateway[0].id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "internal_domain_name" {
  description = "Internal domain name used for DHCP options and the private hosted zone."
  type        = string
  default     = "internal"
}

variable "dns_servers" {
  description = "DNS resolvers handed out via DHCP options (VPC built-in resolver plus a public DNS server)."
  type        = list(string)
  default     = ["10.0.0.2", "8.8.8.8"]
}

variable "admin_cidrs" {
  description = "CIDR blocks allowed to SSH into instances in the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

locals {
  vpc_cidr = "10.0.0.0/16"

  subnets = {
    reserved   = "10.0.0.0/24"
    sandbox    = "10.0.1.0/24"
    web        = "10.0.2.0/24"
    database   = "10.0.3.0/24"
    gameserver = "10.0.4.0/22"
  }
}

# ---------------------------------------------------------------------------
# VPC, Internet Gateway, DHCP options, private DNS
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain_name
  domain_name_servers = var.dns_servers

  tags = {
    Name = "main"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = var.internal_domain_name
  }
}

# ---------------------------------------------------------------------------
# Subnets and route tables
# ---------------------------------------------------------------------------

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  map_public_ip_on_launch = false

  tags = {
    Name = each.key
  }
}

resource "aws_route_table" "this" {
  for_each = local.subnets

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = each.key
  }
}

resource "aws_route_table_association" "this" {
  for_each = local.subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.this[each.key].id
}

# ---------------------------------------------------------------------------
# Network ACLs
# ---------------------------------------------------------------------------

resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.this["sandbox"].id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "sandbox"
  }
}

resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.this["web"].id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "web"
  }
}

resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.this["database"].id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.subnets["web"]
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.subnets["gameserver"]
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.subnets["web"]
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.subnets["gameserver"]
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "database"
  }
}

resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.this["gameserver"].id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    rule_no    = 120
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    rule_no    = 140
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    rule_no    = 150
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  ingress {
    rule_no    = 160
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 110
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "gameserver"
  }
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from admin networks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    protocol    = "tcp"
    from_port   = 22
    to_port     = 22
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from members of this group"
    protocol    = "tcp"
    from_port   = 22
    to_port     = 22
    self        = true
  }

  egress {
    description = "All traffic to the VPC"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from within the VPC for Packer builds"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC"
    protocol    = "tcp"
    from_port   = 22
    to_port     = 22
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from members of this group"
    protocol    = "tcp"
    from_port   = 22
    to_port     = 22
    self        = true
  }

  egress {
    description = "All traffic to the VPC"
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Packer SSH"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  value = aws_vpc.main.id
}

output "subnet_ids" {
  value = { for k, s in aws_subnet.this : k => s.id }
}

output "private_zone_id" {
  value = aws_route53_zone.internal.zone_id
}

output "home_ssh_security_group_id" {
  value = aws_security_group.home_ssh.id
}

output "packer_ssh_security_group_id" {
  value = aws_security_group.packer_ssh.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment name used to prefix resource Name tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private application subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "database_subnet_cidrs" {
  description = "CIDR blocks for the private database subnets"
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.env}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.env}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.env}-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.env}-private-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "database" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.database_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.env}-database-subnet-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${var.env}-nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.env}-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.env}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${var.env}-private-rt-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = var.vpc_cidr
    gateway_id = "local"
  }

  tags = {
    Name = "${var.env}-database-rt"
  }
}

resource "aws_route_table_association" "database" {
  count          = 3
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "database_subnet_ids" {
  value = aws_subnet.database[*].id
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.main[*].id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region in which to create the bucket."
  type        = string
  default     = "us-east-1"
}

variable "bucket" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the AWS IAM account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Prefix the bucket name with a random suffix (ignored when use_account_alias_prefix is true)."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional JSON bucket policy document to be merged with the enforced policy statements."
  type        = string
  default     = ""
}

variable "enable_s3_public_access_block" {
  description = "Enable the S3 public access block on the bucket."
  type        = bool
  default     = true
}

variable "control_object_ownership" {
  description = "Whether to manage S3 bucket ownership controls."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership setting: BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  }
}

variable "kms_master_key_id" {
  description = "KMS key ID/ARN for SSE-KMS. When empty, AES256 (SSE-S3) is used."
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Whether to use an S3 Bucket Key for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning state of the bucket: Enabled, Suspended or Disabled."
  type        = string
  default     = "Enabled"

  validation {
    condition     = contains(["Enabled", "Suspended", "Disabled"], var.versioning_status)
    error_message = "versioning_status must be one of Enabled, Suspended or Disabled."
  }
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects."
  type        = bool
  default     = false
}

variable "transition_default_minimum_object_size" {
  description = "Default minimum object size behavior applied to lifecycle transitions."
  type        = string
  default     = "all_storage_classes_128K"
}

variable "abort_incomplete_multipart_upload_days" {
  description = "Days after initiation to abort incomplete multipart uploads."
  type        = number
  default     = 14
}

variable "noncurrent_version_transition_days" {
  description = "Days after which noncurrent versions transition to STANDARD_IA."
  type        = number
  default     = 30
}

variable "noncurrent_version_expiration_days" {
  description = "Days after which noncurrent versions are expired."
  type        = number
  default     = 365
}

variable "enable_analytics" {
  description = "Enable storage class analytics for the entire bucket."
  type        = bool
  default     = true
}

variable "analytics_prefix" {
  description = "Prefix under which analytics exports are written."
  type        = string
  default     = "_AWSBucketAnalytics/"
}

variable "analytics_expiration_days" {
  description = "Days after which analytics export objects expire."
  type        = number
  default     = 30
}

variable "enable_bucket_inventory" {
  description = "Enable S3 bucket inventory reporting."
  type        = bool
  default     = false
}

variable "inventory_prefix" {
  description = "Prefix under which inventory reports are written."
  type        = string
  default     = "_AWSBucketInventory/"
}

variable "inventory_format" {
  description = "Output format of the inventory reports."
  type        = string
  default     = "ORC"
}

variable "inventory_frequency" {
  description = "Inventory report schedule frequency."
  type        = string
  default     = "Weekly"
}

variable "inventory_expiration_days" {
  description = "Days after which inventory report objects expire."
  type        = number
  default     = 14
}

variable "logging_bucket" {
  description = "Target bucket for server access logs. Logging is disabled when empty."
  type        = string
  default     = ""
}

variable "transfer_acceleration" {
  description = "Transfer acceleration: true (Enabled), false (Suspended), or null to leave unmanaged."
  type        = bool
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply to the bucket. Requires object_ownership other than BucketOwnerEnforced."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules to apply to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "tags" {
  description = "Tags to apply to the bucket."
  type        = map(string)
  default     = {}
}

################################################################################
# Naming
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

resource "random_id" "prefix" {
  count       = var.use_random_suffix && !var.use_account_alias_prefix ? 1 : 0
  byte_length = 4
}

locals {
  bucket_prefix = (
    var.use_account_alias_prefix ? "${data.aws_iam_account_alias.current[0].account_alias}-" :
    var.use_random_suffix ? "${random_id.prefix[0].hex}-" :
    ""
  )

  bucket_name = "${local.bucket_prefix}${var.bucket}"

  sse_algorithm = var.kms_master_key_id != "" ? "aws:kms" : "AES256"
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != "" ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration ? "Enabled" : "Suspended"
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

################################################################################
# Lifecycle
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = var.transition_default_minimum_object_size

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = var.abort_incomplete_multipart_upload_days
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = var.noncurrent_version_transition_days
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_expiration_days
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []

    content {
      id     = "expire-analytics-exports"
      status = "Enabled"

      filter {
        prefix = var.analytics_prefix
      }

      expiration {
        days = var.analytics_expiration_days
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "expire-inventory-reports"
      status = "Enabled"

      filter {
        prefix = var.inventory_prefix
      }

      expiration {
        days = var.inventory_expiration_days
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Analytics & Inventory
################################################################################

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucket"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn        = aws_s3_bucket.this.arn
          bucket_account_id = data.aws_caller_identity.current.account_id
          format            = "CSV"
          prefix            = var.analytics_prefix
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket                   = aws_s3_bucket.this.id
  name                     = "EntireBucketDaily"
  included_object_versions = "All"

  schedule {
    frequency = var.inventory_frequency
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
    "ObjectLockRetainUntilDate",
    "ObjectLockMode",
    "ObjectLockLegalHoldStatus",
    "IntelligentTieringAccessTier",
    "BucketKeyStatus",
    "ChecksumAlgorithm",
  ]

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      account_id = data.aws_caller_identity.current.account_id
      format     = var.inventory_format
      prefix     = var.inventory_prefix

      dynamic "encryption" {
        for_each = var.kms_master_key_id != "" ? [1] : []

        content {
          sse_kms {
            key_id = var.kms_master_key_id
          }
        }
      }

      dynamic "encryption" {
        for_each = var.kms_master_key_id == "" ? [1] : []

        content {
          sse_s3 {}
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

################################################################################
# Bucket Policy
################################################################################

data "aws_iam_policy_document" "bucket_policy" {
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid     = "AllowS3InventoryAndAnalyticsWrites"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.this.arn}/${var.analytics_prefix}*",
      "${aws_s3_bucket.this.arn}/${var.inventory_prefix}*",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# Outputs
################################################################################

output "bucket_id" {
  description = "Name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "Regional domain name of the bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_policy" {
  description = "Effective bucket policy JSON."
  value       = data.aws_iam_policy_document.bucket_policy.json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which to create the bucket."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket."
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment tag value."
  type        = string
  default     = "Development"
}

variable "tags" {
  description = "Additional tags to apply to the bucket."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects."
  type        = bool
  default     = false
}

# Server-side encryption

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: AES256, aws:kms, or none."
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "aws:kms", "aws:kms:dsse", "none"], var.sse_algorithm)
    error_message = "sse_algorithm must be one of AES256, aws:kms, aws:kms:dsse, or none."
  }
}

variable "kms_key_id" {
  description = "KMS key ID or ARN used when sse_algorithm is aws:kms."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 Bucket Keys for SSE-KMS."
  type        = bool
  default     = false
}

# Public access block

variable "block_public_access" {
  description = "Whether to create the S3 public access block."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies."
  type        = bool
  default     = true
}

# ACL / grants / ownership

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g. private, log-delivery-write). Ignored when grants are supplied."
  type        = string
  default     = null
}

variable "grants" {
  description = <<-EOT
    JSON-encoded list of grants. Example:
    [{"type":"CanonicalUser","id":"<canonical-id>","permission":"FULL_CONTROL"},
     {"type":"Group","uri":"http://acs.amazonaws.com/groups/s3/LogDelivery","permission":"WRITE"}]
  EOT
  type        = string
  default     = "[]"
}

variable "acl_owner_id" {
  description = "Canonical user ID of the ACL owner. Defaults to the caller identity canonical user ID."
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Whether to manage S3 bucket ownership controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting: BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced."
  type        = string
  default     = "ObjectWriter"

  validation {
    condition     = contains(["BucketOwnerPreferred", "ObjectWriter", "BucketOwnerEnforced"], var.object_ownership)
    error_message = "object_ownership must be BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced."
  }
}

# Versioning

variable "versioning_enabled" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete (requires versioning and the mfa variable)."
  type        = bool
  default     = false
}

variable "mfa" {
  description = "Concatenation of the authentication device serial number, a space, and the MFA token value. Required when mfa_delete is true."
  type        = string
  default     = null
  sensitive   = true
}

# Logging

variable "bucket_logging" {
  description = "Enable server access logging."
  type        = bool
  default     = false
}

variable "logging_bucket_name" {
  description = "Target bucket name for server access logs."
  type        = string
  default     = ""
}

variable "logging_bucket_prefix" {
  description = "Prefix for server access log objects."
  type        = string
  default     = ""
}

# Object lock

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock (only effective at bucket creation)."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default Object Lock retention mode: GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_retention_days" {
  description = "Default Object Lock retention in days. Mutually exclusive with object_lock_retention_years."
  type        = number
  default     = null
}

variable "object_lock_retention_years" {
  description = "Default Object Lock retention in years. Mutually exclusive with object_lock_retention_days."
  type        = number
  default     = null
}

# Website

variable "website" {
  description = <<-EOT
    Static website configuration map. Supported keys:
      index_document           = "index.html"
      error_document           = "error.html"
      redirect_all_requests_to = { host_name = "example.com", protocol = "https" }
      routing_rules            = "<JSON string of routing rules>"
  EOT
  type        = any
  default     = {}
}

# Intelligent tiering

variable "intelligent_tiering" {
  description = <<-EOT
    Map of intelligent tiering configurations keyed by name. Example:
      {
        archive = {
          status   = "Enabled"
          filter   = { prefix = "logs/", tags = { tier = "archive" } }
          tierings = { ARCHIVE_ACCESS = { days = 90 }, DEEP_ARCHIVE_ACCESS = { days = 180 } }
        }
      }
  EOT
  type        = any
  default     = {}
}

# CloudWatch metrics

variable "metric_configuration" {
  description = <<-EOT
    Map of CloudWatch request metric configurations keyed by name. Example:
      {
        EntireBucket = {}
        Logs         = { filter = { prefix = "logs/", tags = { team = "ops" } } }
      }
  EOT
  type        = any
  default     = {}
}

# CORS

variable "cors_rules" {
  description = <<-EOT
    JSON-encoded list of CORS rules. Example:
    [{"allowed_methods":["GET"],"allowed_origins":["*"],"allowed_headers":["*"],"expose_headers":["ETag"],"max_age_seconds":3000}]
  EOT
  type        = string
  default     = "[]"
}

# Lifecycle

variable "lifecycle_rules" {
  description = <<-EOT
    JSON-encoded list of lifecycle rules. Example:
    [{
      "id": "expire-logs",
      "enabled": true,
      "filter": {"prefix": "logs/"},
      "abort_incomplete_multipart_upload_days": 7,
      "expiration": {"days": 365},
      "transition": [{"days": 30, "storage_class": "STANDARD_IA"}],
      "noncurrent_version_transition": [{"noncurrent_days": 30, "storage_class": "GLACIER"}],
      "noncurrent_version_expiration": {"noncurrent_days": 90}
    }]
  EOT
  type        = string
  default     = "[]"
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_canonical_user_id" "current" {}

locals {
  default_tags = merge(
    var.tags,
    {
      Environment     = var.environment
      ServiceProvider = "Rackspace"
    }
  )

  grants          = jsondecode(var.grants)
  cors_rules      = jsondecode(var.cors_rules)
  lifecycle_rules = jsondecode(var.lifecycle_rules)

  use_grants = length(local.grants) > 0
  create_acl = local.use_grants || var.acl != null

  create_encryption = var.sse_algorithm != "none"
  is_kms            = startswith(var.sse_algorithm, "aws:kms")

  create_website = length(keys(var.website)) > 0

  versioning_status = (var.versioning_enabled || var.object_lock_enabled) ? "Enabled" : "Suspended"
  mfa_delete_status = var.mfa_delete ? "Enabled" : "Disabled"

  object_lock_has_retention = var.object_lock_retention_days != null || var.object_lock_retention_years != null
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.default_tags
}

###############################################################################
# Public access block
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.block_public_access ? 1 : 0

  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

###############################################################################
# Ownership controls
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# ACL / grants
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = local.use_grants ? null : var.acl

  dynamic "access_control_policy" {
    for_each = local.use_grants ? [1] : []

    content {
      dynamic "grant" {
        for_each = local.grants

        content {
          permission = grant.value.permission

          grantee {
            type          = grant.value.type
            id            = try(grant.value.id, null)
            uri           = try(grant.value.uri, null)
            email_address = try(grant.value.email, null)
          }
        }
      }

      owner {
        id = coalesce(var.acl_owner_id, data.aws_canonical_user_id.current.id)
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

###############################################################################
# Server-side encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_encryption ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = local.is_kms ? var.kms_key_id : null
    }

    bucket_key_enabled = local.is_kms ? var.bucket_key_enabled : null
  }
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  mfa    = var.mfa_delete ? var.mfa : null

  versioning_configuration {
    status     = local.versioning_status
    mfa_delete = local.mfa_delete_status
  }
}

###############################################################################
# Logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = var.bucket_logging ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket_name
  target_prefix = var.logging_bucket_prefix
}

###############################################################################
# Object lock
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.object_lock_has_retention ? [1] : []

    content {
      default_retention {
        mode  = var.object_lock_mode
        days  = var.object_lock_retention_days
        years = var.object_lock_retention_years
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_website ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  routing_rules = try(var.website.routing_rules, null)
}

###############################################################################
# Intelligent tiering
###############################################################################

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = var.intelligent_tiering

  bucket = aws_s3_bucket.this.id
  name   = each.key
  status = try(each.value.status, "Enabled")

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = each.value.tierings

    content {
      access_tier = tiering.key
      days        = tiering.value.days
    }
  }
}

###############################################################################
# CloudWatch request metrics
###############################################################################

resource "aws_s3_bucket_metric" "this" {
  for_each = var.metric_configuration

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(local.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = local.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Lifecycle
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(local.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.lifecycle_rules

    content {
      id     = try(rule.value.id, "rule-${rule.key}")
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = [try(rule.value.filter, { prefix = try(rule.value.prefix, null) })]

        content {
          prefix = length(try(filter.value.tags, {})) == 0 ? try(filter.value.prefix, null) : null

          dynamic "and" {
            for_each = length(try(filter.value.tags, {})) > 0 ? [filter.value] : []

            content {
              prefix = try(and.value.prefix, null)
              tags   = and.value.tags
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])

        content {
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, noncurrent_version_transition.value.days, null)
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, noncurrent_version_expiration.value.days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "Name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Bucket regional domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "website_endpoint" {
  description = "Static website endpoint, if website hosting is enabled."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "tags" {
  description = "Tags applied to the bucket."
  value       = aws_s3_bucket.this.tags_all
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name of the S3 bucket. Conflicts with name_prefix."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || length(coalesce(var.name, "x")) <= 63
    error_message = "The bucket name must be 63 characters or fewer."
  }
}

variable "name_prefix" {
  description = "Prefix for a generated bucket name. Conflicts with name."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || length(coalesce(var.name_prefix, "x")) <= 37
    error_message = "The bucket name prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  }
}

variable "acl" {
  description = "Canned ACL applied only when object_ownership is ObjectWriter."
  type        = string
  default     = "private"
}

variable "block_public_acls" {
  description = "Block public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs on the bucket and its objects."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "KMS key ARN for SSE-KMS. When null, AES256 (SSE-S3) is used."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Enable bucket versioning. When false, versioning is Suspended (unless required by object lock or replication)."
  type        = bool
  default     = false
}

variable "policy" {
  description = "Optional custom bucket policy JSON merged with enforced policies."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "ARNs of source buckets permitted to deliver server access logs to this bucket."
  type        = list(string)
  default     = []
}

variable "eventbridge_enabled" {
  description = "Enable Amazon EventBridge notifications for this bucket."
  type        = bool
  default     = false
}

variable "logging" {
  description = "Server access logging configuration for this bucket."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket (must be set at creation)."
  type        = bool
  default     = false
}

variable "object_lock_rule" {
  description = "Default object lock retention rule. Specify either days or years."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null

  validation {
    condition = var.object_lock_rule == null || (
      contains(["GOVERNANCE", "COMPLIANCE"], try(var.object_lock_rule.mode, "")) &&
      ((try(var.object_lock_rule.days, null) == null) != (try(var.object_lock_rule.years, null) == null))
    )
    error_message = "object_lock_rule.mode must be GOVERNANCE or COMPLIANCE, and exactly one of days or years must be set."
  }
}

variable "replication" {
  description = "Cross-region replication configuration."
  type = object({
    role_arn = string
    rules = list(object({
      id                        = string
      priority                  = number
      status                    = optional(string, "Enabled")
      prefix                    = optional(string, "")
      destination_bucket_arn    = string
      storage_class             = optional(string, "STANDARD")
      replica_kms_key_arn       = optional(string)
      destination_account_id    = optional(string)
      delete_marker_replication = optional(bool, false)
      sse_kms_encrypted_objects = optional(bool, false)
    }))
  })
  default = null

  validation {
    condition = var.replication == null || (
      length(distinct([for r in try(var.replication.rules, []) : r.priority])) == length(try(var.replication.rules, []))
    )
    error_message = "Each replication rule must have a unique priority."
  }
}

variable "inventory_configurations" {
  description = "Map of inventory configurations keyed by inventory name."
  type = map(object({
    enabled                  = optional(bool, true)
    included_object_versions = optional(string, "Current")
    frequency                = optional(string, "Daily")
    prefix                   = optional(string)
    optional_fields          = optional(list(string), [])
    destination_bucket_arn   = string
    destination_prefix       = optional(string)
    destination_account_id   = optional(string)
    format                   = optional(string, "Parquet")
    encryption = optional(object({
      type        = string
      kms_key_arn = optional(string)
    }))
  }))
  default = {}

  validation {
    condition = alltrue([
      for k, v in var.inventory_configurations :
      contains(["Daily", "Weekly"], v.frequency) &&
      contains(["CSV", "ORC", "Parquet"], v.format) &&
      (v.encryption == null || contains(["SSE-KMS", "SSE-S3"], try(v.encryption.type, "")))
    ])
    error_message = "Inventory frequency must be Daily/Weekly, format CSV/ORC/Parquet, and encryption type SSE-KMS or SSE-S3."
  }
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    id              = optional(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string), [])
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules."
  type = list(object({
    id                                     = string
    enabled                                = optional(bool, true)
    prefix                                 = optional(string, "")
    expiration_days                        = optional(number)
    expired_object_delete_marker           = optional(bool)
    transitions                            = optional(list(object({ days = number, storage_class = string })), [])
    noncurrent_version_expiration_days     = optional(number)
    newer_noncurrent_versions              = optional(number)
    noncurrent_version_transitions         = optional(list(object({ days = number, storage_class = string })), [])
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "tags" {
  description = "Tags applied to the bucket."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals & Data
################################################################################

data "aws_caller_identity" "current" {}

locals {
  sse_algorithm   = var.kms_key_arn != null ? "aws:kms" : "AES256"
  logging_enabled = length(var.logging_source_bucket_arns) > 0

  versioning_status = (
    var.versioning_enabled || var.object_lock_enabled || var.replication != null
  ) ? "Enabled" : "Suspended"
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.name
  bucket_prefix       = var.name == null ? var.name_prefix : null
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = var.tags
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = var.kms_key_arn != null
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = local.versioning_status
  }
}

################################################################################
# Bucket Policy
################################################################################

data "aws_iam_policy_document" "this" {
  source_policy_documents = compact([var.policy])

  statement {
    sid     = "EnforceSSLOnly"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = local.logging_enabled ? [1] : []

    content {
      sid       = "S3ServerAccessLogsPolicy"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this.arn}/*"]

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# Event Notifications
################################################################################

resource "aws_s3_bucket_notification" "this" {
  count = var.eventbridge_enabled ? 1 : 0

  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

################################################################################
# Server Access Logging
################################################################################

resource "aws_s3_bucket_logging" "this" {
  count = var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix

  lifecycle {
    precondition {
      condition     = !(var.object_lock_enabled && var.object_lock_rule != null && var.logging.target_bucket == aws_s3_bucket.this.id)
      error_message = "Server access logs cannot be delivered to a bucket with an Object Lock default retention period configured."
    }
  }
}

################################################################################
# Object Lock
################################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled && var.object_lock_rule != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_rule.mode
      days  = var.object_lock_rule.days
      years = var.object_lock_rule.years
    }
  }

  lifecycle {
    precondition {
      condition     = !local.logging_enabled
      error_message = "Object Lock default retention cannot be configured on a bucket that receives server access logs (logging_source_bucket_arns must be empty)."
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Replication
################################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.replication != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = var.replication.role_arn

  dynamic "rule" {
    for_each = var.replication.rules

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      filter {
        prefix = rule.value.prefix
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.sse_kms_encrypted_objects ? [1] : []

        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.storage_class
        account       = rule.value.destination_account_id

        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_key_arn != null ? [1] : []

          content {
            replica_kms_key_id = rule.value.replica_kms_key_arn
          }
        }

        dynamic "access_control_translation" {
          for_each = rule.value.destination_account_id != null ? [1] : []

          content {
            owner = "Destination"
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Inventory
################################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = var.inventory_configurations

  bucket                   = aws_s3_bucket.this.id
  name                     = each.key
  enabled                  = each.value.enabled
  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields

  schedule {
    frequency = each.value.frequency
  }

  dynamic "filter" {
    for_each = each.value.prefix != null ? [1] : []

    content {
      prefix = each.value.prefix
    }
  }

  destination {
    bucket {
      bucket_arn = each.value.destination_bucket_arn
      format     = each.value.format
      prefix     = each.value.destination_prefix
      account_id = each.value.destination_account_id

      dynamic "encryption" {
        for_each = each.value.encryption != null ? [each.value.encryption] : []

        content {
          dynamic "sse_kms" {
            for_each = encryption.value.type == "SSE-KMS" ? [1] : []

            content {
              key_id = encryption.value.kms_key_arn
            }
          }

          dynamic "sse_s3" {
            for_each = encryption.value.type == "SSE-S3" ? [1] : []

            content {}
          }
        }
      }
    }
  }
}

################################################################################
# CORS
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

################################################################################
# Lifecycle
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        prefix = rule.value.prefix
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null || rule.value.expired_object_delete_marker != null ? [1] : []

        content {
          days                         = rule.value.expiration_days
          expired_object_delete_marker = rule.value.expiration_days == null ? rule.value.expired_object_delete_marker : null
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []

        content {
          noncurrent_days           = rule.value.noncurrent_version_expiration_days
          newer_noncurrent_versions = rule.value.newer_noncurrent_versions
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []

        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Outputs
################################################################################

output "bucket_id" {
  description = "Name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Bucket region-specific domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_policy_json" {
  description = "Effective bucket policy JSON."
  value       = data.aws_iam_policy_document.this.json
}

output "versioning_status" {
  description = "Effective versioning status."
  value       = local.versioning_status
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the provider and the only region where developers may create S3 buckets."
  type        = string
  default     = "us-east-1"
}

variable "group_name_prefix" {
  description = "Prefix used for IAM group names."
  type        = string
  default     = "app"
}

variable "remote_state_bucket_name" {
  description = "Name of the S3 bucket holding Terraform remote state, which developers must not access."
  type        = string
  default     = "terraform-remote-state"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  mfa_present_condition = {
    Bool = {
      "aws:MultiFactorAuthPresent" = "true"
    }
  }
}

# -----------------------------------------------------------------------------
# Account-wide security baselines
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
}

resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# IAM groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

# -----------------------------------------------------------------------------
# Developer group: AWS-managed policies
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMUserSSHKeys"
}

# -----------------------------------------------------------------------------
# Developer group: custom policies
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "manage_own_access_keys" {
  name        = "${var.group_name_prefix}_manage_own_access_keys"
  description = "Allow users to manage their own access keys."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:GetAccessKeyLastUsed",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_policy" "manage_own_virtual_mfa" {
  name        = "${var.group_name_prefix}_manage_own_virtual_mfa"
  description = "Allow users to manage their own virtual MFA device; deactivation requires MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListVirtualMFADevices"
        Effect   = "Allow"
        Action   = ["iam:ListVirtualMFADevices"]
        Resource = "*"
      },
      {
        Sid    = "ManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice",
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
      },
      {
        Sid    = "ManageOwnUserMFA"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice",
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      },
      {
        Sid       = "DeactivateOwnMFAWithMFA"
        Effect    = "Allow"
        Action    = ["iam:DeactivateMFADevice"]
        Resource  = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
        Condition = local.mfa_present_condition
      }
    ]
  })
}

resource "aws_iam_policy" "developer_s3" {
  name        = "${var.group_name_prefix}_developer_s3"
  description = "MFA-gated S3 access restricted to a single region and excluding the remote-state bucket."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3WithMFA"
        Effect    = "Allow"
        Action    = ["s3:*"]
        Resource  = "*"
        Condition = local.mfa_present_condition
      },
      {
        Sid      = "DenyCreateBucketOutsideRegion"
        Effect   = "Deny"
        Action   = ["s3:CreateBucket"]
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.aws_region
          }
        }
      },
      {
        Sid    = "DenyRemoteStateBucket"
        Effect = "Deny"
        Action = ["s3:*"]
        Resource = [
          "arn:${local.partition}:s3:::${var.remote_state_bucket_name}",
          "arn:${local.partition}:s3:::${var.remote_state_bucket_name}/*",
        ]
      }
    ]
  })
}

resource "aws_iam_policy" "developer_compute" {
  name        = "${var.group_name_prefix}_developer_compute"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling and related service-linked roles."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowComputeServicesWithMFA"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*",
        ]
        Resource  = "*"
        Condition = local.mfa_present_condition
      },
      {
        Sid    = "AllowServiceLinkedRolesWithMFA"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:GetRole",
          "iam:PassRole",
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling*",
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spot.amazonaws.com/AWSServiceRoleForEC2Spot",
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spotfleet.amazonaws.com/AWSServiceRoleForEC2SpotFleet",
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/elasticloadbalancing.amazonaws.com/AWSServiceRoleForElasticLoadBalancing",
        ]
        Condition = local.mfa_present_condition
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_manage_own_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_own_access_keys.arn
}

resource "aws_iam_group_policy_attachment" "developer_manage_own_virtual_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_own_virtual_mfa.arn
}

resource "aws_iam_group_policy_attachment" "developer_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3.arn
}

resource "aws_iam_group_policy_attachment" "developer_compute" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_compute.arn
}

# -----------------------------------------------------------------------------
# Administrative access
# -----------------------------------------------------------------------------

resource "aws_iam_role" "admin" {
  name = "admin"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootAssume"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "admin_full_access_with_mfa" {
  name        = "${var.group_name_prefix}_admin_full_access_with_mfa"
  description = "Full administrative access conditioned on active MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullAccessWithMFA"
        Effect    = "Allow"
        Action    = "*"
        Resource  = "*"
        Condition = local.mfa_present_condition
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_full_access_with_mfa" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access_with_mfa.arn
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${var.group_name_prefix}_assume_admin_role"
  description = "Allow admin group members to assume the admin role when MFA is present."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AssumeAdminRoleWithMFA"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Resource  = aws_iam_role.admin.arn
        Condition = local.mfa_present_condition
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

output "developer_group_name" {
  value = aws_iam_group.developer.name
}

output "admin_group_name" {
  value = aws_iam_group.admin.name
}

output "admin_role_arn" {
  value = aws_iam_role.admin.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnets" {
  description = "List of 16 subnet definitions (0-3 private tier 1, 4-7 private tier 2, 8-11 public, 12-15 spare)"
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24", availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24", availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24", availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24", availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24", availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24", availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24", availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24", availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24", availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24", availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]

  validation {
    condition     = length(var.subnets) == 16
    error_message = "Exactly 16 subnet definitions are required."
  }
}

locals {
  private_tier_1_subnets = slice(var.subnets, 0, 4)
  private_tier_2_subnets = slice(var.subnets, 4, 8)
  public_subnets         = slice(var.subnets, 8, 12)
  spare_subnets          = slice(var.subnets, 12, 16)
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr_block
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway, Elastic IP, NAT Gateway
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "natgw" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.private_tier_1[0].id

  tags = {
    Name = "deployme-natgw"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "private_tier_1" {
  count = length(local.private_tier_1_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_tier_1_subnets[count.index].cidr_block
  availability_zone = local.private_tier_1_subnets[count.index].availability_zone

  tags = {
    Name = local.private_tier_1_subnets[count.index].name
    Tier = "private-1"
  }
}

resource "aws_subnet" "private_tier_2" {
  count = length(local.private_tier_2_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_tier_2_subnets[count.index].cidr_block
  availability_zone = local.private_tier_2_subnets[count.index].availability_zone

  tags = {
    Name = local.private_tier_2_subnets[count.index].name
    Tier = "private-2"
  }
}

resource "aws_subnet" "public" {
  count = length(local.public_subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index].cidr_block
  availability_zone       = local.public_subnets[count.index].availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = local.public_subnets[count.index].name
    Tier = "public"
  }
}

resource "aws_subnet" "spare" {
  count = length(local.spare_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.spare_subnets[count.index].cidr_block
  availability_zone = local.spare_subnets[count.index].availability_zone

  tags = {
    Name = local.spare_subnets[count.index].name
    Tier = "spare"
  }
}

# ---------------------------------------------------------------------------
# Route Tables
# ---------------------------------------------------------------------------

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.natgw.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_tier_1" {
  count = length(aws_subnet.private_tier_1)

  subnet_id      = aws_subnet.private_tier_1[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_tier_2" {
  count = length(aws_subnet.private_tier_2)

  subnet_id      = aws_subnet.private_tier_2[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  count = length(aws_subnet.spare)

  subnet_id      = aws_subnet.spare[count.index].id
  route_table_id = aws_route_table.spare.id
}

# ---------------------------------------------------------------------------
# Security Group
# ---------------------------------------------------------------------------

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow HTTP/HTTPS from anywhere and SSH from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "server_public_ip" {
  description = "Public IP address of the NAT Gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

#-----------------------------------------------------------------------------
# Variables
#-----------------------------------------------------------------------------

variable "name" {
  type        = string
  default     = ""
  description = "Name (e.g. `app` or `cluster`)."
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment (e.g. `prod`, `dev`, `staging`)."
}

variable "repository" {
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
  description = "Terraform current module repo."
}

variable "label_order" {
  type        = list(any)
  default     = ["name", "environment"]
  description = "Label order, e.g. `name`,`environment`."
}

variable "managedby" {
  type        = string
  default     = "opsstation"
  description = "ManagedBy, eg 'opsstation'."
}

variable "enable" {
  type        = bool
  default     = true
  description = "Flag to control module creation."
}

variable "new_sg" {
  type        = bool
  default     = true
  description = "Flag to control creation of a new security group."
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "The ID of the VPC in which the security group will be created."
}

variable "sg_description" {
  type        = string
  default     = "Instance default security group (only egress access is allowed)."
  description = "The security group description."
}

variable "existing_sg_id" {
  type        = string
  default     = null
  description = "ID of an existing security group to which the rules will be applied."
}

variable "prefix_list_enabled" {
  type        = bool
  default     = false
  description = "Enable creation of an EC2 managed prefix list."
}

variable "prefix_list_ids" {
  type        = list(string)
  default     = []
  description = "IDs of existing managed prefix lists to use. If empty and prefix_list_enabled is true, a new prefix list is created."
}

variable "prefix_list_address_family" {
  type        = string
  default     = "IPv4"
  description = "Address family (IPv4 or IPv6) of the managed prefix list."
}

variable "max_entries" {
  type        = number
  default     = 5
  description = "The maximum number of entries that the managed prefix list can contain."
}

variable "entry" {
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default     = []
  description = "List of CIDR entries for the managed prefix list."
}

variable "ingress_rules_with_cidr_blocks" {
  type        = any
  default     = []
  description = "Ingress rules using IPv4/IPv6 CIDR blocks."
}

variable "ingress_rules_with_self" {
  type        = any
  default     = []
  description = "Ingress rules referencing the security group itself."
}

variable "ingress_rules_with_source_sg_id" {
  type        = any
  default     = []
  description = "Ingress rules using a source security group ID."
}

variable "ingress_rules_with_prefix_list" {
  type        = any
  default     = []
  description = "Ingress rules using managed prefix list IDs."
}

variable "egress_rules_with_cidr_blocks" {
  type        = any
  default     = []
  description = "Egress rules using IPv4/IPv6 CIDR blocks."
}

variable "egress_rules_with_self" {
  type        = any
  default     = []
  description = "Egress rules referencing the security group itself."
}

variable "egress_rules_with_source_sg_id" {
  type        = any
  default     = []
  description = "Egress rules using a source security group ID."
}

variable "egress_rules_with_prefix_list" {
  type        = any
  default     = []
  description = "Egress rules using managed prefix list IDs."
}

#-----------------------------------------------------------------------------
# Labels
#-----------------------------------------------------------------------------

module "labels" {
  source      = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

#-----------------------------------------------------------------------------
# Locals
#-----------------------------------------------------------------------------

locals {
  create_sg          = var.enable && var.new_sg
  create_prefix_list = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0

  security_group_id = var.existing_sg_id != null && var.existing_sg_id != "" ? var.existing_sg_id : join("", aws_security_group.default[*].id)

  prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : aws_ec2_managed_prefix_list.prefix_list[*].id

  apply_rules = var.enable && (local.create_sg || (var.existing_sg_id != null && var.existing_sg_id != ""))
}

#-----------------------------------------------------------------------------
# Security Group
#-----------------------------------------------------------------------------

resource "aws_security_group" "default" {
  count = local.create_sg ? 1 : 0

  name        = format("%s-sg", module.labels.id)
  vpc_id      = var.vpc_id
  description = var.sg_description
  tags        = module.labels.tags

  lifecycle {
    create_before_destroy = true
  }
}

#-----------------------------------------------------------------------------
# Managed Prefix List
#-----------------------------------------------------------------------------

resource "aws_ec2_managed_prefix_list" "prefix_list" {
  count = local.create_prefix_list ? 1 : 0

  name           = format("%s-prefix-list", module.labels.id)
  address_family = var.prefix_list_address_family
  max_entries    = var.max_entries
  tags           = module.labels.tags

  dynamic "entry" {
    for_each = var.entry
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }
}

#-----------------------------------------------------------------------------
# Ingress Rules
#-----------------------------------------------------------------------------

resource "aws_security_group_rule" "ingress_with_cidr_blocks" {
  for_each = local.apply_rules ? { for idx, rule in var.ingress_rules_with_cidr_blocks : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type              = "ingress"
  security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = lookup(each.value, "cidr_blocks", null)
  ipv6_cidr_blocks  = lookup(each.value, "ipv6_cidr_blocks", null)
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "ingress_with_self" {
  for_each = local.apply_rules ? { for idx, rule in var.ingress_rules_with_self : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type              = "ingress"
  security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "ingress_with_source_sg_id" {
  for_each = local.apply_rules ? { for idx, rule in var.ingress_rules_with_source_sg_id : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type                     = "ingress"
  security_group_id        = local.security_group_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_security_group_id
  description              = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "ingress_with_prefix_list" {
  for_each = local.apply_rules ? { for idx, rule in var.ingress_rules_with_prefix_list : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type              = "ingress"
  security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = lookup(each.value, "prefix_list_ids", null) != null ? each.value.prefix_list_ids : local.prefix_list_ids
  description       = lookup(each.value, "description", null)
}

#-----------------------------------------------------------------------------
# Egress Rules
#-----------------------------------------------------------------------------

resource "aws_security_group_rule" "egress_with_cidr_blocks" {
  for_each = local.apply_rules ? { for idx, rule in var.egress_rules_with_cidr_blocks : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type              = "egress"
  security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = lookup(each.value, "cidr_blocks", null)
  ipv6_cidr_blocks  = lookup(each.value, "ipv6_cidr_blocks", null)
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "egress_with_self" {
  for_each = local.apply_rules ? { for idx, rule in var.egress_rules_with_self : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type              = "egress"
  security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "egress_with_source_sg_id" {
  for_each = local.apply_rules ? { for idx, rule in var.egress_rules_with_source_sg_id : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type                     = "egress"
  security_group_id        = local.security_group_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_security_group_id
  description              = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "egress_with_prefix_list" {
  for_each = local.apply_rules ? { for idx, rule in var.egress_rules_with_prefix_list : tostring(lookup(rule, "rule_count", idx)) => rule } : {}

  type              = "egress"
  security_group_id = local.security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = lookup(each.value, "prefix_list_ids", null) != null ? each.value.prefix_list_ids : local.prefix_list_ids
  description       = lookup(each.value, "description", null)
}

#-----------------------------------------------------------------------------
# Outputs
#-----------------------------------------------------------------------------

output "security_group_id" {
  value       = local.security_group_id
  description = "ID of the security group the rules were applied to."
}

output "security_group_arn" {
  value       = join("", aws_security_group.default[*].arn)
  description = "ARN of the newly created security group."
}

output "prefix_list_id" {
  value       = join("", aws_ec2_managed_prefix_list.prefix_list[*].id)
  description = "ID of the newly created managed prefix list."
}

output "tags" {
  value       = module.labels.tags
  description = "Tags applied to resources."
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "environment_name" {
  description = "Environment name used to construct IAM role names."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  ecs_execution_managed_policy_arns = [
    "arn:${local.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy",
    "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole",
  ]

  ecs_task_managed_policy_arns = [
    "arn:${local.partition}:iam::aws:policy/SecretsManagerReadWrite",
    "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess",
  ]

  common_tags = {
    Environment = var.environment_name
    ManagedBy   = "terraform"
  }
}

################################################################################
# Account-wide IAM password policy
################################################################################

resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

################################################################################
# ECS task role
################################################################################

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "AllowEcsTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_role" {
  name               = "ecs-task-role-for-${var.environment_name}"
  description        = "ECS task role for the ${var.environment_name} environment."
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_task_role_managed" {
  for_each = toset(local.ecs_task_managed_policy_arns)

  role       = aws_iam_role.ecs_task_role.name
  policy_arn = each.value
}

data "aws_iam_policy_document" "ecs_task_ssm_messages" {
  statement {
    sid    = "AllowSsmMessagesChannels"
    effect = "Allow"
    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_ssm_messages" {
  name   = "ecs-task-ssm-messages-${var.environment_name}"
  role   = aws_iam_role.ecs_task_role.id
  policy = data.aws_iam_policy_document.ecs_task_ssm_messages.json
}

################################################################################
# ECS execution role
################################################################################

resource "aws_iam_role" "ecs_execution_role" {
  name               = "ecs-execution-role-for-${var.environment_name}"
  description        = "ECS task execution role for the ${var.environment_name} environment."
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_execution_role_managed" {
  for_each = toset(local.ecs_execution_managed_policy_arns)

  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = each.value
}

data "aws_iam_policy_document" "ecs_execution_secrets" {
  statement {
    sid    = "AllowSecretsManagerRead"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = ["arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"]
  }

  statement {
    sid       = "AllowKmsDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = ["arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"]
  }
}

resource "aws_iam_role_policy" "ecs_execution_secrets" {
  name   = "ecs-execution-secrets-${var.environment_name}"
  role   = aws_iam_role.ecs_execution_role.id
  policy = data.aws_iam_policy_document.ecs_execution_secrets.json
}

################################################################################
# ECS events role (EventBridge)
################################################################################

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    sid     = "AllowEventBridgeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_events_role" {
  name               = "ecs_events_role-for-${var.environment_name}"
  description        = "EventBridge role for running ECS tasks in the ${var.environment_name} environment."
  assume_role_policy = data.aws_iam_policy_document.events_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_events_role_managed" {
  for_each = toset(local.ecs_execution_managed_policy_arns)

  role       = aws_iam_role.ecs_events_role.name
  policy_arn = each.value
}

################################################################################
# Lambda roles
################################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# Public Lambda role
resource "aws_iam_role" "lambda_public_role" {
  name               = "lambda-public-role-for-${var.environment_name}"
  description        = "Role for public (non-VPC) Lambda functions."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_public" {
  statement {
    sid    = "AllowCloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:*"]
  }
}

resource "aws_iam_policy" "lambda_public" {
  name        = "lambda-public-policy-${var.environment_name}"
  description = "Basic CloudWatch logging permissions for public Lambda functions."
  policy      = data.aws_iam_policy_document.lambda_public.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_public" {
  role       = aws_iam_role.lambda_public_role.name
  policy_arn = aws_iam_policy.lambda_public.arn
}

# VPC Lambda role
resource "aws_iam_role" "lambda_vpc_role" {
  name               = "lambda-vpc-role-for-${var.environment_name}"
  description        = "Role for VPC-attached Lambda functions."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_vpc" {
  statement {
    sid    = "AllowCloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:*"]
  }

  statement {
    sid    = "AllowNetworkInterfaceManagement"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSecretsManagerRead"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = ["arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"]
  }

  statement {
    sid       = "AllowLambdaInvoke"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = ["arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"]
  }
}

resource "aws_iam_policy" "lambda_vpc" {
  name        = "lambda-vpc-policy-${var.environment_name}"
  description = "Permissions for VPC-attached Lambda functions."
  policy      = data.aws_iam_policy_document.lambda_vpc.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_vpc" {
  role       = aws_iam_role.lambda_vpc_role.name
  policy_arn = aws_iam_policy.lambda_vpc.arn
}

################################################################################
# Step Functions state machine role
################################################################################

data "aws_iam_policy_document" "states_assume_role" {
  statement {
    sid     = "AllowStepFunctionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "state_machine_role" {
  name               = "state-machine-role-for-${var.environment_name}"
  description        = "Execution role for Step Functions state machines."
  assume_role_policy = data.aws_iam_policy_document.states_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "state_machine" {
  statement {
    sid    = "AllowLogDelivery"
    effect = "Allow"
    actions = [
      "logs:CreateLogDelivery",
      "logs:GetLogDelivery",
      "logs:UpdateLogDelivery",
      "logs:DeleteLogDelivery",
      "logs:ListLogDeliveries",
      "logs:PutResourcePolicy",
      "logs:DescribeResourcePolicies",
      "logs:DescribeLogGroups",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "AllowLambdaInvoke"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [
      "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*",
    ]
  }

  statement {
    sid       = "AllowDescribeAlarms"
    effect    = "Allow"
    actions   = ["cloudwatch:DescribeAlarms"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "state_machine" {
  name        = "state-machine-policy-${var.environment_name}"
  description = "Permissions for Step Functions state machines."
  policy      = data.aws_iam_policy_document.state_machine.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "state_machine" {
  role       = aws_iam_role.state_machine_role.name
  policy_arn = aws_iam_policy.state_machine.arn
}

################################################################################
# EventBridge execution role (starts Step Functions executions)
################################################################################

resource "aws_iam_role" "eventbridge_execution_role" {
  name               = "eventbridge-execution-role-for-${var.environment_name}"
  description        = "EventBridge role permitted to start Step Functions executions in this account."
  assume_role_policy = data.aws_iam_policy_document.events_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "eventbridge_execution" {
  statement {
    sid       = "AllowStartStateMachineExecution"
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = ["arn:${local.partition}:states:*:${local.account_id}:stateMachine:*"]
  }
}

resource "aws_iam_policy" "eventbridge_execution" {
  name        = "eventbridge-execution-policy-${var.environment_name}"
  description = "Allows EventBridge to start Step Functions executions in the current account only."
  policy      = data.aws_iam_policy_document.eventbridge_execution.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eventbridge_execution" {
  role       = aws_iam_role.eventbridge_execution_role.name
  policy_arn = aws_iam_policy.eventbridge_execution.arn
}

################################################################################
# Human user governance policies
################################################################################

data "aws_iam_policy_document" "developers_limited_mfa" {
  statement {
    sid    = "AllowS3ObjectReadWriteDelete"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["arn:${local.partition}:s3:::*/*"]
  }

  statement {
    sid    = "AllowS3BucketListing"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:ListAllMyBuckets",
      "s3:GetBucketLocation",
    ]
    resources = ["arn:${local.partition}:s3:::*"]
  }

  statement {
    sid    = "AllowSecretsManagerReadOnlyWithMfa"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
      "secretsmanager:ListSecrets",
      "secretsmanager:ListSecretVersionIds",
      "secretsmanager:GetResourcePolicy",
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowCloudWatchAndEcsReadOnlyWithMfa"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "logs:Describe*",
      "logs:Get*",
      "logs:FilterLogEvents",
      "logs:StartQuery",
      "logs:StopQuery",
      "logs:TestMetricFilter",
      "ecs:Describe*",
      "ecs:List*",
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListVirtualMFADevices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:GetAccessKeyLastUsed",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnSSHPublicKeys"
    effect = "Allow"
    actions = [
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:UploadSSHPublicKey",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:mfa/*"]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"]
  }

  statement {
    sid    = "DenyAllExceptListedIfNoMFA"
    effect = "Deny"
    not_actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:GetUser",
      "iam:ChangePassword",
      "iam:GetAccountPasswordPolicy",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
      "sts:GetSessionToken",
    ]
    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developers_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Limited developer access with MFA enforcement and self-service credential management."
  policy      = data.aws_iam_policy_document.developers_limited_mfa.json
  tags        = local.common_tags
}

data "aws_iam_policy_document" "billing_limited_mfa" {
  statement {
    sid    = "AllowBillingAccessWithMfa"
    effect = "Allow"
    actions = [
      "aws-portal:*",
      "billing:*",
      "budgets:*",
      "ce:*",
      "cur:*",
      "payments:*",
      "tax:*",
      "account:GetAccountInformation",
      "invoicing:*",
      "consolidatedbilling:*",
      "freetier:*",
      "purchase-orders:*",
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListVirtualMFADevices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:mfa/*"]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"]
  }

  statement {
    sid    = "DenyAllExceptListedIfNoMFA"
    effect = "Deny"
    not_actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:GetUser",
      "iam:ChangePassword",
      "iam:GetAccountPasswordPolicy",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
      "sts:GetSessionToken",
    ]
    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "billing_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "MFA-conditioned billing access with self-service MFA and password management."
  policy      = data.aws_iam_policy_document.billing_limited_mfa.json
  tags        = local.common_tags
}

################################################################################
# Outputs
################################################################################

output "ecs_task_role_arn" {
  value = aws_iam_role.ecs_task_role.arn
}

output "ecs_execution_role_arn" {
  value = aws_iam_role.ecs_execution_role.arn
}

output "ecs_events_role_arn" {
  value = aws_iam_role.ecs_events_role.arn
}

output "lambda_public_role_arn" {
  value = aws_iam_role.lambda_public_role.arn
}

output "lambda_vpc_role_arn" {
  value = aws_iam_role.lambda_vpc_role.arn
}

output "state_machine_role_arn" {
  value = aws_iam_role.state_machine_role.arn
}

output "eventbridge_execution_role_arn" {
  value = aws_iam_role.eventbridge_execution_role.arn
}

output "developers_policy_arn" {
  value = aws_iam_policy.developers_limited_mfa.arn
}

output "billing_policy_arn" {
  value = aws_iam_policy.billing_limited_mfa.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "config" {
  description = "Path to the YAML file describing buckets, connections, pipelines and triggers."
  type        = string
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  config = yamldecode(file(var.config))

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  tags = merge(var.tags, try(local.config.tags, {}))

  artifact_bucket_name = try(local.config.artifact_bucket.name, "terraforest-artifacts-${local.account_id}-${local.region}")
  cache_bucket_name    = try(local.config.cache_bucket.name, "terraforest-build-cache-${local.account_id}-${local.region}")
  create_default_role  = try(local.config.create_default_role, true)

  connections = { for c in try(local.config.connections, []) : c.name => c }

  ghes_connections = {
    for name, c in local.connections : name => c
    if c.provider_type == "GitHubEnterpriseServer"
  }

  pipelines = { for p in try(local.config.pipelines, []) : p.name => p }

  actions = flatten([
    for pname, p in local.pipelines : [
      for s in p.stages : [
        for a in s.actions : merge(a, {
          pipeline = pname
          stage    = s.name
          key      = "${pname}/${s.name}/${a.name}"
        })
      ]
    ]
  ])

  codebuild_actions = { for a in local.actions : a.key => a if a.type == "codebuild" }
  lambda_actions    = { for a in local.actions : a.key => a if a.type == "lambda" }
  approval_actions  = { for a in local.actions : a.key => a if a.type == "approval" }

  source_types = ["codecommit", "s3", "ecr", "codestar"]

  action_category = {
    codecommit = "Source"
    s3         = "Source"
    ecr        = "Source"
    codestar   = "Source"
    approval   = "Approval"
    codebuild  = "Build"
    lambda     = "Invoke"
  }

  action_provider = {
    codecommit = "CodeCommit"
    s3         = "S3"
    ecr        = "ECR"
    codestar   = "CodeStarSourceConnection"
    approval   = "Manual"
    codebuild  = "CodeBuild"
    lambda     = "Lambda"
  }

  pipeline_stages = {
    for pname, p in local.pipelines : pname => [
      for s in p.stages : {
        name = s.name
        actions = [
          for a in s.actions : {
            name             = a.name
            category         = local.action_category[a.type]
            owner            = "AWS"
            provider         = local.action_provider[a.type]
            version          = "1"
            run_order        = try(a.run_order, null)
            namespace        = try(a.namespace, null)
            input_artifacts  = try(a.input_artifacts, [])
            output_artifacts = try(a.output_artifacts, contains(local.source_types, a.type) ? [replace(a.name, "/[^A-Za-z0-9_-]/", "_")] : [])
            configuration = {
              for k, v in(
                a.type == "codecommit" ? tomap({
                  RepositoryName       = a.repository
                  BranchName           = try(a.branch, "main")
                  PollForSourceChanges = "false"
                  OutputArtifactFormat = try(a.output_format, null)
                }) :
                a.type == "s3" ? tomap({
                  S3Bucket             = a.bucket
                  S3ObjectKey          = a.object_key
                  PollForSourceChanges = "false"
                }) :
                a.type == "ecr" ? tomap({
                  RepositoryName = a.repository
                  ImageTag       = try(a.image_tag, "latest")
                }) :
                a.type == "codestar" ? tomap({
                  ConnectionArn        = try(a.connection_arn, aws_codestarconnections_connection.this[a.connection].arn)
                  FullRepositoryId     = a.repository
                  BranchName           = try(a.branch, "main")
                  DetectChanges        = tostring(try(a.detect_changes, true))
                  OutputArtifactFormat = try(a.output_format, null)
                }) :
                a.type == "approval" ? tomap({
                  NotificationArn    = try(module.approval["${pname}/${s.name}/${a.name}"].topic_arn, null)
                  CustomData         = try(a.custom_data, null)
                  ExternalEntityLink = try(a.external_link, null)
                }) :
                a.type == "codebuild" ? tomap({
                  ProjectName          = try(module.codebuild["${pname}/${s.name}/${a.name}"].project_name, null)
                  PrimarySource        = try(a.primary_source, null)
                  EnvironmentVariables = try(jsonencode(a.pipeline_environment_variables), null)
                }) :
                tomap({
                  FunctionName   = try(module.lambda["${pname}/${s.name}/${a.name}"].function_name, null)
                  UserParameters = try(a.user_parameters, null)
                })
              ) : k => v if v != null
            }
          }
        ]
      }
    ]
  }

  triggers = merge([
    for pname, p in local.pipelines : {
      for idx, t in try(p.triggers, []) : "${pname}-${idx}" => merge(t, {
        pipeline = pname
        index    = idx
      })
    }
  ]...)

  triggered_pipelines = toset([for k, t in local.triggers : t.pipeline])

  trigger_patterns = {
    for k, t in local.triggers : k => (
      t.type == "branch" ? jsonencode({
        source      = ["aws.codecommit"]
        detail-type = ["CodeCommit Repository State Change"]
        resources   = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${t.repository}"]
        detail = {
          event         = ["referenceCreated", "referenceUpdated"]
          referenceType = ["branch"]
          referenceName = [try(t.branch, "main")]
        }
      }) :
      t.type == "tag" ? jsonencode({
        source      = ["aws.codecommit"]
        detail-type = ["CodeCommit Repository State Change"]
        resources   = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${t.repository}"]
        detail = merge(
          {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = ["tag"]
          },
          try({ referenceName = [{ prefix = t.tag_prefix }] }, {})
        )
      }) :
      t.type == "pattern" ? jsonencode(t.pattern) :
      null
    )
  }
}

# -----------------------------------------------------------------------------
# Artifact and build cache buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "artifacts" {
  bucket        = local.artifact_bucket_name
  force_destroy = try(local.config.artifact_bucket.force_destroy, false)
  tags          = local.tags
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "cache" {
  bucket        = local.cache_bucket_name
  force_destroy = try(local.config.cache_bucket.force_destroy, true)
  tags          = local.tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  bucket = aws_s3_bucket.cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  bucket                  = aws_s3_bucket.cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "cache" {
  bucket = aws_s3_bucket.cache.id

  rule {
    id     = "expire-cache"
    status = "Enabled"

    filter {}

    expiration {
      days = try(local.config.cache_bucket.expiration_days, 30)
    }
  }
}

# -----------------------------------------------------------------------------
# Default CodePipeline IAM role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "codepipeline_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "default" {
  count              = local.create_default_role ? 1 : 0
  name               = try(local.config.default_role_name, "terraforest-codepipeline")
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume.json
  tags               = local.tags
}

data "aws_iam_policy_document" "default" {
  statement {
    sid = "CodeCommit"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:UploadArchive",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:CancelUploadArchive",
    ]
    resources = ["*"]
  }

  statement {
    sid = "CodeBuild"
    actions = [
      "codebuild:StartBuild",
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuildBatch",
      "codebuild:BatchGetBuildBatches",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "ECR"
    actions   = ["ecr:DescribeImages"]
    resources = ["*"]
  }

  statement {
    sid = "Artifacts"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:GetBucketAcl",
      "s3:GetBucketLocation",
      "s3:PutObject",
      "s3:PutObjectAcl",
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid       = "CodeStarConnections"
    actions   = ["codestar-connections:UseConnection"]
    resources = ["*"]
  }

  statement {
    sid       = "Lambda"
    actions   = ["lambda:InvokeFunction", "lambda:ListFunctions"]
    resources = ["*"]
  }

  statement {
    sid       = "ApprovalNotifications"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "default" {
  count  = local.create_default_role ? 1 : 0
  name   = "terraforest-codepipeline"
  role   = aws_iam_role.default[0].id
  policy = data.aws_iam_policy_document.default.json
}

# -----------------------------------------------------------------------------
# CodeStar connections
# -----------------------------------------------------------------------------

resource "aws_codestarconnections_host" "this" {
  for_each          = local.ghes_connections
  name              = try(each.value.host_name, each.key)
  provider_endpoint = each.value.endpoint
  provider_type     = "GitHubEnterpriseServer"

  dynamic "vpc_configuration" {
    for_each = try([each.value.vpc], [])

    content {
      vpc_id             = vpc_configuration.value.vpc_id
      subnet_ids         = vpc_configuration.value.subnet_ids
      security_group_ids = vpc_configuration.value.security_group_ids
      tls_certificate    = try(vpc_configuration.value.tls_certificate, null)
    }
  }
}

resource "aws_codestarconnections_connection" "this" {
  for_each      = local.connections
  name          = each.key
  provider_type = each.value.provider_type == "GitHubEnterpriseServer" ? null : each.value.provider_type
  host_arn      = each.value.provider_type == "GitHubEnterpriseServer" ? aws_codestarconnections_host.this[each.key].arn : null
  tags          = local.tags

  lifecycle {
    precondition {
      condition     = contains(["Bitbucket", "GitHub", "GitHubEnterpriseServer"], each.value.provider_type)
      error_message = "Connection provider_type must be one of Bitbucket, GitHub or GitHubEnterpriseServer."
    }
  }
}

# -----------------------------------------------------------------------------
# Action modules
# -----------------------------------------------------------------------------

module "approval" {
  source   = "./modules/approval"
  for_each = local.approval_actions

  name        = try(each.value.topic_name, "${each.value.pipeline}-${each.value.name}-approval")
  subscribers = try(each.value.subscribers, [])
  tags        = local.tags
}

module "codebuild" {
  source   = "./modules/codebuild"
  for_each = local.codebuild_actions

  name                  = try(each.value.project_name, "${each.value.pipeline}-${each.value.name}")
  description           = try(each.value.description, "CodeBuild project for ${each.value.pipeline}/${each.value.stage}/${each.value.name}")
  role_arn              = try(each.value.role_arn, null)
  buildspec             = try(each.value.buildspec, "buildspec.yml")
  image                 = try(each.value.image, "aws/codebuild/standard:7.0")
  compute_type          = try(each.value.compute_type, "BUILD_GENERAL1_SMALL")
  privileged_mode       = try(each.value.privileged_mode, false)
  timeout               = try(each.value.timeout, 60)
  environment_variables = try(each.value.environment_variables, {})
  artifact_bucket_arn   = aws_s3_bucket.artifacts.arn
  cache_bucket          = aws_s3_bucket.cache.bucket
  cache_bucket_arn      = aws_s3_bucket.cache.arn
  vpc_config            = try(each.value.vpc, null)
  tags                  = local.tags
}

module "lambda" {
  source   = "./modules/lambda"
  for_each = local.lambda_actions

  function_name         = try(each.value.function_name, "${each.value.pipeline}-${each.value.name}")
  filename              = try(each.value.filename, null)
  s3_bucket             = try(each.value.s3_bucket, null)
  s3_key                = try(each.value.s3_key, null)
  handler               = try(each.value.handler, "index.handler")
  runtime               = try(each.value.runtime, "python3.12")
  timeout               = try(each.value.timeout, 60)
  role_arn              = try(each.value.role_arn, null)
  environment_variables = try(each.value.environment_variables, {})
  artifact_bucket_arn   = aws_s3_bucket.artifacts.arn
  tags                  = local.tags
}

# -----------------------------------------------------------------------------
# Pipelines
# -----------------------------------------------------------------------------

resource "aws_codepipeline" "this" {
  for_each      = local.pipelines
  name          = each.key
  role_arn      = try(each.value.role_arn, aws_iam_role.default[0].arn)
  pipeline_type = try(each.value.pipeline_type, "V2")
  tags          = local.tags

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    dynamic "encryption_key" {
      for_each = try([each.value.kms_key_arn], [])

      content {
        id   = encryption_key.value
        type = "KMS"
      }
    }
  }

  dynamic "stage" {
    for_each = local.pipeline_stages[each.key]

    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = action.value.run_order
          namespace        = action.value.namespace
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          configuration    = action.value.configuration
        }
      }
    }
  }

  depends_on = [aws_iam_role_policy.default]
}

# -----------------------------------------------------------------------------
# EventBridge triggers
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "events_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "events" {
  for_each           = local.triggered_pipelines
  name               = "terrabits-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.events_assume.json
  tags               = local.tags
}

resource "aws_iam_role_policy" "events" {
  for_each = local.triggered_pipelines
  name     = "terrabits-${each.key}"
  role     = aws_iam_role.events[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["codepipeline:StartPipelineExecution"]
        Resource = [aws_codepipeline.this[each.key].arn]
      }
    ]
  })
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each            = local.triggers
  name                = substr(try(each.value.name, each.key), 0, 64)
  description         = try(each.value.description, "Triggers pipeline ${each.value.pipeline} (${each.value.type})")
  event_bus_name      = try(each.value.event_bus_name, null)
  schedule_expression = each.value.type == "schedule" ? each.value.expression : null
  event_pattern       = local.trigger_patterns[each.key]
  state               = try(each.value.enabled, true) ? "ENABLED" : "DISABLED"
  tags                = local.tags

  lifecycle {
    precondition {
      condition     = contains(["branch", "tag", "schedule", "pattern"], each.value.type)
      error_message = "Trigger type must be one of branch, tag, schedule or pattern."
    }
  }
}

resource "aws_cloudwatch_event_target" "this" {
  for_each       = local.triggers
  rule           = aws_cloudwatch_event_rule.this[each.key].name
  event_bus_name = try(each.value.event_bus_name, null)
  target_id      = "terrabits-${each.value.pipeline}"
  arn            = aws_codepipeline.this[each.value.pipeline].arn
  role_arn       = aws_iam_role.events[each.value.pipeline].arn

  depends_on = [aws_iam_role_policy.events]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "artifact_bucket" {
  value = aws_s3_bucket.artifacts.bucket
}

output "cache_bucket" {
  value = aws_s3_bucket.cache.bucket
}

output "default_role_arn" {
  value = try(aws_iam_role.default[0].arn, null)
}

output "connection_arns" {
  value = { for k, c in aws_codestarconnections_connection.this : k => c.arn }
}

output "pipeline_arns" {
  value = { for k, p in aws_codepipeline.this : k => p.arn }
}

output "trigger_rule_arns" {
  value = { for k, r in aws_cloudwatch_event_rule.this : k => r.arn }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name of the SFTP server. Used as a prefix for related resources."
  type        = string
  default     = "sftp-efs"
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "performance_mode" {
  description = "EFS performance mode."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be either \"generalPurpose\" or \"maxIO\"."
  }
}

variable "kms_key_id" {
  description = "Optional ARN of a customer-managed KMS key used to encrypt EFS. When empty, the AWS-managed key is used."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "Optional VPC ID. When set, the SFTP server uses a VPC endpoint and EFS mount targets are created."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Optional list of subnet IDs for EFS mount targets and the SFTP VPC endpoint."
  type        = list(string)
  default     = []
}

variable "is_public" {
  description = "When true and a VPC is supplied, Elastic IPs are allocated to make the VPC endpoint internet-facing."
  type        = bool
  default     = false
}

variable "create_security_groups" {
  description = "Whether to create dedicated security groups for the SFTP endpoint and EFS mount targets."
  type        = bool
  default     = true
}

variable "sftp_security_group_ids" {
  description = "Existing security group IDs to attach to the SFTP VPC endpoint (in addition to any created)."
  type        = list(string)
  default     = []
}

variable "efs_security_group_ids" {
  description = "Existing security group IDs to attach to the EFS mount targets (in addition to any created)."
  type        = list(string)
  default     = []
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to connect to the SFTP endpoint on port 22."
  type        = list(string)
  default     = []
}

variable "sftp_users" {
  description = "Map of SFTP users keyed by username."
  type = map(object({
    uid        = number
    gid        = number
    public_key = string
    restricted = optional(bool, true)
  }))
  default = {}
}

variable "create_user_access_points" {
  description = "Whether to create an EFS access point per SFTP user."
  type        = bool
  default     = true
}

variable "additional_access_points" {
  description = "Map of additional EFS access points for general storage paths."
  type = map(object({
    path        = string
    uid         = number
    gid         = number
    permissions = optional(string, "0755")
  }))
  default = {}
}

variable "iam_role_arn" {
  description = "Optional existing IAM role ARN for SFTP users. When empty, a role named \"<name>-role\" is created."
  type        = string
  default     = ""

  validation {
    condition     = var.iam_role_arn == "" || can(regex("^arn:aws[a-zA-Z-]*:iam::[0-9]{12}:role/.+$", var.iam_role_arn))
    error_message = "iam_role_arn must be empty or a valid IAM role ARN."
  }
}

variable "logging_enabled" {
  description = "Whether to enable CloudWatch logging for the SFTP server."
  type        = bool
  default     = false
}

variable "log_retention_in_days" {
  description = "Retention period for the SFTP CloudWatch log group."
  type        = number
  default     = 30
}

################################################################################
# Locals & Data
################################################################################

locals {
  use_vpc        = var.vpc_id != ""
  create_mounts  = local.use_vpc && length(var.subnet_ids) > 0
  create_sg      = local.use_vpc && var.create_security_groups
  create_role    = var.iam_role_arn == ""
  allocate_eips  = local.use_vpc && var.is_public
  user_role_arn  = local.create_role ? aws_iam_role.sftp_user[0].arn : var.iam_role_arn
  encrypted_kms  = var.kms_key_id != ""
  user_ap_map    = var.create_user_access_points ? var.sftp_users : {}

  sftp_sg_ids = concat(
    local.create_sg ? [aws_security_group.sftp[0].id] : [],
    var.sftp_security_group_ids,
  )

  efs_sg_ids = concat(
    local.create_sg ? [aws_security_group.efs[0].id] : [],
    var.efs_security_group_ids,
  )
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_vpc" "selected" {
  count = local.use_vpc ? 1 : 0
  id    = var.vpc_id
}

################################################################################
# EFS
################################################################################

resource "aws_efs_file_system" "this" {
  creation_token   = "${var.name}-efs"
  performance_mode = var.performance_mode
  throughput_mode  = "bursting"
  encrypted        = true
  kms_key_id       = local.encrypted_kms ? var.kms_key_id : null

  tags = merge(var.tags, { Name = "${var.name}-efs" })
}

resource "aws_efs_mount_target" "this" {
  for_each = local.create_mounts ? toset(var.subnet_ids) : toset([])

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = each.value
  security_groups = local.efs_sg_ids
}

resource "aws_efs_access_point" "user" {
  for_each = local.user_ap_map

  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = "/${each.key}"

    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-${each.key}" })
}

resource "aws_efs_access_point" "additional" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = each.value.path

    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = each.value.permissions
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-${each.key}" })
}

################################################################################
# Security Groups
################################################################################

resource "aws_security_group" "sftp" {
  count = local.create_sg ? 1 : 0

  name        = "${var.name}-sftp-sg"
  description = "Security group for the ${var.name} SFTP endpoint"
  vpc_id      = var.vpc_id

  tags = merge(var.tags, { Name = "${var.name}-sftp-sg" })
}

resource "aws_vpc_security_group_ingress_rule" "sftp_ssh" {
  for_each = local.create_sg ? toset(var.allowed_cidr_blocks) : toset([])

  security_group_id = aws_security_group.sftp[0].id
  description       = "SFTP access"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = each.value
}

resource "aws_vpc_security_group_egress_rule" "sftp_all" {
  count = local.create_sg ? 1 : 0

  security_group_id = aws_security_group.sftp[0].id
  description       = "Allow all outbound traffic"
  ip_protocol       = "-1"
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_security_group" "efs" {
  count = local.create_sg ? 1 : 0

  name        = "${var.name}-efs-sg"
  description = "Security group for the ${var.name} EFS mount targets"
  vpc_id      = var.vpc_id

  tags = merge(var.tags, { Name = "${var.name}-efs-sg" })
}

resource "aws_vpc_security_group_ingress_rule" "efs_nfs_vpc" {
  count = local.create_sg ? 1 : 0

  security_group_id = aws_security_group.efs[0].id
  description       = "NFS from within the VPC"
  ip_protocol       = "tcp"
  from_port         = 2049
  to_port           = 2049
  cidr_ipv4         = data.aws_vpc.selected[0].cidr_block
}

resource "aws_vpc_security_group_ingress_rule" "efs_nfs_sftp" {
  count = local.create_sg ? 1 : 0

  security_group_id            = aws_security_group.efs[0].id
  description                  = "NFS from the SFTP endpoint"
  ip_protocol                  = "tcp"
  from_port                    = 2049
  to_port                      = 2049
  referenced_security_group_id = aws_security_group.sftp[0].id
}

resource "aws_vpc_security_group_egress_rule" "efs_all" {
  count = local.create_sg ? 1 : 0

  security_group_id = aws_security_group.efs[0].id
  description       = "Allow all outbound traffic"
  ip_protocol       = "-1"
  cidr_ipv4         = "0.0.0.0/0"
}

################################################################################
# Elastic IPs
################################################################################

resource "aws_eip" "sftp" {
  count = local.allocate_eips ? length(var.subnet_ids) : 0

  domain = "vpc"

  tags = merge(var.tags, { Name = "${var.name}-eip-${count.index}" })
}

################################################################################
# CloudWatch Logging
################################################################################

resource "aws_cloudwatch_log_group" "sftp" {
  count = var.logging_enabled ? 1 : 0

  name              = "/aws/transfer/${var.name}"
  retention_in_days = var.log_retention_in_days

  tags = var.tags
}

data "aws_iam_policy_document" "transfer_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0

  name               = "${var.name}-logging-role"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume.json

  tags = var.tags
}

data "aws_iam_policy_document" "logging" {
  count = var.logging_enabled ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.sftp[0].arn,
      "${aws_cloudwatch_log_group.sftp[0].arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "logging" {
  count = var.logging_enabled ? 1 : 0

  name   = "${var.name}-logging-policy"
  role   = aws_iam_role.logging[0].id
  policy = data.aws_iam_policy_document.logging[0].json
}

################################################################################
# Transfer Family Server
################################################################################

resource "aws_transfer_server" "this" {
  domain                 = "EFS"
  protocols              = ["SFTP"]
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = local.use_vpc ? "VPC" : "PUBLIC"
  logging_role           = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  structured_log_destinations = var.logging_enabled ? ["${aws_cloudwatch_log_group.sftp[0].arn}:*"] : null

  dynamic "endpoint_details" {
    for_each = local.use_vpc ? [1] : []

    content {
      vpc_id                 = var.vpc_id
      subnet_ids             = var.subnet_ids
      security_group_ids     = local.sftp_sg_ids
      address_allocation_ids = local.allocate_eips ? aws_eip.sftp[*].id : null
    }
  }

  tags = merge(var.tags, { Name = var.name })

  depends_on = [
    aws_efs_mount_target.this,
    aws_iam_role_policy.logging,
  ]
}

################################################################################
# SFTP User IAM Role
################################################################################

resource "aws_iam_role" "sftp_user" {
  count = local.create_role ? 1 : 0

  name               = "${var.name}-role"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume.json

  tags = var.tags
}

data "aws_iam_policy_document" "sftp_user" {
  count = local.create_role ? 1 : 0

  statement {
    sid    = "EFSClientAccess"
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:DescribeMountTargets",
    ]
    resources = [aws_efs_file_system.this.arn]
  }

  dynamic "statement" {
    for_each = local.encrypted_kms ? [1] : []

    content {
      sid    = "KMSAccess"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:GenerateDataKey",
        "kms:DescribeKey",
      ]
      resources = [var.kms_key_id]
    }
  }
}

resource "aws_iam_role_policy" "sftp_user" {
  count = local.create_role ? 1 : 0

  name   = "${var.name}-efs-access"
  role   = aws_iam_role.sftp_user[0].id
  policy = data.aws_iam_policy_document.sftp_user[0].json
}

################################################################################
# SFTP Users
################################################################################

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.this.id
  user_name = each.key
  role      = local.user_role_arn

  posix_profile {
    uid = each.value.uid
    gid = each.value.gid
  }

  home_directory_type = each.value.restricted ? "LOGICAL" : "PATH"
  home_directory      = each.value.restricted ? null : "/${aws_efs_file_system.this.id}/${each.key}"

  dynamic "home_directory_mappings" {
    for_each = each.value.restricted ? [1] : []

    content {
      entry  = "/"
      target = "/${aws_efs_file_system.this.id}/${each.key}"
    }
  }

  tags = merge(var.tags, { Name = each.key })

  depends_on = [
    aws_efs_access_point.user,
    aws_iam_role_policy.sftp_user,
  ]
}

resource "aws_transfer_ssh_key" "this" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.key].user_name
  body      = each.value.public_key
}

################################################################################
# Outputs
################################################################################

output "sftp_server_id" {
  description = "ID of the Transfer Family server."
  value       = aws_transfer_server.this.id
}

output "sftp_server_arn" {
  description = "ARN of the Transfer Family server."
  value       = aws_transfer_server.this.arn
}

output "sftp_server_endpoint" {
  description = "Endpoint hostname of the Transfer Family server."
  value       = aws_transfer_server.this.endpoint
}

output "sftp_elastic_ips" {
  description = "Elastic IP addresses allocated to the SFTP endpoint."
  value       = aws_eip.sftp[*].public_ip
}

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system."
  value       = aws_efs_file_system.this.arn
}

output "efs_mount_target_ids" {
  description = "IDs of the EFS mount targets."
  value       = [for mt in aws_efs_mount_target.this : mt.id]
}

output "efs_user_access_point_ids" {
  description = "Map of SFTP username to EFS access point ID."
  value       = { for k, ap in aws_efs_access_point.user : k => ap.id }
}

output "efs_additional_access_point_ids" {
  description = "Map of additional access point name to EFS access point ID."
  value       = { for k, ap in aws_efs_access_point.additional : k => ap.id }
}

output "sftp_user_role_arn" {
  description = "IAM role ARN used by SFTP users."
  value       = local.user_role_arn
}

output "sftp_security_group_id" {
  description = "ID of the created SFTP security group, if any."
  value       = local.create_sg ? aws_security_group.sftp[0].id : null
}

output "efs_security_group_id" {
  description = "ID of the created EFS security group, if any."
  value       = local.create_sg ? aws_security_group.efs[0].id : null
}

output "logging_role_arn" {
  description = "ARN of the CloudWatch logging role, if enabled."
  value       = var.logging_enabled ? aws_iam_role.logging[0].arn : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Master toggle controlling whether any resources in this module are created."
  type        = bool
  default     = true
}

variable "create_bucket" {
  description = "Controls whether the S3 bucket (and its dependent resources) should be created."
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Explicit name of the bucket. If null (and bucket_prefix is null), Terraform assigns a random unique name."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket so that it can be destroyed without error."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock should be enabled on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object Lock default retention configuration, e.g. { rule = { default_retention = { mode = \"GOVERNANCE\", days = 30 } } }."
  type        = any
  default     = {}
}

variable "tags" {
  description = "A map of tags to assign to the bucket and KMS key."
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "Canned ACL to apply to the bucket. Conflicts with grant."
  type        = string
  default     = null
}

variable "grant" {
  description = "List of explicit ACL grant objects (or a JSON-encoded string of the same). Conflicts with acl."
  type        = any
  default     = []
}

variable "owner" {
  description = "Bucket owner's display name and ID used with explicit grants. Map with keys id and display_name."
  type        = map(string)
  default     = {}
}

variable "expected_bucket_owner" {
  description = "Account ID of the expected bucket owner."
  type        = string
  default     = null
}

variable "website" {
  description = "Static website hosting configuration (index_document, error_document, redirect_all_requests_to, routing_rules)."
  type        = any
  default     = {}
}

variable "cors_rule" {
  description = "List of CORS rule maps."
  type        = any
  default     = []
}

variable "versioning" {
  description = "Versioning configuration map, e.g. { enabled = true, mfa_delete = false }."
  type        = any
  default     = {}
}

variable "logging" {
  description = "Access logging configuration map with target_bucket and target_prefix."
  type        = any
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status: Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Who pays for download and request fees: BucketOwner or Requester."
  type        = string
  default     = null
}

variable "lifecycle_rule" {
  description = "List of lifecycle rule maps."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration map with role and rules."
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "Map of intelligent tiering configurations keyed by configuration name."
  type        = any
  default     = {}
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  type        = string
  default     = "ObjectWriter"
}

variable "server_side_encryption_configuration" {
  description = "Caller-supplied server-side encryption configuration. When non-empty, replaces the default SSE-KMS encryption with a module-managed key."
  type        = any
  default     = {}
}

variable "kms_key_deletion_window_in_days" {
  description = "Deletion window in days for the module-managed KMS key."
  type        = number
  default     = 7
}

variable "kms_key_enable_rotation" {
  description = "Whether key rotation is enabled on the module-managed KMS key."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Attach a policy allowing classic ELB access log delivery."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Attach a policy allowing ALB/NLB access log delivery."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Attach a policy denying any request made without secure transport."
  type        = bool
  default     = false
}

variable "attach_require_latest_tls_policy" {
  description = "Attach a policy denying requests that use TLS versions older than 1.2."
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Whether to merge the user-supplied JSON policy (var.policy) into the bucket policy."
  type        = bool
  default     = false
}

variable "policy" {
  description = "A valid user-supplied bucket policy JSON document."
  type        = string
  default     = null
}

################################################################################
# Locals & data
################################################################################

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

locals {
  create_bucket = var.create && var.create_bucket

  use_default_kms = local.create_bucket && length(keys(var.server_side_encryption_configuration)) == 0

  attach_policy = (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    var.attach_require_latest_tls_policy ||
    var.attach_policy
  )

  grants = try(jsondecode(var.grant), var.grant)

  create_acl = local.create_bucket && (var.acl != null || length(local.grants) > 0)

  cors_rules     = try(jsondecode(var.cors_rule), var.cors_rule)
  lifecycle_rule = try(jsondecode(var.lifecycle_rule), var.lifecycle_rule)
  intelligent_tiering = try(jsondecode(var.intelligent_tiering), var.intelligent_tiering)

  bucket_id  = try(aws_s3_bucket.this[0].id, "")
  bucket_arn = try(aws_s3_bucket.this[0].arn, "")
}

data "aws_elb_service_account" "this" {
  count = local.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
}

################################################################################
# KMS key (default encryption)
################################################################################

resource "aws_kms_key" "this" {
  count = local.use_default_kms ? 1 : 0

  description             = "KMS key for S3 bucket server-side encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = var.kms_key_enable_rotation

  tags = var.tags
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix

  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "rule" {
    for_each = local.use_default_kms ? [1] : []

    content {
      bucket_key_enabled = true

      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = aws_kms_key.this[0].arn
      }
    }
  }

  dynamic "rule" {
    for_each = local.use_default_kms ? [] : try(flatten([var.server_side_encryption_configuration["rule"]]), [])

    content {
      bucket_key_enabled = try(rule.value.bucket_key_enabled, null)

      dynamic "apply_server_side_encryption_by_default" {
        for_each = try([rule.value.apply_server_side_encryption_by_default], [])

        content {
          sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
          kms_master_key_id = try(apply_server_side_encryption_by_default.value.kms_master_key_id, null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_enabled && try(var.object_lock_configuration.rule.default_retention, null) != null ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  rule {
    default_retention {
      mode  = var.object_lock_configuration.rule.default_retention.mode
      days  = try(var.object_lock_configuration.rule.default_retention.days, null)
      years = try(var.object_lock_configuration.rule.default_retention.years, null)
    }
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  acl = var.acl == "null" ? null : var.acl

  dynamic "access_control_policy" {
    for_each = length(local.grants) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = local.grants

        content {
          permission = grant.value.permission

          grantee {
            type          = grant.value.type
            id            = try(grant.value.id, null)
            uri           = try(grant.value.uri, null)
            email_address = try(grant.value.email, null)
          }
        }
      }

      owner {
        id           = try(var.owner["id"], data.aws_caller_identity.current.id)
        display_name = try(var.owner["display_name"], null)
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(keys(var.website)) > 0 ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "index_document" {
    for_each = try([var.website["index_document"]], [])

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try([var.website["error_document"]], [])

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try([var.website["redirect_all_requests_to"]], [])

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(flatten([var.website["routing_rules"]]), [])

    content {
      dynamic "condition" {
        for_each = try([routing_rule.value.condition], [])

        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(local.cors_rules) > 0 ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "cors_rule" {
    for_each = local.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(keys(var.versioning)) > 0 ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner
  mfa                   = try(var.versioning["mfa"], null)

  versioning_configuration {
    status = try(
      tobool(var.versioning["status"]) ? "Enabled" : "Suspended",
      title(lower(var.versioning["status"])),
      tobool(var.versioning["enabled"]) ? "Enabled" : "Suspended",
      "Enabled"
    )
    mfa_delete = try(tobool(var.versioning["mfa_delete"]) ? "Enabled" : "Disabled", null)
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(keys(var.logging)) > 0 ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  target_bucket = var.logging["target_bucket"]
  target_prefix = try(var.logging["target_prefix"], "")
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner
  status                = title(lower(var.acceleration_status))
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != null ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner
  payer                 = lower(var.request_payer) == "requester" ? "Requester" : "BucketOwner"
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(local.lifecycle_rule) > 0 ? 1 : 0

  bucket                = aws_s3_bucket.this[0].id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "rule" {
    for_each = local.lifecycle_rule

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.enabled ? "Enabled" : "Disabled", tobool(rule.value.status) ? "Enabled" : "Disabled", title(lower(rule.value.status)))

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try([rule.value.abort_incomplete_multipart_upload_days], [])

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = try(flatten([rule.value.expiration]), [])

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(flatten([rule.value.transition]), [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(flatten([rule.value.noncurrent_version_expiration]), [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.days, noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(flatten([rule.value.noncurrent_version_transition]), [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.days, noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      # Rule applies to all objects when no filter is supplied
      dynamic "filter" {
        for_each = length(try(flatten([rule.value.filter]), [])) == 0 ? [true] : []

        content {}
      }

      dynamic "filter" {
        for_each = [for f in try(flatten([rule.value.filter]), []) : f if length(try(f.tags, {})) == 0]

        content {
          prefix                   = try(filter.value.prefix, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)
        }
      }

      dynamic "filter" {
        for_each = [for f in try(flatten([rule.value.filter]), []) : f if length(try(f.tags, {})) > 0]

        content {
          and {
            prefix                   = try(filter.value.prefix, null)
            object_size_greater_than = try(filter.value.object_size_greater_than, null)
            object_size_less_than    = try(filter.value.object_size_less_than, null)
            tags                     = filter.value.tags
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && length(keys(var.replication_configuration)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration["role"]

  dynamic "rule" {
    for_each = flatten(try([var.replication_configuration["rule"]], [var.replication_configuration["rules"]], []))

    content {
      id       = try(rule.value.id, null)
      priority = try(rule.value.priority, null)
      status   = try(tobool(rule.value.status) ? "Enabled" : "Disabled", title(lower(rule.value.status)), "Enabled")

      dynamic "delete_marker_replication" {
        for_each = try([rule.value.delete_marker_replication], [])

        content {
          status = try(tobool(delete_marker_replication.value) ? "Enabled" : "Disabled", title(lower(delete_marker_replication.value)))
        }
      }

      dynamic "filter" {
        for_each = length(try(rule.value.filter.tags, {})) == 0 ? [1] : []

        content {
          prefix = try(rule.value.filter.prefix, null)
        }
      }

      dynamic "filter" {
        for_each = length(try(rule.value.filter.tags, {})) > 0 ? [1] : []

        content {
          and {
            prefix = try(rule.value.filter.prefix, null)
            tags   = rule.value.filter.tags
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account_id, rule.value.destination.account, null)

        dynamic "encryption_configuration" {
          for_each = try([rule.value.destination.replica_kms_key_id], [])

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "access_control_translation" {
          for_each = try([rule.value.destination.access_control_translation], [])

          content {
            owner = access_control_translation.value.owner
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria.sse_kms_encrypted_objects.enabled, null) != null ? [1] : []

        content {
          sse_kms_encrypted_objects {
            status = rule.value.source_selection_criteria.sse_kms_encrypted_objects.enabled ? "Enabled" : "Disabled"
          }
        }
      }
    }
  }

  # Replication requires versioning to be enabled first
  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = { for k, v in local.intelligent_tiering : k => v if local.create_bucket }

  name   = each.key
  bucket = aws_s3_bucket.this[0].id
  status = try(tobool(each.value.status) ? "Enabled" : "Disabled", title(lower(each.value.status)), "Enabled")

  dynamic "filter" {
    for_each = length(try(flatten([each.value.filter]), [])) == 0 ? [] : flatten([each.value.filter])

    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = each.value.tiering

    content {
      access_tier = tiering.key
      days        = tiering.value.days
    }
  }
}

################################################################################
# Bucket policy
################################################################################

data "aws_iam_policy_document" "elb_log_delivery" {
  count = local.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid       = "AllowClassicELBLogDelivery"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${local.bucket_arn}/*"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.this[0].arn]
    }
  }

  # Regions launched after August 2022 use the service principal instead of an account
  statement {
    sid       = "AllowELBLogDeliveryServicePrincipal"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${local.bucket_arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lb_log_delivery" {
  count = local.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid       = "AWSLogDeliveryWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${local.bucket_arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid       = "AWSLogDeliveryAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [local.bucket_arn]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = local.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid     = "denyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "require_latest_tls" {
  count = local.create_bucket && var.attach_require_latest_tls_policy ? 1 : 0

  statement {
    sid     = "denyOutdatedTLS"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

data "aws_iam_policy_document" "combined" {
  count = local.create_bucket && local.attach_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_require_latest_tls_policy ? data.aws_iam_policy_document.require_latest_tls[0].json : "",
    var.attach_policy && var.policy != null ? var.policy : "",
  ])
}

resource "aws_s3_bucket_policy" "this" {
  count = local.create_bucket && local.attach_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

################################################################################
# Public access block & ownership controls (applied after the bucket policy)
################################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets

  # Avoid OperationAborted: A conflicting conditional operation is currently in progress
  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  # Avoid conflicting S3 operations by serializing after policy and public access block
  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket.this,
  ]
}

################################################################################
# Outputs
################################################################################

output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = try(aws_s3_bucket_policy.this[0].id, aws_s3_bucket.this[0].id, "")
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket."
  value       = try(aws_s3_bucket.this[0].arn, "")
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name."
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, "")
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = try(aws_s3_bucket.this[0].bucket_regional_domain_name, "")
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 hosted zone ID for this bucket's region."
  value       = try(aws_s3_bucket.this[0].hosted_zone_id, "")
}

output "s3_bucket_region" {
  description = "The AWS region this bucket resides in."
  value       = try(aws_s3_bucket.this[0].region, "")
}

output "s3_bucket_website_endpoint" {
  description = "The website endpoint, if the bucket is configured with a website."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, "")
}

output "s3_bucket_website_domain" {
  description = "The domain of the website endpoint, if the bucket is configured with a website."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_domain, "")
}

output "s3_bucket_policy" {
  description = "The policy attached to the bucket."
  value       = try(aws_s3_bucket_policy.this[0].policy, "")
}

output "kms_key_arn" {
  description = "ARN of the module-managed KMS key used for default bucket encryption."
  value       = try(aws_kms_key.this[0].arn, "")
}

output "kms_key_id" {
  description = "ID of the module-managed KMS key used for default bucket encryption."
  value       = try(aws_kms_key.this[0].key_id, "")
}

variable "target_stack" {
  description = "Name of the target stack"
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Short git hash of the stack release"
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Full git hash of the stack release"
  type        = string
  default     = "benchmark0000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  description = "S3 bucket holding deployment artifacts, configurations, certificates, and datasets"
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "S3 object key of the primary dataset"
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "S3 object key of the destigmatized dataset"
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "S3 object key of the genomic dataset"
  type        = string
  default     = "genomic_dataset.csv"
}

locals {
  name_suffix = "${var.target_stack}-${var.stack_githash}"

  bucket_arn   = "arn:aws:s3:::${var.stack_s3_bucket}"
  releases_arn = "${local.bucket_arn}/releases/jenkins_pipeline_build_${var.stack_githash_long}"
  configs_arn  = "${local.bucket_arn}/configs/jenkins_pipeline_build_${var.stack_githash_long}"
  certs_arn    = "${local.bucket_arn}/certs"
  data_arn     = "${local.bucket_arn}/data"

  common_security_tools = [
    "${local.bucket_arn}/security-tools/*",
  ]

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy",
    "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore",
  ]

  roles = {
    wildfly = {
      prefix = "wildfly-deployment-s3"
      s3_get_objects = concat([
        "${local.releases_arn}/pic-sure-wildfly.tar.gz",
        "${local.configs_arn}/wildfly/standalone.xml",
        "${local.configs_arn}/wildfly/pic-sure-schema.sql",
        "${local.configs_arn}/wildfly/aggregate-resource.properties",
        "${local.configs_arn}/wildfly/visualization-resource.properties",
        "${local.configs_arn}/wildfly/mysql_server_cert",
        "${local.configs_arn}/wildfly/*",
      ], local.common_security_tools)
      s3_list_prefixes = []
    }

    httpd = {
      prefix = "httpd-deployment-s3"
      s3_get_objects = concat([
        "${local.releases_arn}/pic-sure-ui.tar.gz",
        "${local.configs_arn}/httpd/httpd-vhosts.conf",
        "${local.configs_arn}/httpd/picsureui_settings.json",
        "${local.configs_arn}/httpd/psamaui_settings.json",
        "${local.configs_arn}/httpd/*",
        "${local.certs_arn}/httpd/server.crt",
        "${local.certs_arn}/httpd/server.key",
        "${local.certs_arn}/httpd/server.chain",
        "${local.certs_arn}/httpd/*",
      ], local.common_security_tools)
      s3_list_prefixes = []
    }

    auth_hpds = {
      prefix = "auth-hpds-deployment-s3"
      s3_get_objects = concat([
        "${local.releases_arn}/pic-sure-hpds.tar.gz",
        "${local.configs_arn}/auth-hpds/*",
        "${local.data_arn}/${var.stack_githash_long}/${var.dataset_s3_object_key}",
        "${local.data_arn}/${var.stack_githash_long}/${var.genomic_dataset_s3_object_key}",
        "${local.data_arn}/${var.dataset_s3_object_key}",
        "${local.data_arn}/${var.genomic_dataset_s3_object_key}",
      ], local.common_security_tools)
      s3_list_prefixes = [
        "data/${var.stack_githash_long}/*",
        "releases/jenkins_pipeline_build_${var.stack_githash_long}/*",
        "configs/jenkins_pipeline_build_${var.stack_githash_long}/auth-hpds/*",
      ]
    }

    open_hpds = {
      prefix = "open-hpds-deployment-s3"
      s3_get_objects = concat([
        "${local.releases_arn}/pic-sure-hpds.tar.gz",
        "${local.configs_arn}/open-hpds/*",
        "${local.data_arn}/${var.stack_githash_long}/${var.destigmatized_dataset_s3_object_key}",
        "${local.data_arn}/${var.destigmatized_dataset_s3_object_key}",
      ], local.common_security_tools)
      s3_list_prefixes = [
        "data/${var.stack_githash_long}/*",
        "releases/jenkins_pipeline_build_${var.stack_githash_long}/*",
        "configs/jenkins_pipeline_build_${var.stack_githash_long}/open-hpds/*",
      ]
    }

    dictionary = {
      prefix = "dictionary-deployment-s3"
      s3_get_objects = concat([
        "${local.releases_arn}/pic-sure-hpds-dictionary-resource.tar.gz",
        "${local.configs_arn}/dictionary/*",
        "${local.data_arn}/${var.stack_githash_long}/${var.dataset_s3_object_key}",
        "${local.data_arn}/${var.dataset_s3_object_key}",
      ], local.common_security_tools)
      s3_list_prefixes = [
        "data/${var.stack_githash_long}/*",
        "releases/jenkins_pipeline_build_${var.stack_githash_long}/*",
        "configs/jenkins_pipeline_build_${var.stack_githash_long}/dictionary/*",
      ]
    }
  }

  role_policy_attachments = merge([
    for role_key, role in local.roles : {
      for policy_arn in local.managed_policy_arns :
      "${role_key}-${element(split("/", policy_arn), length(split("/", policy_arn)) - 1)}" => {
        role_key   = role_key
        policy_arn = policy_arn
      }
    }
  ]...)
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "deployment" {
  for_each = local.roles

  statement {
    sid       = "CreateInstanceTags"
    effect    = "Allow"
    actions   = ["ec2:CreateTags"]
    resources = ["arn:aws:ec2:*:*:instance/*"]
  }

  statement {
    sid       = "PublishMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid       = "GetDeploymentObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = distinct(each.value.s3_get_objects)
  }

  dynamic "statement" {
    for_each = length(each.value.s3_list_prefixes) > 0 ? [1] : []

    content {
      sid       = "ListDeploymentBucket"
      effect    = "Allow"
      actions   = ["s3:ListBucket"]
      resources = [local.bucket_arn]

      condition {
        test     = "StringLike"
        variable = "s3:prefix"
        values   = each.value.s3_list_prefixes
      }
    }
  }
}

resource "aws_iam_role" "deployment" {
  for_each = local.roles

  name               = "${each.value.prefix}-${local.name_suffix}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name          = "${each.value.prefix}-${local.name_suffix}"
    Stack         = var.target_stack
    StackGithash  = var.stack_githash
  }
}

resource "aws_iam_instance_profile" "deployment" {
  for_each = local.roles

  name = "${each.value.prefix}-${local.name_suffix}"
  role = aws_iam_role.deployment[each.key].name

  tags = {
    Name          = "${each.value.prefix}-${local.name_suffix}"
    Stack         = var.target_stack
    StackGithash  = var.stack_githash
  }
}

resource "aws_iam_role_policy" "deployment" {
  for_each = local.roles

  name   = "${each.value.prefix}-policy-${local.name_suffix}"
  role   = aws_iam_role.deployment[each.key].id
  policy = data.aws_iam_policy_document.deployment[each.key].json
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = local.role_policy_attachments

  role       = aws_iam_role.deployment[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

output "instance_profile_names" {
  description = "Instance profile names keyed by tier"
  value       = { for k, v in aws_iam_instance_profile.deployment : k => v.name }
}

output "role_arns" {
  description = "IAM role ARNs keyed by tier"
  value       = { for k, v in aws_iam_role.deployment : k => v.arn }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables - General
################################################################################

variable "create" {
  description = "Whether to create any resources in this module"
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Whether to create a new security group. If false, rules are added to the existing security group given by security_group_id"
  type        = bool
  default     = true
}

variable "security_group_id" {
  description = "ID of an existing security group to add rules to when create_sg is false"
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "ID of the VPC where the security group is created or exists"
  type        = string
  default     = null
}

variable "name" {
  description = "Name of the security group to create"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Whether to use name as a prefix for the security group name"
  type        = bool
  default     = true
}

variable "description" {
  description = "Description of the security group"
  type        = string
  default     = "Security group managed by Terraform"
}

variable "create_before_destroy" {
  description = "Whether to enable the create_before_destroy lifecycle on the new security group"
  type        = bool
  default     = true
}

variable "revoke_rules_on_delete" {
  description = "Whether to revoke all attached ingress and egress rules before deleting the security group"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Rules
################################################################################

variable "ingress_rules" {
  description = "Ingress rules for the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id"
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = optional(string, "tcp")
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    tags                         = optional(map(string), {})
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.ingress_rules : length(compact([r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id])) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "egress_rules" {
  description = "Egress rules for the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id"
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = optional(string, "tcp")
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    tags                         = optional(map(string), {})
  }))
  default = [
    {
      description = "Allow all outbound IPv4 traffic"
      ip_protocol = "-1"
      cidr_ipv4   = "0.0.0.0/0"
    }
  ]

  validation {
    condition = alltrue([
      for r in var.egress_rules : length(compact([r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id])) == 1
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_ingress_rules" {
  description = "Ingress rules to add to the existing security group when create_sg is false"
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = optional(string, "tcp")
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    tags                         = optional(map(string), {})
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_sg_ingress_rules : length(compact([r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id])) == 1
    ])
    error_message = "Each existing_sg ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_egress_rules" {
  description = "Egress rules to add to the existing security group when create_sg is false"
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = optional(string, "tcp")
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    tags                         = optional(map(string), {})
  }))
  default = [
    {
      description = "Allow all outbound IPv4 traffic"
      ip_protocol = "-1"
      cidr_ipv4   = "0.0.0.0/0"
    }
  ]

  validation {
    condition = alltrue([
      for r in var.existing_sg_egress_rules : length(compact([r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id])) == 1
    ])
    error_message = "Each existing_sg egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

################################################################################
# Variables - Prefix List
################################################################################

variable "create_prefix_list" {
  description = "Whether to create a customer-managed prefix list (only created when prefix_list_ids is empty)"
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "IDs of existing prefix lists. If non-empty, no new prefix list is created"
  type        = list(string)
  default     = []
}

variable "prefix_list_name" {
  description = "Name of the prefix list to create. Defaults to the security group name"
  type        = string
  default     = null
}

variable "prefix_list_address_family" {
  description = "Address family of the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the prefix list can hold"
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "Entries to populate the prefix list with"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

################################################################################
# Locals
################################################################################

locals {
  create_new_sg      = var.create && var.create_sg
  use_existing_sg    = var.create && !var.create_sg
  create_prefix_list = var.create && var.create_prefix_list && length(var.prefix_list_ids) == 0

  this_sg_id = local.create_new_sg ? (
    var.create_before_destroy ? aws_security_group.this_cbd[0].id : aws_security_group.this[0].id
  ) : var.security_group_id

  new_ingress_rules      = local.create_new_sg ? { for idx, r in var.ingress_rules : tostring(idx) => r } : {}
  new_egress_rules       = local.create_new_sg ? { for idx, r in var.egress_rules : tostring(idx) => r } : {}
  existing_ingress_rules = local.use_existing_sg ? { for idx, r in var.existing_sg_ingress_rules : tostring(idx) => r } : {}
  existing_egress_rules  = local.use_existing_sg ? { for idx, r in var.existing_sg_egress_rules : tostring(idx) => r } : {}

  sg_name = coalesce(var.name, "managed-sg")
}

################################################################################
# Security Group
################################################################################

resource "aws_security_group" "this" {
  count = local.create_new_sg && !var.create_before_destroy ? 1 : 0

  name                   = var.use_name_prefix ? null : local.sg_name
  name_prefix            = var.use_name_prefix ? "${local.sg_name}-" : null
  description            = var.description
  vpc_id                 = var.vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(var.tags, { Name = local.sg_name })
}

resource "aws_security_group" "this_cbd" {
  count = local.create_new_sg && var.create_before_destroy ? 1 : 0

  name                   = var.use_name_prefix ? null : local.sg_name
  name_prefix            = var.use_name_prefix ? "${local.sg_name}-" : null
  description            = var.description
  vpc_id                 = var.vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(var.tags, { Name = local.sg_name })

  lifecycle {
    create_before_destroy = true
  }
}

################################################################################
# Rules - New Security Group
################################################################################

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.new_ingress_rules

  security_group_id = local.this_sg_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id

  tags = merge(var.tags, each.value.tags)
}

resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.new_egress_rules

  security_group_id = local.this_sg_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id

  tags = merge(var.tags, each.value.tags)
}

################################################################################
# Rules - Existing Security Group
################################################################################

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = local.existing_ingress_rules

  security_group_id = var.security_group_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id

  tags = merge(var.tags, each.value.tags)

  lifecycle {
    precondition {
      condition     = var.security_group_id != null && var.vpc_id != null
      error_message = "security_group_id and vpc_id must be set when create_sg is false."
    }
  }
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = local.existing_egress_rules

  security_group_id = var.security_group_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id

  tags = merge(var.tags, each.value.tags)

  lifecycle {
    precondition {
      condition     = var.security_group_id != null && var.vpc_id != null
      error_message = "security_group_id and vpc_id must be set when create_sg is false."
    }
  }
}

################################################################################
# Managed Prefix List
################################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = coalesce(var.prefix_list_name, "${local.sg_name}-prefix-list")
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries

    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(var.tags, { Name = coalesce(var.prefix_list_name, "${local.sg_name}-prefix-list") })

  lifecycle {
    precondition {
      condition     = length(var.prefix_list_entries) <= var.prefix_list_max_entries
      error_message = "The number of prefix_list_entries must not exceed prefix_list_max_entries."
    }
  }
}

################################################################################
# Outputs
################################################################################

output "security_group_id" {
  description = "ID of the security group (created or existing)"
  value       = var.create ? local.this_sg_id : null
}

output "security_group_arn" {
  description = "ARN of the created security group"
  value = local.create_new_sg ? (
    var.create_before_destroy ? aws_security_group.this_cbd[0].arn : aws_security_group.this[0].arn
  ) : null
}

output "security_group_name" {
  description = "Name of the created security group"
  value = local.create_new_sg ? (
    var.create_before_destroy ? aws_security_group.this_cbd[0].name : aws_security_group.this[0].name
  ) : null
}

output "vpc_id" {
  description = "ID of the VPC associated with the security group"
  value       = var.vpc_id
}

output "ingress_rule_ids" {
  description = "IDs of the ingress rules managed by this module"
  value = merge(
    { for k, r in aws_vpc_security_group_ingress_rule.this : k => r.security_group_rule_id },
    { for k, r in aws_vpc_security_group_ingress_rule.existing : k => r.security_group_rule_id }
  )
}

output "egress_rule_ids" {
  description = "IDs of the egress rules managed by this module"
  value = merge(
    { for k, r in aws_vpc_security_group_egress_rule.this : k => r.security_group_rule_id },
    { for k, r in aws_vpc_security_group_egress_rule.existing : k => r.security_group_rule_id }
  )
}

output "prefix_list_id" {
  description = "ID of the created managed prefix list"
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

output "prefix_list_arn" {
  description = "ARN of the created managed prefix list"
  value       = try(aws_ec2_managed_prefix_list.this[0].arn, null)
}

output "prefix_list_ids" {
  description = "Effective prefix list IDs (supplied or created)"
  value       = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : aws_ec2_managed_prefix_list.this[*].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "project" {
  description = "Project name used as a prefix for IAM resources"
  type        = string
  default     = "Cv-React-App"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# Trust policies
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codedeploy_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com",
        "cloudformation.amazonaws.com",
        "lambda.amazonaws.com",
      ]
    }

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

# -----------------------------------------------------------------------------
# EC2 CodeDeploy role + instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Project = var.project
  }
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_ec2_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_s3_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_codedeploy_instance_profile" {
  name = "${var.project}_ec2_codedeploy_instance_profile"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# -----------------------------------------------------------------------------
# CodeDeploy service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project}_codedeploy_service_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role.json

  tags = {
    Project = var.project
  }
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_role_codedeploy" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_role_s3_full" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

# -----------------------------------------------------------------------------
# EC2 CloudWatch Agent role + instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ec2_cloudwatch_agent_role" {
  name               = "${var.project}_ec2_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Project = var.project
  }
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_agent_role_cw_agent" {
  role       = aws_iam_role.ec2_cloudwatch_agent_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_agent_role_s3_full" {
