    type = "S"
  }

  attribute {
    name = "hk1"
    type = "S"
  }

  attribute {
    name = "sk1"
    type = "S"
  }

  global_secondary_index {
    name            = "hk1-sk1-Index"
    hash_key        = "hk1"
    range_key       = "sk1"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-hashes"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

