# ---------------------------------------------------------------------------
# SSM Parameters
# ---------------------------------------------------------------------------
locals {
  ssm_tables = {
    invitations = {
      prefix     = "/file-service/dynamodb/invitations"
      arn        = aws_dynamodb_table.near_files_invitations.arn
      name       = aws_dynamodb_table.near_files_invitations.name
      stream_arn = aws_dynamodb_table.near_files_invitations.stream_arn
    }
    files = {
      prefix     = "/file-service/dynamodb/files"
      arn        = aws_dynamodb_table.near_files.arn
      name       = aws_dynamodb_table.near_files.name
      stream_arn = aws_dynamodb_table.near_files.stream_arn
    }
    hashes = {
      prefix     = "/hashes-service/dynamodb/hashes"
      arn        = aws_dynamodb_table.near_hashes.arn
      name       = aws_dynamodb_table.near_hashes.name
      stream_arn = aws_dynamodb_table.near_hashes.stream_arn
    }
    storage = {
      prefix     = "/file-service/dynamodb/storage"
      arn        = aws_dynamodb_table.near_storage.arn
      name       = aws_dynamodb_table.near_storage.name
      stream_arn = aws_dynamodb_table.near_storage.stream_arn
    }
    wallets = {
      prefix     = "/wallet-service/dynamodb/wallets"
      arn        = aws_dynamodb_table.near_wallets.arn
      name       = aws_dynamodb_table.near_wallets.name
      stream_arn = aws_dynamodb_table.near_wallets.stream_arn
    }
  }
}

resource "aws_ssm_parameter" "table_arn" {
  for_each = local.ssm_tables

  name  = "${each.value.prefix}/arn"
  type  = "String"
  value = each.value.arn

  tags = {
    Name        = "${each.value.prefix}/arn"
    Environment = var.environment
  }
}

resource "aws_ssm_parameter" "table_name" {
  for_each = local.ssm_tables

  name  = "${each.value.prefix}/name"
  type  = "String"
  value = each.value.name

  tags = {
    Name        = "${each.value.prefix}/name"
    Environment = var.environment
  }
}

resource "aws_ssm_parameter" "table_stream_arn" {
  for_each = local.ssm_tables

  name  = "${each.value.prefix}/streamArn"
  type  = "String"
  value = each.value.stream_arn

  tags = {
    Name        = "${each.value.prefix}/streamArn"
    Environment = var.environment
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40.0"
    }
  }
}

provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Project   = var.name_prefix
      ManagedBy = "terraform"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region to deploy the chaos engineering environment into."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to resource names."
  type        = string
  default     = "fis-chaos"

  validation {
    condition     = can(regex("^[a-z0-9-]{3,20}$", var.name_prefix))
    error_message = "name_prefix must be 3-20 characters of lowercase letters, digits, or hyphens."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.20.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the single public subnet."
  type        = string
  default     = "10.20.1.0/24"
}

variable "admin_cidr" {
  description = "CIDR block allowed to SSH into the instances (e.g. 203.0.113.10/32)."
  type        = string

  validation {
    condition     = can(cidrhost(var.admin_cidr, 0)) && var.admin_cidr != "0.0.0.0/0"
    error_message = "admin_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

variable "ssh_public_key" {
  description = "SSH public key material accepted by the instances."
  type        = string

  validation {
    condition     = can(regex("^(ssh-rsa|ssh-ed25519|ecdsa-sha2-nistp(256|384|521)) ", var.ssh_public_key))
    error_message = "ssh_public_key must be an OpenSSH-formatted RSA, ED25519, or ECDSA public key."
  }
}

variable "instance_type" {
  description = "EC2 instance type for the Auto Scaling Group."
  type        = string
  default     = "t3.small"
}

variable "asg_min_size" {
  description = "Minimum number of instances in the Auto Scaling Group."
  type        = number
  default     = 2
}

variable "asg_max_size" {
  description = "Maximum number of instances in the Auto Scaling Group."
  type        = number
  default     = 3
}

variable "asg_desired_capacity" {
  description = "Desired number of instances in the Auto Scaling Group."
  type        = number
  default     = 2
}

variable "chaos_tag_key" {
  description = "Tag key used by FIS experiment templates to select targets."
  type        = string
  default     = "ChaosTarget"
}

variable "chaos_tag_value" {
  description = "Tag value used by FIS experiment templates to select targets."
  type        = string
  default     = "true"
}

variable "fault_duration" {
  description = "ISO 8601 duration for time-bound faults (e.g. PT5M)."
  type        = string
  default     = "PT5M"
}

variable "cpu_stress_duration_seconds" {
  description = "Duration in seconds for the CPU stress SSM document."
  type        = number
  default     = 120
}

variable "log_bucket_force_destroy" {
  description = "Allow Terraform to delete the FIS log bucket even when it contains objects."
  type        = bool
  default     = false
}

################################################################################
# Data sources & locals
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "ecs_optimized_ami" {
  name = "/aws/service/ecs/optimized-ami/amazon-linux-2023/recommended/image_id"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  chaos_tags = {
    (var.chaos_tag_key) = var.chaos_tag_value
  }

  log_bucket_name   = "${var.name_prefix}-fis-logs-${local.account_id}-${local.region}"
  log_delivery_arns = "arn:${local.partition}:logs:${local.region}:${local.account_id}:*"
}

################################################################################
# Networking
################################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.chaos_tags, {
    Name = "${var.name_prefix}-public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.name_prefix}-public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instances" {
  name        = "${var.name_prefix}-instances"
  description = "Chaos target instances: SSH from admin CIDR only"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "${var.name_prefix}-instances"
  }
}

resource "aws_vpc_security_group_ingress_rule" "ssh_admin" {
  security_group_id = aws_security_group.instances.id
  description       = "SSH from admin CIDR"
  cidr_ipv4         = var.admin_cidr
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "all" {
  security_group_id = aws_security_group.instances.id
  description       = "All outbound traffic (ECS agent, SSM, package installs)"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

################################################################################
# EC2 instance IAM (ECS + SSM)
################################################################################

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_instance" {
  name               = "${var.name_prefix}-ec2-instance"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_instance" {
  name = "${var.name_prefix}-ec2-instance"
  role = aws_iam_role.ec2_instance.name
}

################################################################################
# Compute: ECS cluster, launch template, Auto Scaling Group
################################################################################

resource "aws_ecs_cluster" "this" {
  name = "${var.name_prefix}-cluster"
}

resource "aws_key_pair" "admin" {
  key_name   = "${var.name_prefix}-admin"
  public_key = var.ssh_public_key
}

resource "aws_launch_template" "this" {
  name_prefix            = "${var.name_prefix}-"
  image_id               = data.aws_ssm_parameter.ecs_optimized_ami.value
  instance_type          = var.instance_type
  key_name               = aws_key_pair.admin.key_name
  update_default_version = true

  iam_instance_profile {
    arn = aws_iam_instance_profile.ec2_instance.arn
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "enabled"
  }

  network_interfaces {
    device_index                = 0
    associate_public_ip_address = true
    delete_on_termination       = true
    security_groups             = [aws_security_group.instances.id]
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  monitoring {
    enabled = true
  }

  user_data = base64encode(<<-EOF
    #!/bin/bash
    set -euo pipefail
    echo "ECS_CLUSTER=${aws_ecs_cluster.this.name}" >> /etc/ecs/ecs.config
  EOF
  )

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.chaos_tags, {
      Name = "${var.name_prefix}-instance"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.chaos_tags, {
      Name = "${var.name_prefix}-volume"
    })
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "this" {
  name                      = "${var.name_prefix}-asg"
  min_size                  = var.asg_min_size
  max_size                  = var.asg_max_size
  desired_capacity          = var.asg_desired_capacity
  vpc_zone_identifier       = [aws_subnet.public.id]
  health_check_type         = "EC2"
  health_check_grace_period = 120

  launch_template {
    id      = aws_launch_template.this.id
    version = aws_launch_template.this.latest_version
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 50
    }
  }

  tag {
    key                 = "Name"
    value               = "${var.name_prefix}-instance"
    propagate_at_launch = true
  }

  tag {
    key                 = var.chaos_tag_key
    value               = var.chaos_tag_value
    propagate_at_launch = true
  }

  depends_on = [
    aws_route.public_internet,
    aws_route_table_association.public,
  ]
}

################################################################################
# KMS key for FIS log bucket
################################################################################

data "aws_iam_policy_document" "fis_logs_kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid = "AllowAWSLogDeliveryUseOfKey"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.log_delivery_arns]
    }
  }
}

resource "aws_kms_key" "fis_logs" {
  description             = "CMK for ${var.name_prefix} FIS experiment logs bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.fis_logs_kms.json
}

resource "aws_kms_alias" "fis_logs" {
  name          = "alias/${var.name_prefix}-fis-logs"
  target_key_id = aws_kms_key.fis_logs.key_id
}

################################################################################
# S3 bucket for FIS experiment logs
################################################################################

resource "aws_s3_bucket" "fis_logs" {
  bucket        = local.log_bucket_name
  force_destroy = var.log_bucket_force_destroy
}

resource "aws_s3_bucket_ownership_controls" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_logs.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "fis_logs_bucket" {
  statement {
    sid       = "AWSLogDeliveryWrite"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.fis_logs.arn}/AWSLogs/${local.account_id}/*"]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.log_delivery_arns]
    }
  }

  statement {
    sid       = "AWSLogDeliveryAclCheck"
    actions   = ["s3:GetBucketAcl", "s3:ListBucket"]
    resources = [aws_s3_bucket.fis_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.log_delivery_arns]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.fis_logs.arn,
      "${aws_s3_bucket.fis_logs.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = data.aws_iam_policy_document.fis_logs_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.fis_logs]
}

################################################################################
# FIS IAM role
################################################################################

data "aws_iam_policy_document" "fis_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["fis.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:fis:${local.region}:${local.account_id}:experiment/*"]
    }
  }
}

resource "aws_iam_role" "fis" {
  name               = "${var.name_prefix}-fis-experiment"
  assume_role_policy = data.aws_iam_policy_document.fis_assume.json
}

data "aws_iam_policy_document" "fis_permissions" {
  statement {
    sid = "DescribeResources"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeVolumes",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeNetworkAcls",
      "ec2:DescribeManagedPrefixLists",
      "ec2:DescribeVpcPeeringConnections",
      "ec2:DescribeTransitGateways",
      "ec2:DescribeTransitGatewayAttachments",
      "ec2:DescribeVpcEndpoints",
      "ec2:GetManagedPrefixListEntries",
      "iam:ListRoles",
      "tag:GetResources",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "TerminateTaggedInstances"
    actions   = ["ec2:TerminateInstances"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/${var.chaos_tag_key}"
      values   = [var.chaos_tag_value]
    }
  }

  statement {
    sid       = "PauseTaggedVolumeIO"
    actions   = ["ec2:PauseVolumeIO"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:volume/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/${var.chaos_tag_key}"
      values   = [var.chaos_tag_value]
    }
  }

  statement {
    sid     = "SSMSendCommandDocument"
    actions = ["ssm:SendCommand"]
    resources = [
      "arn:${local.partition}:ssm:${local.region}::document/AWSFIS-Run-CPU-Stress",
    ]
  }

  statement {
    sid       = "SSMSendCommandTaggedInstances"
    actions   = ["ssm:SendCommand"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/${var.chaos_tag_key}"
      values   = [var.chaos_tag_value]
    }
  }

  statement {
    sid = "SSMCommandManagement"
    actions = [
      "ssm:ListCommands",
      "ssm:CancelCommand",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "NetworkDisruptCreateAcl"
    actions   = ["ec2:CreateNetworkAcl"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:network-acl/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:RequestTag/managedByFIS"
      values   = ["true"]
    }
  }

  statement {
    sid       = "NetworkDisruptCreateAclInVpc"
    actions   = ["ec2:CreateNetworkAcl"]
    resources = [aws_vpc.this.arn]
  }

  statement {
    sid       = "NetworkDisruptTagAcl"
    actions   = ["ec2:CreateTags"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:network-acl/*"]

    condition {
      test     = "StringEquals"
      variable = "ec2:CreateAction"
      values   = ["CreateNetworkAcl"]
    }
  }

  statement {
    sid = "NetworkDisruptManageFisAcls"
    actions = [
      "ec2:CreateNetworkAclEntry",
      "ec2:DeleteNetworkAcl",
    ]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:network-acl/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/managedByFIS"
      values   = ["true"]
    }
  }

  statement {
    sid     = "NetworkDisruptReplaceAclAssociation"
    actions = ["ec2:ReplaceNetworkAclAssociation"]
    resources = [
      "arn:${local.partition}:ec2:${local.region}:${local.account_id}:subnet/*",
      "arn:${local.partition}:ec2:${local.region}:${local.account_id}:network-acl/*",
    ]
  }

  statement {
    sid       = "InjectApiInternalError"
    actions   = ["fis:InjectApiInternalError"]
    resources = [aws_iam_role.ec2_instance.arn]
  }

  statement {
    sid = "ExperimentLogDelivery"
    actions = [
      "logs:CreateLogDelivery",
      "logs:GetLogDelivery",
      "logs:UpdateLogDelivery",
      "logs:DeleteLogDelivery",
      "logs:ListLogDeliveries",
    ]
    resources = ["*"]
  }

  statement {
    sid = "ExperimentLogBucketPolicy"
    actions = [
      "s3:GetBucketPolicy",
      "s3:PutBucketPolicy",
    ]
    resources = [aws_s3_bucket.fis_logs.arn]
  }
}

resource "aws_iam_role_policy" "fis" {
  name   = "${var.name_prefix}-fis-experiment"
  role   = aws_iam_role.fis.id
  policy = data.aws_iam_policy_document.fis_permissions.json
}

################################################################################
# FIS experiment templates
################################################################################

# The aws:fis:inject-api-* actions only support aws:iam:role targets, which FIS
# selects by ARN rather than by tag; the targeted role is the instance role used
# by the tagged chaos instances.
resource "aws_fis_experiment_template" "api_internal_error" {
  description = "Inject internal errors into EC2 DescribeImages calls made by the chaos instance role"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "inject-describe-images-internal-error"
    action_id = "aws:fis:inject-api-internal-error"

    parameter {
      key   = "service"
      value = "ec2"
    }

    parameter {
      key   = "operations"
      value = "DescribeImages"
    }

    parameter {
      key   = "percentage"
      value = "100"
    }

    parameter {
      key   = "duration"
      value = var.fault_duration
    }

    target {
      key   = "Roles"
      value = "chaos-instance-role"
    }
  }

  target {
    name           = "chaos-instance-role"
    resource_type  = "aws:iam:role"
    selection_mode = "ALL"
    resource_arns  = [aws_iam_role.ec2_instance.arn]
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "api-internal-error"
    }
  }

  tags = {
    Name = "${var.name_prefix}-api-internal-error"
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "Pause I/O on a tagged EBS volume"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "pause-volume-io"
    action_id = "aws:ebs:pause-volume-io"

    parameter {
      key   = "duration"
      value = var.fault_duration
    }

    target {
      key   = "Volumes"
      value = "chaos-volumes"
    }
  }

  target {
    name           = "chaos-volumes"
    resource_type  = "aws:ec2:ebs-volume"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = var.chaos_tag_key
      value = var.chaos_tag_value
    }

    filter {
      path   = "State"
      values = ["in-use"]
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "ebs-pause-io"
    }
  }

  tags = {
    Name = "${var.name_prefix}-ebs-pause-io"
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "ec2_cpu_stress" {
  description = "Run CPU stress on tagged EC2 instances via SSM"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "cpu-stress"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = "arn:${local.partition}:ssm:${local.region}::document/AWSFIS-Run-CPU-Stress"
    }

    parameter {
      key = "documentParameters"
      value = jsonencode({
        DurationSeconds     = tostring(var.cpu_stress_duration_seconds)
        CPU                 = "0"
        InstallDependencies = "True"
      })
    }

    parameter {
      key   = "duration"
      value = var.fault_duration
    }

    target {
      key   = "Instances"
      value = "chaos-instances"
    }
  }

  target {
    name           = "chaos-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = var.chaos_tag_key
      value = var.chaos_tag_value
    }

    filter {
      path   = "State.Name"
      values = ["running"]
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "ec2-cpu-stress"
    }
  }

  tags = {
    Name = "${var.name_prefix}-ec2-cpu-stress"
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "ec2_terminate" {
  description = "Terminate a tagged EC2 instance in the Auto Scaling Group"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "terminate-instance"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "chaos-instances"
    }
  }

  target {
    name           = "chaos-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = var.chaos_tag_key
      value = var.chaos_tag_value
    }

    filter {
      path   = "State.Name"
      values = ["running"]
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "ec2-terminate"
    }
  }

  tags = {
    Name = "${var.name_prefix}-ec2-terminate"
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "network_disrupt" {
  description = "Disrupt all network connectivity on the tagged subnet"
  role_arn    = aws_iam_role.fis.arn

  action {
    name      = "disrupt-connectivity"
    action_id = "aws:network:disrupt-connectivity"

    parameter {
      key   = "duration"
      value = var.fault_duration
    }

    parameter {
      key   = "scope"
      value = "all"
    }

    target {
      key   = "Subnets"
      value = "chaos-subnets"
    }
  }

  target {
    name           = "chaos-subnets"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"

    resource_tag {
      key   = var.chaos_tag_key
      value = var.chaos_tag_value
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "network-disrupt"
    }
  }

  tags = {
    Name = "${var.name_prefix}-network-disrupt"
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the chaos environment VPC."
  value       = aws_vpc.this.id
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "autoscaling_group_name" {
  description = "Name of the chaos target Auto Scaling Group."
  value       = aws_autoscaling_group.this.name
}

output "ecs_cluster_name" {
  description = "Name of the ECS cluster the instances register with."
  value       = aws_ecs_cluster.this.name
}

output "fis_role_arn" {
  description = "ARN of the IAM role assumed by FIS."
  value       = aws_iam_role.fis.arn
}

output "fis_log_bucket" {
  description = "Name of the S3 bucket receiving FIS experiment logs."
  value       = aws_s3_bucket.fis_logs.id
}

output "fis_log_kms_key_arn" {
  description = "ARN of the CMK encrypting the FIS log bucket."
  value       = aws_kms_key.fis_logs.arn
}

output "fis_experiment_template_ids" {
  description = "IDs of the FIS experiment templates."
  value = {
    api_internal_error = aws_fis_experiment_template.api_internal_error.id
    ebs_pause_io       = aws_fis_experiment_template.ebs_pause_io.id
    ec2_cpu_stress     = aws_fis_experiment_template.ec2_cpu_stress.id
    ec2_terminate      = aws_fis_experiment_template.ec2_terminate.id
    network_disrupt    = aws_fis_experiment_template.network_disrupt.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables - General
################################################################################

variable "name" {
  description = "Name used as an identifier on all created resources"
  type        = string
  default     = "main"
}

variable "tags" {
  description = "Tags applied to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - VPC
################################################################################

variable "create_vpc" {
  description = "Controls whether the VPC and all associated resources are created"
  type        = bool
  default     = true
}

variable "cidr" {
  description = "IPv4 CIDR block for the VPC. Ignored when an IPAM pool and netmask length are supplied"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "ID of an IPv4 IPAM pool to allocate the VPC CIDR from"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length of the IPv4 CIDR to allocate from the IPAM pool"
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_network_address_usage_metrics" {
  description = "Enable Network Address Usage metrics for the VPC"
  type        = bool
  default     = false
}

variable "enable_ipv6" {
  description = "Request an Amazon-provided IPv6 /56 CIDR block for the VPC"
  type        = bool
  default     = false
}

variable "vpc_tags" {
  description = "Additional tags for the VPC"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Subnets
################################################################################

variable "public_subnets" {
  description = "Map of public subnets. ipv6_prefix (0-255) carves a /64 from the VPC IPv6 block; ipv6_cidr_block sets it explicitly"
  type = map(object({
    cidr_block              = string
    availability_zone       = string
    ipv6_cidr_block         = optional(string)
    ipv6_prefix             = optional(number)
    ipv6_native             = optional(bool, false)
    map_public_ip_on_launch = optional(bool, true)
    tags                    = optional(map(string), {})
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnets. nat_gateway_key references a key in var.nat_gateways for default IPv4 egress"
  type = map(object({
    cidr_block        = string
    availability_zone = string
    ipv6_cidr_block   = optional(string)
    ipv6_prefix       = optional(number)
    ipv6_native       = optional(bool, false)
    nat_gateway_key   = optional(string)
    tags              = optional(map(string), {})
  }))
  default = {}
}

variable "public_subnet_tags" {
  description = "Additional tags for all public subnets"
  type        = map(string)
  default     = {}
}

variable "private_subnet_tags" {
  description = "Additional tags for all private subnets"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Gateways
################################################################################

variable "create_igw" {
  description = "Controls whether an Internet Gateway is created for public subnets"
  type        = bool
  default     = true
}

variable "create_egress_only_igw" {
  description = "Controls whether an Egress-Only Internet Gateway is created for IPv6 egress from private subnets"
  type        = bool
  default     = false
}

variable "nat_gateways" {
  description = "Map of NAT Gateways to create. subnet_key references a key in var.public_subnets"
  type = map(object({
    subnet_key = string
    tags       = optional(map(string), {})
  }))
  default = {}
}

################################################################################
# Variables - Network ACLs
################################################################################

variable "public_dedicated_network_acl" {
  description = "Whether to use a dedicated network ACL for public subnets"
  type        = bool
  default     = false
}

variable "public_inbound_acl_rules" {
  description = "Public subnet inbound network ACL rules"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "public_outbound_acl_rules" {
  description = "Public subnet outbound network ACL rules"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "private_dedicated_network_acl" {
  description = "Whether to use a dedicated network ACL for private subnets"
  type        = bool
  default     = false
}

variable "private_inbound_acl_rules" {
  description = "Private subnet inbound network ACL rules"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "private_outbound_acl_rules" {
  description = "Private subnet outbound network ACL rules"
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

################################################################################
# Variables - DHCP Options
################################################################################

variable "enable_dhcp_options" {
  description = "Controls whether a custom DHCP options set is created and associated with the VPC"
  type        = bool
  default     = false
}

variable "dhcp_options_domain_name" {
  description = "Domain name for the DHCP options set"
  type        = string
  default     = ""
}

variable "dhcp_options_domain_name_servers" {
  description = "List of DNS server addresses for the DHCP options set"
  type        = list(string)
  default     = ["AmazonProvidedDNS"]
}

variable "dhcp_options_ntp_servers" {
  description = "List of NTP servers for the DHCP options set"
  type        = list(string)
  default     = []
}

variable "dhcp_options_netbios_name_servers" {
  description = "List of NetBIOS name servers for the DHCP options set"
  type        = list(string)
  default     = []
}

variable "dhcp_options_netbios_node_type" {
  description = "NetBIOS node type for the DHCP options set"
  type        = string
  default     = ""
}

variable "dhcp_options_tags" {
  description = "Additional tags for the DHCP options set"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Flow Logs
################################################################################

variable "enable_flow_log" {
  description = "Whether to enable VPC flow logs"
  type        = bool
  default     = false
}

variable "flow_log_destination_type" {
  description = "Flow log destination type: cloud-watch-logs, s3, or kinesis-data-firehose"
  type        = string
  default     = "cloud-watch-logs"

  validation {
    condition     = contains(["cloud-watch-logs", "s3", "kinesis-data-firehose"], var.flow_log_destination_type)
    error_message = "flow_log_destination_type must be one of cloud-watch-logs, s3, or kinesis-data-firehose."
  }
}

variable "flow_log_destination_arn" {
  description = "ARN of the flow log destination. Required unless a CloudWatch log group is created by this module"
  type        = string
  default     = ""
}

variable "flow_log_cloudwatch_iam_role_arn" {
  description = "Existing IAM role ARN used to publish flow logs to CloudWatch"
  type        = string
  default     = ""
}

variable "create_flow_log_cloudwatch_log_group" {
  description = "Whether to create a CloudWatch log group for flow logs"
  type        = bool
  default     = false
}

variable "create_flow_log_cloudwatch_iam_role" {
  description = "Whether to create an IAM role for publishing flow logs to CloudWatch"
  type        = bool
  default     = false
}

variable "flow_log_cloudwatch_log_group_retention_in_days" {
  description = "Retention in days for the flow log CloudWatch log group"
  type        = number
  default     = 30
}

variable "flow_log_cloudwatch_log_group_kms_key_id" {
  description = "KMS key ARN used to encrypt the flow log CloudWatch log group"
  type        = string
  default     = null
}

variable "flow_log_traffic_type" {
  description = "Type of traffic to capture: ACCEPT, REJECT, or ALL"
  type        = string
  default     = "ALL"
}

variable "flow_log_log_format" {
  description = "Custom flow log record format. Null uses the AWS default format"
  type        = string
  default     = null
}

variable "flow_log_max_aggregation_interval" {
  description = "Maximum aggregation interval in seconds (60 or 600)"
  type        = number
  default     = 600

  validation {
    condition     = contains([60, 600], var.flow_log_max_aggregation_interval)
    error_message = "flow_log_max_aggregation_interval must be 60 or 600."
  }
}

variable "flow_log_file_format" {
  description = "S3 flow log file format: plain-text or parquet"
  type        = string
  default     = "plain-text"
}

variable "flow_log_hive_compatible_partitions" {
  description = "Use Hive-compatible prefixes for S3 flow logs"
  type        = bool
  default     = false
}

variable "flow_log_per_hour_partition" {
  description = "Partition S3 flow logs per hour"
  type        = bool
  default     = false
}

variable "flow_log_tags" {
  description = "Additional tags for flow log resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - Default Resources
################################################################################

variable "manage_default_security_group" {
  description = "Adopt and manage the VPC default security group"
  type        = bool
  default     = false
}

variable "default_security_group_ingress" {
  description = "Ingress rules for the default security group. Empty denies all inbound"
  type        = list(map(string))
  default     = []
}

variable "default_security_group_egress" {
  description = "Egress rules for the default security group. Empty denies all outbound"
  type        = list(map(string))
  default     = []
}

variable "manage_default_network_acl" {
  description = "Adopt and manage the VPC default network ACL"
  type        = bool
  default     = false
}

variable "default_network_acl_ingress" {
  description = "Ingress rules for the default network ACL"
  type        = list(map(string))
  default = [
    {
      rule_no    = 100
      action     = "allow"
      from_port  = 0
      to_port    = 0
      protocol   = "-1"
      cidr_block = "0.0.0.0/0"
    },
    {
      rule_no         = 101
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      ipv6_cidr_block = "::/0"
    },
  ]
}

variable "default_network_acl_egress" {
  description = "Egress rules for the default network ACL"
  type        = list(map(string))
  default = [
    {
      rule_no    = 100
      action     = "allow"
      from_port  = 0
      to_port    = 0
      protocol   = "-1"
      cidr_block = "0.0.0.0/0"
    },
    {
      rule_no         = 101
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      ipv6_cidr_block = "::/0"
    },
  ]
}

variable "manage_default_route_table" {
  description = "Adopt and manage the VPC default route table"
  type        = bool
  default     = false
}

variable "default_route_table_routes" {
  description = "Routes for the default route table"
  type        = list(map(string))
  default     = []
}

variable "default_route_table_propagating_vgws" {
  description = "Virtual gateways for route propagation on the default route table"
  type        = list(string)
  default     = []
}

################################################################################
# Locals
################################################################################

locals {
  create_vpc   = var.create_vpc
  use_ipam     = var.ipv4_ipam_pool_id != null && var.ipv4_netmask_length != null
  create_igw   = local.create_vpc && var.create_igw && length(var.public_subnets) > 0
  create_eigw  = local.create_vpc && var.create_egress_only_igw && var.enable_ipv6
  public_nacl  = local.create_vpc && var.public_dedicated_network_acl && length(var.public_subnets) > 0
  private_nacl = local.create_vpc && var.private_dedicated_network_acl && length(var.private_subnets) > 0

  # Resolves to the VPC ID only after secondary CIDRs are associated, so subnets in those ranges can be created
  vpc_id = try(aws_vpc_ipv4_cidr_block_association.this[0].vpc_id, aws_vpc.this[0].id, "")

  vpc_ipv6_cidr_block = try(aws_vpc.this[0].ipv6_cidr_block, null)

  private_subnets_with_nat = {
    for k, v in var.private_subnets : k => v if v.nat_gateway_key != null
  }

  enable_flow_log           = local.create_vpc && var.enable_flow_log
  flow_log_to_cloudwatch    = local.enable_flow_log && var.flow_log_destination_type == "cloud-watch-logs"
  create_flow_log_log_group = local.flow_log_to_cloudwatch && var.create_flow_log_cloudwatch_log_group
  create_flow_log_iam_role  = local.flow_log_to_cloudwatch && var.create_flow_log_cloudwatch_iam_role

  flow_log_destination_arn = local.create_flow_log_log_group ? aws_cloudwatch_log_group.flow_log[0].arn : var.flow_log_destination_arn
  flow_log_iam_role_arn    = local.flow_log_to_cloudwatch ? (local.create_flow_log_iam_role ? aws_iam_role.flow_log[0].arn : var.flow_log_cloudwatch_iam_role_arn) : null
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block          = local.use_ipam ? null : var.cidr
  ipv4_ipam_pool_id   = var.ipv4_ipam_pool_id
  ipv4_netmask_length = var.ipv4_netmask_length

  assign_generated_ipv6_cidr_block     = var.enable_ipv6
  instance_tenancy                     = var.instance_tenancy
  enable_dns_hostnames                 = var.enable_dns_hostnames
  enable_dns_support                   = var.enable_dns_support
  enable_network_address_usage_metrics = var.enable_network_address_usage_metrics

  tags = merge({ Name = var.name }, var.tags, var.vpc_tags)
}

resource "aws_vpc_ipv4_cidr_block_association" "this" {
  count = local.create_vpc ? length(var.secondary_cidr_blocks) : 0

  vpc_id     = aws_vpc.this[0].id
  cidr_block = element(var.secondary_cidr_blocks, count.index)
}

################################################################################
# DHCP Options
################################################################################

resource "aws_vpc_dhcp_options" "this" {
  count = local.create_vpc && var.enable_dhcp_options ? 1 : 0

  domain_name          = var.dhcp_options_domain_name != "" ? var.dhcp_options_domain_name : null
  domain_name_servers  = length(var.dhcp_options_domain_name_servers) > 0 ? var.dhcp_options_domain_name_servers : null
  ntp_servers          = length(var.dhcp_options_ntp_servers) > 0 ? var.dhcp_options_ntp_servers : null
  netbios_name_servers = length(var.dhcp_options_netbios_name_servers) > 0 ? var.dhcp_options_netbios_name_servers : null
  netbios_node_type    = var.dhcp_options_netbios_node_type != "" ? var.dhcp_options_netbios_node_type : null

  tags = merge({ Name = var.name }, var.tags, var.dhcp_options_tags)
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = local.create_vpc && var.enable_dhcp_options ? 1 : 0

  vpc_id          = local.vpc_id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

################################################################################
# Internet Gateways
################################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge({ Name = var.name }, var.tags)
}

resource "aws_egress_only_internet_gateway" "this" {
  count = local.create_eigw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge({ Name = var.name }, var.tags)
}

################################################################################
# Public Subnets
################################################################################

resource "aws_subnet" "public" {
  for_each = local.create_vpc ? var.public_subnets : {}

  vpc_id            = local.vpc_id
  availability_zone = each.value.availability_zone
  cidr_block        = each.value.ipv6_native ? null : each.value.cidr_block
  ipv6_native       = var.enable_ipv6 && each.value.ipv6_native

  ipv6_cidr_block = var.enable_ipv6 ? (
    each.value.ipv6_prefix != null ? cidrsubnet(local.vpc_ipv6_cidr_block, 8, each.value.ipv6_prefix) : each.value.ipv6_cidr_block
  ) : null

  assign_ipv6_address_on_creation = var.enable_ipv6 && (each.value.ipv6_prefix != null || each.value.ipv6_cidr_block != null)
  map_public_ip_on_launch         = each.value.ipv6_native ? false : each.value.map_public_ip_on_launch

  tags = merge(
    { Name = "${var.name}-public-${each.key}" },
    var.tags,
    var.public_subnet_tags,
    each.value.tags,
  )
}

resource "aws_route_table" "public" {
  count = local.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge({ Name = "${var.name}-public" }, var.tags)
}

resource "aws_route" "public_internet_gateway" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id

  timeouts {
    create = "5m"
  }
}

resource "aws_route" "public_internet_gateway_ipv6" {
  count = local.create_igw && var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.public[0].id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# NAT Gateways
################################################################################

resource "aws_eip" "nat" {
  for_each = local.create_vpc ? var.nat_gateways : {}

  domain = "vpc"

  tags = merge({ Name = "${var.name}-nat-${each.key}" }, var.tags, each.value.tags)

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  for_each = local.create_vpc ? var.nat_gateways : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.value.subnet_key].id

  tags = merge({ Name = "${var.name}-${each.key}" }, var.tags, each.value.tags)

  depends_on = [aws_internet_gateway.this]
}

################################################################################
# Private Subnets
################################################################################

resource "aws_subnet" "private" {
  for_each = local.create_vpc ? var.private_subnets : {}

  vpc_id            = local.vpc_id
  availability_zone = each.value.availability_zone
  cidr_block        = each.value.ipv6_native ? null : each.value.cidr_block
  ipv6_native       = var.enable_ipv6 && each.value.ipv6_native

  ipv6_cidr_block = var.enable_ipv6 ? (
    each.value.ipv6_prefix != null ? cidrsubnet(local.vpc_ipv6_cidr_block, 8, each.value.ipv6_prefix) : each.value.ipv6_cidr_block
  ) : null

  assign_ipv6_address_on_creation = var.enable_ipv6 && (each.value.ipv6_prefix != null || each.value.ipv6_cidr_block != null)

  tags = merge(
    { Name = "${var.name}-private-${each.key}" },
    var.tags,
    var.private_subnet_tags,
    each.value.tags,
  )
}

resource "aws_route_table" "private" {
  for_each = local.create_vpc ? var.private_subnets : {}

  vpc_id = local.vpc_id

  tags = merge({ Name = "${var.name}-private-${each.key}" }, var.tags)
}

resource "aws_route" "private_nat_gateway" {
  for_each = local.create_vpc ? local.private_subnets_with_nat : {}

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.value.nat_gateway_key].id

  timeouts {
    create = "5m"
  }
}

resource "aws_route" "private_ipv6_egress" {
  for_each = local.create_eigw ? var.private_subnets : {}

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id
}

################################################################################
# Public Network ACLs
################################################################################

resource "aws_network_acl" "public" {
  count = local.public_nacl ? 1 : 0

  vpc_id     = local.vpc_id
  subnet_ids = [for s in aws_subnet.public : s.id]

  tags = merge({ Name = "${var.name}-public" }, var.tags)
}

resource "aws_network_acl_rule" "public_inbound" {
  count = local.public_nacl ? length(var.public_inbound_acl_rules) : 0

  network_acl_id  = aws_network_acl.public[0].id
  egress          = false
  rule_number     = var.public_inbound_acl_rules[count.index]["rule_number"]
  rule_action     = var.public_inbound_acl_rules[count.index]["rule_action"]
  from_port       = lookup(var.public_inbound_acl_rules[count.index], "from_port", null)
  to_port         = lookup(var.public_inbound_acl_rules[count.index], "to_port", null)
  icmp_code       = lookup(var.public_inbound_acl_rules[count.index], "icmp_code", null)
  icmp_type       = lookup(var.public_inbound_acl_rules[count.index], "icmp_type", null)
  protocol        = var.public_inbound_acl_rules[count.index]["protocol"]
  cidr_block      = lookup(var.public_inbound_acl_rules[count.index], "cidr_block", null)
  ipv6_cidr_block = lookup(var.public_inbound_acl_rules[count.index], "ipv6_cidr_block", null)
}

resource "aws_network_acl_rule" "public_outbound" {
  count = local.public_nacl ? length(var.public_outbound_acl_rules) : 0

  network_acl_id  = aws_network_acl.public[0].id
  egress          = true
  rule_number     = var.public_outbound_acl_rules[count.index]["rule_number"]
  rule_action     = var.public_outbound_acl_rules[count.index]["rule_action"]
  from_port       = lookup(var.public_outbound_acl_rules[count.index], "from_port", null)
  to_port         = lookup(var.public_outbound_acl_rules[count.index], "to_port", null)
  icmp_code       = lookup(var.public_outbound_acl_rules[count.index], "icmp_code", null)
  icmp_type       = lookup(var.public_outbound_acl_rules[count.index], "icmp_type", null)
  protocol        = var.public_outbound_acl_rules[count.index]["protocol"]
  cidr_block      = lookup(var.public_outbound_acl_rules[count.index], "cidr_block", null)
  ipv6_cidr_block = lookup(var.public_outbound_acl_rules[count.index], "ipv6_cidr_block", null)
}

################################################################################
# Private Network ACLs
################################################################################

resource "aws_network_acl" "private" {
  count = local.private_nacl ? 1 : 0

  vpc_id     = local.vpc_id
  subnet_ids = [for s in aws_subnet.private : s.id]

  tags = merge({ Name = "${var.name}-private" }, var.tags)
}

resource "aws_network_acl_rule" "private_inbound" {
  count = local.private_nacl ? length(var.private_inbound_acl_rules) : 0

  network_acl_id  = aws_network_acl.private[0].id
  egress          = false
  rule_number     = var.private_inbound_acl_rules[count.index]["rule_number"]
  rule_action     = var.private_inbound_acl_rules[count.index]["rule_action"]
  from_port       = lookup(var.private_inbound_acl_rules[count.index], "from_port", null)
  to_port         = lookup(var.private_inbound_acl_rules[count.index], "to_port", null)
  icmp_code       = lookup(var.private_inbound_acl_rules[count.index], "icmp_code", null)
  icmp_type       = lookup(var.private_inbound_acl_rules[count.index], "icmp_type", null)
  protocol        = var.private_inbound_acl_rules[count.index]["protocol"]
  cidr_block      = lookup(var.private_inbound_acl_rules[count.index], "cidr_block", null)
  ipv6_cidr_block = lookup(var.private_inbound_acl_rules[count.index], "ipv6_cidr_block", null)
}

resource "aws_network_acl_rule" "private_outbound" {
  count = local.private_nacl ? length(var.private_outbound_acl_rules) : 0

  network_acl_id  = aws_network_acl.private[0].id
  egress          = true
  rule_number     = var.private_outbound_acl_rules[count.index]["rule_number"]
  rule_action     = var.private_outbound_acl_rules[count.index]["rule_action"]
  from_port       = lookup(var.private_outbound_acl_rules[count.index], "from_port", null)
  to_port         = lookup(var.private_outbound_acl_rules[count.index], "to_port", null)
  icmp_code       = lookup(var.private_outbound_acl_rules[count.index], "icmp_code", null)
  icmp_type       = lookup(var.private_outbound_acl_rules[count.index], "icmp_type", null)
  protocol        = var.private_outbound_acl_rules[count.index]["protocol"]
  cidr_block      = lookup(var.private_outbound_acl_rules[count.index], "cidr_block", null)
  ipv6_cidr_block = lookup(var.private_outbound_acl_rules[count.index], "ipv6_cidr_block", null)
}

################################################################################
# Flow Logs
################################################################################

resource "aws_cloudwatch_log_group" "flow_log" {
  count = local.create_flow_log_log_group ? 1 : 0

  name              = "/aws/vpc-flow-log/${var.name}"
  retention_in_days = var.flow_log_cloudwatch_log_group_retention_in_days
  kms_key_id        = var.flow_log_cloudwatch_log_group_kms_key_id

  tags = merge(var.tags, var.flow_log_tags)
}

data "aws_iam_policy_document" "flow_log_assume_role" {
  count = local.create_flow_log_iam_role ? 1 : 0

  statement {
    sid     = "AWSVPCFlowLogsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "flow_log" {
  count = local.create_flow_log_iam_role ? 1 : 0

  name_prefix        = "${var.name}-vpc-flow-log-"
  assume_role_policy = data.aws_iam_policy_document.flow_log_assume_role[0].json

  tags = merge(var.tags, var.flow_log_tags)
}

data "aws_iam_policy_document" "flow_log_cloudwatch" {
  count = local.create_flow_log_iam_role ? 1 : 0

  statement {
    sid    = "AWSVPCFlowLogsPushToCloudWatch"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]
    resources = local.create_flow_log_log_group ? [
      aws_cloudwatch_log_group.flow_log[0].arn,
      "${aws_cloudwatch_log_group.flow_log[0].arn}:*",
    ] : ["*"]
  }
}

resource "aws_iam_role_policy" "flow_log" {
  count = local.create_flow_log_iam_role ? 1 : 0

  name_prefix = "${var.name}-vpc-flow-log-"
  role        = aws_iam_role.flow_log[0].id
  policy      = data.aws_iam_policy_document.flow_log_cloudwatch[0].json
}

resource "aws_flow_log" "this" {
  count = local.enable_flow_log ? 1 : 0

  vpc_id                   = local.vpc_id
  traffic_type             = var.flow_log_traffic_type
  log_destination_type     = var.flow_log_destination_type
  log_destination          = local.flow_log_destination_arn
  log_format               = var.flow_log_log_format
  iam_role_arn             = local.flow_log_iam_role_arn
  max_aggregation_interval = var.flow_log_max_aggregation_interval

  dynamic "destination_options" {
    for_each = var.flow_log_destination_type == "s3" ? [true] : []

    content {
      file_format                = var.flow_log_file_format
      hive_compatible_partitions = var.flow_log_hive_compatible_partitions
      per_hour_partition         = var.flow_log_per_hour_partition
    }
  }

  tags = merge({ Name = var.name }, var.tags, var.flow_log_tags)
}

################################################################################
# Default Security Group
################################################################################

resource "aws_default_security_group" "this" {
  count = local.create_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  dynamic "ingress" {
    for_each = var.default_security_group_ingress

    content {
      self             = lookup(ingress.value, "self", null)
      cidr_blocks      = compact(split(",", lookup(ingress.value, "cidr_blocks", "")))
      ipv6_cidr_blocks = compact(split(",", lookup(ingress.value, "ipv6_cidr_blocks", "")))
      prefix_list_ids  = compact(split(",", lookup(ingress.value, "prefix_list_ids", "")))
      security_groups  = compact(split(",", lookup(ingress.value, "security_groups", "")))
      description      = lookup(ingress.value, "description", null)
      from_port        = lookup(ingress.value, "from_port", 0)
      to_port          = lookup(ingress.value, "to_port", 0)
      protocol         = lookup(ingress.value, "protocol", "-1")
    }
  }

  dynamic "egress" {
    for_each = var.default_security_group_egress

    content {
      self             = lookup(egress.value, "self", null)
      cidr_blocks      = compact(split(",", lookup(egress.value, "cidr_blocks", "")))
      ipv6_cidr_blocks = compact(split(",", lookup(egress.value, "ipv6_cidr_blocks", "")))
      prefix_list_ids  = compact(split(",", lookup(egress.value, "prefix_list_ids", "")))
      security_groups  = compact(split(",", lookup(egress.value, "security_groups", "")))
      description      = lookup(egress.value, "description", null)
      from_port        = lookup(egress.value, "from_port", 0)
      to_port          = lookup(egress.value, "to_port", 0)
      protocol         = lookup(egress.value, "protocol", "-1")
    }
  }

  tags = merge({ Name = "${var.name}-default" }, var.tags)
}

################################################################################
# Default Network ACL
################################################################################

resource "aws_default_network_acl" "this" {
  count = local.create_vpc && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  # Subnets not attached to a dedicated ACL remain on the default ACL; let AWS track membership
  subnet_ids = null

  dynamic "ingress" {
    for_each = var.default_network_acl_ingress

    content {
      action          = ingress.value.action
      cidr_block      = lookup(ingress.value, "cidr_block", null)
      from_port       = ingress.value.from_port
      icmp_code       = lookup(ingress.value, "icmp_code", null)
      icmp_type       = lookup(ingress.value, "icmp_type", null)
      ipv6_cidr_block = lookup(ingress.value, "ipv6_cidr_block", null)
      protocol        = ingress.value.protocol
      rule_no         = ingress.value.rule_no
      to_port         = ingress.value.to_port
    }
  }

  dynamic "egress" {
    for_each = var.default_network_acl_egress

    content {
      action          = egress.value.action
      cidr_block      = lookup(egress.value, "cidr_block", null)
      from_port       = egress.value.from_port
      icmp_code       = lookup(egress.value, "icmp_code", null)
      icmp_type       = lookup(egress.value, "icmp_type", null)
      ipv6_cidr_block = lookup(egress.value, "ipv6_cidr_block", null)
      protocol        = egress.value.protocol
      rule_no         = egress.value.rule_no
      to_port         = egress.value.to_port
    }
  }

  tags = merge({ Name = "${var.name}-default" }, var.tags)

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

################################################################################
# Default Route Table
################################################################################

resource "aws_default_route_table" "this" {
  count = local.create_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id
  propagating_vgws       = var.default_route_table_propagating_vgws

  dynamic "route" {
    for_each = var.default_route_table_routes

    content {
      cidr_block                 = lookup(route.value, "cidr_block", null)
      ipv6_cidr_block            = lookup(route.value, "ipv6_cidr_block", null)
      destination_prefix_list_id = lookup(route.value, "destination_prefix_list_id", null)
      egress_only_gateway_id     = lookup(route.value, "egress_only_gateway_id", null)
      gateway_id                 = lookup(route.value, "gateway_id", null)
      instance_id                = lookup(route.value, "instance_id", null)
      nat_gateway_id             = lookup(route.value, "nat_gateway_id", null)
      network_interface_id       = lookup(route.value, "network_interface_id", null)
      transit_gateway_id         = lookup(route.value, "transit_gateway_id", null)
      vpc_endpoint_id            = lookup(route.value, "vpc_endpoint_id", null)
      vpc_peering_connection_id  = lookup(route.value, "vpc_peering_connection_id", null)
    }
  }

  timeouts {
    create = "5m"
    update = "5m"
  }

  tags = merge({ Name = "${var.name}-default" }, var.tags)
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_arn" {
  description = "ARN of the VPC"
  value       = try(aws_vpc.this[0].arn, null)
}

output "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block of the VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "vpc_secondary_cidr_blocks" {
  description = "Secondary IPv4 CIDR blocks associated with the VPC"
  value       = aws_vpc_ipv4_cidr_block_association.this[*].cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block of the VPC"
  value       = local.vpc_ipv6_cidr_block
}

output "public_subnet_ids" {
  description = "Map of public subnet keys to IDs"
  value       = { for k, v in aws_subnet.public : k => v.id }
}

output "private_subnet_ids" {
  description = "Map of private subnet keys to IDs"
  value       = { for k, v in aws_subnet.private : k => v.id }
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "Map of private subnet keys to route table IDs"
  value       = { for k, v in aws_route_table.private : k => v.id }
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "egress_only_internet_gateway_id" {
  description = "ID of the Egress-Only Internet Gateway"
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
}

output "nat_gateway_ids" {
  description = "Map of NAT Gateway keys to IDs"
  value       = { for k, v in aws_nat_gateway.this : k => v.id }
}

output "nat_public_ips" {
  description = "Map of NAT Gateway keys to Elastic IP addresses"
  value       = { for k, v in aws_eip.nat : k => v.public_ip }
}

output "public_network_acl_id" {
  description = "ID of the dedicated public network ACL"
  value       = try(aws_network_acl.public[0].id, null)
}

output "private_network_acl_id" {
  description = "ID of the dedicated private network ACL"
  value       = try(aws_network_acl.private[0].id, null)
}

output "dhcp_options_id" {
  description = "ID of the DHCP options set"
  value       = try(aws_vpc_dhcp_options.this[0].id, null)
}

output "flow_log_id" {
  description = "ID of the VPC flow log"
  value       = try(aws_flow_log.this[0].id, null)
}

output "flow_log_cloudwatch_iam_role_arn" {
  description = "ARN of the IAM role used for CloudWatch flow logs"
  value       = local.flow_log_iam_role_arn
}

output "default_security_group_id" {
  description = "ID of the default security group"
  value       = try(aws_vpc.this[0].default_security_group_id, null)
}

output "default_network_acl_id" {
  description = "ID of the default network ACL"
  value       = try(aws_vpc.this[0].default_network_acl_id, null)
}

output "default_route_table_id" {
  description = "ID of the default route table"
  value       = try(aws_vpc.this[0].default_route_table_id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name of the Transfer Server. If null, a two-word random pet name is used."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "logging_role" {
  description = "ARN of an existing IAM role for Transfer logging. If null, a role with AWSTransferLoggingAccess is created."
  type        = string
  default     = null
}

variable "identity_provider_type" {
  description = "Identity provider type: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, or AWS_LAMBDA."
  type        = string
  default     = "SERVICE_MANAGED"

  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "AWS_LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be one of SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, AWS_LAMBDA."
  }
}

variable "api_gw_url" {
  description = "API Gateway URL used when identity_provider_type is API_GATEWAY."
  type        = string
  default     = null
}

variable "invocation_role" {
  description = "Existing IAM role ARN used to invoke the API Gateway identity provider. If null and API_GATEWAY is used, a role is created."
  type        = string
  default     = null
}

variable "directory_id" {
  description = "Directory ID used when identity_provider_type is AWS_DIRECTORY_SERVICE."
  type        = string
  default     = null
}

variable "function" {
  description = "Lambda function ARN used when identity_provider_type is AWS_LAMBDA."
  type        = string
  default     = null
}

variable "endpoint_type" {
  description = "Endpoint type of the Transfer Server: PUBLIC, VPC, or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "endpoint_details" {
  description = "Endpoint details for VPC or VPC_ENDPOINT endpoint types."
  type = object({
    address_allocation_ids = optional(list(string))
    security_group_ids     = optional(list(string))
    subnet_ids             = optional(list(string))
    vpc_endpoint_id        = optional(string)
    vpc_id                 = optional(string)
  })
  default = null
}

variable "domain" {
  description = "Storage domain for the Transfer Server: S3 or EFS."
  type        = string
  default     = "S3"

  validation {
    condition     = contains(["S3", "EFS"], var.domain)
    error_message = "domain must be S3 or EFS."
  }
}

variable "protocols" {
  description = "File transfer protocols enabled on the server."
  type        = list(string)
  default     = ["SFTP"]
}

variable "certificate" {
  description = "ACM certificate ARN, required when FTPS is enabled."
  type        = string
  default     = null
}

variable "pre_authentication_login_banner" {
  description = "Banner displayed to users before authentication."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "Banner displayed to users after authentication."
  type        = string
  default     = null
}

variable "security_policy_name" {
  description = "Security policy attached to the Transfer Server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "host_key" {
  description = "RSA, ECDSA, or ED25519 private key used as the server host key."
  type        = string
  default     = null
  sensitive   = true
}

variable "structured_log_destinations" {
  description = "List of CloudWatch log group ARNs (suffixed with :*) for structured logging."
  type        = list(string)
  default     = []
}

variable "protocol_details" {
  description = "Protocol settings for the Transfer Server."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = null
}

variable "force_destroy" {
  description = "Delete all users associated with the server when the server is destroyed."
  type        = bool
  default     = false
}

variable "zone_id" {
  description = "Route 53 hosted zone ID. If set, a CNAME record is created for the server endpoint."
  type        = string
  default     = null
}

variable "sub_domain" {
  description = "Sub-domain used for the Route 53 CNAME record."
  type        = string
  default     = "sftp"
}

variable "dns_ttl" {
  description = "TTL of the Route 53 CNAME record."
  type        = number
  default     = 300
}

variable "sftp_users" {
  description = "Map of SFTP users keyed by user name, each with an S3 home directory bucket and optional key prefix."
  type = map(object({
    home_directory_bucket     = string
    home_directory_key_prefix = optional(string, "")
  }))
  default = {}
}

variable "sftp_users_ssh_key" {
  description = "Map of SSH public keys keyed by user name. Keys are only associated with users present in sftp_users."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  server_name = coalesce(var.name, random_pet.name.id)

  create_logging_role = var.logging_role == null
  logging_role_arn    = local.create_logging_role ? aws_iam_role.logging[0].arn : var.logging_role

  is_api_gateway         = var.identity_provider_type == "API_GATEWAY"
  create_invocation_role = local.is_api_gateway && var.invocation_role == null
  invocation_role_arn = local.is_api_gateway ? (
    local.create_invocation_role ? aws_iam_role.api_gw[0].arn : var.invocation_role
  ) : null

  is_vpc = var.endpoint_type == "VPC"

  ep_subnet_ids       = try(coalesce(var.endpoint_details.subnet_ids, []), [])
  ep_security_groups  = try(coalesce(var.endpoint_details.security_group_ids, []), [])
  ep_allocation_ids   = try(coalesce(var.endpoint_details.address_allocation_ids, []), [])
  ep_vpc_id           = try(var.endpoint_details.vpc_id, null)
  ep_vpc_endpoint_id  = try(var.endpoint_details.vpc_endpoint_id, null)

  create_security_group = local.is_vpc && length(local.ep_security_groups) == 0
  create_eips           = local.is_vpc && length(local.ep_allocation_ids) == 0

  security_group_ids = local.create_security_group ? [aws_security_group.this[0].id] : local.ep_security_groups
  address_allocation_ids = local.create_eips ? [
    for eip in aws_eip.this : eip.allocation_id
  ] : local.ep_allocation_ids

  user_ssh_keys = {
    for user, key in var.sftp_users_ssh_key : user => key
    if contains(keys(var.sftp_users), user)
  }
}

################################################################################
# Naming
################################################################################

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

################################################################################
# Data sources
################################################################################

data "aws_partition" "current" {}

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

################################################################################
# Logging role
################################################################################

resource "aws_iam_role" "logging" {
  count = local.create_logging_role ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = local.create_logging_role ? 1 : 0

  role       = aws_iam_role.logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

################################################################################
# API Gateway invocation role
################################################################################

resource "aws_iam_role" "api_gw" {
  count = local.create_invocation_role ? 1 : 0

  name               = "${local.server_name}-transfer-api-gw"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "api_gw" {
  count = local.create_invocation_role ? 1 : 0

  statement {
    sid       = "InvokeApi"
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = ["arn:${data.aws_partition.current.partition}:execute-api:*:*:*"]
  }

  statement {
    sid       = "ReadApi"
    effect    = "Allow"
    actions   = ["apigateway:GET"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "api_gw" {
  count = local.create_invocation_role ? 1 : 0

  name   = "${local.server_name}-transfer-api-gw"
  role   = aws_iam_role.api_gw[0].id
  policy = data.aws_iam_policy_document.api_gw[0].json
}

################################################################################
# VPC networking
################################################################################

resource "aws_security_group" "this" {
  count = local.create_security_group ? 1 : 0

  name        = "${local.server_name}-transfer-sftp"
  description = "Security group for Transfer Server ${local.server_name}"
  vpc_id      = local.ep_vpc_id

  ingress {
    description = "SFTP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "${local.server_name}-transfer-sftp" })
}

resource "aws_eip" "this" {
  count = local.create_eips ? length(local.ep_subnet_ids) : 0

  domain = "vpc"
  tags   = merge(var.tags, { Name = "${local.server_name}-transfer-${count.index}" })
}

################################################################################
# Transfer Server
################################################################################

resource "aws_transfer_server" "this" {
  identity_provider_type = var.identity_provider_type
  url                    = local.is_api_gateway ? var.api_gw_url : null
  invocation_role        = local.invocation_role_arn
  directory_id           = var.identity_provider_type == "AWS_DIRECTORY_SERVICE" ? var.directory_id : null
  function               = var.identity_provider_type == "AWS_LAMBDA" ? var.function : null

  endpoint_type = var.endpoint_type
  domain        = var.domain
  protocols     = var.protocols
  certificate   = var.certificate

  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner
  security_policy_name             = var.security_policy_name
  host_key                         = var.host_key
  force_destroy                    = var.force_destroy

  logging_role                = local.logging_role_arn
  structured_log_destinations = length(var.structured_log_destinations) > 0 ? var.structured_log_destinations : null

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "VPC" ? [1] : []

    content {
      vpc_id                 = local.ep_vpc_id
      subnet_ids             = local.ep_subnet_ids
      security_group_ids     = local.security_group_ids
      address_allocation_ids = local.address_allocation_ids
    }
  }

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "VPC_ENDPOINT" ? [1] : []

    content {
      vpc_endpoint_id = local.ep_vpc_endpoint_id
    }
  }

  dynamic "protocol_details" {
    for_each = var.protocol_details != null ? [var.protocol_details] : []

    content {
      as2_transports              = protocol_details.value.as2_transports
      passive_ip                  = protocol_details.value.passive_ip
      set_stat_option             = protocol_details.value.set_stat_option
      tls_session_resumption_mode = protocol_details.value.tls_session_resumption_mode
    }
  }

  tags = merge(var.tags, { Name = local.server_name })
}

################################################################################
# Route 53
################################################################################

resource "aws_route53_record" "this" {
  count = var.zone_id != null ? 1 : 0

  zone_id = var.zone_id
  name    = var.sub_domain
  type    = "CNAME"
  ttl     = var.dns_ttl
  records = [aws_transfer_server.this.endpoint]
}

################################################################################
# SFTP users
################################################################################

resource "aws_iam_role" "user" {
  for_each = var.sftp_users

  name               = "${local.server_name}-transfer-user-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "user" {
  for_each = var.sftp_users

  statement {
    sid       = "ListHomeDirectory"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::${each.value.home_directory_bucket}"]

    dynamic "condition" {
      for_each = each.value.home_directory_key_prefix != "" ? [1] : []

      content {
        test     = "StringLike"
        variable = "s3:prefix"
        values = [
          trimsuffix(each.value.home_directory_key_prefix, "/"),
          "${trimsuffix(each.value.home_directory_key_prefix, "/")}/*",
        ]
      }
    }
  }

  statement {
    sid    = "HomeDirectoryObjectAccess"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectACL",
      "s3:PutObjectACL",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
    ]
    resources = [
      each.value.home_directory_key_prefix != "" ?
      "arn:${data.aws_partition.current.partition}:s3:::${each.value.home_directory_bucket}/${trimsuffix(each.value.home_directory_key_prefix, "/")}/*" :
      "arn:${data.aws_partition.current.partition}:s3:::${each.value.home_directory_bucket}/*"
    ]
  }
}

resource "aws_iam_role_policy" "user" {
  for_each = var.sftp_users

  name   = "${local.server_name}-transfer-user-${each.key}"
  role   = aws_iam_role.user[each.key].id
  policy = data.aws_iam_policy_document.user[each.key].json
}

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.this.id
  user_name = each.key
  role      = aws_iam_role.user[each.key].arn

  home_directory = each.value.home_directory_key_prefix != "" ? "/${each.value.home_directory_bucket}/${trimsuffix(each.value.home_directory_key_prefix, "/")}" : "/${each.value.home_directory_bucket}"

  tags = var.tags
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.user_ssh_keys

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.key].user_name
  body      = each.value
}

################################################################################
# Outputs
################################################################################

output "server_id" {
  description = "ID of the Transfer Server."
  value       = aws_transfer_server.this.id
}

output "server_arn" {
  description = "ARN of the Transfer Server."
  value       = aws_transfer_server.this.arn
}

output "server_name" {
  description = "Name of the Transfer Server."
  value       = local.server_name
}

output "server_endpoint" {
  description = "Endpoint of the Transfer Server."
  value       = aws_transfer_server.this.endpoint
}

output "logging_role_arn" {
  description = "ARN of the IAM role used for Transfer logging."
  value       = local.logging_role_arn
}

output "invocation_role_arn" {
  description = "ARN of the IAM role used to invoke the API Gateway identity provider."
  value       = local.invocation_role_arn
}

output "security_group_ids" {
  description = "Security group IDs attached to the VPC endpoint."
  value       = local.is_vpc ? local.security_group_ids : []
}

output "elastic_ips" {
  description = "Public IPs of Elastic IPs created for the VPC endpoint."
  value       = [for eip in aws_eip.this : eip.public_ip]
}

output "dns_record_fqdn" {
  description = "FQDN of the Route 53 CNAME record."
  value       = try(aws_route53_record.this[0].fqdn, null)
}

output "user_arns" {
  description = "Map of Transfer user names to ARNs."
  value       = { for k, u in aws_transfer_user.this : k => u.arn }
}

output "user_role_arns" {
  description = "Map of Transfer user names to IAM role ARNs."
  value       = { for k, r in aws_iam_role.user : k => r.arn }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "md-k8s"
}

variable "kubernetes_version" {
  description = "Kubernetes version for the EKS control plane (null uses the AWS default)"
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC"
  type        = string
  default     = "192.168.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"]
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  az_count = min(3, length(data.aws_availability_zones.available.names))
  azs      = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  public_subnet_cidrs  = slice(var.public_subnet_cidrs, 0, local.az_count)
  private_subnet_cidrs = slice(var.private_subnet_cidrs, 0, local.az_count)

  common_tags = {
    Cluster = var.cluster_name
  }
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                                        = "${var.cluster_name}-public-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  })
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                                        = "${var.cluster_name}-private-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"           = "1"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-private-rt"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this.id
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "private" {
  name       = "${var.cluster_name}-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-private-subnet-group"
  })
}

################################################################################
# KMS key for secrets envelope encryption
################################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowEKSClusterRoleUse"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.cluster.arn]
    }
  }
}

resource "aws_kms_key" "eks" {
  description             = "EKS secrets envelope encryption key for ${var.cluster_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-eks-secrets"
  })
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${var.cluster_name}-eks-secrets"
  target_key_id = aws_kms_key.eks.key_id
}

################################################################################
# IAM - cluster service role
################################################################################

data "aws_iam_policy_document" "cluster_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cluster" {
  name               = "${var.cluster_name}-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.cluster_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cluster_eks_cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "cluster_vpc_resource_controller" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

data "aws_iam_policy_document" "cluster_elb_sl_role_creation" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeAccountAttributes",
      "ec2:DescribeAddresses",
      "ec2:DescribeInternetGateways",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "cluster_elb_sl_role_creation" {
  name   = "${var.cluster_name}-elb-sl-role-creation"
  role   = aws_iam_role.cluster.id
  policy = data.aws_iam_policy_document.cluster_elb_sl_role_creation.json
}

data "aws_iam_policy_document" "cluster_cloudwatch_metrics" {
  statement {
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "cluster_cloudwatch_metrics" {
  name   = "${var.cluster_name}-cloudwatch-metrics"
  role   = aws_iam_role.cluster.id
  policy = data.aws_iam_policy_document.cluster_cloudwatch_metrics.json
}

################################################################################
# Security groups
################################################################################

resource "aws_security_group" "control_plane" {
  name        = "${var.cluster_name}-control-plane-sg"
  description = "Communication between the control plane and worker nodegroups"
  vpc_id      = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-control-plane-sg"
  })
}

resource "aws_vpc_security_group_egress_rule" "control_plane_vpc" {
  security_group_id = aws_security_group.control_plane.id
  description       = "Allow outbound traffic within the VPC"
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

resource "aws_security_group" "shared_node" {
  name        = "${var.cluster_name}-cluster-shared-node-sg"
  description = "Communication between all nodes in the cluster"
  vpc_id      = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-cluster-shared-node-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "shared_node_self" {
  security_group_id            = aws_security_group.shared_node.id
  description                  = "Allow nodes to communicate with each other (all ports)"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.shared_node.id
}

resource "aws_vpc_security_group_ingress_rule" "shared_node_from_cluster" {
  security_group_id            = aws_security_group.shared_node.id
  description                  = "Allow managed and unmanaged nodes to communicate with each other (all ports)"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
}

resource "aws_vpc_security_group_ingress_rule" "cluster_from_shared_node" {
  security_group_id            = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
  description                  = "Allow unmanaged nodes to communicate with control plane (all ports)"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.shared_node.id
}

resource "aws_vpc_security_group_egress_rule" "shared_node_vpc" {
  security_group_id = aws_security_group.shared_node.id
  description       = "Allow outbound traffic within the VPC"
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

################################################################################
# EKS cluster (control plane only)
################################################################################

resource "aws_eks_cluster" "this" {
  name     = var.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = var.kubernetes_version

  vpc_config {
    subnet_ids              = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
    security_group_ids      = [aws_security_group.control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.cluster_eks_cluster_policy,
    aws_iam_role_policy_attachment.cluster_vpc_resource_controller,
    aws_iam_role_policy.cluster_elb_sl_role_creation,
    aws_iam_role_policy.cluster_cloudwatch_metrics,
    aws_route_table_association.public,
    aws_route_table_association.private,
    aws_route.private_nat,
  ]
}

################################################################################
# Outputs
################################################################################

output "cluster_name" {
  value = aws_eks_cluster.this.name
}

output "cluster_endpoint" {
  value = aws_eks_cluster.this.endpoint
}

output "cluster_certificate_authority_data" {
  value = aws_eks_cluster.this.certificate_authority[0].data
}

output "cluster_security_group_id" {
  value = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
}

output "control_plane_security_group_id" {
  value = aws_security_group.control_plane.id
}

output "shared_node_security_group_id" {
  value = aws_security_group.shared_node.id
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "db_subnet_group_name" {
  value = aws_db_subnet_group.private.name
}

output "kms_key_arn" {
  value = aws_kms_key.eks.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "region" {
  type        = string
  description = "AWS region in which to create the bucket"
  default     = "us-east-1"
}

variable "enabled" {
  type        = bool
  description = "Set to false to prevent the module from creating any resources"
  default     = true
}

variable "namespace" {
  type        = string
  description = "Namespace, usually an abbreviation of your organization name"
  default     = null
}

variable "environment" {
  type        = string
  description = "Environment, e.g. 'uw2', 'us-west-2', or 'prod'"
  default     = null
}

variable "stage" {
  type        = string
  description = "Stage, e.g. 'prod', 'staging', 'dev'"
  default     = null
}

variable "name" {
  type        = string
  description = "Solution name, e.g. 'app' or 'assets'"
  default     = "bucket"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes appended to the generated ID"
  default     = []
}

variable "delimiter" {
  type        = string
  description = "Delimiter used between ID elements"
  default     = "-"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources"
  default     = {}
}

variable "force_destroy" {
  type        = bool
  description = "Delete all objects from the bucket so that it can be destroyed without error"
  default     = false
}

variable "versioning_enabled" {
  type        = bool
  description = "Enable object versioning"
  default     = true
}

variable "kms_encryption_enabled" {
  type        = bool
  description = "Use SSE-KMS encryption. When false, SSE-S3 (AES256) is used"
  default     = true
}

variable "kms_master_key_id" {
  type        = string
  description = "Existing KMS key ID/ARN to use for SSE-KMS. If empty, a dedicated customer-managed key is created"
  default     = ""
}

variable "kms_key_deletion_window_in_days" {
  type        = number
  description = "Deletion window for the created KMS key"
  default     = 30

  validation {
    condition     = var.kms_key_deletion_window_in_days >= 7 && var.kms_key_deletion_window_in_days <= 30
    error_message = "kms_key_deletion_window_in_days must be between 7 and 30."
  }
}

variable "bucket_key_enabled" {
  type        = bool
  description = "Enable S3 Bucket Keys to reduce KMS request costs"
  default     = true
}

variable "lifecycle_rules" {
  type = list(object({
    id                                     = string
    enabled                                = optional(bool, true)
    prefix                                 = optional(string, "")
    tags                                   = optional(map(string), {})
    standard_transition_days               = optional(number)
    glacier_transition_days                = optional(number)
    deep_archive_transition_days           = optional(number)
    expiration_days                        = optional(number)
    noncurrent_version_standard_ia_days    = optional(number)
    noncurrent_version_glacier_days        = optional(number)
    noncurrent_version_deep_archive_days   = optional(number)
    noncurrent_version_expiration_days     = optional(number)
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  description = "Lifecycle rules for transitions to STANDARD_IA, GLACIER, DEEP_ARCHIVE, expiration and noncurrent version handling"
  default     = []
}

variable "logging" {
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  description = "Bucket access logging configuration targeting a separate, existing bucket"
  default     = null
}

variable "website" {
  type = object({
    index_document = optional(string, "index.html")
    error_document = optional(string)
    routing_rules  = optional(string)
  })
  description = "Static website hosting configuration. routing_rules is a JSON-encoded array of routing rules"
  default     = null
}

variable "cors_rules" {
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string), [])
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number)
  }))
  description = "CORS rules for the bucket"
  default     = []
}

variable "object_lock_configuration" {
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  description = "Object lock default retention. Requires versioning; can only be enabled at bucket creation"
  default     = null

  validation {
    condition     = var.object_lock_configuration == null || try(contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_configuration.mode), false)
    error_message = "object_lock_configuration.mode must be GOVERNANCE or COMPLIANCE."
  }

  validation {
    condition     = var.object_lock_configuration == null || try((var.object_lock_configuration.days == null) != (var.object_lock_configuration.years == null), false)
    error_message = "Specify exactly one of object_lock_configuration.days or object_lock_configuration.years."
  }
}

variable "source_policy_documents" {
  type        = list(string)
  description = "JSON IAM policy documents merged into the bucket policy"
  default     = []
}

variable "allow_ssl_requests_only" {
  type        = bool
  description = "Add a bucket policy statement denying requests not made over TLS"
  default     = false
}

variable "acceleration_status" {
  type        = string
  description = "Transfer acceleration status: Enabled or Suspended. Null leaves it unmanaged"
  default     = null

  validation {
    condition     = var.acceleration_status == null || contains(["Enabled", "Suspended"], coalesce(var.acceleration_status, "Enabled"))
    error_message = "acceleration_status must be Enabled or Suspended."
  }
}

variable "request_payer" {
  type        = string
  description = "Who pays for requests and data transfer: BucketOwner or Requester. Null leaves it unmanaged"
  default     = null

  validation {
    condition     = var.request_payer == null || contains(["BucketOwner", "Requester"], coalesce(var.request_payer, "BucketOwner"))
    error_message = "request_payer must be BucketOwner or Requester."
  }
}

variable "acl" {
  type        = string
  description = "Canned ACL to apply. Ignored when grants are specified. Null disables ACLs (BucketOwnerEnforced)"
  default     = null

  validation {
    condition = var.acl == null || contains([
      "private", "public-read", "public-read-write", "aws-exec-read",
      "authenticated-read", "bucket-owner-read", "bucket-owner-full-control", "log-delivery-write"
    ], coalesce(var.acl, "private"))
    error_message = "acl must be a valid S3 canned ACL."
  }
}

variable "grants" {
  type = list(object({
    type        = string
    permissions = list(string)
    id          = optional(string)
    uri         = optional(string)
  }))
  description = "Fine-grained ACL grants. Takes precedence over the canned acl"
  default     = []
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  enabled = var.enabled

  create_kms_key = local.enabled && var.kms_encryption_enabled && var.kms_master_key_id == ""
  kms_key_id     = var.kms_encryption_enabled ? (local.create_kms_key ? one(aws_kms_key.default[*].arn) : var.kms_master_key_id) : null

  acl_enabled = var.acl != null || length(var.grants) > 0

  acl_grants = flatten([
    for g in var.grants : [
      for p in g.permissions : {
        type       = g.type
        id         = g.id
        uri        = g.uri
        permission = p
      }
    ]
  ])

  policy_enabled = local.enabled && (length(var.source_policy_documents) > 0 || var.allow_ssl_requests_only)
}

# ---------------------------------------------------------------------------
# Label
# ---------------------------------------------------------------------------

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled     = var.enabled
  namespace   = var.namespace
  environment = var.environment
  stage       = var.stage
  name        = var.name
  attributes  = var.attributes
  delimiter   = var.delimiter
  tags        = var.tags
}

data "aws_canonical_user_id" "default" {
  count = local.enabled && length(var.grants) > 0 ? 1 : 0
}

# ---------------------------------------------------------------------------
# KMS
# ---------------------------------------------------------------------------

resource "aws_kms_key" "default" {
  count = local.create_kms_key ? 1 : 0

  description             = "KMS key for S3 bucket ${module.label.id}"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  tags                    = module.label.tags
}

resource "aws_kms_alias" "default" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${module.label.id}"
  target_key_id = aws_kms_key.default[0].key_id
}

# ---------------------------------------------------------------------------
# Bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "default" {
  count = local.enabled ? 1 : 0

  bucket              = module.label.id
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_configuration != null
  tags                = module.label.tags
}

resource "aws_s3_bucket_public_access_block" "default" {
  count = local.enabled ? 1 : 0

  bucket                  = aws_s3_bucket.default[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "default" {
  count = local.enabled ? 1 : 0

  bucket = aws_s3_bucket.default[0].id

  rule {
    object_ownership = local.acl_enabled ? "BucketOwnerPreferred" : "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "default" {
  count = local.enabled ? 1 : 0

  bucket = aws_s3_bucket.default[0].id

  versioning_configuration {
    status = var.versioning_enabled || var.object_lock_configuration != null ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "default" {
  count = local.enabled ? 1 : 0

  bucket = aws_s3_bucket.default[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_encryption_enabled ? "aws:kms" : "AES256"
      kms_master_key_id = local.kms_key_id
    }
    bucket_key_enabled = var.kms_encryption_enabled ? var.bucket_key_enabled : null
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "default" {
  count = local.enabled && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.default[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = length(rule.value.tags) == 0 ? [1] : []
        content {
          prefix = rule.value.prefix
        }
      }

      dynamic "filter" {
        for_each = length(rule.value.tags) > 0 ? [1] : []
        content {
          and {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "transition" {
        for_each = {
          for k, v in {
            STANDARD_IA  = rule.value.standard_transition_days
            GLACIER      = rule.value.glacier_transition_days
            DEEP_ARCHIVE = rule.value.deep_archive_transition_days
          } : k => v if v != null
        }
        content {
          days          = transition.value
          storage_class = transition.key
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [rule.value.expiration_days] : []
        content {
          days = expiration.value
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = {
          for k, v in {
            STANDARD_IA  = rule.value.noncurrent_version_standard_ia_days
            GLACIER      = rule.value.noncurrent_version_glacier_days
            DEEP_ARCHIVE = rule.value.noncurrent_version_deep_archive_days
          } : k => v if v != null
        }
        content {
          noncurrent_days = noncurrent_version_transition.value
          storage_class   = noncurrent_version_transition.key
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [rule.value.noncurrent_version_expiration_days] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.default]
}

resource "aws_s3_bucket_logging" "default" {
  count = local.enabled && var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.default[0].id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_website_configuration" "default" {
  count = local.enabled && var.website != null ? 1 : 0

  bucket        = aws_s3_bucket.default[0].id
  routing_rules = var.website.routing_rules

  index_document {
    suffix = var.website.index_document
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "default" {
  count = local.enabled && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.default[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "default" {
  count = local.enabled && var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.default[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }

  depends_on = [aws_s3_bucket_versioning.default]
}

resource "aws_s3_bucket_accelerate_configuration" "default" {
  count = local.enabled && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.default[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "default" {
  count = local.enabled && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.default[0].id
  payer  = var.request_payer
}

resource "aws_s3_bucket_acl" "default" {
  count = local.enabled && local.acl_enabled ? 1 : 0

  bucket = aws_s3_bucket.default[0].id
  acl    = length(var.grants) == 0 ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = local.acl_grants
        content {
          grantee {
            type = grant.value.type
            id   = grant.value.id
            uri  = grant.value.uri
          }
          permission = grant.value.permission
        }
      }

      owner {
        id = one(data.aws_canonical_user_id.default[*].id)
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.default,
    aws_s3_bucket_public_access_block.default,
  ]
}

# ---------------------------------------------------------------------------
# Bucket policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "bucket_policy" {
  count = local.policy_enabled ? 1 : 0

  source_policy_documents = var.source_policy_documents

  dynamic "statement" {
    for_each = var.allow_ssl_requests_only ? [1] : []
    content {
      sid     = "ForceSSLOnlyAccess"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.default[0].arn,
        "${aws_s3_bucket.default[0].arn}/*",
      ]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "default" {
  count = local.policy_enabled ? 1 : 0

  bucket = aws_s3_bucket.default[0].id
  policy = data.aws_iam_policy_document.bucket_policy[0].json

  depends_on = [aws_s3_bucket_public_access_block.default]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "bucket_id" {
  description = "Bucket name"
  value       = one(aws_s3_bucket.default[*].id)
}

output "bucket_arn" {
  description = "Bucket ARN"
  value       = one(aws_s3_bucket.default[*].arn)
}

output "bucket_domain_name" {
  description = "Bucket domain name"
  value       = one(aws_s3_bucket.default[*].bucket_domain_name)
}

output "bucket_regional_domain_name" {
  description = "Bucket region-specific domain name"
  value       = one(aws_s3_bucket.default[*].bucket_regional_domain_name)
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for encryption (null when using AES256)"
  value       = local.enabled ? local.kms_key_id : null
}

output "tags" {
  description = "Tags applied to the bucket"
  value       = module.label.tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy the VPC into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC, used as a prefix for all resource names."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/18"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "az_count" {
  description = "Number of availability zones to use. Null (default) uses all available AZs in the region."
  type        = number
  default     = null

  validation {
    condition     = var.az_count == null ? true : (var.az_count >= 1 && var.az_count <= 8)
    error_message = "az_count must be between 1 and 8, or null to use all available AZs."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets (and the internet gateway)."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnet egress. Requires public subnets."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  available_azs = data.aws_availability_zones.available.names
  az_count      = min(var.az_count == null ? length(local.available_azs) : var.az_count, length(local.available_azs), 8)
  azs           = slice(local.available_azs, 0, local.az_count)

  # The /18 is split into 16 /22 blocks: indexes 0-7 for public, 8-15 for private.
  public_subnet_cidrs  = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, i)]
  private_subnet_cidrs = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, i + 8)]

  public_subnet_count  = var.create_public_subnets ? local.az_count : 0
  private_subnet_count = var.create_private_subnets ? local.az_count : 0
  create_igw           = var.create_public_subnets
  create_nat           = var.create_nat_gateway && var.create_public_subnets && var.create_private_subnets

  common_tags = merge(
    {
      ManagedBy = "terraform"
      VPC       = var.vpc_name
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

# Lock down the default security group so nothing uses it implicitly.
resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-default-sg"
  })
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

# -----------------------------------------------------------------------------
# NAT Gateway
# -----------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = local.create_nat ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.create_nat ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

# -----------------------------------------------------------------------------
# Route Tables
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  count = var.create_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  count = local.create_nat ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# -----------------------------------------------------------------------------
# Network ACLs
# -----------------------------------------------------------------------------

resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
    Tier = "public"
  })
}

resource "aws_network_acl_rule" "public_ingress_vpc" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = false
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
}

resource "aws_network_acl_rule" "public_ingress_http" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral_tcp" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 130
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_ingress_ephemeral_udp" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 140
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_egress_all" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = true
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
    Tier = "private"
  })
}

resource "aws_network_acl_rule" "private_ingress_vpc" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = false
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
}

resource "aws_network_acl_rule" "private_ingress_ephemeral_tcp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_ingress_ephemeral_udp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 120
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_all" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = true
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the VPC."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway, if created."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway, if created."
  value       = try(aws_nat_gateway.this[0].id, null)
}

output "nat_public_ip" {
  description = "Public IP of the NAT gateway, if created."
  value       = try(aws_eip.nat[0].public_ip, null)
}

output "public_route_table_id" {
  description = "ID of the public route table, if created."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_id" {
  description = "ID of the private route table, if created."
  value       = try(aws_route_table.private[0].id, null)
}

output "public_network_acl_id" {
  description = "ID of the public network ACL, if created."
  value       = try(aws_network_acl.public[0].id, null)
}

output "private_network_acl_id" {
  description = "ID of the private network ACL, if created."
  value       = try(aws_network_acl.private[0].id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC."
  type        = string
  default     = "main-vpc"
}

variable "vpc_cidr_block" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Whether to request an Amazon-provided IPv6 CIDR block for the VPC."
  type        = bool
  default     = true
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether DNS support is enabled in the VPC."
  type        = bool
  default     = true
}

variable "ipv4_subnet_new_bits" {
  description = "Additional bits added to the VPC IPv4 prefix for each subnet (/16 + 4 = /20)."
  type        = number
  default     = 4
}

variable "ipv6_subnet_new_bits" {
  description = "Additional bits added to the VPC IPv6 prefix for each subnet (/56 + 8 = /64)."
  type        = number
  default     = 8
}

variable "sn_details" {
  description = "List of subnet definitions: name, availability zone, and whether the subnet is public."
  type = list(object({
    name      = string
    az        = string
    is_public = bool
  }))
  default = [
    { name = "sn-reserved-a", az = "us-east-1a", is_public = false },
    { name = "sn-db-a", az = "us-east-1a", is_public = false },
    { name = "sn-app-a", az = "us-east-1a", is_public = false },
    { name = "sn-web-a", az = "us-east-1a", is_public = true },
    { name = "sn-reserved-b", az = "us-east-1b", is_public = false },
    { name = "sn-db-b", az = "us-east-1b", is_public = false },
    { name = "sn-app-b", az = "us-east-1b", is_public = false },
    { name = "sn-web-b", az = "us-east-1b", is_public = true },
    { name = "sn-reserved-c", az = "us-east-1c", is_public = false },
    { name = "sn-db-c", az = "us-east-1c", is_public = false },
    { name = "sn-app-c", az = "us-east-1c", is_public = false },
    { name = "sn-web-c", az = "us-east-1c", is_public = true },
  ]

  validation {
    condition     = length(var.sn_details) == length(distinct([for s in var.sn_details : s.name]))
    error_message = "Each subnet name in sn_details must be unique."
  }
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr_block
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support

  tags = {
    Name = var.vpc_name
  }
}

################################################################################
# Subnet CIDR calculation
################################################################################

module "subnet_addrs_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block
  networks = [
    for sn in var.sn_details : {
      name     = sn.name
      new_bits = var.ipv4_subnet_new_bits
    }
  ]
}

module "subnet_addrs_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"
  count   = var.is_ipv6_enabled ? 1 : 0

  base_cidr_block = aws_vpc.main.ipv6_cidr_block
  networks = [
    for sn in var.sn_details : {
      name     = sn.name
      new_bits = var.ipv6_subnet_new_bits
    }
  ]
}

locals {
  subnets_by_name = { for sn in var.sn_details : sn.name => sn }

  public_subnet_names = [for sn in var.sn_details : sn.name if sn.is_public]
}

################################################################################
# Subnets
################################################################################

resource "aws_subnet" "this" {
  for_each = local.subnets_by_name

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.az
  cidr_block        = module.subnet_addrs_ipv4.network_cidr_blocks[each.key]

  ipv6_cidr_block                 = var.is_ipv6_enabled ? module.subnet_addrs_ipv6[0].network_cidr_blocks[each.key] : null
  assign_ipv6_address_on_creation = var.is_ipv6_enabled
  map_public_ip_on_launch         = each.value.is_public

  tags = {
    Name   = each.key
    Public = tostring(each.value.is_public)
  }
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

################################################################################
# Public routing
################################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_default" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = toset(local.public_subnet_names)

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

################################################################################
# Security groups
################################################################################

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Web tier: TLS from internet, SSH from VPC, TLS egress to app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "App tier: TLS from web tier, TLS egress to db tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "DB tier: TLS from app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

# web_sg rules

resource "aws_vpc_security_group_ingress_rule" "web_tls_from_internet" {
  security_group_id = aws_security_group.web_sg.id
  description       = "TLS from anywhere"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_ingress_rule" "web_ssh_from_vpc" {
  security_group_id = aws_security_group.web_sg.id
  description       = "SSH from within the VPC"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_egress_rule" "web_tls_to_app" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "TLS to app tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.app_sg.id
}

# app_sg rules

resource "aws_vpc_security_group_ingress_rule" "app_tls_from_web" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "TLS from web tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.web_sg.id
}

resource "aws_vpc_security_group_egress_rule" "app_tls_to_db" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "TLS to db tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.db_sg.id
}

# db_sg rules

resource "aws_vpc_security_group_ingress_rule" "db_tls_from_app" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "TLS from app tier"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.app_sg.id
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  value = aws_vpc.main.ipv6_cidr_block
}

output "subnet_ids" {
  value = { for name, sn in aws_subnet.this : name => sn.id }
}

output "subnet_ipv4_cidrs" {
  value = module.subnet_addrs_ipv4.network_cidr_blocks
}

output "subnet_ipv6_cidrs" {
  value = var.is_ipv6_enabled ? module.subnet_addrs_ipv6[0].network_cidr_blocks : {}
}

output "internet_gateway_id" {
  value = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  value = aws_route_table.public.id
}

output "security_group_ids" {
  value = {
    web_sg = aws_security_group.web_sg.id
    app_sg = aws_security_group.app_sg.id
    db_sg  = aws_security_group.db_sg.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket used to store canary artifacts"
  type        = string
  default     = "benchmark-canary-bucket-tf5x"
}

variable "enable_versioning" {
  description = "Enable versioning on the canary artifact bucket"
  type        = bool
  default     = false
}

variable "enable_kms" {
  description = "Create and use a customer managed KMS key"
  type        = bool
  default     = true
}

variable "kms_alias" {
  description = "Alias for the customer managed KMS key"
  type        = string
  default     = "alias/benchmark-canary-key"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic used for canary failure notifications"
  type        = string
  default     = "benchmark-canary-topic"
}

variable "alert_email" {
  description = "Email address subscribed to canary failure notifications"
  type        = string
  default     = "nobody@example.com"
}

variable "enable_success_percent_alarm" {
  description = "Create an additional SuccessPercent alarm for each canary"
  type        = bool
  default     = false
}

variable "vpc_canaries" {
  description = "Map of VPC canary configurations. Provide either zip_file or s3_bucket/s3_key."
  type = map(object({
    name                = string
    handler             = string
    runtime_version     = string
    schedule_expression = optional(string, "rate(5 minutes)")
    subnet_ids          = list(string)
    security_group_ids  = list(string)
    zip_file            = optional(string)
    s3_bucket           = optional(string)
    s3_key              = optional(string)
    s3_version          = optional(string)
  }))
  default = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  kms_key_arn = var.enable_kms ? aws_kms_key.canary[0].arn : null
}

resource "random_pet" "role_prefix" {
  length    = 2
  separator = "-"
}

# KMS

data "aws_iam_policy_document" "kms" {
  statement {
    sid     = "EnableRootAccountPermissions"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    resources = ["*"]
  }
}

resource "aws_kms_key" "canary" {
  count = var.enable_kms ? 1 : 0

  description             = "KMS key for CloudWatch Synthetics canary artifacts and notifications"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
}

resource "aws_kms_alias" "canary" {
  count = var.enable_kms ? 1 : 0

  name          = var.kms_alias
  target_key_id = aws_kms_key.canary[0].key_id
}

# S3

resource "aws_s3_bucket" "canary" {
  bucket        = var.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "canary" {
  bucket = aws_s3_bucket.canary.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "canary" {
  bucket = aws_s3_bucket.canary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "canary" {
  bucket = aws_s3_bucket.canary.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary" {
  bucket = aws_s3_bucket.canary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = var.enable_kms
  }
}

# IAM

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "canary" {
  name_prefix        = "${random_pet.role_prefix.id}-"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

data "aws_iam_policy_document" "canary" {
  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
    ]
    resources = ["${aws_s3_bucket.canary.arn}/*"]
  }

  statement {
    sid    = "S3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:ListAllMyBuckets",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatchMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "cloudwatch:namespace"
      values   = ["CloudWatchSynthetics"]
    }
  }

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:${data.aws_partition.current.partition}:logs:*:*:*"]
  }

  statement {
    sid    = "EC2NetworkInterfaces"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
    ]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.enable_kms ? [1] : []

    content {
      sid    = "KMSAccess"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey",
      ]
      resources = [aws_kms_key.canary[0].arn]
    }
  }
}

resource "aws_iam_role_policy" "canary" {
  name   = "${random_pet.role_prefix.id}-canary-policy"
  role   = aws_iam_role.canary.id
  policy = data.aws_iam_policy_document.canary.json
}

# SNS

resource "aws_sns_topic" "canary" {
  name              = var.sns_topic_name
  kms_master_key_id = var.enable_kms ? aws_kms_key.canary[0].id : "alias/aws/sns"
}

resource "aws_sns_topic_subscription" "email" {
  topic_arn = aws_sns_topic.canary.arn
  protocol  = "email"
  endpoint  = var.alert_email
}

data "aws_iam_policy_document" "sns" {
  statement {
    sid       = "AllowCloudWatchAlarmsPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.canary.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "canary" {
  arn    = aws_sns_topic.canary.arn
  policy = data.aws_iam_policy_document.sns.json
}

# Canaries

resource "aws_synthetics_canary" "vpc" {
  for_each = var.vpc_canaries

  name                 = each.value.name
  artifact_s3_location = "s3://${aws_s3_bucket.canary.bucket}/${each.value.name}/"
  execution_role_arn   = aws_iam_role.canary.arn
  handler              = each.value.handler
  runtime_version      = each.value.runtime_version
  start_canary         = true

  zip_file   = each.value.zip_file
  s3_bucket  = each.value.zip_file == null ? each.value.s3_bucket : null
  s3_key     = each.value.zip_file == null ? each.value.s3_key : null
  s3_version = each.value.zip_file == null ? each.value.s3_version : null

  schedule {
    expression = each.value.schedule_expression
  }

  run_config {
    timeout_in_seconds = 120
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }

  depends_on = [
    aws_iam_role_policy.canary,
    aws_s3_bucket_server_side_encryption_configuration.canary,
  ]
}

# Alarms

resource "aws_cloudwatch_metric_alarm" "canary_failed" {
  for_each = var.vpc_canaries

  alarm_name          = "${each.value.name}-failed"
  alarm_description   = "Canary ${each.value.name} reported one or more failures"
  namespace           = "CloudWatchSynthetics"
  metric_name         = "Failed"
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = aws_synthetics_canary.vpc[each.key].name
  }

  alarm_actions = [aws_sns_topic.canary.arn]
}

resource "aws_cloudwatch_metric_alarm" "canary_success_percent" {
  for_each = var.enable_success_percent_alarm ? var.vpc_canaries : {}

  alarm_name          = "${each.value.name}-success-percent"
  alarm_description   = "Canary ${each.value.name} success percent fell below 90"
  namespace           = "CloudWatchSynthetics"
  metric_name         = "SuccessPercent"
  statistic           = "Average"
  period              = 60
  evaluation_periods  = 1
  threshold           = 90
  comparison_operator = "LessThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = aws_synthetics_canary.vpc[each.key].name
  }

  ok_actions = [aws_sns_topic.canary.arn]
}

output "canary_role_arn" {
  value = aws_iam_role.canary.arn
}

output "artifact_bucket_name" {
  value = aws_s3_bucket.canary.bucket
}

output "kms_key_arn" {
  value = local.kms_key_arn
}

output "sns_topic_arn" {
  value = aws_sns_topic.canary.arn
}

output "canary_names" {
  value = { for k, c in aws_synthetics_canary.vpc : k => c.name }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create_vpc" {
  description = "Controls if the VPC and all associated resources should be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name to be used as an identifier on all resources"
  type        = string
  default     = "main"
}

variable "cidr" {
  description = "The IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "azs" {
  description = "A list of availability zone names or IDs in the region"
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "A list of public subnet CIDR blocks inside the VPC"
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "A list of private subnet CIDR blocks inside the VPC"
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "A list of intra (isolated) subnet CIDR blocks inside the VPC"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix appended to public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix appended to private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix appended to intra subnet names"
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit values to use as the Name tag for public subnets. If empty, names are generated"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit values to use as the Name tag for private subnets. If empty, names are generated"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit values to use as the Name tag for intra subnets. If empty, names are generated"
  type        = list(string)
  default     = []
}

variable "map_public_ip_on_launch" {
  description = "Specify true to indicate that instances launched into the public subnets should be assigned a public IP address"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway is created for public subnets and the related routes"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Should be true to provision NAT Gateways for each of the private networks"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  # AZ IDs look like "use1-az1"; AZ names look like "us-east-1a"
  az_is_id = [for az in var.azs : can(regex("^[a-z]{2,5}[0-9]+-az[0-9]+$", az))]

  len_public_subnets  = length(var.public_subnets)
  len_private_subnets = length(var.private_subnets)
  len_intra_subnets   = length(var.intra_subnets)

  create_public_subnets  = var.create_vpc && local.len_public_subnets > 0
  create_private_subnets = var.create_vpc && local.len_private_subnets > 0
  create_intra_subnets   = var.create_vpc && local.len_intra_subnets > 0

  create_igw = local.create_public_subnets && var.create_igw

  nat_gateway_count = (
    local.create_public_subnets && local.create_private_subnets && var.enable_nat_gateway
    ? min(local.len_public_subnets, local.len_private_subnets)
    : 0
  )

  vpc_id = try(aws_vpc.this[0].id, "")
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    { "Name" = var.name },
    var.tags,
  )
}

################################################################################
# Public Subnets
################################################################################

resource "aws_subnet" "public" {
  count = local.create_public_subnets ? local.len_public_subnets : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = element(local.az_is_id, count.index) ? null : element(var.azs, count.index)
  availability_zone_id    = element(local.az_is_id, count.index) ? element(var.azs, count.index) : null
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    {
      "Name" = try(
        var.public_subnet_names[count.index],
        format("${var.name}-${var.public_subnet_suffix}-%s", element(var.azs, count.index))
      )
    },
    var.tags,
  )
}

resource "aws_route_table" "public" {
  count = local.create_public_subnets ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    { "Name" = "${var.name}-${var.public_subnet_suffix}" },
    var.tags,
  )
}

resource "aws_route_table_association" "public" {
  count = local.create_public_subnets ? local.len_public_subnets : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    { "Name" = var.name },
    var.tags,
  )
}

resource "aws_route" "public_internet_gateway" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id

  timeouts {
    create = "5m"
  }
}

################################################################################
# Private Subnets
################################################################################

resource "aws_subnet" "private" {
  count = local.create_private_subnets ? local.len_private_subnets : 0

  vpc_id               = local.vpc_id
  cidr_block           = var.private_subnets[count.index]
  availability_zone    = element(local.az_is_id, count.index) ? null : element(var.azs, count.index)
  availability_zone_id = element(local.az_is_id, count.index) ? element(var.azs, count.index) : null

  tags = merge(
    {
      "Name" = try(
        var.private_subnet_names[count.index],
        format("${var.name}-${var.private_subnet_suffix}-%s", element(var.azs, count.index))
      )
    },
    var.tags,
  )
}

resource "aws_route_table" "private" {
  count = local.create_private_subnets ? local.len_private_subnets : 0

  vpc_id = local.vpc_id

  tags = merge(
    {
      "Name" = format("${var.name}-${var.private_subnet_suffix}-%s", element(var.azs, count.index))
    },
    var.tags,
  )
}

resource "aws_route_table_association" "private" {
  count = local.create_private_subnets ? local.len_private_subnets : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

################################################################################
# NAT Gateways
################################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(
    {
      "Name" = format("${var.name}-%s", element(var.azs, count.index))
    },
    var.tags,
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    {
      "Name" = format("${var.name}-%s", element(var.azs, count.index))
    },
    var.tags,
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count > 0 ? local.len_private_subnets : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element(aws_nat_gateway.this[*].id, count.index)

  timeouts {
    create = "5m"
  }
}

################################################################################
# Intra Subnets (isolated, no internet routes)
################################################################################

resource "aws_subnet" "intra" {
  count = local.create_intra_subnets ? local.len_intra_subnets : 0

  vpc_id               = local.vpc_id
  cidr_block           = var.intra_subnets[count.index]
  availability_zone    = element(local.az_is_id, count.index) ? null : element(var.azs, count.index)
  availability_zone_id = element(local.az_is_id, count.index) ? element(var.azs, count.index) : null

  tags = merge(
    {
      "Name" = try(
        var.intra_subnet_names[count.index],
        format("${var.name}-${var.intra_subnet_suffix}-%s", element(var.azs, count.index))
      )
    },
    var.tags,
  )
}

resource "aws_route_table" "intra" {
  count = local.create_intra_subnets ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    { "Name" = "${var.name}-${var.intra_subnet_suffix}" },
    var.tags,
  )
}

resource "aws_route_table_association" "intra" {
  count = local.create_intra_subnets ? local.len_intra_subnets : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[0].id
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "public_subnets" {
  description = "List of IDs of public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnets" {
  description = "List of IDs of private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnets" {
  description = "List of IDs of intra subnets"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_ids" {
  description = "List of IDs of public route tables"
  value       = aws_route_table.public[*].id
}

output "private_route_table_ids" {
  description = "List of IDs of private route tables"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "List of IDs of intra route tables"
  value       = aws_route_table.intra[*].id
}

output "igw_id" {
  description = "The ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_ids" {
  description = "List of allocation IDs of Elastic IPs created for NAT Gateways"
  value       = aws_eip.nat[*].id
}

output "nat_public_ips" {
  description = "List of public Elastic IPs created for NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}

output "natgw_ids" {
  description = "List of NAT Gateway IDs"
  value       = aws_nat_gateway.this[*].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "api_type" {
  description = "Type of API Gateway to provision: \"http\" (API Gateway v2) or \"rest\" (API Gateway v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either \"http\" or \"rest\"."
  }
}

variable "api_name" {
  description = "Name of the API."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name. The stage is named \"<environment>-stage\"."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

# --- Networking / VPC link ---------------------------------------------------

variable "enable_vpc_link" {
  description = "Create a VPC link (HTTP: apigatewayv2 VPC link; REST: NLB + apigateway VPC link)."
  type        = bool
  default     = false
}

variable "vpc_id" {
  description = "VPC ID used for VPC link security groups and the NLB target group."
  type        = string
  default     = null
}

variable "private_subnet_ids" {
  description = "Private subnet IDs for the VPC link / internal NLB."
  type        = list(string)
  default     = []
}

variable "vpc_link_ingress_cidrs" {
  description = "CIDR blocks the HTTP API VPC link security group may send traffic to."
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "alb_id" {
  description = "ID (ARN) of the Application Load Balancer targeted by the REST API NLB target group."
  type        = string
  default     = null
}

variable "alb_port" {
  description = "TCP port of the ALB listener targeted by the NLB."
  type        = number
  default     = 443
}

variable "alb_health_check_path" {
  description = "HTTPS health check path used by the NLB target group."
  type        = string
  default     = "/"
}

# --- HTTP API ----------------------------------------------------------------

variable "http_routes" {
  description = "HTTP API routes keyed by route key (e.g. \"GET /items\", \"ANY /{proxy+}\")."
  type = map(object({
    integration_uri        = string
    integration_type       = optional(string, "HTTP_PROXY")
    integration_method     = optional(string, "ANY")
    use_vpc_link           = optional(bool, false)
    timeout_milliseconds   = optional(number, 30000)
    payload_format_version = optional(string)
  }))
  default = {}
}

variable "http_throttling_burst_limit" {
  description = "Default route throttling burst limit for the HTTP API stage."
  type        = number
  default     = 500
}

variable "http_throttling_rate_limit" {
  description = "Default route throttling rate limit for the HTTP API stage."
  type        = number
  default     = 1000
}

variable "enable_custom_domain" {
  description = "Create a custom domain and API mapping for the HTTP API."
  type        = bool
  default     = false
}

variable "domain_name" {
  description = "Custom domain name for the HTTP API."
  type        = string
  default     = null
}

variable "certificate_arn" {
  description = "Regional ACM certificate ARN for the custom domain."
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Create a Route 53 alias A record for the custom domain."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for the custom domain alias record."
  type        = string
  default     = null
}

# --- REST API ----------------------------------------------------------------

variable "rest_routes" {
  description = <<-EOT
    REST API routes. Paths may be up to three segments deep and may contain path
    parameters (e.g. "/users/{id}", "/{proxy+}"). Path parameters are automatically
    mapped from the method request to the integration request; entries in
    request_parameters override or extend those mappings.
  EOT
  type = map(object({
    path                   = string
    method                 = string
    integration_uri        = string
    integration_type       = optional(string, "HTTP_PROXY")
    integration_method     = optional(string, "ANY")
    use_vpc_link           = optional(bool, false)
    authorization_required = optional(bool, true)
    api_key_required       = optional(bool, false)
    request_parameters     = optional(map(string), {})
  }))
  default = {}

  validation {
    condition = alltrue([
      for r in values(var.rest_routes) : length(split("/", trim(r.path, "/"))) <= 3
    ])
    error_message = "REST route paths may be at most three segments deep."
  }
}

variable "allowed_source_ips" {
  description = "If non-empty, attach a resource policy restricting REST API access to these CIDRs."
  type        = list(string)
  default     = []
}

variable "enable_api_key" {
  description = "Create a usage plan and API key (stored in SSM as a SecureString) for the REST API."
  type        = bool
  default     = false
}

variable "usage_plan_quota_limit" {
  description = "Maximum number of requests per day for the usage plan."
  type        = number
  default     = 10000
}

variable "usage_plan_burst_limit" {
  description = "Usage plan throttle burst limit."
  type        = number
  default     = 100
}

variable "usage_plan_rate_limit" {
  description = "Usage plan throttle rate limit."
  type        = number
  default     = 50
}

variable "enable_authorizer" {
  description = "Create a custom Lambda TOKEN authorizer for the REST API."
  type        = bool
  default     = false
}

variable "authorizer_runtime" {
  # nodejs16.x is deprecated by AWS Lambda; override if function creation is blocked.
  description = "Runtime for the Lambda authorizer function."
  type        = string
  default     = "nodejs16.x"
}

variable "authorizer_result_ttl_in_seconds" {
  description = "TTL for cached authorizer results."
  type        = number
  default     = 300
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  is_http = var.api_type == "http"
  is_rest = var.api_type == "rest"

  name_prefix = "${var.api_name}-${var.environment}"
  stage_name  = "${var.environment}-stage"

  common_tags = merge(
    {
      Name        = var.api_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )

  create_http_vpc_link   = local.is_http && var.enable_vpc_link
  create_rest_vpc_link   = local.is_rest && var.enable_vpc_link
  create_custom_domain   = local.is_http && var.enable_custom_domain
  create_route53_record  = local.create_custom_domain && var.create_route53_record
  create_rest_policy     = local.is_rest && length(var.allowed_source_ips) > 0
  create_rest_api_key    = local.is_rest && var.enable_api_key
  create_rest_authorizer = local.is_rest && var.enable_authorizer

  # REST resource tree: every prefix of every route path, split by depth.
  rest_route_paths = { for k, r in var.rest_routes : k => trim(r.path, "/") }

  rest_all_paths = distinct(flatten([
    for p in values(local.rest_route_paths) : p == "" ? [] : [
      for i in range(length(split("/", p))) : join("/", slice(split("/", p), 0, i + 1))
    ]
  ]))

  rest_level1 = {
    for p in local.rest_all_paths : p => p
    if local.is_rest && length(split("/", p)) == 1
  }

  rest_level2 = {
    for p in local.rest_all_paths : p => {
      parent = join("/", slice(split("/", p), 0, 1))
      part   = element(split("/", p), 1)
    }
    if local.is_rest && length(split("/", p)) == 2
  }

  rest_level3 = {
    for p in local.rest_all_paths : p => {
      parent = join("/", slice(split("/", p), 0, 2))
      part   = element(split("/", p), 2)
    }
    if local.is_rest && length(split("/", p)) == 3
  }

  rest_resource_ids = merge(
    { "" = one(aws_api_gateway_rest_api.this[*].root_resource_id) },
    { for k, r in aws_api_gateway_resource.level1 : k => r.id },
    { for k, r in aws_api_gateway_resource.level2 : k => r.id },
    { for k, r in aws_api_gateway_resource.level3 : k => r.id },
  )

  # Path parameter names per route; "{proxy+}" yields "proxy".
  rest_path_params = {
    for k, p in local.rest_route_paths : k => flatten(regexall("\\{([^}+]+)\\+?\\}", p))
  }

  rest_methods = local.is_rest ? var.rest_routes : {}
}

# -----------------------------------------------------------------------------
# HTTP API (v2)
# -----------------------------------------------------------------------------

resource "aws_apigatewayv2_api" "this" {
  count = local.is_http ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"
  tags          = local.common_tags
}

resource "aws_security_group" "http_vpc_link" {
  count = local.create_http_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-vpc-link"
  description = "Security group for the ${var.api_name} HTTP API VPC link"
  vpc_id      = var.vpc_id

  egress {
    description = "Allow VPC link traffic to private backends"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = var.vpc_link_ingress_cidrs
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_vpc_link" "this" {
  count = local.create_http_vpc_link ? 1 : 0

  name               = "${local.name_prefix}-vpc-link"
  subnet_ids         = var.private_subnet_ids
  security_group_ids = [aws_security_group.http_vpc_link[0].id]
  tags               = local.common_tags
}

resource "aws_apigatewayv2_integration" "this" {
  for_each = local.is_http ? var.http_routes : {}

  api_id                 = aws_apigatewayv2_api.this[0].id
  integration_type       = each.value.integration_type
  integration_uri        = each.value.integration_uri
  integration_method     = each.value.integration_method
  timeout_milliseconds   = each.value.timeout_milliseconds
  payload_format_version = coalesce(each.value.payload_format_version, each.value.integration_type == "AWS_PROXY" ? "2.0" : "1.0")

  connection_type = each.value.use_vpc_link && local.create_http_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id   = each.value.use_vpc_link && local.create_http_vpc_link ? aws_apigatewayv2_vpc_link.this[0].id : null
}

resource "aws_apigatewayv2_route" "this" {
  for_each = local.is_http ? var.http_routes : {}

  api_id    = aws_apigatewayv2_api.this[0].id
  route_key = each.key
  target    = "integrations/${aws_apigatewayv2_integration.this[each.key].id}"
}

resource "aws_apigatewayv2_stage" "this" {
  count = local.is_http ? 1 : 0

  api_id      = aws_apigatewayv2_api.this[0].id
  name        = local.stage_name
  auto_deploy = true

  default_route_settings {
    throttling_burst_limit = var.http_throttling_burst_limit
    throttling_rate_limit  = var.http_throttling_rate_limit
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_domain_name" "this" {
  count = local.create_custom_domain ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = var.certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = local.common_tags

  lifecycle {
    precondition {
      condition     = var.domain_name != null && var.certificate_arn != null
      error_message = "domain_name and certificate_arn are required when enable_custom_domain is true."
    }
  }
}

resource "aws_apigatewayv2_api_mapping" "this" {
  count = local.create_custom_domain ? 1 : 0

  api_id      = aws_apigatewayv2_api.this[0].id
  domain_name = aws_apigatewayv2_domain_name.this[0].id
  stage       = aws_apigatewayv2_stage.this[0].id
}

resource "aws_route53_record" "this" {
  count = local.create_route53_record ? 1 : 0

  zone_id = var.route53_zone_id
  name    = aws_apigatewayv2_domain_name.this[0].domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.this[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# -----------------------------------------------------------------------------
# REST API (v1)
# -----------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "this" {
  count = local.is_rest ? 1 : 0

  name = var.api_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "level1" {
  for_each = local.rest_level1

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  parent_id   = aws_api_gateway_rest_api.this[0].root_resource_id
  path_part   = each.value
}

resource "aws_api_gateway_resource" "level2" {
  for_each = local.rest_level2

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  parent_id   = aws_api_gateway_resource.level1[each.value.parent].id
  path_part   = each.value.part
}

resource "aws_api_gateway_resource" "level3" {
  for_each = local.rest_level3

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  parent_id   = aws_api_gateway_resource.level2[each.value.parent].id
  path_part   = each.value.part
}

resource "aws_api_gateway_method" "this" {
  for_each = local.rest_methods

  rest_api_id      = aws_api_gateway_rest_api.this[0].id
  resource_id      = local.rest_resource_ids[local.rest_route_paths[each.key]]
  http_method      = upper(each.value.method)
  api_key_required = each.value.api_key_required

  authorization = local.create_rest_authorizer && each.value.authorization_required ? "CUSTOM" : "NONE"
  authorizer_id = local.create_rest_authorizer && each.value.authorization_required ? aws_api_gateway_authorizer.this[0].id : null

  request_parameters = {
    for p in local.rest_path_params[each.key] : "method.request.path.${p}" => true
  }
}

resource "aws_api_gateway_integration" "this" {
  for_each = local.rest_methods

  rest_api_id             = aws_api_gateway_rest_api.this[0].id
  resource_id             = aws_api_gateway_method.this[each.key].resource_id
  http_method             = aws_api_gateway_method.this[each.key].http_method
  type                    = each.value.integration_type
  uri                     = each.value.integration_uri
  integration_http_method = each.value.integration_method

  connection_type = each.value.use_vpc_link && local.create_rest_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id   = each.value.use_vpc_link && local.create_rest_vpc_link ? aws_api_gateway_vpc_link.this[0].id : null

  request_parameters = merge(
    {
      for p in local.rest_path_params[each.key] : "integration.request.path.${p}" => "method.request.path.${p}"
    },
    each.value.request_parameters
  )
}

data "aws_iam_policy_document" "rest_ip_restriction" {
  count = local.create_rest_policy ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = ["${aws_api_gateway_rest_api.this[0].execution_arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }

  statement {
    effect    = "Deny"
    actions   = ["execute-api:Invoke"]
    resources = ["${aws_api_gateway_rest_api.this[0].execution_arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "NotIpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_source_ips
    }
  }
}

resource "aws_api_gateway_rest_api_policy" "this" {
  count = local.create_rest_policy ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  policy      = data.aws_iam_policy_document.rest_ip_restriction[0].json
}

resource "aws_api_gateway_deployment" "this" {
  count = local.is_rest ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      var.rest_routes,
      local.rest_resource_ids,
      [for m in aws_api_gateway_method.this : m.id],
      [for i in aws_api_gateway_integration.this : i.id],
      one(aws_api_gateway_rest_api_policy.this[*].policy),
      one(aws_api_gateway_authorizer.this[*].id),
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.this,
    aws_api_gateway_integration.this,
    aws_api_gateway_rest_api_policy.this,
  ]
}

resource "aws_api_gateway_stage" "this" {
  count = local.is_rest ? 1 : 0

  rest_api_id   = aws_api_gateway_rest_api.this[0].id
  deployment_id = aws_api_gateway_deployment.this[0].id
  stage_name    = local.stage_name
  tags          = local.common_tags
}

# --- Usage plan & API key ----------------------------------------------------

resource "aws_api_gateway_api_key" "this" {
  count = local.create_rest_api_key ? 1 : 0

  name    = "${local.name_prefix}-key"
  enabled = true
  tags    = local.common_tags
}

resource "aws_api_gateway_usage_plan" "this" {
  count = local.create_rest_api_key ? 1 : 0

  name = "${local.name_prefix}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.this[0].id
    stage  = aws_api_gateway_stage.this[0].stage_name
  }

  quota_settings {
    limit  = var.usage_plan_quota_limit
    period = "DAY"
  }

  throttle_settings {
    burst_limit = var.usage_plan_burst_limit
    rate_limit  = var.usage_plan_rate_limit
  }

  tags = local.common_tags
}

resource "aws_api_gateway_usage_plan_key" "this" {
  count = local.create_rest_api_key ? 1 : 0

  key_id        = aws_api_gateway_api_key.this[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.this[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = local.create_rest_api_key ? 1 : 0

  name        = "/${var.api_name}/${var.environment}/api-key"
  description = "API key for ${var.api_name} (${var.environment})"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.this[0].value
  tags        = local.common_tags
}

# --- Lambda authorizer -------------------------------------------------------

resource "random_password" "authorizer_token" {
  count = local.create_rest_authorizer ? 1 : 0

  length  = 40
  special = false
}

resource "aws_ssm_parameter" "authorizer_token" {
  count = local.create_rest_authorizer ? 1 : 0

  name        = "/${var.api_name}/${var.environment}/authorizer-token"
  description = "Bearer token accepted by the ${var.api_name} Lambda authorizer"
  type        = "SecureString"
  value       = random_password.authorizer_token[0].result
  tags        = local.common_tags
}

data "archive_file" "authorizer" {
  count = local.create_rest_authorizer ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/.build/authorizer.zip"

  source {
    filename = "index.js"
    content  = <<-EOT
      exports.handler = async (event) => {
        const token = (event.authorizationToken || "").replace(/^Bearer\s+/i, "");
        if (!token || token !== process.env.EXPECTED_TOKEN) {
          throw new Error("Unauthorized");
        }
        return {
          principalId: "api-client",
          policyDocument: {
            Version: "2012-10-17",
            Statement: [
              {
                Action: "execute-api:Invoke",
                Effect: "Allow",
                Resource: event.methodArn,
              },
            ],
          },
        };
      };
    EOT
  }
}

data "aws_iam_policy_document" "authorizer_lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "authorizer_execution" {
  count = local.create_rest_authorizer ? 1 : 0

  name               = "${local.name_prefix}-authorizer-exec"
  assume_role_policy = data.aws_iam_policy_document.authorizer_lambda_assume.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "authorizer_execution" {
  count = local.create_rest_authorizer ? 1 : 0

  role       = aws_iam_role.authorizer_execution[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  count = local.create_rest_authorizer ? 1 : 0

  function_name    = "${local.name_prefix}-authorizer"
  role             = aws_iam_role.authorizer_execution[0].arn
  runtime          = var.authorizer_runtime
  handler          = "index.handler"
  filename         = data.archive_file.authorizer[0].output_path
  source_code_hash = data.archive_file.authorizer[0].output_base64sha256
  timeout          = 10

  environment {
    variables = {
      EXPECTED_TOKEN = random_password.authorizer_token[0].result
    }
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.authorizer_execution]
}

data "aws_iam_policy_document" "authorizer_invocation_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "authorizer_invocation" {
  count = local.create_rest_authorizer ? 1 : 0

  name               = "${local.name_prefix}-authorizer-invoke"
  assume_role_policy = data.aws_iam_policy_document.authorizer_invocation_assume.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy" "authorizer_invocation" {
  count = local.create_rest_authorizer ? 1 : 0

  name = "invoke-authorizer"
  role = aws_iam_role.authorizer_invocation[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = aws_lambda_function.authorizer[0].arn
      }
    ]
  })
}

resource "aws_api_gateway_authorizer" "this" {
  count = local.create_rest_authorizer ? 1 : 0

  name                             = "${local.name_prefix}-authorizer"
  rest_api_id                      = aws_api_gateway_rest_api.this[0].id
  type                             = "TOKEN"
  identity_source                  = "method.request.header.Authorization"
  authorizer_uri                   = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials           = aws_iam_role.authorizer_invocation[0].arn
  authorizer_result_ttl_in_seconds = var.authorizer_result_ttl_in_seconds
}

# --- REST VPC link (internal NLB -> ALB) ------------------------------------

resource "aws_lb" "rest_vpc_link" {
  count = local.create_rest_vpc_link ? 1 : 0

  name               = trimsuffix(substr("${local.name_prefix}-nlb", 0, 32), "-")
  internal           = true
  load_balancer_type = "network"
  subnets            = var.private_subnet_ids
  tags               = local.common_tags
}

resource "aws_lb_target_group" "rest_vpc_link" {
  count = local.create_rest_vpc_link ? 1 : 0

  name        = trimsuffix(substr("${local.name_prefix}-alb-tg", 0, 32), "-")
  target_type = "alb"
  protocol    = "TCP"
  port        = var.alb_port
  vpc_id      = var.vpc_id

  health_check {
    enabled  = true
    protocol = "HTTPS"
    port     = "traffic-port"
    path     = var.alb_health_check_path
  }

  tags = local.common_tags
}

resource "aws_lb_target_group_attachment" "rest_vpc_link" {
  count = local.create_rest_vpc_link ? 1 : 0

  target_group_arn = aws_lb_target_group.rest_vpc_link[0].arn
  target_id        = var.alb_id
  port             = var.alb_port

  lifecycle {
    precondition {
      condition     = var.alb_id != null
      error_message = "alb_id is required when enable_vpc_link is true for a REST API."
    }
  }
}

resource "aws_lb_listener" "rest_vpc_link" {
  count = local.create_rest_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.rest_vpc_link[0].arn
  port              = var.alb_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.rest_vpc_link[0].arn
  }

  tags = local.common_tags
}

resource "aws_api_gateway_vpc_link" "this" {
  count = local.create_rest_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-vpc-link"
  target_arns = [aws_lb.rest_vpc_link[0].arn]
  tags        = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "api_type" {
  description = "Type of API provisioned."
  value       = var.api_type
}

output "api_id" {
  description = "ID of the API."
  value       = local.is_http ? one(aws_apigatewayv2_api.this[*].id) : one(aws_api_gateway_rest_api.this[*].id)
}

output "stage_name" {
  description = "Name of the deployed stage."
  value       = local.stage_name
}

output "invoke_url" {
  description = "Invoke URL of the deployed stage."
  value       = local.is_http ? one(aws_apigatewayv2_stage.this[*].invoke_url) : one(aws_api_gateway_stage.this[*].invoke_url)
}

output "execution_arn" {
  description = "Execution ARN of the API."
  value       = local.is_http ? one(aws_apigatewayv2_api.this[*].execution_arn) : one(aws_api_gateway_rest_api.this[*].execution_arn)
}

output "vpc_link_id" {
  description = "ID of the VPC link, if created."
  value       = local.is_http ? one(aws_apigatewayv2_vpc_link.this[*].id) : one(aws_api_gateway_vpc_link.this[*].id)
}

output "nlb_arn" {
  description = "ARN of the internal NLB backing the REST API VPC link, if created."
  value       = one(aws_lb.rest_vpc_link[*].arn)
}

output "custom_domain_target" {
  description = "Regional target domain name for the HTTP API custom domain, if created."
  value       = one(aws_apigatewayv2_domain_name.this[*].domain_name_configuration[0].target_domain_name)
}

output "api_key_ssm_parameter_name" {
  description = "SSM parameter holding the REST API key, if created."
  value       = one(aws_ssm_parameter.api_key[*].name)
}

output "authorizer_token_ssm_parameter_name" {
  description = "SSM parameter holding the Lambda authorizer bearer token, if created."
  value       = one(aws_ssm_parameter.authorizer_token[*].name)
}

output "authorizer_function_arn" {
  description = "ARN of the Lambda authorizer function, if created."
  value       = one(aws_lambda_function.authorizer[*].arn)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.1"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "account-audit-trail"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. If empty, a name is generated from account ID, region and a random suffix."
  type        = string
  default     = ""
}

variable "s3_key_prefix" {
  description = "Optional S3 key prefix for CloudTrail log files."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Allow the S3 bucket to be destroyed even if it contains objects."
  type        = bool
  default     = true
}

variable "enable_versioning" {
  description = "Enable versioning on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "kms_alias_prefix" {
  description = "Prefix for the CloudTrail KMS key alias (the trail name is appended)."
  type        = string
  default     = "alias/cloudtrail-"
}

variable "kms_deletion_window_in_days" {
  description = "Deletion window in days for the CloudTrail KMS key."
  type        = number
  default     = 30
}

variable "log_decryption_role_arn" {
  description = "Optional IAM role ARN permitted to decrypt CloudTrail log files."
  type        = string
  default     = ""
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group. If empty, defaults to /aws/cloudtrail/<trail_name>."
  type        = string
  default     = ""
}

variable "log_retention_days" {
  description = "Number of days to retain CloudTrail logs in CloudWatch Logs."
  type        = number
  default     = 90
}

variable "include_global_service_events" {
  description = "Whether the trail publishes events from global services such as IAM."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail is created in all regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an AWS Organizations trail."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Type of events to log. Valid values: ReadOnly, WriteOnly, All."
  type        = string
  default     = "All"

  validation {
    condition     = contains(["ReadOnly", "WriteOnly", "All"], var.read_write_type)
    error_message = "read_write_type must be one of ReadOnly, WriteOnly, or All."
  }
}

variable "include_management_events" {
  description = "Whether to include management events in the event selector."
  type        = bool
  default     = true
}

variable "data_resources" {
  description = "List of data resource selectors, e.g. [{ type = \"AWS::S3::Object\", values = [\"arn:aws:s3\"] }]."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of CloudTrail Insights types to enable. Valid values: ApiCallRateInsight, ApiErrorRateInsight."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic for CloudTrail log delivery notifications."
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "Name of the SNS topic to create when create_sns_topic is true. Defaults to <trail_name>-notifications."
  type        = string
  default     = ""
}

variable "sns_topic_arn" {
  description = "Existing SNS topic ARN to use for notifications when create_sns_topic is false."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

################################################################################
# Data sources & locals
################################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "random_string" "bucket_suffix" {
  length  = 8
  lower   = true
  upper   = false
  numeric = false
  special = false
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "cloudtrail-${local.account_id}-${local.region}-${random_string.bucket_suffix.result}"

  log_group_name = var.cloudwatch_log_group_name != "" ? var.cloudwatch_log_group_name : "/aws/cloudtrail/${var.trail_name}"

  trail_arn = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"

  s3_log_prefix = var.s3_key_prefix != "" ? "${var.s3_key_prefix}/" : ""

  sns_topic_name = var.sns_topic_name != "" ? var.sns_topic_name : "${var.trail_name}-notifications"

  sns_topic_arn = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].arn : (var.sns_topic_arn != "" ? var.sns_topic_arn : null)
}

################################################################################
# KMS key
################################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowCloudTrailEncryptLogs"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey*"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid       = "AllowCloudTrailDescribeKey"
    effect    = "Allow"
    actions   = ["kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowCloudTrailSNSPublish"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${local.region}.amazonaws.com"]
    }
  }

  dynamic "statement" {
    for_each = var.log_decryption_role_arn != "" ? [var.log_decryption_role_arn] : []

    content {
      sid    = "AllowLogDecryption"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:ReEncryptFrom",
      ]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      condition {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [local.account_id]
      }

      condition {
        test     = "StringLike"
        variable = "kms:EncryptionContext:aws:cloudtrail:arn"
        values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
      }
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail ${var.trail_name} log encryption"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  rotation_period_in_days = 365
  policy                  = data.aws_iam_policy_document.kms.json

  tags = var.tags
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "${var.kms_alias_prefix}${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

################################################################################
# S3 bucket
################################################################################

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = var.tags
}

resource "aws_s3_bucket_ownership_controls" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/${local.s3_log_prefix}AWSLogs/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.cloudtrail.arn,
      "${aws_s3_bucket.cloudtrail.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

################################################################################
# CloudWatch Logs
################################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  tags = var.tags
}

data "aws_iam_policy_document" "cloudtrail_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${var.trail_name}-cloudwatch-logs-role"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume.json

  tags = var.tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid    = "AWSCloudTrailCreateLogStreamAndPutLogEvents"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "${var.trail_name}-cloudwatch-logs-policy"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch.json
}

################################################################################
# SNS (optional)
################################################################################

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.cloudtrail.arn

  tags = var.tags
}

data "aws_iam_policy_document" "sns" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid       = "AWSCloudTrailSNSPolicy"
    effect    = "Allow"
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.cloudtrail[0].arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail[0].arn
  policy = data.aws_iam_policy_document.sns[0].json
}

################################################################################
# CloudTrail
################################################################################

resource "aws_cloudtrail" "this" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  enable_log_file_validation    = true
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_arn

  event_selector {
    read_write_type           = var.read_write_type
    include_management_events = var.include_management_events

    dynamic "data_resource" {
      for_each = var.data_resources

      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors

    content {
      insight_type = insight_selector.value
    }
  }

  tags = var.tags

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_s3_bucket_server_side_encryption_configuration.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch,
    aws_sns_topic_policy.cloudtrail,
  ]
}

################################################################################
# Outputs
################################################################################

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.this.arn
}

output "cloudtrail_home_region" {
  description = "Home region of the CloudTrail trail."
  value       = aws_cloudtrail.this.home_region
}

output "s3_bucket_name" {
  description = "Name of the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail.id
}

output "s3_bucket_arn" {
  description = "ARN of the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail.arn
}

output "kms_key_arn" {
  description = "ARN of the CloudTrail KMS key."
  value       = aws_kms_key.cloudtrail.arn
}

output "kms_key_alias" {
  description = "Alias of the CloudTrail KMS key."
  value       = aws_kms_alias.cloudtrail.name
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudTrail CloudWatch Log Group."
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "cloudwatch_logs_role_arn" {
  description = "ARN of the IAM role used by CloudTrail to write to CloudWatch Logs."
  value       = aws_iam_role.cloudtrail_cloudwatch.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic used for CloudTrail notifications, if any."
  value       = local.sns_topic_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0"
    }
  }
}

variable "enabled" {
  description = "Global flag to enable or disable creation of all resources in this module."
  type        = bool
  default     = true
}

variable "region" {
  description = "Region in which to manage EBS account-level settings. Defaults to the provider's current region when null."
  type        = string
  default     = null
}

variable "enable_ebs_encryption_by_default" {
  description = "Whether to enable EBS encryption by default for the region."
  type        = bool
  default     = true
}

variable "enable_snapshot_block_public_access" {
  description = "Whether to manage EBS snapshot block public access for the region."
  type        = bool
  default     = true
}

variable "snapshot_block_public_access_state" {
  description = "State of EBS snapshot block public access. Valid values: block-all-sharing, block-new-sharing, unblocked."
  type        = string
  default     = "block-all-sharing"

  validation {
    condition     = contains(["block-all-sharing", "block-new-sharing", "unblocked"], var.snapshot_block_public_access_state)
    error_message = "snapshot_block_public_access_state must be one of: block-all-sharing, block-new-sharing, unblocked."
  }
}

data "aws_region" "current" {}

locals {
  region = coalesce(var.region, data.aws_region.current.region)

  create_ebs_encryption_by_default    = var.enabled && var.enable_ebs_encryption_by_default
  create_snapshot_block_public_access = var.enabled && var.enable_snapshot_block_public_access
}

resource "aws_ebs_encryption_by_default" "this" {
  count = local.create_ebs_encryption_by_default ? 1 : 0

  region  = local.region
  enabled = true
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count = local.create_snapshot_block_public_access ? 1 : 0

  region = local.region
  state  = var.snapshot_block_public_access_state
}

output "region" {
  description = "Region in which the EBS account-level settings are managed."
  value       = local.region
}

output "ebs_encryption_by_default_enabled" {
  description = "Whether EBS encryption by default is enabled by this module."
  value       = try(aws_ebs_encryption_by_default.this[0].enabled, false)
}

output "snapshot_block_public_access_state" {
  description = "The configured EBS snapshot block public access state, or null if not managed."
  value       = try(aws_ebs_snapshot_block_public_access.this[0].state, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the provider."
  type        = string
  default     = "us-east-1"
}

variable "user_name" {
  description = "Name of the IAM deployment user."
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional tags to apply to created resources."
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of target S3 bucket ARNs. When non-empty, an S3 policy is created and attached to the user."
  type        = list(string)
  default     = []
}

variable "s3_bucket_paths" {
  description = "Sub-paths within each target bucket to which object permissions are granted."
  type        = list(string)
  default     = ["*"]
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs. When non-empty, a Lambda policy is created and attached to the user."
  type        = list(string)
  default     = []
}

locals {
  create_s3_policy     = length(var.s3_bucket_arns) > 0
  create_lambda_policy = length(var.lambda_function_arns) > 0

  s3_object_arns = [
    for pair in setproduct(var.s3_bucket_arns, var.s3_bucket_paths) :
    "${pair[0]}/${trimprefix(pair[1], "/")}"
  ]
}

resource "aws_iam_user" "deployment" {
  name = var.user_name
  tags = var.tags
}

data "aws_iam_policy_document" "s3" {
  count = local.create_s3_policy ? 1 : 0

  statement {
    sid    = "ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectAcl",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:DeleteObject",
    ]
    resources = local.s3_object_arns
  }

  statement {
    sid       = "BucketListing"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = var.s3_bucket_arns
  }
}

resource "aws_iam_policy" "s3" {
  count = local.create_s3_policy ? 1 : 0

  name        = "${var.user_name}-s3-access"
  description = "S3 artifact access for ${var.user_name}."
  policy      = data.aws_iam_policy_document.s3[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "s3" {
  count = local.create_s3_policy ? 1 : 0

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.s3[0].arn
}

data "aws_iam_policy_document" "lambda" {
  count = local.create_lambda_policy ? 1 : 0

  statement {
    sid       = "UpdateFunctionCode"
    effect    = "Allow"
    actions   = ["lambda:UpdateFunctionCode"]
    resources = var.lambda_function_arns
  }
}

resource "aws_iam_policy" "lambda" {
  count = local.create_lambda_policy ? 1 : 0

  name        = "${var.user_name}-lambda-deploy"
  description = "Lambda code deployment access for ${var.user_name}."
  policy      = data.aws_iam_policy_document.lambda[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "lambda" {
  count = local.create_lambda_policy ? 1 : 0

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.lambda[0].arn
}

output "user_name" {
  description = "Name of the IAM deployment user."
  value       = aws_iam_user.deployment.name
}

output "user_arn" {
  description = "ARN of the IAM deployment user."
  value       = aws_iam_user.deployment.arn
}

output "s3_policy_arn" {
  description = "ARN of the S3 policy, if created."
  value       = local.create_s3_policy ? aws_iam_policy.s3[0].arn : null
}

output "lambda_policy_arn" {
  description = "ARN of the Lambda policy, if created."
  value       = local.create_lambda_policy ? aws_iam_policy.lambda[0].arn : null
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.0"
      configuration_aliases = []
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

################################################################################
# Providers
################################################################################

provider "aws" {
  region = var.aws_region
}

# CloudFront-scoped resources (ACM certificates, WAFv2 web ACLs) must live in us-east-1.
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

################################################################################
# Variables
################################################################################

variable "aws_region" {
  description = "AWS region in which the S3 bucket and KMS key are created."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Custom S3 bucket name. Falls back to domain_name, then to an auto-generated name if both are blank."
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Optional custom domain name for the website (e.g. example.com). Enables ACM, Route 53 and custom aliases when set."
  type        = string
  default     = ""
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID for domain_name. Required when domain_name is set."
  type        = string
  default     = ""
}

variable "enable_www_and_wildcard" {
  description = "When true and domain_name is set, adds a www. alias and a wildcard subject alternative name to the certificate."
  type        = bool
  default     = false
}

variable "enable_versioning" {
  description = "Enable versioning on the S3 bucket."
  type        = bool
  default     = false
}

variable "price_class" {
  description = "CloudFront price class."
  type        = string
  default     = "PriceClass_100"

  validation {
    condition     = contains(["PriceClass_All", "PriceClass_200", "PriceClass_100"], var.price_class)
    error_message = "price_class must be one of PriceClass_All, PriceClass_200 or PriceClass_100."
  }
}

variable "is_ipv6_enabled" {
  description = "Enable IPv6 on the CloudFront distribution."
  type        = bool
  default     = true
}

variable "default_root_object" {
  description = "Default root object served by CloudFront."
  type        = string
  default     = "index.html"
}

variable "minimum_protocol_version" {
  description = "Minimum TLS protocol version for viewer connections when a custom domain is used."
  type        = string
  default     = "TLSv1.2_2021"
}

variable "custom_error_responses" {
  description = "Custom error responses for the CloudFront distribution."
  type = list(object({
    error_code            = number
    response_code         = number
    error_caching_min_ttl = number
    response_page_path    = string
  }))
  default = [
    {
      error_code            = 403
      response_code         = 404
      error_caching_min_ttl = 10
      response_page_path    = "/index.html"
    },
    {
      error_code            = 404
      response_code         = 404
      error_caching_min_ttl = 10
      response_page_path    = "/index.html"
    }
  ]
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals & data sources
################################################################################

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

locals {
  use_custom_domain = trimspace(var.domain_name) != ""

  bucket_name = (
    trimspace(var.bucket_name) != "" ? trimspace(var.bucket_name) :
    local.use_custom_domain ? trimspace(var.domain_name) :
    "webapp-template-${random_id.bucket_suffix.hex}"
  )

  s3_origin_id = "s3-${local.bucket_name}"

  aliases = local.use_custom_domain ? (
    var.enable_www_and_wildcard
    ? [var.domain_name, "www.${var.domain_name}"]
    : [var.domain_name]
  ) : []

  subject_alternative_names = local.use_custom_domain && var.enable_www_and_wildcard ? ["*.${var.domain_name}"] : []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

################################################################################
# KMS (customer-managed key for S3 SSE-KMS)
################################################################################

resource "aws_kms_key" "s3" {
  description             = "CMK for S3 static website bucket ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${replace(local.bucket_name, ".", "-")}-s3"
  target_key_id = aws_kms_key.s3.key_id
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudFrontServicePrincipalSSE-KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.this.arn]
    }
  }
}

resource "aws_kms_key_policy" "s3" {
  key_id = aws_kms_key.s3.id
  policy = data.aws_iam_policy_document.kms.json
}

################################################################################
# S3 bucket (private)
################################################################################

resource "aws_s3_bucket" "this" {
  bucket = local.bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count  = var.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid       = "AllowCloudFrontServicePrincipalReadOnly"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.this.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.this.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# WAFv2 (CloudFront scope)
################################################################################

resource "aws_wafv2_web_acl" "this" {
  provider    = aws.us_east_1
  name        = "${replace(local.bucket_name, ".", "-")}-web-acl"
  description = "Web ACL for CloudFront distribution serving ${local.bucket_name}"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${replace(local.bucket_name, ".", "-")}-web-acl"
    sampled_requests_enabled   = true
  }

  tags = var.tags
}

################################################################################
# ACM certificate (us-east-1) & DNS validation
################################################################################

resource "aws_acm_certificate" "this" {
  count    = local.use_custom_domain ? 1 : 0
  provider = aws.us_east_1

  domain_name               = var.domain_name
  subject_alternative_names = local.subject_alternative_names
  validation_method         = "DNS"
  tags                      = var.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = local.use_custom_domain ? {
    for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  } : {}

  allow_overwrite = true
  zone_id         = var.hosted_zone_id
  name            = each.value.name
  type            = each.value.type
  ttl             = 60
  records         = [each.value.record]
}

resource "aws_acm_certificate_validation" "this" {
  count    = local.use_custom_domain ? 1 : 0
  provider = aws.us_east_1

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

################################################################################
# CloudFront
################################################################################

resource "aws_cloudfront_origin_access_control" "this" {
  name                              = substr("oac-${local.bucket_name}", 0, 64)
  description                       = "OAC for ${local.bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  comment             = "Static website for ${local.bucket_name}"
  price_class         = var.price_class
  is_ipv6_enabled     = var.is_ipv6_enabled
  default_root_object = var.default_root_object
  aliases             = local.aliases
  web_acl_id          = aws_wafv2_web_acl.this.arn

  origin {
    domain_name              = aws_s3_bucket.this.bucket_regional_domain_name
    origin_id                = local.s3_origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
  }

  dynamic "custom_error_response" {
    for_each = var.custom_error_responses
    content {
      error_code            = custom_error_response.value.error_code
      response_code         = custom_error_response.value.response_code
      error_caching_min_ttl = custom_error_response.value.error_caching_min_ttl
      response_page_path    = custom_error_response.value.response_page_path
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = local.use_custom_domain ? false : true
    acm_certificate_arn            = local.use_custom_domain ? aws_acm_certificate_validation.this[0].certificate_arn : null
    ssl_support_method             = local.use_custom_domain ? "sni-only" : null
    minimum_protocol_version       = local.use_custom_domain ? var.minimum_protocol_version : "TLSv1"
  }

  tags = var.tags

  lifecycle {
    precondition {
      condition     = !local.use_custom_domain || trimspace(var.hosted_zone_id) != ""
      error_message = "hosted_zone_id must be a non-empty Route 53 hosted zone ID when domain_name is specified."
    }
  }
}

################################################################################
# Route 53 alias records
################################################################################

resource "aws_route53_record" "alias_a" {
  for_each = toset(local.aliases)

  zone_id = var.hosted_zone_id
  name    = each.value
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.this.domain_name
    zone_id                = aws_cloudfront_distribution.this.hosted_zone_id
    evaluate_target_health = false
  }
}

################################################################################
# Outputs
################################################################################

output "bucket_name" {
  description = "Name of the S3 bucket hosting the website content."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for bucket encryption."
  value       = aws_kms_key.s3.arn
}

output "cloudfront_distribution_id" {
  description = "ID of the CloudFront distribution."
  value       = aws_cloudfront_distribution.this.id
}

output "cloudfront_distribution_arn" {
  description = "ARN of the CloudFront distribution."
  value       = aws_cloudfront_distribution.this.arn
}

output "cloudfront_domain_name" {
  description = "Domain name of the CloudFront distribution."
  value       = aws_cloudfront_distribution.this.domain_name
}

output "web_acl_arn" {
  description = "ARN of the WAFv2 web ACL attached to the distribution."
  value       = aws_wafv2_web_acl.this.arn
}

output "acm_certificate_arn" {
  description = "ARN of the validated ACM certificate (null when no domain is configured)."
  value       = local.use_custom_domain ? aws_acm_certificate_validation.this[0].certificate_arn : null
}

output "website_urls" {
  description = "URLs at which the website is reachable."
  value       = local.use_custom_domain ? [for a in local.aliases : "https://${a}"] : ["https://${aws_cloudfront_distribution.this.domain_name}"]
}

variable "region" {
  description = "AWS region to deploy the VPC into"
  type        = string
  default     = "us-east-1"
}

variable "network_prefix" {
  description = "First two octets of the VPC CIDR block, e.g. 10.20"
  type        = string
  default     = "10.20"
}

variable "aws_azs" {
  description = "Comma-separated list of availability zone names to use"
  type        = string
  default     = "us-east-1a, us-east-1b, us-east-1d"
}

variable "az_count" {
  description = "Number of active availability zones"
  type        = number
  default     = 3
}

variable "global_tags" {
  description = "Tags applied to all taggable resources"
  type        = map(string)
  default = {
    "Author"     = "Fairwinds"
    "Managed By" = "Terraform"
  }
}

variable "enable_s3_vpc_endpoint" {
  description = "Whether to provision an S3 gateway VPC endpoint"
  type        = bool
  default     = false
}

variable "multi_az_nat_gateway" {
  description = "Set to 1 to create one NAT gateway per availability zone"
  type        = number
  default     = 1
}

variable "single_nat_gateway" {
  description = "Set to 1 to create a single NAT gateway shared by all availability zones"
  type        = number
  default     = 0
}

variable "admin_subnet_suffixes" {
  description = "CIDR suffixes appended to network_prefix for admin subnets"
  type        = list(string)
  default     = [".0.0/21", ".8.0/21", ".16.0/21"]
}

variable "public_subnet_suffixes" {
  description = "CIDR suffixes appended to network_prefix for public subnets"
  type        = list(string)
  default     = [".32.0/21", ".40.0/21", ".48.0/21"]
}

variable "private_prod_subnet_suffixes" {
  description = "CIDR suffixes appended to network_prefix for private production subnets"
  type        = list(string)
  default     = [".64.0/21", ".72.0/21", ".80.0/21"]
}

variable "private_working_subnet_suffixes" {
  description = "CIDR suffixes appended to network_prefix for private working subnets"
  type        = list(string)
  default     = [".96.0/21", ".104.0/21", ".112.0/21"]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

locals {
  vpc_cidr = "${var.network_prefix}.0.0/16"
  azs      = slice([for az in split(",", var.aws_azs) : trimspace(az)], 0, var.az_count)

  nat_count = var.multi_az_nat_gateway == 1 ? var.az_count : (var.single_nat_gateway == 1 ? 1 : 0)
}

resource "aws_vpc" "default" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.global_tags, {
    Name = "vpc"
  })
}

resource "aws_internet_gateway" "default" {
  vpc_id = aws_vpc.default.id

  tags = merge(var.global_tags, {
    Name = "vpc"
  })
}

resource "aws_subnet" "admin" {
  count             = var.az_count
  vpc_id            = aws_vpc.default.id
  cidr_block        = "${var.network_prefix}${var.admin_subnet_suffixes[count.index]}"
  availability_zone = local.azs[count.index]

  tags = merge(var.global_tags, {
    Name = "admin_az${count.index + 1}"
  })
}

resource "aws_subnet" "public" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.default.id
  cidr_block              = "${var.network_prefix}${var.public_subnet_suffixes[count.index]}"
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.global_tags, {
    Name = "public_az${count.index + 1}"
  })
}

resource "aws_subnet" "private_prod" {
  count             = var.az_count
  vpc_id            = aws_vpc.default.id
  cidr_block        = "${var.network_prefix}${var.private_prod_subnet_suffixes[count.index]}"
  availability_zone = local.azs[count.index]

  tags = merge(var.global_tags, {
    Name = "private_prod_az${count.index + 1}"
  })
}

resource "aws_subnet" "private_working" {
  count             = var.az_count
  vpc_id            = aws_vpc.default.id
  cidr_block        = "${var.network_prefix}${var.private_working_subnet_suffixes[count.index]}"
  availability_zone = local.azs[count.index]

  tags = merge(var.global_tags, {
    Name = "private_working_az${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.default.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.default.id
  }

  tags = merge(var.global_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count          = var.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = local.nat_count
  domain = "vpc"

  tags = merge(var.global_tags, {
    Name = "nat_az${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.default]
}

resource "aws_nat_gateway" "nat" {
  count         = local.nat_count
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.global_tags, {
    Name = "nat_az${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.default]
}

resource "aws_route_table" "private_az1" {
  vpc_id = aws_vpc.default.id

  tags = merge(var.global_tags, {
    Name = "private_az1"
  })
}

resource "aws_route_table" "private_az2" {
  vpc_id = aws_vpc.default.id

  tags = merge(var.global_tags, {
    Name = "private_az2"
  })
}

resource "aws_route_table" "private_az3" {
  vpc_id = aws_vpc.default.id

  tags = merge(var.global_tags, {
    Name = "private_az3"
  })
}

locals {
  private_route_table_ids = [
    aws_route_table.private_az1.id,
    aws_route_table.private_az2.id,
    aws_route_table.private_az3.id,
  ]
}

resource "aws_route" "private_nat" {
  count                  = local.nat_count > 0 ? var.az_count : 0
  route_table_id         = local.private_route_table_ids[count.index]
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[var.multi_az_nat_gateway == 1 ? count.index : 0].id
}

resource "aws_route_table_association" "admin" {
  count          = var.az_count
  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = local.private_route_table_ids[count.index]
}

resource "aws_route_table_association" "private_prod" {
  count          = var.az_count
  subnet_id      = aws_subnet.private_prod[count.index].id
  route_table_id = local.private_route_table_ids[count.index]
}

resource "aws_route_table_association" "private_working" {
  count          = var.az_count
  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = local.private_route_table_ids[count.index]
}

resource "aws_vpc_endpoint" "s3" {
  count             = var.enable_s3_vpc_endpoint ? 1 : 0
  vpc_id            = aws_vpc.default.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.private_route_table_ids

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "*"
        Resource  = "*"
      }
    ]
  })

  tags = merge(var.global_tags, {
    Name = "s3"
  })
}

output "vpc_id" {
  value = aws_vpc.default.id
}

output "vpc_cidr" {
  value = aws_vpc.default.cidr_block
}

output "admin_subnet_ids" {
  value = aws_subnet.admin[*].id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_prod_subnet_ids" {
  value = aws_subnet.private_prod[*].id
}

output "private_working_subnet_ids" {
  value = aws_subnet.private_working[*].id
}

output "private_route_table_ids" {
  value = local.private_route_table_ids
}

output "nat_gateway_ids" {
  value = aws_nat_gateway.nat[*].id
}

output "s3_vpc_endpoint_id" {
  value = var.enable_s3_vpc_endpoint ? aws_vpc_endpoint.s3[0].id : null
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "web-backend"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the two public subnets."
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.1.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "app_port" {
  description = "Port the application container listens on."
  type        = number
  default     = 80
}

variable "health_check_path" {
  description = "HTTP path used by the target group health check."
  type        = string
  default     = "/"
}

variable "container_image" {
  description = "Placeholder container image; replaced later by CI/CD."
  type        = string
  default     = "public.ecr.aws/nginx/nginx:latest"
}

variable "task_cpu" {
  description = "Fargate task CPU units."
  type        = number
  default     = 256
}

variable "task_memory" {
  description = "Fargate task memory (MiB)."
  type        = number
  default     = 512
}

variable "github_org" {
  description = "GitHub organization or account whose workflows may assume the CI/CD role."
  type        = string
}

variable "db_username" {
  description = "Initial bootstrap database username."
  type        = string
  default     = "postgres"
}

variable "db_password" {
  description = "Initial bootstrap database password."
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "db_name" {
  description = "Name of the initial database."
  type        = string
  default     = "mydb"
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
  default     = "db.t3.micro"
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Project   = var.project_name
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${var.project_name}-alb-sg"
  description = "Internal ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from within the VPC (redirected to HTTPS)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-alb-sg"
  })
}

resource "aws_security_group" "app" {
  name        = "${var.project_name}-app-sg"
  description = "ECS application containers security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "All traffic from the load balancer only"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-app-sg"
  })
}

resource "aws_security_group" "db" {
  name        = "${var.project_name}-db-sg"
  description = "RDS PostgreSQL security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from application containers only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-db-sg"
  })
}

# -----------------------------------------------------------------------------
# Self-signed certificate imported into ACM
# -----------------------------------------------------------------------------

resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name  = "${var.project_name}.internal"
    organization = var.project_name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  private_key      = tls_private_key.alb.private_key_pem
  certificate_body = tls_self_signed_cert.alb.cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-self-signed"
  })
}

# -----------------------------------------------------------------------------
# Application Load Balancer (internal)
# -----------------------------------------------------------------------------

resource "aws_lb" "main" {
  name                       = "${var.project_name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true

  tags = local.common_tags
}

resource "aws_lb_target_group" "app" {
  name        = "${var.project_name}-tg"
  port        = var.app_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    path                = var.health_check_path
    protocol            = "HTTP"
    matcher             = "200-399"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = local.common_tags
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# -----------------------------------------------------------------------------
# ECR repository
# -----------------------------------------------------------------------------

resource "aws_ecr_repository" "app" {
  name                 = var.project_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "${var.project_name}-db-subnets"
  subnet_ids = aws_subnet.private[*].id

  tags = local.common_tags
}

resource "aws_db_instance" "main" {
  identifier             = "${var.project_name}-db"
  engine                 = "postgres"
  instance_class         = var.db_instance_class
  allocated_storage      = 20
  storage_type           = "gp3"
  storage_encrypted      = true
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  port                   = 5432
  multi_az               = false
  publicly_accessible    = false
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  skip_final_snapshot    = true

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# IAM roles for ECS
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_tasks_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_execution" {
  name               = "${var.project_name}-ecs-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_execution" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task" {
  name               = "${var.project_name}-ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# ECS cluster, task definition, service
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${var.project_name}"
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_ecs_cluster" "main" {
  name = "${var.project_name}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = local.common_tags
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 1
  }

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 4
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = var.project_name
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.task_cpu
  memory                   = var.task_memory
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "app"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = var.app_port
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "DATABASE_URL"
          value = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
        },
        {
          name  = "DB_HOST"
          value = aws_db_instance.main.address
        },
        {
          name  = "DB_PORT"
          value = tostring(aws_db_instance.main.port)
        },
        {
          name  = "DB_NAME"
          value = var.db_name
        },
        {
          name  = "DB_USER"
          value = var.db_username
        },
        {
          name  = "DB_PASSWORD"
          value = var.db_password
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.app.name
          awslogs-region        = var.aws_region
          awslogs-stream-prefix = "app"
        }
      }
    }
  ])

  tags = local.common_tags
}

resource "aws_ecs_service" "app" {
  name                              = "${var.project_name}-service"
  cluster                           = aws_ecs_cluster.main.id
  task_definition                   = aws_ecs_task_definition.app.arn
  desired_count                     = 2
  health_check_grace_period_seconds = 60

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 1
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 4
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.app.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "app"
    container_port   = var.app_port
  }

  depends_on = [
    aws_lb_listener.https,
    aws_ecs_cluster_capacity_providers.main,
  ]

  lifecycle {
    ignore_changes = [task_definition, desired_count]
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Auto scaling
# -----------------------------------------------------------------------------

resource "aws_appautoscaling_target" "app" {
  service_namespace  = "ecs"
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  min_capacity       = 2
  max_capacity       = 4
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "${var.project_name}-cpu-target-tracking"
  policy_type        = "TargetTrackingScaling"
  service_namespace  = aws_appautoscaling_target.app.service_namespace
  resource_id        = aws_appautoscaling_target.app.resource_id
  scalable_dimension = aws_appautoscaling_target.app.scalable_dimension

  target_tracking_scaling_policy_configuration {
    target_value       = 70
    scale_in_cooldown  = 300
    scale_out_cooldown = 60

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "${var.project_name}-memory-target-tracking"
  policy_type        = "TargetTrackingScaling"
  service_namespace  = aws_appautoscaling_target.app.service_namespace
  resource_id        = aws_appautoscaling_target.app.resource_id
  scalable_dimension = aws_appautoscaling_target.app.scalable_dimension

  target_tracking_scaling_policy_configuration {
    target_value       = 75
    scale_in_cooldown  = 300
    scale_out_cooldown = 60

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
  }
}

# -----------------------------------------------------------------------------
# GitHub Actions OIDC + CI/CD role
# -----------------------------------------------------------------------------

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1", "1c58a3a8518e8759bf075b76b750d4f2df264fcd"]

  tags = local.common_tags
}

data "aws_iam_policy_document" "github_assume" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_org}/*"]
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name               = "${var.project_name}-github-actions-role"
  assume_role_policy = data.aws_iam_policy_document.github_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "github_actions" {
  statement {
    sid       = "EcrAuth"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid = "EcrPush"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:CompleteLayerUpload",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:PutImage",
      "ecr:UploadLayerPart",
    ]
    resources = [aws_ecr_repository.app.arn]
  }

  statement {
    sid = "EcsTaskDefinitions"
    actions = [
      "ecs:RegisterTaskDefinition",
      "ecs:DeregisterTaskDefinition",
      "ecs:DeleteTaskDefinitions",
      "ecs:DescribeTaskDefinition",
      "ecs:ListTaskDefinitions",
      "ecs:TagResource",
    ]
    resources = ["*"]
  }

  statement {
    sid = "EcsService"
    actions = [
      "ecs:UpdateService",
      "ecs:DescribeServices",
    ]
    resources = [aws_ecs_service.app.id]
  }

  statement {
    sid     = "PassTaskRoles"
    actions = ["iam:PassRole"]
    resources = [
      aws_iam_role.ecs_execution.arn,
      aws_iam_role.ecs_task.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "github_actions" {
  name   = "${var.project_name}-github-actions-deploy"
  role   = aws_iam_role.github_actions.id
  policy = data.aws_iam_policy_document.github_actions.json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  value = aws_vpc.main.id
}

output "alb_dns_name" {
  value = aws_lb.main.dns_name
}

output "ecr_repository_url" {
  value = aws_ecr_repository.app.repository_url
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

output "ecs_service_name" {
  value = aws_ecs_service.app.name
}

output "ecs_task_execution_role_arn" {
  value = aws_iam_role.ecs_execution.arn
}

output "ecs_task_role_arn" {
  value = aws_iam_role.ecs_task.arn
}

output "github_actions_role_arn" {
  value = aws_iam_role.github_actions.arn
}

output "db_endpoint" {
  value = aws_db_instance.main.address
}

output "account_id" {
  value = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "cluster_tag" {
  type        = string
  description = "Tag used to identify all resources belonging to this cluster."
  default     = "default"
}

variable "enable_key_rotation" {
  type        = bool
  description = "Enable annual rotation of the Vault seal KMS key."
  default     = false
}

variable "machine_roles" {
  type        = map(set(string))
  description = "Map of machine role names to the set of policy identifiers to attach."
  default     = {}
}

locals {
  secret_names = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ])

  policy_arns = {
    "read-tags"   = aws_iam_policy.read_tags.arn
    "vault-kms"   = aws_iam_policy.vault_kms.arn
    "nomad-keys"  = aws_iam_policy.nomad_keys.arn
    "consul-keys" = aws_iam_policy.consul_keys.arn
    "vault-keys"  = aws_iam_policy.vault_keys.arn
    "client-keys" = aws_iam_policy.client_keys.arn
  }

  role_policy_attachments = {
    for pair in flatten([
      for role, policies in var.machine_roles : [
        for policy in policies : {
          role   = role
          policy = policy
        } if contains(keys(local.policy_arns), policy)
      ]
    ]) : "${pair.role}:${pair.policy}" => pair
  }
}

# KMS key for Vault auto-unseal

resource "aws_kms_key" "vault" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation     = var.enable_key_rotation
  rotation_period_in_days = var.enable_key_rotation ? 365 : null

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# Secrets Manager secrets for HashiStack tokens and keys

resource "aws_secretsmanager_secret" "secret" {
  for_each = local.secret_names

  name = "resinstack-${each.key}-${var.cluster_tag}"

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# IAM policy documents

data "aws_iam_policy_document" "vault_kms" {
  statement {
    sid    = "VaultKMSUnseal"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.vault.arn]
  }
}

data "aws_iam_policy_document" "read_tags" {
  statement {
    sid       = "ResinStackReadTags"
    effect    = "Allow"
    actions   = ["ec2:DescribeInstances"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "client_keys" {
  statement {
    effect  = "Allow"
    actions = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.secret["consul-agent-token"].arn,
      aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
      aws_secretsmanager_secret.secret["nomad-client-consul-token"].arn,
    ]
  }
}

data "aws_iam_policy_document" "nomad_keys" {
  statement {
    effect  = "Allow"
    actions = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.secret["consul-agent-token"].arn,
      aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
      aws_secretsmanager_secret.secret["nomad-gossip-key"].arn,
      aws_secretsmanager_secret.secret["nomad-server-consul-token"].arn,
      aws_secretsmanager_secret.secret["nomad-vault-token"].arn,
    ]
  }
}

data "aws_iam_policy_document" "consul_keys" {
  statement {
    effect  = "Allow"
    actions = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
    ]
  }
}

data "aws_iam_policy_document" "vault_keys" {
  statement {
    effect  = "Allow"
    actions = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
      aws_secretsmanager_secret.secret["vault-consul-token"].arn,
    ]
  }
}

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# IAM policies

resource "aws_iam_policy" "vault_kms" {
  name        = "resinstack-vault-kms-${var.cluster_tag}"
  description = "Allow Vault to unseal using KMS"
  policy      = data.aws_iam_policy_document.vault_kms.json

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_policy" "read_tags" {
  name        = "resinstack-read-tags-${var.cluster_tag}"
  description = "Allow describing EC2 instances for cluster discovery"
  policy      = data.aws_iam_policy_document.read_tags.json

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_policy" "client_keys" {
  name        = "resinstack-client-keys-${var.cluster_tag}"
  description = "Allow clients to retrieve their secrets"
  policy      = data.aws_iam_policy_document.client_keys.json

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_policy" "nomad_keys" {
  name        = "resinstack-nomad-keys-${var.cluster_tag}"
  description = "Allow Nomad servers to retrieve their secrets"
  policy      = data.aws_iam_policy_document.nomad_keys.json

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_policy" "consul_keys" {
  name        = "resinstack-consul-keys-${var.cluster_tag}"
  description = "Allow Consul servers to retrieve their secrets"
  policy      = data.aws_iam_policy_document.consul_keys.json

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_policy" "vault_keys" {
  name        = "resinstack-vault-keys-${var.cluster_tag}"
  description = "Allow Vault servers to retrieve their secrets"
  policy      = data.aws_iam_policy_document.vault_keys.json

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# Machine roles and instance profiles

resource "aws_iam_role" "machine_role" {
  for_each = var.machine_roles

  name                 = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume.json
  max_session_duration = 43200

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_instance_profile" "machine_profile" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.machine_role[each.key].name

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_role_policy_attachment" "machine_role" {
  for_each = local.role_policy_attachments

  role       = aws_iam_role.machine_role[each.value.role].name
  policy_arn = local.policy_arns[each.value.policy]
}

# Outputs

output "vault_kms_key_id" {
  description = "ID of the KMS key used for Vault auto-unseal."
  value       = aws_kms_key.vault.key_id
}

output "secrets" {
  description = "Map of logical secret names to Secrets Manager secret names."
  value       = { for k, s in aws_secretsmanager_secret.secret : k => s.name }
}

output "machine_roles" {
  description = "Map of machine role keys to IAM role names."
  value       = { for k, r in aws_iam_role.machine_role : k => r.name }
}

output "instance_profiles" {
  description = "Map of machine role keys to IAM instance profile names."
  value       = { for k, p in aws_iam_instance_profile.machine_profile : k => p.name }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.67"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the network into."
  type        = string
  default     = "us-east-1"
}

variable "environment_prefix" {
  description = "Environment prefix used for resource tagging."
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "64.0.0.0/16"
}

variable "availability_zones" {
  description = "Map of availability zones to subnet offset values."
  type        = map(number)
  default = {
    "us-east-1a" = 11
    "us-east-1b" = 22
    "us-east-1c" = 33
  }
}

variable "private_subnet_offset_shift" {
  description = "Value added to each AZ offset to compute distinct private subnet ranges."
  type        = number
  default     = 100
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true
  enable_classiclink   = false

  tags = {
    Name        = "${var.environment_prefix}-vpc"
    Environment = var.environment_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment_prefix}-igw"
    Environment = var.environment_prefix
  }
}

resource "aws_subnet" "public" {
  for_each = var.availability_zones

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value)
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment_prefix}-public-${each.key}"
    Environment = var.environment_prefix
    Tier        = "public"
  }
}

resource "aws_subnet" "private" {
  for_each = var.availability_zones

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value + var.private_subnet_offset_shift)
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment_prefix}-private-${each.key}"
    Environment = var.environment_prefix
    Tier        = "private"
  }
}

resource "aws_route_table" "public" {
  for_each = var.availability_zones

  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment_prefix}-public-rt-${each.key}"
    Environment = var.environment_prefix
  }
}

resource "aws_route" "public_internet" {
  for_each = var.availability_zones

  route_table_id         = aws_route_table.public[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = var.availability_zones

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[each.key].id
}

resource "aws_eip" "nat" {
  for_each = var.availability_zones

  vpc = true

  tags = {
    Name        = "${var.environment_prefix}-nat-eip-${each.key}"
    Environment = var.environment_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  for_each = var.availability_zones

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = {
    Name        = "${var.environment_prefix}-nat-${each.key}"
    Environment = var.environment_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  for_each = var.availability_zones

  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment_prefix}-private-rt-${each.key}"
    Environment = var.environment_prefix
  }
}

resource "aws_route" "private_nat" {
  for_each = var.availability_zones

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[each.key].id

  lifecycle {
    ignore_changes = [
      route_table_id,
      nat_gateway_id,
    ]
  }
}

resource "aws_route_table_association" "private" {
  for_each = var.availability_zones

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [
      route_table_id,
    ]
  }
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Map of AZ to public subnet IDs."
  value       = { for az, subnet in aws_subnet.public : az => subnet.id }
}

output "private_subnet_ids" {
  description = "Map of AZ to private subnet IDs."
  value       = { for az, subnet in aws_subnet.private : az => subnet.id }
}

output "nat_gateway_ids" {
  description = "Map of AZ to NAT gateway IDs."
  value       = { for az, nat in aws_nat_gateway.main : az => nat.id }
}

output "nat_eip_public_ips" {
  description = "Map of AZ to NAT gateway Elastic IP addresses."
  value       = { for az, eip in aws_eip.nat : az => eip.public_ip }
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "creation_token" {
  description = "A unique name used as reference when creating the EFS file system."
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "The file system performance mode. Can be either generalPurpose or maxIO."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be either \"generalPurpose\" or \"maxIO\"."
  }
}

variable "throughput_mode" {
  description = "Throughput mode for the file system. Valid values: bursting, provisioned, elastic."
  type        = string
  default     = "bursting"

  validation {
    condition     = contains(["bursting", "provisioned", "elastic"], var.throughput_mode)
    error_message = "throughput_mode must be one of \"bursting\", \"provisioned\", or \"elastic\"."
  }
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s. Only applicable when throughput_mode is provisioned."
  type        = number
  default     = null
}

variable "subnet_ids" {
  description = "List of subnet IDs in which to create EFS mount targets."
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "List of security group IDs to attach to each EFS mount target."
  type        = list(string)
  default     = []
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period, in days, before the KMS key is deleted after destruction."
  type        = number
  default     = 30
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "efs_kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowEFSServiceUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["elasticfilesystem.${var.aws_region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "efs" {
  description             = "KMS key for encrypting EFS file system ${var.creation_token}"
  enable_key_rotation     = true
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  policy                  = data.aws_iam_policy_document.efs_kms.json

  tags = merge(var.tags, {
    Name = "${var.creation_token}-efs-kms"
  })
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${var.creation_token}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "this" {
  creation_token                  = var.creation_token
  performance_mode                = var.performance_mode
  throughput_mode                 = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null
  encrypted                       = true
  kms_key_id                      = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = merge(var.tags, {
    Name = var.creation_token
  })
}

resource "aws_efs_mount_target" "this" {
  count = length(var.subnet_ids)

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = var.security_group_ids
}

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system."
  value       = aws_efs_file_system.this.arn
}

output "efs_dns_name" {
  description = "DNS name of the EFS file system."
  value       = aws_efs_file_system.this.dns_name
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt the EFS file system."
  value       = aws_kms_key.efs.arn
}

output "mount_target_ids" {
  description = "IDs of the EFS mount targets."
  value       = aws_efs_mount_target.this[*].id
}

output "mount_target_dns_names" {
  description = "DNS names of the EFS mount targets."
  value       = aws_efs_mount_target.this[*].mount_target_dns_name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "user_name" {
  description = "Name of the IAM user created for cert-manager."
  type        = string
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID cert-manager is allowed to manage. Use \"*\" to allow all hosted zones."
  type        = string
  default     = "*"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

resource "aws_iam_user" "cert_manager" {
  name = var.user_name
  tags = var.tags
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
}

resource "aws_ssm_parameter" "access_key" {
  name        = "/cert-manager/access-key"
  description = "Access key ID for the cert-manager IAM user."
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.id
  tags        = var.tags
}

resource "aws_ssm_parameter" "secret_key" {
  name        = "/cert-manager/secret-key"
  description = "Secret access key for the cert-manager IAM user."
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.secret
  tags        = var.tags
}

data "aws_iam_policy_document" "cert_manager" {
  statement {
    sid       = "GetChange"
    effect    = "Allow"
    actions   = ["route53:GetChange"]
    resources = ["arn:aws:route53:::change/*"]
  }

  statement {
    sid    = "ManageHostedZoneRecords"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets",
    ]
    resources = ["arn:aws:route53:::hostedzone/${var.hosted_zone_id}"]
  }

  statement {
    sid       = "ListHostedZonesByName"
    effect    = "Allow"
    actions   = ["route53:ListHostedZonesByName"]
    resources = ["*"]
  }
}

output "iam_user_name" {
  description = "Name of the cert-manager IAM user."
  value       = aws_iam_user.cert_manager.name
}

output "iam_user_arn" {
  description = "ARN of the cert-manager IAM user."
  value       = aws_iam_user.cert_manager.arn
}

output "access_key_parameter_name" {
  description = "SSM parameter name holding the access key ID."
  value       = aws_ssm_parameter.access_key.name
}

output "secret_key_parameter_name" {
  description = "SSM parameter name holding the secret access key."
  value       = aws_ssm_parameter.secret_key.name
}

output "policy_json" {
  description = "Route 53 IAM policy document JSON for cert-manager (not attached)."
  value       = data.aws_iam_policy_document.cert_manager.json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.0, < 6.0"
      configuration_aliases = []
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

################################################################################
# Providers
################################################################################

provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "Primary AWS region for GuardDuty and the primary findings bucket."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "AWS region for the replica findings bucket."
  type        = string
  default     = "us-west-2"
}

variable "name_prefix" {
  description = "Prefix used when naming created resources."
  type        = string
  default     = "guardduty"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "enable_guardduty" {
  description = "Enable the GuardDuty detector."
  type        = bool
  default     = true
}

variable "enable_s3_protection" {
  description = "Enable S3 data event (S3 logs) monitoring."
  type        = bool
  default     = true
}

variable "enable_kubernetes_protection" {
  description = "Enable Kubernetes audit log monitoring."
  type        = bool
  default     = true
}

variable "enable_malware_protection" {
  description = "Enable EC2 malware protection (EBS volume scanning)."
  type        = bool
  default     = true
}

variable "enable_snapshot_retention" {
  description = "Retain EBS snapshots when malware is detected (RETENTION_WITH_FINDING) or not (NO_RETENTION)."
  type        = bool
  default     = false
}

variable "finding_publishing_frequency" {
  description = "Frequency of notifications sent for subsequent finding occurrences."
  type        = string
  default     = "FIFTEEN_MINUTES"

  validation {
    condition     = contains(["FIFTEEN_MINUTES", "ONE_HOUR", "SIX_HOURS"], var.finding_publishing_frequency)
    error_message = "finding_publishing_frequency must be FIFTEEN_MINUTES, ONE_HOUR, or SIX_HOURS."
  }
}

variable "filter_config" {
  description = "List of GuardDuty finding filters."
  type = list(object({
    name        = string
    description = optional(string)
    rank        = number
    action      = string
    criterion = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(string)
      greater_than_or_equal = optional(string)
      less_than             = optional(string)
      less_than_or_equal    = optional(string)
    }))
  }))
  default = []
}

variable "ipset_config" {
  description = "List of trusted IP sets. Each entry's content is uploaded to the managed S3 bucket."
  type = list(object({
    name     = string
    activate = optional(bool, true)
    format   = optional(string, "TXT")
    content  = string
    key      = string
  }))
  default = []
}

variable "threatintelset_config" {
  description = "List of threat intelligence sets. Each entry's content is uploaded to the managed S3 bucket."
  type = list(object({
    name     = string
    activate = optional(bool, true)
    format   = optional(string, "TXT")
    content  = string
    key      = string
  }))
  default = []
}

variable "publishing_config" {
  description = "List of findings publishing destinations. If destination_arn/kms_key_arn are null, the managed bucket and KMS key are used."
  type = list(object({
    destination_type = optional(string, "S3")
    destination_arn  = optional(string)
    kms_key_arn      = optional(string)
  }))
  default = []
}

variable "replication_storage_class" {
  description = "Storage class for replicated objects in the replica bucket."
  type        = string
  default     = "STANDARD"
}

################################################################################
# Data & Locals
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  create_s3 = length(var.ipset_config) > 0 || length(var.threatintelset_config) > 0 || length(var.publishing_config) > 0

  primary_bucket_name = "${var.name_prefix}-findings-${local.account_id}-${var.region}"
  log_bucket_name     = "${var.name_prefix}-access-logs-${local.account_id}-${var.region}"
  replica_bucket_name = "${var.name_prefix}-findings-replica-${local.account_id}-${var.replica_region}"

  snapshot_preservation = var.enable_snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"

  filters         = { for f in var.filter_config : f.name => f }
  ipsets          = { for i in var.ipset_config : i.name => i }
  threatintelsets = { for t in var.threatintelset_config : t.name => t }
  publishing      = { for idx, p in var.publishing_config : tostring(idx) => p }
}

################################################################################
# GuardDuty Detector
################################################################################

resource "aws_guardduty_detector" "primary" {
  enable                       = var.enable_guardduty
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.enable_s3_protection
    }

    kubernetes {
      audit_logs {
        enable = var.enable_kubernetes_protection
      }
    }

    malware_protection {
      scan_ec2_instance_with_findings {
        ebs_volumes {
          enable = var.enable_malware_protection
        }
      }
    }
  }

  tags = var.tags
}

resource "null_resource" "malware_snapshot_retention" {
  count = var.enable_malware_protection ? 1 : 0

  triggers = {
    detector_id           = aws_guardduty_detector.primary.id
    snapshot_preservation = local.snapshot_preservation
    region                = var.region
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --region ${self.triggers.region} --detector-id ${self.triggers.detector_id} --ebs-snapshot-preservation ${self.triggers.snapshot_preservation}"
  }
}

################################################################################
# GuardDuty Filters
################################################################################

resource "aws_guardduty_filter" "this" {
  for_each = local.filters

  detector_id = aws_guardduty_detector.primary.id
  name        = each.value.name
  description = each.value.description
  rank        = each.value.rank
  action      = each.value.action

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criterion
      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = var.tags
}

################################################################################
# KMS (multi-region primary + replica)
################################################################################

data "aws_iam_policy_document" "kms" {
  count = local.create_s3 ? 1 : 0

  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowGuardDutyUseOfKey"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowGuardDutyServiceLinkedRoleDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:PrincipalArn"
      values   = ["arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/guardduty.amazonaws.com/*"]
    }
  }
}

resource "aws_kms_key" "primary" {
  count = local.create_s3 ? 1 : 0

  description             = "${var.name_prefix} GuardDuty findings and threat list encryption key"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = var.tags
}

resource "aws_kms_alias" "primary" {
  count = local.create_s3 ? 1 : 0

  name          = "alias/${var.name_prefix}-findings"
  target_key_id = aws_kms_key.primary[0].key_id
}

resource "aws_kms_replica_key" "replica" {
  count    = local.create_s3 ? 1 : 0
  provider = aws.replica

  description             = "${var.name_prefix} GuardDuty findings replica key"
  primary_key_arn         = aws_kms_key.primary[0].arn
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = var.tags
}

################################################################################
# Access Log Bucket
################################################################################

resource "aws_s3_bucket" "log" {
  count = local.create_s3 ? 1 : 0

  bucket        = local.log_bucket_name
  force_destroy = false

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "log" {
  count = local.create_s3 ? 1 : 0

  bucket                  = aws_s3_bucket.log[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "log" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "log" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "log_bucket" {
  count = local.create_s3 ? 1 : 0

  statement {
    sid       = "S3ServerAccessLogsPolicy"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:s3:::${local.primary_bucket_name}"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.log[0].arn, "${aws_s3_bucket.log[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "log" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.log[0].id
  policy = data.aws_iam_policy_document.log_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.log]
}

################################################################################
# Primary Findings Bucket
################################################################################

resource "aws_s3_bucket" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket        = local.primary_bucket_name
  force_destroy = false

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket                  = aws_s3_bucket.primary[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket        = aws_s3_bucket.primary[0].id
  target_bucket = aws_s3_bucket.log[0].id
  target_prefix = "s3-access-logs/${local.primary_bucket_name}/"

  depends_on = [aws_s3_bucket_policy.log]
}

data "aws_iam_policy_document" "primary_bucket" {
  count = local.create_s3 ? 1 : 0

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.primary[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }

  statement {
    sid       = "DenyIncorrectEncryptionKey"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.primary[0].arn]
    }
  }

  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.primary[0].arn, "${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  policy = data.aws_iam_policy_document.primary_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.primary]
}

################################################################################
# Replica Bucket (cross-region)
################################################################################

resource "aws_s3_bucket" "replica" {
  count    = local.create_s3 ? 1 : 0
  provider = aws.replica

  bucket        = local.replica_bucket_name
  force_destroy = false

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = local.create_s3 ? 1 : 0
  provider = aws.replica

  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = local.create_s3 ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.create_s3 ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = local.create_s3 ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_replica_key.replica[0].arn
    }
    bucket_key_enabled = true
  }
}

################################################################################
# Replication IAM Role & Policy
################################################################################

data "aws_iam_policy_document" "replication_assume" {
  count = local.create_s3 ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_s3 ? 1 : 0

  name               = "${var.name_prefix}-findings-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume[0].json

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_s3 ? 1 : 0

  statement {
    sid       = "SourceBucketConfig"
    effect    = "Allow"
    actions   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
    resources = [aws_s3_bucket.primary[0].arn]
  }

  statement {
    sid    = "SourceObjectRead"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]
  }

  statement {
    sid    = "DestinationObjectWrite"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }

  statement {
    sid       = "SourceKeyDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.primary[0].arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${var.region}.amazonaws.com"]
    }
  }

  statement {
    sid       = "DestinationKeyEncrypt"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_replica_key.replica[0].arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica_region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "replication" {
  count = local.create_s3 ? 1 : 0

  name   = "${var.name_prefix}-findings-replication"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_s3 ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

################################################################################
# Replication Configuration (RTC 15 minutes)
################################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  count = local.create_s3 ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id       = "replicate-all"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = var.replication_storage_class

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.replica[0].arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

################################################################################
# IP Sets
################################################################################

resource "aws_s3_object" "ipset" {
  for_each = local.ipsets

  bucket                 = aws_s3_bucket.primary[0].id
  key                    = each.value.key
  content                = each.value.content
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.primary[0].arn

  tags = var.tags

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.primary]
}

resource "aws_guardduty_ipset" "this" {
  for_each = local.ipsets

  detector_id = aws_guardduty_detector.primary.id
  name        = each.value.name
  activate    = each.value.activate
  format      = each.value.format
  location    = "https://s3.amazonaws.com/${aws_s3_object.ipset[each.key].bucket}/${aws_s3_object.ipset[each.key].key}"

  tags = var.tags
}

################################################################################
# Threat Intel Sets
################################################################################

resource "aws_s3_object" "threatintelset" {
  for_each = local.threatintelsets

  bucket                 = aws_s3_bucket.primary[0].id
  key                    = each.value.key
  content                = each.value.content
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.primary[0].arn

  tags = var.tags

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.primary]
}

resource "aws_guardduty_threatintelset" "this" {
  for_each = local.threatintelsets

  detector_id = aws_guardduty_detector.primary.id
  name        = each.value.name
  activate    = each.value.activate
  format      = each.value.format
  location    = "https://s3.amazonaws.com/${aws_s3_object.threatintelset[each.key].bucket}/${aws_s3_object.threatintelset[each.key].key}"

  tags = var.tags
}

################################################################################
# Publishing Destinations
################################################################################

resource "aws_guardduty_publishing_destination" "this" {
  for_each = local.publishing

  detector_id      = aws_guardduty_detector.primary.id
  destination_type = each.value.destination_type
  destination_arn  = coalesce(each.value.destination_arn, aws_s3_bucket.primary[0].arn)
  kms_key_arn      = coalesce(each.value.kms_key_arn, aws_kms_key.primary[0].arn)

  depends_on = [
    aws_s3_bucket_policy.primary,
    aws_kms_key.primary,
  ]
}

################################################################################
# Outputs
################################################################################

output "guardduty_detector_id" {
  description = "ID of the primary GuardDuty detector."
  value       = aws_guardduty_detector.primary.id
}

output "guardduty_detector_arn" {
  description = "ARN of the primary GuardDuty detector."
  value       = aws_guardduty_detector.primary.arn
}

output "ebs_snapshot_preservation" {
  description = "Configured EBS snapshot preservation setting for malware scans."
  value       = local.snapshot_preservation
}

output "guardduty_filter_ids" {
  description = "Map of filter name to filter ID."
  value       = { for k, v in aws_guardduty_filter.this : k => v.id }
}

output "guardduty_ipset_ids" {
  description = "Map of IP set name to IP set ID."
  value       = { for k, v in aws_guardduty_ipset.this : k => v.id }
}

output "guardduty_threatintelset_ids" {
  description = "Map of threat intel set name to ID."
  value       = { for k, v in aws_guardduty_threatintelset.this : k => v.id }
}

output "guardduty_publishing_destination_ids" {
  description = "Map of publishing destination index to ID."
  value       = { for k, v in aws_guardduty_publishing_destination.this : k => v.id }
}

output "kms_key_arn" {
  description = "ARN of the multi-region primary KMS key."
  value       = try(aws_kms_key.primary[0].arn, null)
}

output "kms_replica_key_arn" {
  description = "ARN of the replica KMS key in the replica region."
  value       = try(aws_kms_replica_key.replica[0].arn, null)
}

output "primary_bucket_arn" {
  description = "ARN of the primary findings bucket."
  value       = try(aws_s3_bucket.primary[0].arn, null)
}

output "log_bucket_arn" {
  description = "ARN of the access log bucket."
  value       = try(aws_s3_bucket.log[0].arn, null)
}

output "replica_bucket_arn" {
  description = "ARN of the replica findings bucket."
  value       = try(aws_s3_bucket.replica[0].arn, null)
}

output "replication_role_arn" {
  description = "ARN of the S3 replication IAM role."
  value       = try(aws_iam_role.replication[0].arn, null)
}

variable "name_prefix" {
  description = "Prefix applied to the names of all IAM resources"
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "Tags applied to all taggable resources"
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_partition" "current" {}

locals {
  policy_arn_prefix = "arn:${data.aws_partition.current.partition}:iam::aws:policy"
}

# -----------------------------------------------------------------------------
# EMR service role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["elasticmapreduce.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_service" {
  name               = "${var.name_prefix}-emr-service-role"
  assume_role_policy = data.aws_iam_policy_document.emr_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_service" {
  role       = aws_iam_role.emr_service.name
  policy_arn = "${local.policy_arn_prefix}/service-role/AmazonElasticMapReduceRole"
}

# -----------------------------------------------------------------------------
# EC2 instance profile role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "emr_ec2" {
  name               = "${var.name_prefix}-emr-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_ec2_default" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "${local.policy_arn_prefix}/service-role/AmazonElasticMapReduceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_cloudwatch" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "${local.policy_arn_prefix}/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_ssm" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "${local.policy_arn_prefix}/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "emr_ec2" {
  name = "${var.name_prefix}-emr-ec2-instance-profile"
  role = aws_iam_role.emr_ec2.name
  tags = var.tags
}

# -----------------------------------------------------------------------------
# EMR autoscaling role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_autoscaling_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "elasticmapreduce.amazonaws.com",
        "application-autoscaling.amazonaws.com",
      ]
    }
  }
}

resource "aws_iam_role" "emr_autoscaling" {
  name               = "${var.name_prefix}-emr-autoscaling-role"
  assume_role_policy = data.aws_iam_policy_document.emr_autoscaling_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling" {
  role       = aws_iam_role.emr_autoscaling.name
  policy_arn = "${local.policy_arn_prefix}/service-role/AmazonElasticMapReduceforAutoScalingRole"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "emr_service_role_arn" {
  description = "ARN of the EMR service role"
  value       = aws_iam_role.emr_service.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service role"
  value       = aws_iam_role.emr_service.name
}

output "emr_service_role_unique_id" {
  description = "Unique ID of the EMR service role"
  value       = aws_iam_role.emr_service.unique_id
}

output "emr_ec2_role_arn" {
  description = "ARN of the EMR EC2 instance role"
  value       = aws_iam_role.emr_ec2.arn
}

output "emr_ec2_role_name" {
  description = "Name of the EMR EC2 instance role"
  value       = aws_iam_role.emr_ec2.name
}

output "emr_ec2_role_unique_id" {
  description = "Unique ID of the EMR EC2 instance role"
  value       = aws_iam_role.emr_ec2.unique_id
}

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling.name
}

output "emr_autoscaling_role_unique_id" {
  description = "Unique ID of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling.unique_id
}

output "emr_ec2_instance_profile_id" {
  description = "ID of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2.id
}

output "emr_ec2_instance_profile_arn" {
  description = "ARN of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2.arn
}

output "emr_ec2_instance_profile_name" {
  description = "Name of the EMR EC2 instance profile"
  value       = aws_iam_instance_profile.emr_ec2.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "user_name" {
  description = "Name of the IAM user used for API integration testing and monitoring."
  type        = string
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  description = "Optional ARN of a Cognito user pool. When set, the user is granted cognito-idp:AdminInitiateAuth on that pool."
  type        = string
  default     = ""
}

locals {
  enable_cognito = var.cognito_user_pool_arn != ""
}

resource "aws_iam_user" "postman" {
  name = var.user_name
  path = "/"
}

resource "aws_iam_access_key" "postman" {
  user = aws_iam_user.postman.name
}

data "aws_iam_policy_document" "readonly" {
  statement {
    sid       = "ApiGatewayReadOnly"
    effect    = "Allow"
    actions   = ["apigateway:GET"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchMetricsReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "readonly" {
  name        = "${var.user_name}-readonly"
  path        = "/"
  description = "Read-only access to API Gateway and CloudWatch metrics for ${var.user_name}."
  policy      = data.aws_iam_policy_document.readonly.json
}

resource "aws_iam_user_policy_attachment" "readonly" {
  user       = aws_iam_user.postman.name
  policy_arn = aws_iam_policy.readonly.arn
}

data "aws_iam_policy_document" "cognito" {
  count = local.enable_cognito ? 1 : 0

  statement {
    sid       = "CognitoAdminInitiateAuth"
    effect    = "Allow"
    actions   = ["cognito-idp:AdminInitiateAuth"]
    resources = [var.cognito_user_pool_arn]
  }
}

resource "aws_iam_policy" "cognito" {
  count = local.enable_cognito ? 1 : 0

  name        = "${var.user_name}-cognito-auth"
  path        = "/"
  description = "Allows ${var.user_name} to call AdminInitiateAuth on the specified Cognito user pool."
  policy      = data.aws_iam_policy_document.cognito[0].json
}

resource "aws_iam_user_policy_attachment" "cognito" {
  count = local.enable_cognito ? 1 : 0

  user       = aws_iam_user.postman.name
  policy_arn = aws_iam_policy.cognito[0].arn
}

output "user_name" {
  description = "Name of the IAM user."
  value       = aws_iam_user.postman.name
}

output "user_arn" {
  description = "ARN of the IAM user."
  value       = aws_iam_user.postman.arn
}

output "access_key_id" {
  description = "Access key ID for the IAM user."
  value       = aws_iam_access_key.postman.id
}

output "secret_access_key" {
  description = "Secret access key for the IAM user."
  value       = aws_iam_access_key.postman.secret
  sensitive   = true
}

terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

variable "cluster_name" {
  type    = string
  default = "legion"
}

# EKS control plane role

data "aws_iam_policy_document" "master_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.master_assume_role.json
}

resource "aws_iam_role_policy_attachment" "master_eks_cluster_policy" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "master_eks_service_policy" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# Worker node role

data "aws_iam_policy_document" "node_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "node_eks_worker_node_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_eks_cni_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_read_only" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.node.name
}

# Cluster Autoscaler policy

data "aws_iam_policy_document" "worker_autoscaling" {
  statement {
    sid    = "EksWorkerAutoscalingAll"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EksWorkerAutoscalingOwn"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "worker_autoscaling" {
  name_prefix = "eks-worker-autoscaling-${var.cluster_name}"
  description = "EKS worker node autoscaling policy for cluster ${var.cluster_name}"
  policy      = data.aws_iam_policy_document.worker_autoscaling.json
}

resource "aws_iam_role_policy_attachment" "node_worker_autoscaling" {
  role       = aws_iam_role.node.name
  policy_arn = aws_iam_policy.worker_autoscaling.arn
}

output "master_role_arn" {
  value = aws_iam_role.master.arn
}

output "node_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_instance_profile_name" {
  value = aws_iam_instance_profile.node.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.69.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "vpc_name"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "172.69.1.0/24"
}

variable "public_subnet_name" {
  description = "Name tag for the public subnet"
  type        = string
  default     = "public_subnet"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "172.69.2.0/24"
}

variable "private_subnet_name" {
  description = "Name tag for the private subnet"
  type        = string
  default     = "private_subnet"
}

variable "igw_name" {
  description = "Name tag for the internet gateway"
  type        = string
  default     = "igw_tag"
}

variable "rtb_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "rtb_tag"
}

variable "web_sg_name_tag" {
  description = "Name tag for the web server security group"
  type        = string
  default     = "web-server_security_group"
}

variable "db_sg_name_tag" {
  description = "Name tag for the database security group"
  type        = string
  default     = "database_security_group"
}

variable "web_ingress_rules" {
  description = "Ingress rules for the web server security group"
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      description = "HTTP from anywhere"
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      description = "SSH from within the VPC"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

variable "db_port" {
  description = "Database port allowed into the database security group"
  type        = number
  default     = 3306
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = var.public_subnet_name
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.private_subnet_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.rtb_name
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web servers"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.web_ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    description = "All outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.web_sg_name_tag
  }
}

resource "aws_security_group" "db" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for database servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from web servers"
    from_port       = var.db_port
    to_port         = var.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.web.id]
  }

  egress {
    description = "All outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.db_sg_name_tag
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "web_security_group_id" {
  description = "ID of the web server security group"
  value       = aws_security_group.web.id
}

output "db_security_group_id" {
  description = "ID of the database security group"
  value       = aws_security_group.db.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "awscademo-"
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "contact" {
  description = "Contact for the deployed resources."
  type        = string
  default     = "admin@example.com"
}

variable "deployment_date" {
  description = "Date of deployment (YYYY-MM-DD)."
  type        = string
  default     = "2026-10-09"
}

provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Contact        = var.contact
      DeployedBy     = "terraform"
      DeploymentDate = var.deployment_date
      TTL            = "infinite"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  user_arn   = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
  mfa_arn    = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
}

# -----------------------------------------------------------------------------
# Demo users group with self-management policy
# -----------------------------------------------------------------------------

resource "aws_iam_group" "demo_users" {
  name = "${var.name}demo-users"
}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListVirtualMFADevices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = [local.user_arn]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:GetAccessKeyLastUsed",
    ]
    resources = [local.user_arn]
  }

  statement {
    sid    = "AllowManageOwnSSHPublicKeys"
    effect = "Allow"
    actions = [
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:UploadSSHPublicKey",
    ]
    resources = [local.user_arn]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [local.mfa_arn]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = [local.user_arn]
  }

  statement {
    sid    = "AllowDeactivateOwnUserMFAOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [local.user_arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${var.name}self-management"
  description = "Allows users to manage their own passwords, access keys, SSH public keys, and virtual MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

# -----------------------------------------------------------------------------
# Read-only users group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "readonly_users" {
  name = "${var.name}readonly-users"
}

resource "aws_iam_group_policy_attachment" "readonly_users" {
  group      = aws_iam_group.readonly_users.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/ReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# MFA superadmin group and admin role
# -----------------------------------------------------------------------------

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name}mfa-superadmin"
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name_prefix          = substr("${var.name}admin-", 0, 31)
  description          = "Administrative role requiring MFA."
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  max_session_duration = 43200
}

data "aws_iam_policy_document" "admin" {
  statement {
    sid       = "AllowFullAdminWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role_policy" "admin" {
  name   = "${var.name}admin-policy"
  role   = aws_iam_role.admin.id
  policy = data.aws_iam_policy_document.admin.json
}

data "aws_iam_policy_document" "mfa_superadmin_assume" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "mfa_superadmin_assume" {
  name   = "${var.name}assume-admin-role"
  group  = aws_iam_group.mfa_superadmin.name
  policy = data.aws_iam_policy_document.mfa_superadmin_assume.json
}

output "demo_users_group_name" {
  value = aws_iam_group.demo_users.name
}

output "readonly_users_group_name" {
  value = aws_iam_group.readonly_users.name
}

output "mfa_superadmin_group_name" {
  value = aws_iam_group.mfa_superadmin.name
}

output "admin_role_arn" {
  value = aws_iam_role.admin.arn
}

output "self_management_policy_arn" {
  value = aws_iam_policy.self_management.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

