      "s3:CreateBucket",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketPolicy",
      "s3:PutBucketPolicy",
      "s3:DeleteBucketPolicy",
      "s3:PutBucketTagging",
      "s3:PutBucketWebsite",
      "s3:GetObject",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:DeleteObject",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SQS"
    effect = "Allow"
    actions = [
      "sqs:CreateQueue",
      "sqs:GetQueueUrl",
      "sqs:GetQueueAttributes",
      "sqs:SetQueueAttributes",
      "sqs:ListQueues",
      "sqs:TagQueue",
      "sqs:DeleteQueue",
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "serverless_assume_role" {
  statement {
    sid     = "LambdaAndEdgeLambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "lambda.amazonaws.com",
        "edgelambda.amazonaws.com",
      ]
    }
  }
}

# -----------------------------------------------------------------------------
# Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group_policy" "admin" {
  name   = "admin"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin.json
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin.json
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group_policy" "github" {
  name   = "github"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github.json
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless.json
}

# -----------------------------------------------------------------------------
# Users
# -----------------------------------------------------------------------------

resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/admin/"
}

resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

resource "aws_iam_user" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# -----------------------------------------------------------------------------
# Group memberships
# -----------------------------------------------------------------------------

resource "aws_iam_group_membership" "admin" {
  name  = "admin-membership"
  group = aws_iam_group.admin.name
  users = [
    aws_iam_user.admin.name,
    aws_iam_user.admin_macbook_pro.name,
  ]
}

resource "aws_iam_group_membership" "admin_terraform_cloud" {
  name  = "admin-terraform-cloud-membership"
  group = aws_iam_group.admin_terraform_cloud.name
  users = [aws_iam_user.admin_terraform_cloud.name]
}

resource "aws_iam_group_membership" "github" {
  name  = "github-membership"
  group = aws_iam_group.github.name
  users = [aws_iam_user.github.name]
}

resource "aws_iam_group_membership" "serverless" {
  name  = "serverless-membership"
  group = aws_iam_group.serverless.name
  users = [aws_iam_user.serverless.name]
}

# -----------------------------------------------------------------------------
# Serverless role and managed policy
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Permissions for serverless deployments (ACM, CloudFront, IAM, Lambda, Logs, Route53, S3, SQS)."
  policy      = data.aws_iam_policy_document.serverless.json
}

resource "aws_iam_role" "serverless" {
  name               = "serverless"
  path               = "/serverless/"
  assume_role_policy = data.aws_iam_policy_document.serverless_assume_role.json
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "admin_macbook_pro_access_key_id" {
  value = aws_iam_access_key.admin_macbook_pro.id
}

output "admin_macbook_pro_secret_access_key" {
  value     = aws_iam_access_key.admin_macbook_pro.secret
  sensitive = true
}

output "admin_terraform_cloud_access_key_id" {
  value = aws_iam_access_key.admin_terraform_cloud.id
}

output "admin_terraform_cloud_secret_access_key" {
  value     = aws_iam_access_key.admin_terraform_cloud.secret
  sensitive = true
}

output "serverless_role_arn" {
  value = aws_iam_role.serverless.arn
}

output "serverless_policy_arn" {
  value = aws_iam_policy.serverless.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type        = string
  description = "AWS region"
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Namespace (e.g. `cp` or `cloudposse`)"
  default     = "cp"
}

variable "environment" {
  type        = string
  description = "Environment (e.g. `prod`, `dev`, `staging`)"
  default     = "dev"
}

variable "name" {
  type        = string
  description = "Name (e.g. `app` or `iam`)"
  default     = "iam"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes (e.g. `1`)"
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags"
  default     = {}
}

variable "admin_user_names" {
  type        = list(string)
  description = "Optional list of IAM user names to add to the admin group"
  default     = []
}

variable "readonly_user_names" {
  type        = list(string)
  description = "Optional list of IAM user names to add to the non-admin group"
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

module "admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = compact(concat(var.attributes, ["admin"]))
  tags        = var.tags
}

module "readonly_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = compact(concat(var.attributes, ["readonly"]))
  tags        = var.tags
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# Self-management policy (attached to both groups)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "manage_mfa" {
  statement {
    sid = "AllowUsersToCreateEnableResyncTheirOwnVirtualMFADevice"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid = "AllowUsersToDeactivateTheirOwnVirtualMFADevice"

    actions = [
      "iam:DeactivateMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid = "AllowUsersToDeleteTheirOwnVirtualMFADevice"

    actions = [
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid = "AllowUsersToListMFADevicesandUsersForConsole"

    actions = [
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ListUsers",
    ]

    resources = ["*"]
  }

  statement {
    sid = "AllowUsersToManageTheirOwnPasswordAndAccessKeys"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:GetLoginProfile",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:GetAccessKeyLastUsed",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid = "AllowUsersToViewAccountPasswordPolicy"

    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "manage_mfa" {
  name        = "${module.admin_label.id}-self-manage-mfa"
  description = "Allow IAM users to manage their own passwords, access keys and virtual MFA devices"
  policy      = data.aws_iam_policy_document.manage_mfa.json
  tags        = module.admin_label.tags
}

# -----------------------------------------------------------------------------
# Admin role (assumable only with MFA)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "role_trust" {
  statement {
    sid     = "AllowAccountToAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = module.admin_label.id
  description        = "Administrator role assumable only with MFA"
  assume_role_policy = data.aws_iam_policy_document.role_trust.json
  tags               = module.admin_label.tags
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AdministratorAccess"
}

# -----------------------------------------------------------------------------
# Policy allowing admin group to assume the admin role with MFA
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "assume_role_admin" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "assume_role_admin" {
  name        = "${module.admin_label.id}-assume-role"
  description = "Allow assuming the admin role with MFA"
  policy      = data.aws_iam_policy_document.assume_role_admin.json
  tags        = module.admin_label.tags
}

# -----------------------------------------------------------------------------
# Admin group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_role_admin.arn
}

resource "aws_iam_group_policy_attachment" "admin_manage_mfa" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.manage_mfa.arn
}

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_user_names) > 0 ? 1 : 0

  name  = module.admin_label.id
  group = aws_iam_group.admin.name
  users = var.admin_user_names
}

# -----------------------------------------------------------------------------
# Non-admin (readonly) group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "readonly" {
  name = module.readonly_label.id
}

resource "aws_iam_group_policy_attachment" "readonly_manage_mfa" {
  group      = aws_iam_group.readonly.name
  policy_arn = aws_iam_policy.manage_mfa.arn
}

resource "aws_iam_group_membership" "readonly" {
  count = length(var.readonly_user_names) > 0 ? 1 : 0

  name  = module.readonly_label.id
  group = aws_iam_group.readonly.name
  users = var.readonly_user_names
}

output "admin_group_name" {
  value       = aws_iam_group.admin.name
  description = "Name of the admin group"
}

output "readonly_group_name" {
  value       = aws_iam_group.readonly.name
  description = "Name of the non-admin group"
}

output "admin_role_arn" {
  value       = aws_iam_role.admin.arn
  description = "ARN of the admin role"
}

output "admin_role_name" {
  value       = aws_iam_role.admin.name
  description = "Name of the admin role"
}

output "manage_mfa_policy_arn" {
  value       = aws_iam_policy.manage_mfa.arn
  description = "ARN of the self-management policy"
}

output "assume_role_admin_policy_arn" {
  value       = aws_iam_policy.assume_role_admin.arn
  description = "ARN of the policy allowing admin role assumption"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev/test)"
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "test"], var.environment)
    error_message = "Environment must be either 'dev' or 'test'."
  }
}

variable "name_prefix" {
  description = "Prefix used for resource names"
  type        = string
  default     = "multitier"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC (must be a /16)"
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0)) && endswith(var.vpc_cidr, "/16")
    error_message = "vpc_cidr must be a valid /16 CIDR block."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs  = slice(data.aws_availability_zones.available.names, 0, 2)
  name = "${var.name_prefix}-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Stack       = local.name
  }

  public_subnets = {
    for idx, az in local.azs : "public-${idx + 1}" => {
      az   = az
      cidr = cidrsubnet(var.vpc_cidr, 8, idx)
    }
  }

  private_subnets = merge([
    for idx, az in local.azs : {
      for tier in [1, 2] : "private-${idx + 1}-${tier}" => {
        az   = az
        cidr = cidrsubnet(var.vpc_cidr, 8, 10 + (idx * 10) + tier)
      }
    }
  ]...)
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id                  = aws_vpc.this.id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-${each.key}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id                  = aws_vpc.this.id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-${each.key}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "public" {
  name        = "${local.name}-public-sg"
  description = "Public tier security group"
  vpc_id      = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "public_all_from_vpc" {
  security_group_id = aws_security_group.public.id
  description       = "All traffic from VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh_from_vpc" {
  security_group_id = aws_security_group.public.id
  description       = "SSH from VPC CIDR"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = var.vpc_cidr
}

resource "aws_vpc_security_group_ingress_rule" "public_http_from_anywhere" {
  security_group_id = aws_security_group.public.id
  description       = "HTTP from anywhere"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_egress_rule" "public_all_to_vpc" {
  security_group_id = aws_security_group.public.id
  description       = "All outbound traffic to VPC CIDR only"
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

resource "aws_security_group" "private" {
  name        = "${local.name}-private-sg"
  description = "Private tier security group"
  vpc_id      = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "private_all_from_vpc" {
  security_group_id = aws_security_group.private.id
  description       = "All traffic from VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

resource "aws_vpc_security_group_egress_rule" "private_all_to_vpc" {
  security_group_id = aws_security_group.private.id
  description       = "All outbound traffic to VPC CIDR only"
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "vpc_cidr" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.this.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.this.id
}

output "availability_zones" {
  description = "Availability zones used"
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = { for k, s in aws_subnet.public : k => s.id }
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = { for k, s in aws_subnet.private : k => s.id }
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table"
  value       = aws_route_table.private.id
}

output "public_security_group_id" {
  description = "ID of the public security group"
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "ID of the private security group"
  value       = aws_security_group.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the provider."
  type        = string
  default     = "us-east-1"
}

variable "name_suffix" {
  description = "Optional suffix appended to all resource names."
  type        = string
  default     = ""
}

locals {
  name_prefix = "prod-ci-"

  role_name       = "${local.name_prefix}role${var.name_suffix}"
  policy_name     = "${local.name_prefix}assume-role-policy${var.name_suffix}"
  group_name      = "${local.name_prefix}group${var.name_suffix}"
  user_name       = "${local.name_prefix}user${var.name_suffix}"
  membership_name = "${local.name_prefix}group-membership${var.name_suffix}"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "AllowWildcardPrincipalAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    # The wildcard principal is restricted to this account. Without this
    # condition, any AWS account in the world could assume the role.
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "ci" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = {
    Name = local.role_name
  }
}

data "aws_iam_policy_document" "assume_ci_role" {
  statement {
    sid       = "AllowAssumeCiRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.ci.arn]
  }
}

resource "aws_iam_policy" "assume_ci_role" {
  name        = local.policy_name
  description = "Allows assuming the ${local.role_name} role."
  policy      = data.aws_iam_policy_document.assume_ci_role.json

  tags = {
    Name = local.policy_name
  }
}

resource "aws_iam_group" "ci" {
  name = local.group_name
}

resource "aws_iam_group_policy_attachment" "ci" {
  group      = aws_iam_group.ci.name
  policy_arn = aws_iam_policy.assume_ci_role.arn
}

resource "aws_iam_user" "ci" {
  name = local.user_name

  tags = {
    Name = local.user_name
  }
}

resource "aws_iam_group_membership" "ci" {
  name  = local.membership_name
  group = aws_iam_group.ci.name
  users = [aws_iam_user.ci.name]
}

output "role_arn" {
  value = aws_iam_role.ci.arn
}

output "policy_arn" {
  value = aws_iam_policy.assume_ci_role.arn
}

output "group_name" {
  value = aws_iam_group.ci.name
}

output "user_name" {
  value = aws_iam_user.ci.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  default_tags {
    tags = {
      ManagedBy = "Terraform"
    }
  }
}

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }
}

output "configuration_aggregator_arn" {
  value = aws_config_configuration_aggregator.default.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC and used as a prefix for related resources"
  type        = string
  default     = "benchmark-vpc"
}

variable "tags" {
  description = "Additional tags applied to all resources"
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "CIDR ranges allowed to SSH into the public tier"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  azs      = data.aws_availability_zones.available.names
  az_count = length(local.azs)
  newbits  = ceil(log(local.az_count * 2, 2))

  public_subnet_cidrs  = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, local.newbits, i)]
  private_subnet_cidrs = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, local.newbits, i + local.az_count)]

  ephemeral_from = 1024
  ephemeral_to   = 65535
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = var.vpc_name
  })
}

# ---------------------------------------------------------------------------
# Default NACL and security group (managed, locked down, tagged)
# ---------------------------------------------------------------------------

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = merge(var.tags, {
    Name = "${var.vpc_name} Default"
  })

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name} Default"
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

# ---------------------------------------------------------------------------
# Internet Gateway, EIP, NAT Gateway
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

# ---------------------------------------------------------------------------
# Route tables
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-rt"
  })
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.this.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups - public tier
# ---------------------------------------------------------------------------

resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Public tier security group"
  vpc_id      = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg"
  })
}

resource "aws_security_group_rule" "public_ingress_http" {
  type              = "ingress"
  description       = "HTTP from everywhere"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_ingress_https" {
  type              = "ingress"
  description       = "HTTPS from everywhere"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_ingress_ssh" {
  type              = "ingress"
  description       = "SSH from allowed CIDRs"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = var.ssh_inbound
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_egress_http" {
  type              = "egress"
  description       = "HTTP within the VPC"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.public.id
}

resource "aws_security_group_rule" "public_egress_https" {
  type              = "egress"
  description       = "HTTPS within the VPC"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.public.id
}

# ---------------------------------------------------------------------------
# Security groups - private tier
# ---------------------------------------------------------------------------

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Private tier security group"
  vpc_id      = aws_vpc.this.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-sg"
  })
}

resource "aws_security_group_rule" "private_ingress_http" {
  type              = "ingress"
  description       = "HTTP from public subnets"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = local.public_subnet_cidrs
  security_group_id = aws_security_group.private.id
}

resource "aws_security_group_rule" "private_ingress_https" {
  type              = "ingress"
  description       = "HTTPS from public subnets"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = local.public_subnet_cidrs
  security_group_id = aws_security_group.private.id
}

resource "aws_security_group_rule" "private_egress_https" {
  type              = "egress"
  description       = "HTTPS within the VPC"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.private.id
}

# ---------------------------------------------------------------------------
# Network ACL - public tier
# ---------------------------------------------------------------------------

resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.public[*].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-nacl"
  })
}

resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 10
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 20
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 30
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = local.ephemeral_from
  to_port        = local.ephemeral_to
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  count = length(var.ssh_inbound)

  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 10
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 20
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 30
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = local.ephemeral_from
  to_port        = local.ephemeral_to
}

# ---------------------------------------------------------------------------
# Network ACL - private tier
# ---------------------------------------------------------------------------

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-nacl"
  })
}

resource "aws_network_acl_rule" "private_ingress_http" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_subnet_cidrs[count.index]
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_subnet_cidrs[count.index]
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = local.ephemeral_from
  to_port        = local.ephemeral_to
}

resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_egress_ephemeral_private" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.private_subnet_cidrs[count.index]
  from_port      = local.ephemeral_from
  to_port        = local.ephemeral_to
}

resource "aws_network_acl_rule" "private_egress_ephemeral_public" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 300 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_subnet_cidrs[count.index]
  from_port      = local.ephemeral_from
  to_port        = local.ephemeral_to
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Availability zones used"
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidrs" {
  description = "CIDR blocks of the public subnets"
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidrs" {
  description = "CIDR blocks of the private subnets"
  value       = aws_subnet.private[*].cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = aws_internet_gateway.this.id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway"
  value       = aws_nat_gateway.this.id
}

output "nat_public_ip" {
  description = "Public IP of the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private (main) route table"
  value       = aws_route_table.private.id
}

output "public_security_group_id" {
  description = "ID of the public security group"
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "ID of the private security group"
  value       = aws_security_group.private.id
}

output "public_network_acl_id" {
  description = "ID of the public network ACL"
  value       = aws_network_acl.public.id
}

output "private_network_acl_id" {
  description = "ID of the private network ACL"
  value       = aws_network_acl.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "imagebuilder" {
  name_prefix        = "imagebuilder_"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  description        = "IAM role for EC2 Image Builder automation"
}

resource "aws_iam_role_policy_attachment" "imagebuilder_full_access" {
  role       = aws_iam_role.imagebuilder.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSImageBuilderFullAccess"
}

resource "aws_iam_instance_profile" "imagebuilder" {
  name_prefix = "imagebuilder_"
  path        = "/"
  role        = aws_iam_role.imagebuilder.name
}

output "role_name" {
  value = aws_iam_role.imagebuilder.name
}

output "role_arn" {
  value = aws_iam_role.imagebuilder.arn
}

output "instance_profile_name" {
  value = aws_iam_instance_profile.imagebuilder.name
}

output "instance_profile_arn" {
  value = aws_iam_instance_profile.imagebuilder.arn
}

variable "iam_role_name" {
  type        = string
  description = "The name to give to the IAM role"
  default     = "tamr-instance-role"
}

variable "iam_instance_profile_name" {
  type        = string
  description = "The name to give to the IAM instance profile"
  default     = "tamr-instance-profile"
}

variable "permissions_boundary" {
  type        = string
  description = "ARN of the policy to be used as the permissions boundary for the IAM role. Set to null to omit."
  default     = null
}

variable "additional_tags" {
  type        = map(string)
  description = "Additional tags to be attached to the created resources"
  default     = {}
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_instance_role" {
  name                 = var.iam_role_name
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  permissions_boundary = var.permissions_boundary
  tags                 = var.additional_tags
}

resource "aws_iam_instance_profile" "tamr_instance_profile" {
  name = var.iam_instance_profile_name
  role = aws_iam_role.tamr_instance_role.name
  tags = var.additional_tags
}

output "iam_role_name" {
  description = "Name of the IAM role"
  value       = aws_iam_role.tamr_instance_role.name
}

output "iam_role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.tamr_instance_role.arn
}

output "iam_instance_profile_name" {
  description = "Name of the IAM instance profile"
  value       = aws_iam_instance_profile.tamr_instance_profile.name
}

output "iam_instance_profile_arn" {
  description = "ARN of the IAM instance profile"
  value       = aws_iam_instance_profile.tamr_instance_profile.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Tags to apply to IAM resources"
  type        = map(string)
  default = {
    Purpose = "RDSCustomSQLServer"
  }
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_custom_sqlserver_instance_role" {
  name               = "AWSRDSCustomSQLServerInstanceRole"
  path               = "/"
  description        = "Instance role for Amazon RDS Custom for SQL Server"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "rds_custom_instance_profile_policy" {
  role       = aws_iam_role.rds_custom_sqlserver_instance_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonRDSCustomInstanceProfileRolePolicy"
}

resource "aws_iam_instance_profile" "rds_custom_sqlserver_instance_profile" {
  name = "AWSRDSCustomSQLServerInstanceProfile"
  path = "/"
  role = aws_iam_role.rds_custom_sqlserver_instance_role.name

  tags = var.tags
}

output "instance_role_name" {
  description = "Name of the RDS Custom for SQL Server instance role"
  value       = aws_iam_role.rds_custom_sqlserver_instance_role.name
}

output "instance_role_arn" {
  description = "ARN of the RDS Custom for SQL Server instance role"
  value       = aws_iam_role.rds_custom_sqlserver_instance_role.arn
}

output "instance_profile_name" {
  description = "Name of the RDS Custom for SQL Server instance profile"
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.name
}

output "instance_profile_arn" {
  description = "ARN of the RDS Custom for SQL Server instance profile"
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.arn
}

variable "resource_prefix" {
  description = "Environment-specific prefix applied to resource names (e.g. dev, stg, prod)"
  type        = string
}

variable "target_account_id" {
  description = "AWS account ID that owns the role granting read access to the software installation files in S3"
  type        = string

  validation {
    condition     = can(regex("^[0-9]{12}$", var.target_account_id))
    error_message = "target_account_id must be a 12-digit AWS account ID."
  }
}

variable "target_role_name" {
  description = "Name of the IAM role in the target account to be assumed by the Packer builder instance"
  type        = string
}

variable "tags" {
  description = "Additional tags to apply to resources"
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

locals {
  target_role_arn = "arn:${data.aws_partition.current.partition}:iam::${var.target_account_id}:role/${var.target_role_name}"

  common_tags = merge(
    {
      Name      = "${var.resource_prefix}-packer-builder"
      ManagedBy = "terraform"
    },
    var.tags,
  )
}

data "aws_iam_policy_document" "packer_builder_trust" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "packer_builder" {
  name               = "${var.resource_prefix}-packer-builder-role"
  description        = "Role for the EC2 Packer builder instance"
  assume_role_policy = data.aws_iam_policy_document.packer_builder_trust.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "assume_target_role" {
  statement {
    sid       = "AllowAssumeSoftwareInstallRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [local.target_role_arn]
  }
}

resource "aws_iam_policy" "assume_target_role" {
  name        = "${var.resource_prefix}-packer-builder-assume-role-policy"
  description = "Allows the Packer builder instance to assume the cross-account role for reading software installation files from S3"
  policy      = data.aws_iam_policy_document.assume_target_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "assume_target_role" {
  role       = aws_iam_role.packer_builder.name
  policy_arn = aws_iam_policy.assume_target_role.arn
}

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${var.resource_prefix}-packer-builder-instance-profile"
  role = aws_iam_role.packer_builder.name

  tags = local.common_tags
}

output "packer_builder_role_name" {
  description = "Name of the Packer builder IAM role"
  value       = aws_iam_role.packer_builder.name
}

output "packer_builder_role_arn" {
  description = "ARN of the Packer builder IAM role (add to the target role's trust policy)"
  value       = aws_iam_role.packer_builder.arn
}

output "packer_builder_instance_profile_name" {
  description = "Name of the Packer builder instance profile"
  value       = aws_iam_instance_profile.packer_builder.name
}

output "packer_builder_instance_profile_arn" {
  description = "ARN of the Packer builder instance profile"
  value       = aws_iam_instance_profile.packer_builder.arn
}

output "target_role_arn" {
  description = "ARN of the cross-account role the Packer builder is permitted to assume"
  value       = local.target_role_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "three-tier-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "presentation_subnet_cidr" {
  description = "CIDR block for the presentation subnet"
  type        = string
  default     = "10.16.0.0/24"
}

variable "application_subnet_cidr" {
  description = "CIDR block for the application subnet"
  type        = string
  default     = "10.16.1.0/24"
}

variable "data_subnet_cidr" {
  description = "CIDR block for the data subnet"
  type        = string
  default     = "10.16.2.0/24"
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.presentation_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "presentation-subnet"
    Tier = "presentation"
  }
}

resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.application_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "application-subnet"
    Tier = "application"
  }
}

resource "aws_subnet" "data" {
  vpc_id            = aws_vpc.this.id
  cidr_block        = var.data_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "data-subnet"
    Tier = "data"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "presentation-route-table"
  }
}

resource "aws_route" "presentation_internet" {
  route_table_id         = aws_route_table.presentation.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "presentation_subnet_id" {
  description = "ID of the presentation subnet"
  value       = aws_subnet.presentation.id
}

output "application_subnet_id" {
  description = "ID of the application subnet"
  value       = aws_subnet.application.id
}

output "data_subnet_id" {
  description = "ID of the data subnet"
  value       = aws_subnet.data.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.this.id
}

output "presentation_route_table_id" {
  description = "ID of the presentation route table"
  value       = aws_route_table.presentation.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "group_name" {
  description = "Name of the IAM group for Service Catalog end users."
  type        = string
  default     = "ServiceCatalogEndUsers"
}

variable "user_name" {
  description = "Name of the console-enabled IAM user."
  type        = string
  default     = "service-catalog-test-user"
}

variable "pgp_key" {
  description = "Optional PGP key (base64 or keybase:username) used to encrypt the initial console password."
  type        = string
  default     = null
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Service Catalog launch role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "service_catalog_assume_role" {
  statement {
    sid     = "AllowServiceCatalogAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name               = "test_role"
  description        = "Launch constraint role assumed by AWS Service Catalog for product provisioning."
  assume_role_policy = data.aws_iam_policy_document.service_catalog_assume_role.json

  tags = {
    Purpose   = "ServiceCatalogLaunchConstraint"
    ManagedBy = "Terraform"
  }
}

data "aws_iam_policy_document" "launch_constraint" {
  statement {
    sid    = "CloudFormationStackOperations"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStacks",
      "cloudformation:SetStackPolicy",
      "cloudformation:UpdateStack",
      "cloudformation:TagResource",
      "cloudformation:UntagResource",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:cloudformation:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:stack/SC-*",
    ]
  }

  statement {
    sid    = "CloudFormationTemplateOperations"
    effect = "Allow"
    actions = [
      "cloudformation:GetTemplateSummary",
      "cloudformation:ValidateTemplate",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "ReadServiceCatalogTemplates"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "s3:ExistingObjectTag/servicecatalog:provisioning"
      values   = ["true"]
    }
  }

  statement {
    sid    = "ScopedS3BucketProvisioning"
    effect = "Allow"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutBucketTagging",
      "s3:PutBucketVersioning",
      "s3:PutEncryptionConfiguration",
      "s3:PutBucketPublicAccessBlock",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::sc-*",
    ]
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "test_role_launch_constraint"
  description = "Scoped launch constraint permissions for the Service Catalog test_role."
  policy      = data.aws_iam_policy_document.launch_constraint.json
}

resource "aws_iam_role_policy_attachment" "launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

# ---------------------------------------------------------------------------
# IAM group and console-enabled user
# ---------------------------------------------------------------------------

resource "aws_iam_group" "service_catalog_users" {
  name = var.group_name
  path = "/"
}

resource "aws_iam_group_policy_attachment" "end_user_access" {
  group      = aws_iam_group.service_catalog_users.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSServiceCatalogEndUserFullAccess"
}

resource "aws_iam_user" "console_user" {
  name          = var.user_name
  path          = "/"
  force_destroy = true

  tags = {
    Purpose   = "ServiceCatalogTesting"
    ManagedBy = "Terraform"
  }
}

resource "aws_iam_user_login_profile" "console_user" {
  user                    = aws_iam_user.console_user.name
  pgp_key                 = var.pgp_key
  password_length         = 20
  password_reset_required = true

  lifecycle {
    ignore_changes = [
      password_length,
      password_reset_required,
      pgp_key,
    ]
  }
}

resource "aws_iam_user_group_membership" "console_user" {
  user   = aws_iam_user.console_user.name
  groups = [aws_iam_group.service_catalog_users.name]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "test_role_arn" {
  description = "ARN of the Service Catalog launch constraint role."
  value       = aws_iam_role.test_role.arn
}

output "group_name" {
  description = "Name of the IAM group."
  value       = aws_iam_group.service_catalog_users.name
}

output "user_name" {
  description = "Name of the console-enabled IAM user."
  value       = aws_iam_user.console_user.name
}

output "console_signin_url" {
  description = "AWS console sign-in URL for the account."
  value       = "https://${data.aws_caller_identity.current.account_id}.signin.aws.amazon.com/console"
}

output "user_initial_password" {
  description = "Initial console password (plaintext when no PGP key is supplied)."
  value       = var.pgp_key == null ? aws_iam_user_login_profile.console_user.password : null
  sensitive   = true
}

output "user_encrypted_password" {
  description = "PGP-encrypted initial console password (when a PGP key is supplied)."
  value       = var.pgp_key != null ? aws_iam_user_login_profile.console_user.encrypted_password : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  default_tags {
    tags = var.tags
  }
}

variable "name" {
  description = "Name of the VPC and prefix for related resources"
  type        = string
  default     = "DatatogAgentlessScanner"
}

variable "cidr" {
  description = "CIDR block of the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "tags" {
  description = "Tags applied to all resources"
  type        = map(string)
  default = {
    "Datadog"                 = "true"
    "DatadogAgentlessScanner" = "true"
  }
}

variable "enable_ssm_vpc_endpoint" {
  description = "Whether to create SSM interface VPC endpoints (ec2messages, ssmmessages, ssm)"
  type        = bool
  default     = false
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, min(3, length(data.aws_availability_zones.available.names)))

  # Public subnets use the first /19 blocks, private subnets are offset by 4 blocks
  public_subnets  = [for i, az in local.azs : cidrsubnet(var.cidr, 3, i)]
  private_subnets = [for i, az in local.azs : cidrsubnet(var.cidr, 3, i + 4)]

  interface_endpoints = toset(["lambda", "ebs"])
  ssm_endpoints       = var.enable_ssm_vpc_endpoint ? toset(["ec2messages", "ssmmessages", "ssm"]) : toset([])
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id            = aws_vpc.vpc.id
  cidr_block        = local.public_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.name}-public-${local.azs[count.index]}"
  }
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.vpc.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.name}-private-${local.azs[count.index]}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = var.name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "${var.name}-public"
  }
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = var.name
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = var.name
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "${var.name}-private"
  }
}

resource "aws_route" "private_nat_gateway" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat.id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = {
    Name = "${var.name}-s3"
  }
}

resource "aws_security_group" "endpoints" {
  name        = "${var.name}-vpc-endpoints"
  description = "Allow HTTPS from the VPC to interface VPC endpoints"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.vpc.cidr_block]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.vpc.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-${each.key}"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  for_each = local.ssm_endpoints

  vpc_id              = aws_vpc.vpc.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-${each.key}"
  }
}

output "vpc" {
  description = "The created VPC"
  value       = aws_vpc.vpc
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway"
  value       = aws_nat_gateway.nat.id
}

output "private_route_table_id" {
  description = "ID of the private route table"
  value       = aws_route_table.private.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

##-----------------------------------------------------------------------------
## Variables
##-----------------------------------------------------------------------------

variable "enable" {
  type        = bool
  default     = true
  description = "Master flag to enable or disable creation of all resources in this module."
}

variable "name" {
  type        = string
  default     = ""
  description = "Name (e.g. `app` or `cluster`)."
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment (e.g. `prod`, `dev`, `staging`)."
}

variable "repository" {
  type        = string
  default     = "https://github.com/sohanyadav/terraform-aws-security-group"
  description = "Terraform current module repo."
}

variable "label_order" {
  type        = list(string)
  default     = ["name", "environment"]
  description = "Label order, e.g. `name`,`environment`."
}

variable "managedby" {
  type        = string
  default     = "terraform"
  description = "ManagedBy, e.g. 'terraform' or 'team-name'."
}

variable "new_sg" {
  type        = bool
  default     = true
  description = "Set to true to create a new security group, false to attach rules to an existing security group."
}

variable "existing_sg_id" {
  type        = string
  default     = null
  description = "ID of an existing security group to manage rules on when `new_sg` is false."
}

variable "vpc_id" {
  type        = string
  default     = null
  description = "VPC ID in which to create the security group. If not supplied, a fallback VPC is created."
}

variable "fallback_vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "CIDR block of the fallback VPC created when no VPC ID is supplied."
}

variable "sg_description" {
  type        = string
  default     = "Security group managed by Terraform."
  description = "Description of the security group."
}

variable "sg_revoke_rules_on_delete" {
  type        = bool
  default     = false
  description = "Instruct Terraform to revoke all of the security group's attached rules before deleting it."
}

variable "prefix_list_enabled" {
  type        = bool
  default     = false
  description = "Enable creation of a managed prefix list."
}

variable "prefix_list_ids" {
  type        = list(string)
  default     = []
  description = "IDs of pre-existing managed prefix lists. When empty and `prefix_list_enabled` is true, a new prefix list is created."
}

variable "prefix_list_address_family" {
  type        = string
  default     = "IPv4"
  description = "Address family (IPv4 or IPv6) of the managed prefix list."

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "max_entries" {
  type        = number
  default     = 5
  description = "Maximum number of entries the managed prefix list can hold."
}

variable "entry" {
  type        = list(any)
  default     = []
  description = "List of entries ({ cidr, description }) for the managed prefix list."
}

## New security group rules

variable "new_sg_ingress_rules_with_cidr_blocks" {
  type        = list(any)
  default     = []
  description = "Ingress rules with CIDR blocks for the new security group."
}

variable "new_sg_ingress_rules_with_self" {
  type        = list(any)
  default     = []
  description = "Self-referencing ingress rules for the new security group."
}

variable "new_sg_ingress_rules_with_source_sg_id" {
  type        = list(any)
  default     = []
  description = "Ingress rules with source security group IDs for the new security group."
}

variable "new_sg_ingress_rules_with_prefix_list" {
  type        = list(any)
  default     = []
  description = "Ingress rules with prefix lists for the new security group."
}

variable "new_sg_egress_rules_with_cidr_blocks" {
  type        = list(any)
