##-----------------------------------------------------------------------------
## Labels
##-----------------------------------------------------------------------------

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

##-----------------------------------------------------------------------------
## Locals
##-----------------------------------------------------------------------------

locals {
  create_new_sg       = var.enable && var.new_sg
  manage_existing_sg  = var.enable && !var.new_sg && var.existing_sg_id != null
  create_fallback_vpc = local.create_new_sg && (var.vpc_id == null || var.vpc_id == "")
  create_prefix_list  = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0

  vpc_id = local.create_fallback_vpc ? one(aws_vpc.default[*].id) : var.vpc_id

  new_sg_id      = one(aws_security_group.default[*].id)
  existing_sg_id = var.existing_sg_id

  prefix_list_ids = local.create_prefix_list ? aws_ec2_managed_prefix_list.prefix_list[*].id : var.prefix_list_ids
}

##-----------------------------------------------------------------------------
## Fallback VPC
##-----------------------------------------------------------------------------

resource "aws_vpc" "default" {
  count = local.create_fallback_vpc ? 1 : 0

  cidr_block           = var.fallback_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    module.labels.tags,
    {
      "Name" = format("%s-vpc", module.labels.id)
    }
  )
}

##-----------------------------------------------------------------------------
## Security Group
##-----------------------------------------------------------------------------

resource "aws_security_group" "default" {
  count = local.create_new_sg ? 1 : 0

  name                   = format("%s-sg", module.labels.id)
  description            = var.sg_description
  vpc_id                 = local.vpc_id
  revoke_rules_on_delete = var.sg_revoke_rules_on_delete

  tags = merge(
    module.labels.tags,
    {
      "Name" = format("%s-sg", module.labels.id)
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

##-----------------------------------------------------------------------------
## Managed Prefix List
##-----------------------------------------------------------------------------

resource "aws_ec2_managed_prefix_list" "prefix_list" {
  count = local.create_prefix_list ? 1 : 0

  name           = format("%s-prefix-list", module.labels.id)
  address_family = var.prefix_list_address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.entry
    content {
      cidr        = lookup(entry.value, "cidr", null)
      description = lookup(entry.value, "description", null)
    }
  }

  tags = merge(
    module.labels.tags,
    {
      "Name" = format("%s-prefix-list", module.labels.id)
    }
  )
}

##-----------------------------------------------------------------------------
## New Security Group - Ingress Rules
##-----------------------------------------------------------------------------

resource "aws_security_group_rule" "new_sg_ingress_with_cidr_blocks" {
  count = local.create_new_sg ? length(var.new_sg_ingress_rules_with_cidr_blocks) : 0

  type              = "ingress"
  security_group_id = local.new_sg_id
  from_port         = var.new_sg_ingress_rules_with_cidr_blocks[count.index].from_port
  to_port           = var.new_sg_ingress_rules_with_cidr_blocks[count.index].to_port
  protocol          = lookup(var.new_sg_ingress_rules_with_cidr_blocks[count.index], "protocol", "tcp")
  cidr_blocks       = lookup(var.new_sg_ingress_rules_with_cidr_blocks[count.index], "cidr_blocks", null)
  ipv6_cidr_blocks  = lookup(var.new_sg_ingress_rules_with_cidr_blocks[count.index], "ipv6_cidr_blocks", null)
  description       = lookup(var.new_sg_ingress_rules_with_cidr_blocks[count.index], "description", null)
