terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

resource "random_pet" "log_group_suffix" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "this" {
  name              = "logs-${random_pet.log_group_suffix.id}"
  retention_in_days = 7
}

data "aws_iam_policy_document" "log_group_write" {
  statement {
    sid    = "AllowLogStreamOperations"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.this.arn,
      "${aws_cloudwatch_log_group.this.arn}:log-stream:*",
    ]
  }
}

resource "aws_iam_policy" "log_group_write" {
  name        = "logs-${random_pet.log_group_suffix.id}-write"
  description = "Allows creating, describing, and writing to log streams in the ${aws_cloudwatch_log_group.this.name} log group."
  policy      = data.aws_iam_policy_document.log_group_write.json
}

output "log_group_name" {
  description = "Name of the CloudWatch Logs log group."
  value       = aws_cloudwatch_log_group.this.name
}

output "log_group_arn" {
  description = "ARN of the CloudWatch Logs log group."
  value       = aws_cloudwatch_log_group.this.arn
}

output "iam_policy_arn" {
  description = "ARN of the IAM policy granting log stream access to the log group."
  value       = aws_iam_policy.log_group_write.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "enabled" {
  description = "Whether to create the SSM Automation log group and configure the SSM service settings."
  type        = bool
  default     = true
}

variable "log_group_name" {
  description = "Name of the CloudWatch log group for SSM Automation executeScript output."
  type        = string
  default     = "/aws/ssm/automation/executeScript"
}

variable "log_retention_in_days" {
  description = "Retention period, in days, for the SSM Automation log group."
  type        = number
  default     = 14
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  service_setting_arn_prefix = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:servicesetting"
}

resource "aws_cloudwatch_log_group" "ssm_automation" {
  count = var.enabled ? 1 : 0

  name              = var.log_group_name
  retention_in_days = var.log_retention_in_days
}

resource "aws_ssm_service_setting" "automation_log_destination" {
  count = var.enabled ? 1 : 0

  setting_id    = "${local.service_setting_arn_prefix}/ssm/automation/customer-script-log-destination"
  setting_value = "CloudWatch"
}

resource "aws_ssm_service_setting" "automation_log_group_name" {
  count = var.enabled ? 1 : 0

  setting_id    = "${local.service_setting_arn_prefix}/ssm/automation/customer-script-log-group-name"
  setting_value = aws_cloudwatch_log_group.ssm_automation[0].name

  depends_on = [aws_ssm_service_setting.automation_log_destination]
}

resource "aws_ssm_service_setting" "documents_public_sharing" {
  count = var.enabled ? 1 : 0

  setting_id    = "${local.service_setting_arn_prefix}/ssm/documents/console/public-sharing-permission"
  setting_value = "Disable"
}

output "log_group_name" {
  description = "Name of the SSM Automation CloudWatch log group."
  value       = var.enabled ? aws_cloudwatch_log_group.ssm_automation[0].name : null
}

output "log_group_arn" {
  description = "ARN of the SSM Automation CloudWatch log group."
  value       = var.enabled ? aws_cloudwatch_log_group.ssm_automation[0].arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources in"
  type        = string
  default     = "us-east-1"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:aws:logs:*:*:*"]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  path        = "/"
  description = "IAM policy for logging from a Lambda function"
  policy      = data.aws_iam_policy_document.lambda_logging.json
}

# Create backup role

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    effect    = "Allow"
    actions   = ["dynamodb:CreateBackup"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "create_ddb_backup_policy" {
  name   = "create_ddb_backup_policy"
  role   = aws_iam_role.create_ddb_backup_role.id
  policy = data.aws_iam_policy_document.create_ddb_backup.json
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Remove backup role

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

data "aws_iam_policy_document" "remove_ddb_backup" {
  statement {
    effect = "Allow"
    actions = [
      "dynamodb:ListBackups",
      "dynamodb:DeleteBackup",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "remove_ddb_backup_policy" {
  name   = "remove_ddb_backup_policy"
  role   = aws_iam_role.remove_ddb_backup_role.id
  policy = data.aws_iam_policy_document.remove_ddb_backup.json
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

output "create_ddb_backup_role" {
  description = "IAM role for the Lambda that creates DynamoDB backups"
  value       = aws_iam_role.create_ddb_backup_role
}

output "remove_ddb_backup_role" {
  description = "IAM role for the Lambda that lists and deletes DynamoDB backups"
  value       = aws_iam_role.remove_ddb_backup_role
}

