terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "github_oidc_url" {
  description = "GitHub Actions OIDC issuer URL."
  type        = string
  default     = "https://token.actions.githubusercontent.com"
}

variable "client_id_list" {
  description = "Audiences (client IDs) allowed for the OIDC provider."
  type        = list(string)
  default     = ["sts.amazonaws.com"]
}

variable "github_thumbprints" {
  description = "GitHub's published thumbprints for token.actions.githubusercontent.com."
  type        = list(string)
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

variable "roles" {
  description = <<-EOT
    Optional map of GitHub-federated IAM roles to create, keyed by role name.
    Each entry specifies the GitHub subject patterns allowed to assume the role
    (e.g. "repo:my-org/my-repo:ref:refs/heads/main") and managed policy ARNs to attach.
  EOT
  type = map(object({
    subjects             = list(string)
    policy_arns          = optional(list(string), [])
    description          = optional(string, "GitHub Actions federated role")
    max_session_duration = optional(number, 3600)
    path                 = optional(string, "/")
  }))
  default = {}
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "tls_certificate" "github" {
  url = var.github_oidc_url
}

locals {
  issuer_host = replace(var.github_oidc_url, "https://", "")

  thumbprint_list = distinct(concat(
    [for cert in data.tls_certificate.github.certificates : cert.sha1_fingerprint if cert.is_ca],
    var.github_thumbprints,
  ))

  role_policy_attachments = merge([
    for role_name, role in var.roles : {
      for arn in role.policy_arns : "${role_name}|${arn}" => {
        role       = role_name
        policy_arn = arn
      }
    }
  ]...)
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = var.github_oidc_url
  client_id_list  = var.client_id_list
  thumbprint_list = local.thumbprint_list

  tags = var.tags
}

data "aws_iam_policy_document" "assume_role" {
  for_each = var.roles

  statement {
    sid     = "GitHubActionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.issuer_host}:aud"
      values   = var.client_id_list
    }

    condition {
      test     = "StringLike"
      variable = "${local.issuer_host}:sub"
      values   = each.value.subjects
    }
  }
}

resource "aws_iam_role" "github" {
  for_each = var.roles

  name                 = each.key
  path                 = each.value.path
  description          = each.value.description
  max_session_duration = each.value.max_session_duration
  assume_role_policy   = data.aws_iam_policy_document.assume_role[each.key].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "github" {
  for_each = local.role_policy_attachments

  role       = aws_iam_role.github[each.value.role].name
  policy_arn = each.value.policy_arn
}

output "oidc_provider_arn" {
  description = "ARN of the GitHub Actions OIDC provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "oidc_provider_thumbprints" {
  description = "Thumbprints configured on the OIDC provider."
  value       = aws_iam_openid_connect_provider.github.thumbprint_list
}

output "role_arns" {
  description = "ARNs of the GitHub-federated IAM roles created (empty by default)."
  value       = { for name, role in aws_iam_role.github : name => role.arn }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "projectvpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "projectvpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.projectvpc.id

  tags = {
    Name = "projectvpc-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "projectvpc-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.projectvpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "projectvpc-private-subnet"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "projectvpc-nat-eip"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "projectvpc-nat-gateway"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "projectvpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "projectvpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  value = aws_vpc.projectvpc.id
}

output "public_subnet_id" {
  value = aws_subnet.public.id
}

output "private_subnet_id" {
  value = aws_subnet.private.id
}

output "nat_gateway_id" {
  value = aws_nat_gateway.nat.id
}

output "nat_eip_public_ip" {
  value = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name            = "demo-vpc"
  vpc_cidr        = "10.0.0.0/16"
  private_subnets = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
  public_subnets  = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  tags = {
    Name        = local.name
    Environment = "dev"
    Terraform   = "true"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 1, 4)
}

resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = local.name
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = length(local.public_subnets)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(local.private_subnets)

  vpc_id            = aws_vpc.this.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.tags, {
    Name = "${local.name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.tags, {
    Name = "${local.name}-public"
  })
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${local.name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.tags, {
    Name = "${local.name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.tags, {
    Name = "${local.name}-private"
  })
}

resource "aws_route" "private_nat_gateway" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this.id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "availability_zones" {
  value = local.azs
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  value = aws_nat_gateway.this.id
}

output "nat_public_ip" {
  value = aws_eip.nat.public_ip
}

output "internet_gateway_id" {
  value = aws_internet_gateway.this.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpcs = {
    dev  = "10.0.0.0/16"
    test = "172.24.0.0/16"
  }

  peers = {
    dev  = "test"
    test = "dev"
  }

  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  public_subnets = merge([
    for vpc_name, vpc_cidr in local.vpcs : {
      for idx, az in local.azs :
      "${vpc_name}-public-${idx + 1}" => {
        vpc  = vpc_name
        az   = az
        cidr = cidrsubnet(vpc_cidr, 8, 101 + idx)
      }
    }
  ]...)

  private_subnets = merge([
    for vpc_name, vpc_cidr in local.vpcs : {
      for idx, az in local.azs :
      "${vpc_name}-private-${idx + 1}" => {
        vpc  = vpc_name
        az   = az
        cidr = cidrsubnet(vpc_cidr, 8, 1 + idx)
      }
    }
  ]...)
}

resource "aws_vpc" "this" {
  for_each = local.vpcs

  cidr_block           = each.value
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = each.key
  }
}

resource "aws_internet_gateway" "this" {
  for_each = local.vpcs

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name = "${each.key}-igw"
  }
}

resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id                  = aws_vpc.this[each.value.vpc].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = true

  tags = {
    Name = each.key
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = aws_vpc.this[each.value.vpc].id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = {
    Name = each.key
    Tier = "private"
  }
}

resource "aws_route_table" "public" {
  for_each = local.vpcs

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name = "${each.key}-public"
  }
}

resource "aws_route" "public_internet" {
  for_each = local.vpcs

  route_table_id         = aws_route_table.public[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[each.key].id
}

resource "aws_route_table" "private" {
  for_each = local.vpcs

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name = "${each.key}-private"
  }
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[each.value.vpc].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.value.vpc].id
}

resource "aws_vpc_peering_connection" "dev_test" {
  vpc_id      = aws_vpc.this["dev"].id
  peer_vpc_id = aws_vpc.this["test"].id
  auto_accept = true

  tags = {
    Name = "dev-test-vpc-peer"
  }
}

resource "aws_vpc_peering_connection_options" "dev_test" {
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  accepter {
    allow_remote_vpc_dns_resolution = true
  }
}

resource "aws_route" "public_to_peer" {
  for_each = local.peers

  route_table_id            = aws_route_table.public[each.key].id
  destination_cidr_block    = aws_vpc.this[each.value].cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "private_to_peer" {
  for_each = local.peers

  route_table_id            = aws_route_table.private[each.key].id
  destination_cidr_block    = aws_vpc.this[each.value].cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

output "vpc_ids" {
  value = { for k, v in aws_vpc.this : k => v.id }
}

output "public_subnet_ids" {
  value = { for k, v in aws_subnet.public : k => v.id }
}

output "private_subnet_ids" {
  value = { for k, v in aws_subnet.private : k => v.id }
}

output "vpc_peering_connection_id" {
  value = aws_vpc_peering_connection.dev_test.id
}

