terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "name" {
  description = "Name of the IAM role"
  type        = string
  default     = "github-actions-oidc"
}

variable "path" {
  description = "Path of the IAM role"
  type        = string
  default     = "/"
}

variable "description" {
  description = "Description of the IAM role"
  type        = string
  default     = "IAM role assumed by GitHub Actions via OIDC web identity federation"
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role"
  type        = number
  default     = 3600
}

variable "permissions_boundary_arn" {
  description = "ARN of the policy used as the permissions boundary for the role"
  type        = string
  default     = null
}

variable "audience" {
  description = "Audience value expected in the GitHub OIDC token"
  type        = string
  default     = "sts.amazonaws.com"
}

variable "subjects" {
  description = "List of GitHub repository patterns allowed to assume the role (e.g. \"my-org/my-repo:*\", \"my-org/*:ref:refs/heads/main\"). The \"repo:\" prefix is added automatically"
  type        = list(string)
  default     = []
}

variable "policies" {
  description = "Map of arbitrary keys to managed policy ARNs to attach to the role"
  type        = map(string)
  default     = {}
}

variable "tags" {
  description = "Tags to apply to the IAM role"
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  provider_url = "token.actions.githubusercontent.com"
  provider_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${local.provider_url}"
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "GithubOidcAuth"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [local.provider_arn]
    }

    condition {
      test     = "ForAllValues:StringEquals"
      variable = "${local.provider_url}:iss"
      values   = ["https://${local.provider_url}"]
    }

    condition {
      test     = "ForAllValues:StringEquals"
      variable = "${local.provider_url}:aud"
      values   = [var.audience]
    }

    dynamic "condition" {
      for_each = length(var.subjects) > 0 ? [1] : []

      content {
        test     = "StringLike"
        variable = "${local.provider_url}:sub"
        values   = [for subject in var.subjects : "repo:${subject}"]
      }
    }
  }
}

resource "aws_iam_role" "this" {
  name                  = var.name
  path                  = var.path
  description           = var.description
  max_session_duration  = var.max_session_duration
  permissions_boundary  = var.permissions_boundary_arn
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.assume_role.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "this" {
  for_each = var.policies

  role       = aws_iam_role.this.name
  policy_arn = each.value
}

output "arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.this.arn
}

output "name" {
  description = "Name of the IAM role"
  value       = aws_iam_role.this.name
}

output "path" {
  description = "Path of the IAM role"
  value       = aws_iam_role.this.path
}

output "unique_id" {
  description = "Unique ID of the IAM role"
  value       = aws_iam_role.this.unique_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the provider configuration."
  type        = string
  default     = "us-east-1"
}

data "aws_iam_policy_document" "managed_force_mfa" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListVirtualMFADevices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = ["arn:aws:iam::*:mfa/$${aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowDeactivateOwnMFAOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowSelfInspectionOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:GetLoginProfile",
      "iam:ListAccessKeys",
      "iam:ListGroupsForUser",
      "iam:ListAttachedUserPolicies",
      "iam:ListUserPolicies",
      "iam:ListSigningCertificates",
      "iam:ListSSHPublicKeys",
      "iam:ListServiceSpecificCredentials",
      "iam:GetAccessKeyLastUsed",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows IAM users to view account info and manage their own password and virtual MFA device; MFA deactivation and broader self-inspection require MFA."
  policy      = data.aws_iam_policy_document.managed_force_mfa.json
}

output "managed_force_mfa_policy_arn" {
  description = "ARN of the managed-force-mfa-policy IAM policy."
  value       = aws_iam_policy.managed_force_mfa.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the provider configuration."
  type        = string
  default     = "us-east-1"
}

# -----------------------------------------------------------------------------
# Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "billing" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport" {
  name = "SuportGroup"
}

# -----------------------------------------------------------------------------
# Policies
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "billing" {
  statement {
    sid    = "BillingReadOnly"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "billing:Get*",
      "billing:List*",
      "budgets:ViewBudget",
      "budgets:Describe*",
      "ce:Get*",
      "ce:Describe*",
      "ce:List*",
      "cur:Describe*",
      "cur:Get*",
      "pricing:DescribeServices",
      "pricing:GetAttributeValues",
      "pricing:GetProducts",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing" {
  name        = "BillingPolicy"
  description = "Read-only access to billing, usage, budgets, cost reports and pricing."
  policy      = data.aws_iam_policy_document.billing.json
}

data "aws_iam_policy_document" "suport" {
  statement {
    sid    = "SupportReadOnly"
    effect = "Allow"
    actions = [
      "ec2:Describe*",
      "ec2:Get*",
      "ec2:List*",
      "s3:Describe*",
      "s3:Get*",
      "s3:List*",
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "rds:Describe*",
      "rds:Get*",
      "rds:List*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "suport" {
  name        = "SuportPolicy"
  description = "Read-only describe, get and list access to EC2, S3, CloudWatch and RDS."
  policy      = data.aws_iam_policy_document.suport.json
}

# -----------------------------------------------------------------------------
# Group policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "billing" {
  group      = aws_iam_group.billing.name
  policy_arn = aws_iam_policy.billing.arn
}

resource "aws_iam_group_policy_attachment" "admin" {
  group      = aws_iam_group.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport" {
  group      = aws_iam_group.suport.name
  policy_arn = aws_iam_policy.suport.arn
}

# -----------------------------------------------------------------------------
# Users
# -----------------------------------------------------------------------------

resource "aws_iam_user" "billing" {
  name          = "Billing"
  force_destroy = true
}

resource "aws_iam_user" "admin" {
  name          = "Admin"
  force_destroy = true
}

resource "aws_iam_user" "suport" {
  name          = "Suport"
  force_destroy = true
}

# -----------------------------------------------------------------------------
# Group memberships
# -----------------------------------------------------------------------------

resource "aws_iam_user_group_membership" "billing" {
  user   = aws_iam_user.billing.name
  groups = [aws_iam_group.billing.name]
}

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "suport" {
  user   = aws_iam_user.suport.name
  groups = [aws_iam_group.suport.name]
}

# -----------------------------------------------------------------------------
# Console login profiles
# -----------------------------------------------------------------------------

resource "aws_iam_user_login_profile" "billing" {
  user            = aws_iam_user.billing.name
  password_length = 8
}

resource "aws_iam_user_login_profile" "admin" {
  user            = aws_iam_user.admin.name
  password_length = 8
}

resource "aws_iam_user_login_profile" "suport" {
  user            = aws_iam_user.suport.name
  password_length = 8
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "billing_user" {
  description = "Username and generated console password for the Billing user."
  sensitive   = true
  value = {
    username = aws_iam_user.billing.name
    password = aws_iam_user_login_profile.billing.password
  }
}

output "admin_user" {
  description = "Username and generated console password for the Admin user."
  sensitive   = true
  value = {
    username = aws_iam_user.admin.name
    password = aws_iam_user_login_profile.admin.password
  }
}

output "suport_user" {
  description = "Username and generated console password for the Suport user."
  sensitive   = true
  value = {
    username = aws_iam_user.suport.name
    password = aws_iam_user_login_profile.suport.password
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the EFS file system."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name tag applied to the EFS file system."
  type        = string
  default     = "shared-storage-test"
}

variable "tags" {
  description = "Additional tags to apply to the EFS file system."
  type        = map(string)
  default     = {}
}

resource "random_id" "creation_token" {
  byte_length = 8
  prefix      = "${var.name}-"
}

resource "aws_efs_file_system" "this" {
  creation_token   = random_id.creation_token.hex
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = merge(
    var.tags,
    {
      Name = var.name
    }
  )
}

resource "aws_efs_backup_policy" "this" {
  file_system_id = aws_efs_file_system.this.id

  backup_policy {
    status = "ENABLED"
  }
}

output "file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.this.id
}

output "file_system_arn" {
  description = "ARN of the EFS file system."
  value       = aws_efs_file_system.this.arn
}

output "file_system_dns_name" {
  description = "DNS name of the EFS file system."
  value       = aws_efs_file_system.this.dns_name
}

output "creation_token" {
  description = "Creation token used for the EFS file system."
  value       = aws_efs_file_system.this.creation_token
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id          = data.aws_caller_identity.current.account_id
  region              = data.aws_region.current.name
  partition           = data.aws_partition.current.partition
  nlp_bucket_name     = "nlp-pipeline-bucket"
  results_table_name  = "NLPResults"
  state_machine_name  = "YourStateMachineName"
  state_bucket_name   = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"
  nlp_bucket_arn      = "arn:${data.aws_partition.current.partition}:s3:::nlp-pipeline-bucket"
  nlp_bucket_objects  = "arn:${data.aws_partition.current.partition}:s3:::nlp-pipeline-bucket/*"
}

# -----------------------------------------------------------------------------
# Terraform remote state storage
# -----------------------------------------------------------------------------

resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed KMS key for Terraform state bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state-${local.account_id}"
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

# -----------------------------------------------------------------------------
# Shared S3 object access policy document
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "nlp_bucket_object_access" {
  statement {
    sid    = "NlpBucketObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [local.nlp_bucket_objects]
  }
}

# -----------------------------------------------------------------------------
# Glue service role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "glue_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "glue_service_role" {
  name               = "glue-service-role"
  assume_role_policy = data.aws_iam_policy_document.glue_assume_role.json
}

resource "aws_iam_role_policy_attachment" "glue_service_managed" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_s3_access" {
  name   = "glue-nlp-bucket-access"
  role   = aws_iam_role.glue_service_role.id
  policy = data.aws_iam_policy_document.nlp_bucket_object_access.json
}

# -----------------------------------------------------------------------------
# Comprehend service role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "comprehend_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "comprehend_service_role" {
  name               = "comprehend-service-role"
  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role.json
}

resource "aws_iam_role_policy" "comprehend_s3_access" {
  name   = "comprehend-nlp-bucket-access"
  role   = aws_iam_role.comprehend_service_role.id
  policy = data.aws_iam_policy_document.nlp_bucket_object_access.json
}

# -----------------------------------------------------------------------------
# Lambda execution role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name               = "lambda-execution-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_inline" {
  statement {
    sid    = "NlpBucketObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [local.nlp_bucket_objects]
  }

  statement {
    sid    = "NlpResultsTableWrite"
    effect = "Allow"
    actions = [
      "dynamodb:PutItem",
      "dynamodb:UpdateItem",
      "dynamodb:BatchWriteItem",
    ]
    resources = [
      "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/${local.results_table_name}",
    ]
  }

  statement {
    sid     = "StartStateMachineExecution"
    effect  = "Allow"
    actions = ["states:StartExecution"]
    resources = [
      "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:${local.state_machine_name}",
    ]
  }
}

resource "aws_iam_role_policy" "lambda_inline" {
  name   = "lambda-nlp-pipeline-access"
  role   = aws_iam_role.lambda_execution_role.id
  policy = data.aws_iam_policy_document.lambda_inline.json
}

# -----------------------------------------------------------------------------
# Step Functions service role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "step_functions_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "step_functions_service_role" {
  name               = "step-functions-service-role"
  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role.json
}

data "aws_iam_policy_document" "step_functions_inline" {
  statement {
    sid     = "InvokeLambdaFunctions"
    effect  = "Allow"
    actions = ["lambda:InvokeFunction"]
    resources = [
      "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*",
    ]
  }

  statement {
    sid     = "StartGlueJobRuns"
    effect  = "Allow"
    actions = ["glue:StartJobRun"]
    resources = [
      "arn:${local.partition}:glue:${local.region}:${local.account_id}:job/*",
    ]
  }
}

resource "aws_iam_role_policy" "step_functions_inline" {
  name   = "step-functions-nlp-pipeline-access"
  role   = aws_iam_role.step_functions_service_role.id
  policy = data.aws_iam_policy_document.step_functions_inline.json
}

