# Outputs
# -----------------------------------------------------------------------------

output "terraform_state_bucket_name" {
  value = aws_s3_bucket.terraform_state.bucket
}

output "terraform_state_kms_key_arn" {
  value = aws_kms_key.terraform_state.arn
}

output "terraform_locks_table_name" {
  value = aws_dynamodb_table.terraform_locks.name
}

output "glue_service_role_arn" {
  value = aws_iam_role.glue_service_role.arn
}

output "comprehend_service_role_arn" {
  value = aws_iam_role.comprehend_service_role.arn
}

output "lambda_execution_role_arn" {
  value = aws_iam_role.lambda_execution_role.arn
}

output "step_functions_service_role_arn" {
  value = aws_iam_role.step_functions_service_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.9.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.1.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "zenml_version" {
  description = "ZenML version for the generated stack file"
  type        = string
  default     = "0.12.0"
}

variable "stack_file_path" {
  description = "Local path where the ZenML stack YAML file will be written"
  type        = string
  default     = "./aws_minimal_stack.yaml"
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  prefix = "demo"

  tags = {
    managedBy   = "terraform"
    application = local.prefix
  }

  artifact_bucket_name = "${local.prefix}-artifact-store-${data.aws_caller_identity.current.account_id}"
  ecr_registry_uri     = "${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.name}.amazonaws.com"
}

# KMS key for artifact store encryption
resource "aws_kms_key" "artifact_store" {
  description             = "KMS key for ZenML artifact store bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "artifact_store" {
  name          = "alias/${local.prefix}-artifact-store"
  target_key_id = aws_kms_key.artifact_store.key_id
}

# S3 artifact store
resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.artifact_bucket_name
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id
  acl    = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.artifact_store,
    aws_s3_bucket_public_access_block.artifact_store,
  ]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifact_store.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ECR container registry
resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.tags
}

# ZenML stack definition
resource "local_file" "zenml_stack" {
  filename = var.stack_file_path

  content = yamlencode({
    zenml_version = var.zenml_version
    stack_name    = "aws_minimal_stack_${local.prefix}"
    components = {
      artifact_store = {
        flavor = "s3"
        name   = "s3_artifact_store_${local.prefix}"
        path   = "s3://${aws_s3_bucket.artifact_store.bucket}"
      }
      container_registry = {
        flavor = "aws"
        name   = "aws_container_registry_${local.prefix}"
        uri    = local.ecr_registry_uri
      }
      orchestrator = {
        flavor = "local"
        name   = "default"
      }
      secrets_manager = {
        flavor      = "aws"
        name        = "aws_secrets_manager_${local.prefix}"
        region_name = data.aws_region.current.name
      }
    }
  })

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.artifact_store,
    aws_s3_bucket_acl.artifact_store,
  ]
}

output "artifact_store_bucket" {
  description = "Name of the S3 artifact store bucket"
  value       = aws_s3_bucket.artifact_store.bucket
}

output "artifact_store_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt the artifact store"
  value       = aws_kms_key.artifact_store.arn
}

output "ecr_registry_uri" {
  description = "URI of the account's ECR registry"
  value       = local.ecr_registry_uri
}

output "ecr_repository_url" {
  description = "URL of the zenml-kubernetes ECR repository"
  value       = aws_ecr_repository.zenml_kubernetes.repository_url
}

output "zenml_stack_file" {
  description = "Path to the generated ZenML stack YAML file"
  value       = local_file.zenml_stack.filename
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix used when naming resources."
  type        = string
  default     = "nim"
}

variable "registry_username" {
  description = "Username for the container registry credential."
  type        = string
  default     = "AWS"
}

variable "registry_password" {
  description = "Password for the container registry credential."
  type        = string
  default     = ""
  sensitive   = true
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "ECSTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name_prefix        = "${var.name_prefix}-ecs_task_execution-"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_secretsmanager_secret" "repo_secret" {
  name_prefix = "${var.name_prefix}-reposecret-"
}

resource "aws_secretsmanager_secret_version" "repo_secret" {
  secret_id = aws_secretsmanager_secret.repo_secret.id
  secret_string = jsonencode({
    username = var.registry_username
    password = var.registry_password
  })
}

data "aws_iam_policy_document" "ecs_task_access_secrets" {
  statement {
    sid       = "ReadRepoSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.repo_secret.arn]
  }
}

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.ecs_task_execution.id
  policy = data.aws_iam_policy_document.ecs_task_access_secrets.json
}

output "ecs_task_execution_role_arn" {
  description = "ARN of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution.arn
}

output "ecs_task_execution_role_name" {
  description = "Name of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution.name
}

output "repo_secret_arn" {
  description = "ARN of the container registry credential secret."
  value       = aws_secretsmanager_secret.repo_secret.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region used by the provider. AWS Organizations is a global service, but the provider requires a region."
  type        = string
  default     = "us-east-1"
}

variable "aws_service_access_principals" {
  description = "List of AWS service principal names to enable integration with the organization (e.g. cloudtrail.amazonaws.com)."
  type        = list(string)
  default     = []
}

variable "organizational_units" {
  description = "List of slash-delimited organizational unit paths relative to the organization root (e.g. \"Workloads/Prod/App\"). Intermediate OUs are created automatically. Maximum depth is five levels."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for p in var.organizational_units :
      length(trim(p, "/")) > 0 &&
      length(split("/", trim(p, "/"))) <= 5 &&
      alltrue([for s in split("/", trim(p, "/")) : length(trimspace(s)) > 0])
    ])
    error_message = "Each organizational unit path must be non-empty, contain no empty segments, and be at most five levels deep."
  }
}

locals {
  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]

  normalized_ou_paths = [
    for p in var.organizational_units : join("/", [for s in split("/", trim(p, "/")) : trimspace(s)])
  ]

  # Expand every path into all of its ancestor paths so intermediate OUs are created.
  all_ou_paths = distinct(flatten([
    for p in local.normalized_ou_paths : [
      for i in range(length(split("/", p))) : join("/", slice(split("/", p), 0, i + 1))
    ]
  ]))

  ou_level_1 = { for p in local.all_ou_paths : p => p if length(split("/", p)) == 1 }
  ou_level_2 = { for p in local.all_ou_paths : p => p if length(split("/", p)) == 2 }
  ou_level_3 = { for p in local.all_ou_paths : p => p if length(split("/", p)) == 3 }
  ou_level_4 = { for p in local.all_ou_paths : p => p if length(split("/", p)) == 4 }
  ou_level_5 = { for p in local.all_ou_paths : p => p if length(split("/", p)) == 5 }
}

resource "aws_organizations_organization" "this" {
  feature_set                   = "ALL"
  aws_service_access_principals = var.aws_service_access_principals
  enabled_policy_types          = local.enabled_policy_types
}

resource "aws_organizations_organizational_unit" "level_1" {
  for_each = local.ou_level_1

  name      = element(split("/", each.key), 0)
  parent_id = aws_organizations_organization.this.roots[0].id
}

resource "aws_organizations_organizational_unit" "level_2" {
  for_each = local.ou_level_2

  name      = element(split("/", each.key), 1)
  parent_id = aws_organizations_organizational_unit.level_1[join("/", slice(split("/", each.key), 0, 1))].id
}

resource "aws_organizations_organizational_unit" "level_3" {
  for_each = local.ou_level_3

  name      = element(split("/", each.key), 2)
  parent_id = aws_organizations_organizational_unit.level_2[join("/", slice(split("/", each.key), 0, 2))].id
}

resource "aws_organizations_organizational_unit" "level_4" {
  for_each = local.ou_level_4

  name      = element(split("/", each.key), 3)
  parent_id = aws_organizations_organizational_unit.level_3[join("/", slice(split("/", each.key), 0, 3))].id
}

resource "aws_organizations_organizational_unit" "level_5" {
  for_each = local.ou_level_5

  name      = element(split("/", each.key), 4)
  parent_id = aws_organizations_organizational_unit.level_4[join("/", slice(split("/", each.key), 0, 4))].id
}

output "organization_id" {
  description = "ID of the AWS Organization."
  value       = aws_organizations_organization.this.id
}

output "organization_arn" {
  description = "ARN of the AWS Organization."
  value       = aws_organizations_organization.this.arn
}

output "root_id" {
  description = "ID of the organization root."
  value       = aws_organizations_organization.this.roots[0].id
}

output "organizational_unit_ids" {
  description = "Map of organizational unit path to OU ID."
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level_1 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_2 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_3 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_4 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_5 : k => v.id },
  )
}

output "organizational_unit_arns" {
  description = "Map of organizational unit path to OU ARN."
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level_1 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_2 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_3 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_4 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_5 : k => v.arn },
  )
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "swe-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name          = var.vpc_name
    ResourceGroup = "default"
  }
}

resource "aws_default_network_acl" "this" {
  default_network_acl_id = aws_vpc.this.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = aws_vpc.this.cidr_block
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 200
    action     = "deny"
    protocol   = "tcp"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    rule_no    = 210
    action     = "deny"
    protocol   = "tcp"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = aws_vpc.this.cidr_block
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name          = "${var.vpc_name}-default_acl"
    ResourceGroup = "default"
  }

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name          = "${var.vpc_name}-default_sg"
    ResourceGroup = "default"
  }
}

resource "aws_vpc_security_group_ingress_rule" "icmp_echo" {
  security_group_id = aws_default_security_group.this.id
  description       = "Allow ICMP echo request (ping) from anywhere"
  ip_protocol       = "icmp"
  from_port         = 8
  to_port           = 0
  cidr_ipv4         = "0.0.0.0/0"

  tags = {
    Name = "${var.vpc_name}-allow-icmp-echo"
  }
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_default_security_group.this.id
  description       = "Allow HTTP from anywhere"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = "0.0.0.0/0"

  tags = {
    Name = "${var.vpc_name}-allow-http"
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "default_network_acl_id" {
  description = "ID of the VPC default network ACL"
  value       = aws_default_network_acl.this.id
}

output "default_security_group_id" {
  description = "ID of the VPC default security group"
  value       = aws_default_security_group.this.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "eu-west-3"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_a = data.aws_availability_zones.available.names[0]
  az_b = data.aws_availability_zones.available.names[1]

  environments = {
    dev = {
      vpc_name = "vpc_dev"
      prefix   = "10.16"
      igw_name = "gatway_dev"
    }
    rec = {
      vpc_name = "vpc_rec"
      prefix   = "10.32"
      igw_name = "gatway_rec"
    }
  }

  subnet_layout = {
    public_a   = { third_octet = 12, az = local.az_a }
    public_b   = { third_octet = 11, az = local.az_b }
    internal_a = { third_octet = 1, az = local.az_a }
    internal_b = { third_octet = 2, az = local.az_b }
    external_a = { third_octet = 5, az = local.az_a }
    external_b = { third_octet = 6, az = local.az_b }
  }

  subnets = merge([
    for env_key, env in local.environments : {
      for sn_key, sn in local.subnet_layout :
      "${env_key}_${sn_key}" => {
        env        = env_key
        name       = "subnet_${env_key}_${sn_key}"
        cidr_block = "${env.prefix}.${sn.third_octet}.0/24"
        az         = sn.az
      }
    }
  ]...)
}

resource "aws_vpc" "this" {
  for_each = local.environments

  cidr_block                       = "${each.value.prefix}.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name        = each.value.vpc_name
    Environment = each.key
  }
}

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id            = aws_vpc.this[each.value.env].id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.az

  tags = {
    Name        = each.value.name
    Environment = each.value.env
  }
}

resource "aws_internet_gateway" "this" {
  for_each = local.environments

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name        = each.value.igw_name
    Environment = each.key
  }
}

resource "aws_route" "default_ipv4" {
  for_each = local.environments

  route_table_id         = aws_vpc.this[each.key].main_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[each.key].id
}

resource "aws_route" "default_ipv6" {
  for_each = local.environments

  route_table_id              = aws_vpc.this[each.key].main_route_table_id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[each.key].id
}

output "vpc_dev_id" {
  description = "ID of the development VPC"
  value       = aws_vpc.this["dev"].id
}

output "vpc_rec_id" {
  description = "ID of the recette (staging) VPC"
  value       = aws_vpc.this["rec"].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type        = string
  description = "AWS region in which to enable GuardDuty"
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "ID element. Usually an abbreviation of your organization name"
  default     = "eg"
}

variable "stage" {
  type        = string
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'dev'"
  default     = "test"
}

variable "name" {
  type        = string
  description = "ID element. Usually the component or solution name"
  default     = "guardduty"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags"
  default     = {}
}

variable "enable_cloudwatch" {
  type        = bool
  description = "Flag to enable EventBridge (CloudWatch Events) rule for GuardDuty findings"
  default     = false
}

variable "create_sns_topic" {
  type        = bool
  description = "Flag to create an SNS topic for GuardDuty finding notifications"
  default     = false
}

variable "findings_notification_arn" {
  type        = string
  description = "ARN of an existing SNS topic to send findings to (used when create_sns_topic is false)"
  default     = null
}

variable "cloudwatch_event_rule_pattern_detail_type" {
  type        = string
  description = "Detail type for the EventBridge rule pattern"
  default     = "GuardDuty Finding"
}

variable "s3_protection_enabled" {
  type        = bool
  description = "Flag to enable S3 protection"
  default     = false
}

variable "finding_publishing_frequency" {
  type        = string
  description = "Finding publishing frequency. Null leaves the service default (SIX_HOURS)"
  default     = null
}

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace = var.namespace
  stage     = var.stage
  name      = var.name
  tags      = var.tags
}

module "findings_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  attributes = ["guardduty", "findings"]
  context    = module.this.context
}

locals {
  enable_notifications = var.enable_cloudwatch
  create_sns_topic     = local.enable_notifications && var.create_sns_topic
  findings_topic_arn   = local.create_sns_topic ? aws_sns_topic.findings[0].arn : var.findings_notification_arn
}

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  tags = module.this.tags
}

resource "aws_guardduty_detector_feature" "s3_protection" {
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = var.s3_protection_enabled ? "ENABLED" : "DISABLED"
}

resource "aws_sns_topic" "findings" {
  count = local.create_sns_topic ? 1 : 0

  name = module.findings_label.id
  tags = module.findings_label.tags
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = local.create_sns_topic ? 1 : 0

  statement {
    sid     = "AllowEventBridgePublish"
    effect  = "Allow"
    actions = ["sns:Publish"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    resources = [aws_sns_topic.findings[0].arn]
  }
}

resource "aws_sns_topic_policy" "findings" {
  count = local.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.findings[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

resource "aws_cloudwatch_event_rule" "findings" {
  count = local.enable_notifications ? 1 : 0

  name        = module.findings_label.id
  description = "GuardDuty findings"
  tags        = module.findings_label.tags

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = [var.cloudwatch_event_rule_pattern_detail_type]
  })
}

resource "aws_cloudwatch_event_target" "findings" {
  count = local.enable_notifications && local.findings_topic_arn != null ? 1 : 0

  rule      = aws_cloudwatch_event_rule.findings[0].name
  target_id = "guardduty-findings-sns"
  arn       = local.findings_topic_arn
}

output "guardduty_detector_id" {
  description = "ID of the GuardDuty detector"
  value       = aws_guardduty_detector.this.id
}

output "guardduty_detector_arn" {
  description = "ARN of the GuardDuty detector"
  value       = aws_guardduty_detector.this.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic for findings, if created"
  value       = local.create_sns_topic ? aws_sns_topic.findings[0].arn : null
}

output "cloudwatch_event_rule_arn" {
  description = "ARN of the EventBridge rule for findings, if created"
  value       = local.enable_notifications ? aws_cloudwatch_event_rule.findings[0].arn : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the backup resources into."
  type        = string
  default     = "us-east-1"
}

variable "backup_schedule" {
  description = "Cron expression for the backup rule schedule (UTC)."
  type        = string
  default     = "cron(0 12 * * ? *)"
}

variable "cold_storage_after" {
  description = "Number of days after creation that a recovery point is moved to cold storage. Null disables the transition."
  type        = number
  default     = null
}

variable "delete_after" {
  description = "Number of days after creation that a recovery point is deleted. Null disables expiration."
  type        = number
  default     = null
}

variable "copy_destination_vault_arn" {
  description = "ARN of a destination backup vault for a copy action. Null disables the copy action."
  type        = string
  default     = null
}

variable "copy_cold_storage_after" {
  description = "Number of days after creation that a copied recovery point is moved to cold storage. Null disables the transition."
  type        = number
  default     = null
}

variable "copy_delete_after" {
  description = "Number of days after creation that a copied recovery point is deleted. Null disables expiration."
  type        = number
  default     = null
}

variable "selection_tag_key" {
  description = "Tag key used to select resources for backup."
  type        = string
  default     = "backup"
}

variable "selection_tag_value" {
  description = "Tag value used to select resources for backup."
  type        = string
  default     = "true"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"

  has_lifecycle      = var.cold_storage_after != null || var.delete_after != null
  has_copy_lifecycle = var.copy_cold_storage_after != null || var.copy_delete_after != null
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAWSBackupUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "backup" {
  description             = "${local.prefix} AWS Backup vault encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms.json

  tags = {
    Name = "${local.prefix}-backup-key"
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.prefix}-backup-key"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "this" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name = "${local.prefix}-backup-vault"
  }
}

resource "aws_backup_plan" "this" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_schedule

    recovery_point_tags = {
      Name = "${local.prefix}-recovery-point"
    }

    dynamic "lifecycle" {
      for_each = local.has_lifecycle ? [1] : []
      content {
        cold_storage_after = var.cold_storage_after
        delete_after       = var.delete_after
      }
    }

    dynamic "copy_action" {
      for_each = var.copy_destination_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.copy_destination_vault_arn

        dynamic "lifecycle" {
          for_each = local.has_copy_lifecycle ? [1] : []
          content {
            cold_storage_after = var.copy_cold_storage_after
            delete_after       = var.copy_delete_after
          }
        }
      }
    }
  }

  tags = {
    Name = "${local.prefix}-backup-plan"
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_selection" "this" {
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.this.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

output "name_prefix" {
  description = "Generated resource name prefix."
  value       = local.prefix
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used by the backup vault."
  value       = aws_kms_key.backup.arn
}

output "backup_vault_name" {
  description = "Name of the backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_vault_arn" {
  description = "ARN of the backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_plan_id" {
  description = "ID of the backup plan."
  value       = aws_backup_plan.this.id
}

output "backup_plan_arn" {
  description = "ARN of the backup plan."
  value       = aws_backup_plan.this.arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_selection_id" {
  description = "ID of the backup selection."
  value       = aws_backup_selection.this.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy Cognito resources into"
  type        = string
  default     = "us-east-1"
}

variable "application_name" {
  description = "Application name used for naming Cognito resources"
  type        = string
  default     = "coop-tweets"
}

resource "aws_cognito_user_pool" "this" {
  name = var.application_name

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
    require_lowercase = false
  }
}

resource "aws_cognito_user_pool_domain" "this" {
  domain       = "${var.application_name}-domain"
  user_pool_id = aws_cognito_user_pool.this.id
}

resource "aws_cognito_identity_pool" "this" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false
}

data "aws_iam_policy_document" "auth_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "unauth_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

data "aws_iam_policy_document" "cognito_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "auth" {
  name               = "${var.application_name}_cognito_auth_role"
  assume_role_policy = data.aws_iam_policy_document.auth_assume_role.json
}

resource "aws_iam_role" "unauth" {
  name               = "${var.application_name}_cognito_unauth_role"
  assume_role_policy = data.aws_iam_policy_document.unauth_assume_role.json
}

resource "aws_iam_policy" "auth" {
  name        = "cognito_kibana_auth_${var.application_name}"
  description = "Permissions for authenticated Cognito identities of ${var.application_name}"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_policy" "unauth" {
  name        = "cognito_kibana_unauth_${var.application_name}"
  description = "Permissions for unauthenticated Cognito identities of ${var.application_name}"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_role_policy_attachment" "auth" {
  role       = aws_iam_role.auth.name
  policy_arn = aws_iam_policy.auth.arn
}

resource "aws_iam_role_policy_attachment" "unauth" {
  role       = aws_iam_role.unauth.name
  policy_arn = aws_iam_policy.unauth.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "this" {
  identity_pool_id = aws_cognito_identity_pool.this.id

  roles = {
    authenticated   = aws_iam_role.auth.arn
    unauthenticated = aws_iam_role.unauth.arn
  }
}

output "user_pool_id" {
  value = aws_cognito_user_pool.this.id
}

output "user_pool_domain" {
  value = aws_cognito_user_pool_domain.this.domain
}

output "identity_pool_id" {
  value = aws_cognito_identity_pool.this.id
}

output "auth_role_arn" {
  value = aws_iam_role.auth.arn
}

output "unauth_role_arn" {
  value = aws_iam_role.unauth.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "enable_s3_export" {
  description = "Whether to export GuardDuty findings to an S3 bucket."
  type        = bool
  default     = false
}

variable "findings_bucket_name" {
  description = "Name of the S3 bucket to create for GuardDuty findings export. Required when enable_s3_export is true."
  type        = string
  default     = null

  validation {
    condition     = var.findings_bucket_name == null || can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.findings_bucket_name))
    error_message = "findings_bucket_name must be a valid S3 bucket name."
  }
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
  partition   = data.aws_partition.current.partition
  bucket_name = coalesce(var.findings_bucket_name, "guardduty-findings-${local.account_id}-${local.region}")
}

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = var.tags
}

data "aws_iam_policy_document" "guardduty_kms" {
  statement {
    sid     = "EnableAccountAdministration"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid     = "AllowGuardDutyToGenerateDataKeys"
    effect  = "Allow"
    actions = ["kms:GenerateDataKey"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:guardduty:${local.region}:${local.account_id}:detector/*"]
    }
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "Customer-managed KMS key for encrypting GuardDuty findings exports"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.guardduty_kms.json

  tags = var.tags
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  name        = "guardduty-finding-events"
  description = "Matches Amazon GuardDuty finding events"

  event_pattern = jsonencode({
    source        = ["aws.guardduty"]
    "detail-type" = ["GuardDuty Finding"]
  })

  tags = var.tags
}

resource "aws_s3_bucket" "findings" {
  count = var.enable_s3_export ? 1 : 0

  bucket = local.bucket_name

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count = var.enable_s3_export ? 1 : 0

  bucket                  = aws_s3_bucket.findings[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count = var.enable_s3_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "findings" {
  count = var.enable_s3_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "findings_bucket" {
  count = var.enable_s3_export ? 1 : 0

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.this.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.this.arn]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }

  statement {
    sid       = "DenyIncorrectEncryptionHeader"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.guardduty.arn]
    }
  }

  statement {
    sid     = "DenyNonHTTPSAccess"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.findings[0].arn,
      "${aws_s3_bucket.findings[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "findings" {
  count = var.enable_s3_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id
  policy = data.aws_iam_policy_document.findings_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.findings]
}

resource "aws_guardduty_publishing_destination" "s3" {
  count = var.enable_s3_export ? 1 : 0

  detector_id      = aws_guardduty_detector.this.id
  destination_type = "S3"
  destination_arn  = aws_s3_bucket.findings[0].arn
  kms_key_arn      = aws_kms_key.guardduty.arn

  depends_on = [
    aws_s3_bucket_policy.findings,
    aws_kms_alias.guardduty,
  ]
}

output "guardduty_detector_id" {
  description = "ID of the GuardDuty detector."
  value       = aws_guardduty_detector.this.id
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for GuardDuty findings exports."
  value       = aws_kms_key.guardduty.arn
}

output "kms_alias_name" {
  description = "Alias of the GuardDuty KMS key."
  value       = aws_kms_alias.guardduty.name
}

output "eventbridge_rule_arn" {
  description = "ARN of the EventBridge rule matching GuardDuty findings."
  value       = aws_cloudwatch_event_rule.guardduty_findings.arn
}

output "findings_bucket_name" {
  description = "Name of the S3 bucket receiving GuardDuty findings, if export is enabled."
  value       = var.enable_s3_export ? aws_s3_bucket.findings[0].id : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the S3 bucket."
  type        = string
  default     = "us-east-1"
}

variable "bucket_prefix" {
  description = "Prefix used to auto-generate the S3 bucket name."
  type        = string
  default     = "private-bucket-"
}

resource "aws_s3_bucket" "this" {
  bucket_prefix = var.bucket_prefix
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

output "bucket_id" {
  description = "The name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "The regional domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "billing_full_access_users" {
  description = "List of IAM user names to add to the billing-full-access group."
  type        = list(string)
  default     = []
}

variable "billing_view_access_users" {
  description = "List of IAM user names to add to the billing-view-access group."
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

data "aws_iam_policy_document" "assume_role_with_mfa" {
  statement {
    sid     = "AllowAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Full access role

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "BillingFullAccess"
    effect = "Allow"
    actions = [
      "aws-portal:*Billing",
      "aws-portal:*Usage",
      "aws-portal:*PaymentMethods",
      "budgets:ViewBudget",
      "budgets:ModifyBudget",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Allows full access to billing, usage, payment methods, and budgets."
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  path               = "/"
  description        = "Role granting full access to the AWS billing console. Requires MFA."
  assume_role_policy = data.aws_iam_policy_document.assume_role_with_mfa.json
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

# View access role

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "BillingViewAccess"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "aws-portal:ViewPaymentMethods",
      "budgets:ViewBudget",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "Allows viewing billing, usage, account, payment methods, and budgets."
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  path               = "/"
  description        = "Role granting view-only access to the AWS billing console. Requires MFA."
  assume_role_policy = data.aws_iam_policy_document.assume_role_with_mfa.json
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# Groups

resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    sid       = "AllowAssumeBillingFullAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    sid       = "AllowAssumeBillingViewAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

resource "aws_iam_group_policy" "billing_full_access_assume_role" {
  name   = "billing-full-access-assume-role"
  group  = aws_iam_group.billing_full_access.name
  policy = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

resource "aws_iam_group_policy" "billing_view_access_assume_role" {
  name   = "billing-view-access-assume-role"
  group  = aws_iam_group.billing_view_access.name
  policy = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

resource "aws_iam_group_membership" "billing_full_access" {
  count = length(var.billing_full_access_users) > 0 ? 1 : 0

  name  = "billing-full-access-membership"
  group = aws_iam_group.billing_full_access.name
  users = var.billing_full_access_users
}

resource "aws_iam_group_membership" "billing_view_access" {
  count = length(var.billing_view_access_users) > 0 ? 1 : 0

  name  = "billing-view-access-membership"
  group = aws_iam_group.billing_view_access.name
  users = var.billing_view_access_users
}

output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access IAM role."
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access IAM role."
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access IAM group."
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access IAM group."
  value       = aws_iam_group.billing_view_access.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {}

variable "base_name" {
  description = "Base name used for all Cognito resources."
  type        = string
  default     = "cognito"
}

# Helper module that exposes the current AWS partition, region, and account.
# Expected outputs: partition, region, account_id.
module "aws_context" {
  source = "./modules/aws_context"
}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = false
  special = false
}

locals {
  name           = "${var.base_name}-${random_pet.suffix.id}"
  user_pool_name = replace(local.name, "-", "_")

  partition  = module.aws_context.partition
  region     = module.aws_context.region
  account_id = module.aws_context.account_id

  profile_string_attributes = [
    "profile_user_id",
    "profile_email",
    "profile_first_name",
    "profile_last_name",
    "profile_gender",
    "profile_age",
    "profile_persona",
  ]

  identity_pool_arn = "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.this.id}"
  sync_pool_arn     = "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.this.id}"
}

# -----------------------------------------------------------------------------
# SMS role for the user pool
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "cognito_sms_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cognito-idp.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.sms_external_id.result]
    }
  }
}

resource "aws_iam_role" "cognito_sms" {
  name               = "${local.name}-sms"
  assume_role_policy = data.aws_iam_policy_document.cognito_sms_assume.json
}

data "aws_iam_policy_document" "cognito_sms" {
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "cognito_sms" {
  name   = "${local.name}-sms-publish"
  role   = aws_iam_role.cognito_sms.id
  policy = data.aws_iam_policy_document.cognito_sms.json
}

# -----------------------------------------------------------------------------
# User pool and client
# -----------------------------------------------------------------------------

resource "aws_cognito_user_pool" "this" {
  name                     = local.user_pool_name
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]

  schema {
    name                     = "email"
    attribute_data_type      = "String"
    required                 = true
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  schema {
    name                     = "phone_number"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  dynamic "schema" {
    for_each = local.profile_string_attributes

    content {
      name                     = schema.value
      attribute_data_type      = "String"
      required                 = false
      mutable                  = true
      developer_only_attribute = false

      string_attribute_constraints {
        min_length = 0
        max_length = 2048
      }
    }
  }

  sms_configuration {
    external_id    = random_string.sms_external_id.result
    sns_caller_arn = aws_iam_role.cognito_sms.arn
  }

  depends_on = [aws_iam_role_policy.cognito_sms]
}

resource "aws_cognito_user_pool_client" "this" {
  name            = "${local.name}-client"
  user_pool_id    = aws_cognito_user_pool.this.id
  generate_secret = false
}

# -----------------------------------------------------------------------------
# Identity pool
# -----------------------------------------------------------------------------

resource "aws_cognito_identity_pool" "this" {
  identity_pool_name               = local.user_pool_name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.this.id
    provider_name           = aws_cognito_user_pool.this.endpoint
    server_side_token_check = false
  }
}

# Authenticated (signed users) role

data "aws_iam_policy_document" "authenticated_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "${local.name}-signed-users"
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume.json
}

data "aws_iam_policy_document" "authenticated" {
  statement {
    effect    = "Allow"
    actions   = ["cognito-identity:*"]
    resources = [local.identity_pool_arn]
  }

  statement {
    effect    = "Allow"
    actions   = ["cognito-sync:*"]
    resources = [local.sync_pool_arn, "${local.sync_pool_arn}/*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "${local.name}-signed-users"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated.json
}

# Unauthenticated (anonymous users) role

data "aws_iam_policy_document" "unauthenticated_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "unauthenticated" {
  name               = "${local.name}-anonymous-users"
  assume_role_policy = data.aws_iam_policy_document.unauthenticated_assume.json
}

data "aws_iam_policy_document" "unauthenticated" {
  statement {
    effect    = "Allow"
    actions   = ["cognito-identity:*"]
    resources = [local.identity_pool_arn]
  }
}

resource "aws_iam_role_policy" "unauthenticated" {
  name   = "${local.name}-anonymous-users"
  role   = aws_iam_role.unauthenticated.id
  policy = data.aws_iam_policy_document.unauthenticated.json
}

resource "aws_cognito_identity_pool_roles_attachment" "this" {
  identity_pool_id = aws_cognito_identity_pool.this.id

  roles = {
    authenticated   = aws_iam_role.authenticated.arn
    unauthenticated = aws_iam_role.unauthenticated.arn
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "user_pool_id" {
  value = aws_cognito_user_pool.this.id
}

output "user_pool_client_id" {
  value = aws_cognito_user_pool_client.this.id
}

output "identity_pool_id" {
  value = aws_cognito_identity_pool.this.id
}

output "authenticated_role_arn" {
  value = aws_iam_role.authenticated.arn
}

output "unauthenticated_role_arn" {
  value = aws_iam_role.unauthenticated.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name     = "${terraform.workspace}-batch"
  vpc_cidr = "192.168.0.0/16"
  az       = data.aws_availability_zones.available.names[1]

  tags = {
    Name      = local.name
    Workspace = terraform.workspace
  }
}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.tags
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${local.name}-private" })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${local.name}-public" })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = local.tags
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.name}-nat" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = local.tags

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(local.tags, { Name = "${local.name}-public" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(local.tags, { Name = "${local.name}-private" })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "batch" {
  name        = local.name
  description = "Security group for ${local.name} compute environment"
  vpc_id      = aws_vpc.this.id

  egress {
    description = "HTTPS to VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = local.tags
}

# ------------------------------------------------------------------------------
# S3 results bucket and KMS key
# ------------------------------------------------------------------------------

resource "aws_kms_key" "results" {
  description             = "KMS key for ${local.name} results bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.tags
}

resource "aws_kms_alias" "results" {
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.results.key_id
}

resource "aws_s3_bucket" "results" {
  bucket = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}"

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.results.arn
    }
    bucket_key_enabled = true
  }
}

# ------------------------------------------------------------------------------
# IAM - ECS instance role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_instance" {
  name               = "${local.name}-ecs-instance-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "ecs_instance" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

data "aws_iam_policy_document" "ecs_s3" {
  statement {
    sid = "S3ReadList"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListAllMyBuckets",
      "s3:GetBucketLocation",
    ]
    resources = ["*"]
  }

  statement {
    sid = "ResultsBucketReadWrite"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.results.arn,
      "${aws_s3_bucket.results.arn}/*",
    ]
  }

  statement {
    sid = "ResultsKms"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.results.arn]
  }
}

resource "aws_iam_role_policy" "ecs_s3_policy" {
  name   = "ecs_s3_policy"
  role   = aws_iam_role.ecs_instance.id
  policy = data.aws_iam_policy_document.ecs_s3.json
}

resource "aws_iam_instance_profile" "ecs_instance" {
  name = "${local.name}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = local.tags
}

# ------------------------------------------------------------------------------
# IAM - Batch service role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "batch_assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["batch.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "batch_service" {
  name               = "${local.name}-service-role"
  assume_role_policy = data.aws_iam_policy_document.batch_assume.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBatchServiceRole"
}

# ------------------------------------------------------------------------------
# AWS Batch
# ------------------------------------------------------------------------------

resource "aws_batch_compute_environment" "this" {
  compute_environment_name = local.name
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_type       = ["optimal"]
    instance_role       = aws_iam_instance_profile.ecs_instance.arn
    min_vcpus           = 0
    max_vcpus           = 4
    subnets             = [aws_subnet.private.id]
    security_group_ids  = [aws_security_group.batch.id]

    ec2_configuration {
      image_type = "ECS_AL2023"
    }

    tags = local.tags
  }

  tags = local.tags

  depends_on = [
    aws_iam_role_policy_attachment.batch_service,
    aws_iam_role_policy_attachment.ecs_instance,
    aws_route_table_association.private,
  ]
}

resource "aws_batch_job_queue" "this" {
  name     = "${local.name}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    order               = 1
    compute_environment = aws_batch_compute_environment.this.arn
  }

  tags = merge(local.tags, { Name = "${local.name}-queue" })
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "vpc_id" {
  value = aws_vpc.this.id
}

output "compute_environment_arn" {
  value = aws_batch_compute_environment.this.arn
}

output "job_queue_arn" {
  value = aws_batch_job_queue.this.arn
}

output "results_bucket" {
  value = aws_s3_bucket.results.bucket
}

output "results_kms_key_arn" {
  value = aws_kms_key.results.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_kms_alias" "s3" {
  name = "alias/aws/s3"
}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = local.bucket_name
  object_lock_enabled = false

  tags = {
    Name    = local.bucket_name
    Purpose = "endpoint-backup"
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "endpoint_backup_bucket_policy" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid     = "DenyOutdatedTLS"
    effect  = "Deny"
    actions = ["s3:*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceLockOver90Days"
    effect = "Deny"
    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

data "aws_iam_policy_document" "endpoint_backup_access" {
  statement {
    sid    = "BucketLevelAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetBucketObjectLockConfiguration",
    ]
    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid    = "ObjectLevelAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectAttributes",
      "s3:GetObjectVersionAttributes",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "S3ManagedKmsKeyAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [data.aws_kms_alias.s3.target_key_arn]
  }
}

resource "aws_iam_policy" "endpoint_backup_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Read/write access to the ${local.bucket_name} S3 bucket"
  policy      = data.aws_iam_policy_document.endpoint_backup_access.json
}

resource "aws_iam_user_policy_attachment" "endpoint_backup_access" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_access.arn
}

output "bucket_name" {
  value = aws_s3_bucket.endpoint_backup.id
}

output "bucket_arn" {
  value = aws_s3_bucket.endpoint_backup.arn
}

output "iam_user_arn" {
  value = aws_iam_user.endpoint_backup.arn
}

output "iam_policy_arn" {
  value = aws_iam_policy.endpoint_backup_access.arn
}

