terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "app_name" {
  description = "Application name used for naming and tagging"
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Environment name used for naming and tagging"
  type        = string
  default     = "testing"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = false
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_ipv6" {
  description = "Request an Amazon-provided IPv6 CIDR block for the VPC and subnets"
  type        = bool
  default     = false
}

variable "enable_ipv6_egress" {
  description = "Create an egress-only internet gateway and IPv6 default route for private subnets (requires enable_ipv6)"
  type        = bool
  default     = false
}

variable "az_count" {
  description = "Number of availability zones to use"
  type        = number
  default     = 3
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets, one per availability zone"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets, one per availability zone"
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
}

variable "map_public_ip_on_launch" {
  description = "Assign public IPv4 addresses to instances launched in public subnets"
  type        = bool
  default     = true
}

variable "enable_transit_gateway_attachment" {
  description = "Attach the VPC to an existing transit gateway"
  type        = bool
  default     = false
}

variable "transit_gateway_id" {
  description = "ID of the transit gateway to attach to (required when enable_transit_gateway_attachment is true)"
  type        = string
  default     = null
}

variable "transit_gateway_routes" {
  description = "Destination CIDR blocks routed from the private route table to the transit gateway"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_suffix = "${var.app_name}-${var.environment}"
  azs         = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  common_tags = merge(
    {
      App         = var.app_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )

  create_ipv6_egress = var.enable_ipv6 && var.enable_ipv6_egress
  create_tgw         = var.enable_transit_gateway_attachment && var.transit_gateway_id != null
}

resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_cidr
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "vpc-${local.name_suffix}"
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "igw-${local.name_suffix}"
  })
}

resource "aws_subnet" "public" {
  count = var.az_count

  vpc_id                          = aws_vpc.this.id
  cidr_block                      = var.public_subnet_cidrs[count.index]
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = var.map_public_ip_on_launch
  ipv6_cidr_block                 = var.enable_ipv6 ? cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index) : null
  assign_ipv6_address_on_creation = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "subnet-public-${local.name_suffix}-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = var.az_count

  vpc_id                          = aws_vpc.this.id
  cidr_block                      = var.private_subnet_cidrs[count.index]
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  ipv6_cidr_block                 = var.enable_ipv6 ? cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index + var.az_count) : null
  assign_ipv6_address_on_creation = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "subnet-private-${local.name_suffix}-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "rt-public-${local.name_suffix}"
  })
}

resource "aws_route" "public_internet_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route" "public_internet_ipv6" {
  count = var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = var.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "eip-nat-${local.name_suffix}"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "nat-${local.name_suffix}"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "rt-private-${local.name_suffix}"
  })
}

resource "aws_route" "private_nat_ipv4" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this.id
}

resource "aws_route_table_association" "private" {
  count = var.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_egress_only_internet_gateway" "this" {
  count = local.create_ipv6_egress ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "eigw-${local.name_suffix}"
  })
}

resource "aws_route" "private_ipv6_egress" {
  count = local.create_ipv6_egress ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  count = local.create_tgw ? 1 : 0

  transit_gateway_id = var.transit_gateway_id
  vpc_id             = aws_vpc.this.id
  subnet_ids         = aws_subnet.private[*].id
  ipv6_support       = var.enable_ipv6 ? "enable" : "disable"

  tags = merge(local.common_tags, {
    Name = "tgw-attach-${local.name_suffix}"
  })
}

resource "aws_route" "private_tgw" {
  for_each = local.create_tgw ? toset(var.transit_gateway_routes) : toset([])

  route_table_id         = aws_route_table.private.id
  destination_cidr_block = each.value
  transit_gateway_id     = var.transit_gateway_id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

resource "aws_db_subnet_group" "this" {
  name        = "db-subnet-${local.name_suffix}"
  description = "Database subnet group for ${local.name_suffix}"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "db-subnet-${local.name_suffix}"
  })
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.this.id
}

output "vpc_arn" {
  description = "ARN of the VPC"
  value       = aws_vpc.this.arn
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the VPC"
  value       = aws_vpc.this.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block of the VPC (empty when IPv6 is disabled)"
  value       = aws_vpc.this.ipv6_cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets"
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidr_blocks" {
  description = "CIDR blocks of the public subnets"
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidr_blocks" {
  description = "CIDR blocks of the private subnets"
  value       = aws_subnet.private[*].cidr_block
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the shared private route table"
  value       = aws_route_table.private.id
}

output "default_security_group_id" {
  description = "ID of the VPC default security group"
  value       = aws_vpc.this.default_security_group_id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.this.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = aws_nat_gateway.this.id
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway"
  value       = aws_eip.nat.public_ip
}

output "nat_eip_allocation_id" {
  description = "Allocation ID of the NAT gateway Elastic IP"
  value       = aws_eip.nat.id
}

output "db_subnet_group_name" {
  description = "Name of the DB subnet group"
  value       = aws_db_subnet_group.this.name
}

output "db_subnet_group_arn" {
  description = "ARN of the DB subnet group"
  value       = aws_db_subnet_group.this.arn
}

output "egress_only_internet_gateway_id" {
  description = "ID of the egress-only internet gateway (null when disabled)"
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
}

output "transit_gateway_attachment_id" {
  description = "ID of the transit gateway VPC attachment (null when disabled)"
  value       = try(aws_ec2_transit_gateway_vpc_attachment.this[0].id, null)
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.4"
    }
  }
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-west-2"
}

provider "aws" {
  region = var.region
}

locals {
  name = "gitops-bridge"

  repositories = toset([
    "gitops-apps",
    "gitops-platform",
    "gitops-addons",
  ])

  ssh_dir              = pathexpand("~/.ssh")
  ssh_private_key_path = "${local.ssh_dir}/gitops_ssh.pem"
  ssh_config_path      = "${local.ssh_dir}/config"

  ssh_config_marker_begin = "# BEGIN ${local.name} codecommit"
  ssh_config_marker_end   = "# END ${local.name} codecommit"

  ssh_config_block = <<-EOT
    ${local.ssh_config_marker_begin}
    Host git-codecommit.*.amazonaws.com
      User ${aws_iam_user_ssh_key.gitops.ssh_public_key_id}
      IdentityFile ${local.ssh_private_key_path}
      IdentitiesOnly yes
    ${local.ssh_config_marker_end}
  EOT

  tags = {
    Blueprint = local.name
  }
}

################################################################################
# CodeCommit Repositories
################################################################################

resource "aws_codecommit_repository" "this" {
  for_each = local.repositories

  repository_name = each.value
  description     = "Argo CD GitOps bridge repository: ${each.value}"

  tags = local.tags
}

################################################################################
# IAM User with SSH Key
################################################################################

resource "aws_iam_user" "gitops" {
  name = "${local.name}-gitops"
  path = "/"

  tags = local.tags
}

resource "tls_private_key" "gitops" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_iam_user_ssh_key" "gitops" {
  username   = aws_iam_user.gitops.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops.public_key_openssh
}

data "aws_iam_policy_document" "gitops_access" {
  statement {
    sid    = "GitPullPush"
    effect = "Allow"

    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush",
    ]

    resources = [for repo in aws_codecommit_repository.this : repo.arn]
  }
}

resource "aws_iam_policy" "gitops_access" {
  name        = "${local.name}-gitops"
  path        = "/"
  description = "Git pull and push access to the GitOps bridge CodeCommit repositories"
  policy      = data.aws_iam_policy_document.gitops_access.json

  tags = local.tags
}

resource "aws_iam_user_policy_attachment" "gitops_access" {
  user       = aws_iam_user.gitops.name
  policy_arn = aws_iam_policy.gitops_access.arn
}

################################################################################
# Secrets Manager - Private Key
################################################################################

resource "random_string" "secret_suffix" {
  length  = 5
  special = false
  upper   = false
}

resource "aws_secretsmanager_secret" "codecommit_key" {
  name                    = "codecommit-key-${random_string.secret_suffix.result}"
  description             = "SSH private key for the ${aws_iam_user.gitops.name} IAM user to access CodeCommit"
  recovery_window_in_days = 0

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "codecommit_key" {
  secret_id     = aws_secretsmanager_secret.codecommit_key.id
  secret_string = tls_private_key.gitops.private_key_pem
}

################################################################################
# Local SSH Private Key and Config
################################################################################

resource "local_sensitive_file" "ssh_private_key" {
  content              = tls_private_key.gitops.private_key_pem
  filename             = local.ssh_private_key_path
  file_permission      = "0600"
  directory_permission = "0700"
}

# Appends a marker-delimited Host block to ~/.ssh/config without overwriting
# existing entries, and removes only that block on destroy.
resource "terraform_data" "ssh_config" {
  input = {
    config_path  = local.ssh_config_path
    marker_begin = local.ssh_config_marker_begin
    marker_end   = local.ssh_config_marker_end
    block        = local.ssh_config_block
  }

  triggers_replace = [
    aws_iam_user_ssh_key.gitops.ssh_public_key_id,
    local.ssh_private_key_path,
  ]

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    environment = {
      CONFIG_PATH  = self.input.config_path
      MARKER_BEGIN = self.input.marker_begin
      MARKER_END   = self.input.marker_end
      BLOCK        = self.input.block
    }
    command = <<-EOT
      set -euo pipefail
      mkdir -p "$(dirname "$CONFIG_PATH")"
      chmod 700 "$(dirname "$CONFIG_PATH")"
      touch "$CONFIG_PATH"
      chmod 600 "$CONFIG_PATH"
      tmp="$(mktemp)"
      awk -v b="$MARKER_BEGIN" -v e="$MARKER_END" '
        $0 == b { skip = 1; next }
        $0 == e { skip = 0; next }
        !skip { print }
      ' "$CONFIG_PATH" > "$tmp"
      printf '\n%s' "$BLOCK" >> "$tmp"
      cat "$tmp" > "$CONFIG_PATH"
      rm -f "$tmp"
    EOT
  }

  provisioner "local-exec" {
    when        = destroy
    interpreter = ["/bin/bash", "-c"]
    environment = {
      CONFIG_PATH  = self.input.config_path
      MARKER_BEGIN = self.input.marker_begin
      MARKER_END   = self.input.marker_end
    }
    command = <<-EOT
      set -euo pipefail
      [ -f "$CONFIG_PATH" ] || exit 0
      tmp="$(mktemp)"
      awk -v b="$MARKER_BEGIN" -v e="$MARKER_END" '
        $0 == b { skip = 1; next }
        $0 == e { skip = 0; next }
        !skip { print }
      ' "$CONFIG_PATH" > "$tmp"
      cat "$tmp" > "$CONFIG_PATH"
      rm -f "$tmp"
    EOT
  }

  depends_on = [local_sensitive_file.ssh_private_key]
}

################################################################################
# Outputs
################################################################################

output "repositories" {
  description = "CodeCommit repository SSH clone URLs"
  value       = { for name, repo in aws_codecommit_repository.this : name => repo.clone_url_ssh }
}

output "iam_user_name" {
  description = "IAM user used by the GitOps bridge"
  value       = aws_iam_user.gitops.name
}

output "ssh_public_key_id" {
  description = "SSH public key ID to use as the SSH user for CodeCommit"
  value       = aws_iam_user_ssh_key.gitops.ssh_public_key_id
}

output "ssh_private_key_secret_name" {
  description = "Secrets Manager secret holding the SSH private key"
  value       = aws_secretsmanager_secret.codecommit_key.name
}

output "ssh_private_key_path" {
  description = "Local path of the SSH private key"
  value       = local_sensitive_file.ssh_private_key.filename
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name of the EC2 instance and prefix for related resources."
  type        = string
  default     = "benchmark-instance"
}

variable "create_network" {
  description = "Whether the module creates its own VPC, subnet, internet gateway and route table."
  type        = bool
  default     = true
}

variable "existing_vpc_id" {
  description = "VPC ID to use when create_network is false."
  type        = string
  default     = null
}

variable "existing_vpc_cidr" {
  description = "CIDR block of the existing VPC when create_network is false."
  type        = string
  default     = null
}

variable "existing_subnet_id" {
  description = "Subnet ID to use when create_network is false."
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.70.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet."
  type        = string
  default     = "10.70.0.0/24"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t2.micro"
}

variable "ami_id" {
  description = "Optional AMI ID override. When null, the latest Ubuntu 22.04 AMI is used."
  type        = string
  default     = null
}

variable "key_name" {
  description = "Name of the SSH key pair created by this module."
  type        = string
  default     = "benchmark-d8bc612be4e0-key"
}

variable "public_key" {
  description = "SSH public key material used to create the key pair."
  type        = string
}

variable "monitoring" {
  description = "Enable detailed monitoring on the instance."
  type        = bool
  default     = true
}

variable "associate_public_ip_address" {
  description = "Associate a public IP address with the primary network interface."
  type        = bool
  default     = true
}

variable "create_eip" {
  description = "Create and attach an Elastic IP to the instance."
  type        = bool
  default     = true
}

variable "root_volume_size" {
  description = "Size of the root volume in GiB."
  type        = number
  default     = 10
}

variable "root_volume_type" {
  description = "Type of the root volume."
  type        = string
  default     = "gp2"
}

variable "ingress_rules" {
  description = "Optional ingress rules for the instance security group. None by default."
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = []
}

variable "ebs_volumes" {
  description = "Optional additional EBS volumes keyed by a logical name."
  type = map(object({
    device_name = string
    size        = number
    type        = optional(string, "gp2")
    encrypted   = optional(bool, true)
    kms_key_id  = optional(string)
  }))
  default = {}
}

variable "network_interfaces" {
  description = "Optional additional network interfaces keyed by a logical name. Each may get an Elastic IP."
  type = map(object({
    device_index      = number
    subnet_id         = optional(string)
    private_ips       = optional(list(string))
    create_eip        = optional(bool, true)
    security_group_ids = optional(list(string))
  }))
  default = {}
}

variable "alarm_evaluation_periods" {
  description = "Number of consecutive periods the status check must fail before rebooting."
  type        = number
  default     = 5
}

variable "alarm_period" {
  description = "Period in seconds for the status check alarm."
  type        = number
  default     = 60
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

locals {
  vpc_id    = var.create_network ? aws_vpc.this[0].id : var.existing_vpc_id
  vpc_cidr  = var.create_network ? aws_vpc.this[0].cidr_block : var.existing_vpc_cidr
  subnet_id = var.create_network ? aws_subnet.this[0].id : var.existing_subnet_id
  ami_id    = coalesce(var.ami_id, data.aws_ami.ubuntu.id)
  az        = data.aws_availability_zones.available.names[0]

  tags = merge({ Name = var.name }, var.tags)
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_vpc" "this" {
  count = var.create_network ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${var.name}-vpc" })
}

resource "aws_subnet" "this" {
  count = var.create_network ? 1 : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.subnet_cidr
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${var.name}-subnet" })
}

resource "aws_internet_gateway" "this" {
  count = var.create_network ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.tags, { Name = "${var.name}-igw" })
}

resource "aws_route_table" "this" {
  count = var.create_network ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[0].id
  }

  tags = merge(local.tags, { Name = "${var.name}-rt" })
}

resource "aws_route_table_association" "this" {
  count = var.create_network ? 1 : 0

  subnet_id      = aws_subnet.this[0].id
  route_table_id = aws_route_table.this[0].id
}

resource "aws_security_group" "this" {
  name        = "${var.name}-sg"
  description = "Dedicated security group for ${var.name}"
  vpc_id      = local.vpc_id

  egress {
    description = "Allow egress to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  tags = merge(local.tags, { Name = "${var.name}-sg" })
}

resource "aws_key_pair" "this" {
  key_name   = var.key_name
  public_key = var.public_key

  tags = local.tags
}

resource "aws_iam_role" "this" {
  name               = "${var.name}-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = local.tags
}

resource "aws_iam_instance_profile" "this" {
  name = "${var.name}-profile"
  role = aws_iam_role.this.name

  tags = local.tags
}

resource "aws_instance" "this" {
  ami                         = local.ami_id
  instance_type               = var.instance_type
  subnet_id                   = local.subnet_id
  vpc_security_group_ids      = [aws_security_group.this.id]
  key_name                    = aws_key_pair.this.key_name
  iam_instance_profile        = aws_iam_instance_profile.this.name
  monitoring                  = var.monitoring
  associate_public_ip_address = var.associate_public_ip_address

  root_block_device {
    volume_type           = var.root_volume_type
    volume_size           = var.root_volume_size
    encrypted             = true
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  tags        = local.tags
  volume_tags = local.tags

  depends_on = [aws_route_table_association.this]
}

resource "aws_eip" "this" {
  count = var.create_eip ? 1 : 0

  domain   = "vpc"
  instance = aws_instance.this.id

  tags = merge(local.tags, { Name = "${var.name}-eip" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_ebs_volume" "this" {
  for_each = var.ebs_volumes

  availability_zone = aws_instance.this.availability_zone
  size              = each.value.size
  type              = each.value.type
  encrypted         = each.value.encrypted
  kms_key_id        = each.value.kms_key_id

  tags = merge(local.tags, { Name = "${var.name}-${each.key}" })
}

resource "aws_volume_attachment" "this" {
  for_each = var.ebs_volumes

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.this[each.key].id
  instance_id = aws_instance.this.id
}

resource "aws_network_interface" "this" {
  for_each = var.network_interfaces

  subnet_id       = coalesce(each.value.subnet_id, local.subnet_id)
  private_ips     = each.value.private_ips
  security_groups = coalesce(each.value.security_group_ids, [aws_security_group.this.id])

  tags = merge(local.tags, { Name = "${var.name}-${each.key}" })
}

resource "aws_network_interface_attachment" "this" {
  for_each = var.network_interfaces

  instance_id          = aws_instance.this.id
  network_interface_id = aws_network_interface.this[each.key].id
  device_index         = each.value.device_index
}

resource "aws_eip" "network_interface" {
  for_each = { for k, v in var.network_interfaces : k => v if v.create_eip }

  domain            = "vpc"
  network_interface = aws_network_interface.this[each.key].id

  tags = merge(local.tags, { Name = "${var.name}-${each.key}-eip" })

  depends_on = [
    aws_internet_gateway.this,
    aws_network_interface_attachment.this,
  ]
}

resource "aws_cloudwatch_metric_alarm" "instance_status_check" {
  alarm_name          = "${var.name}-status-check-failed-instance"
  alarm_description   = "Reboot ${var.name} when the instance status check fails."
  namespace           = "AWS/EC2"
  metric_name         = "StatusCheckFailed_Instance"
  statistic           = "Maximum"
  period              = var.alarm_period
  evaluation_periods  = var.alarm_evaluation_periods
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"

  dimensions = {
    InstanceId = aws_instance.this.id
  }

  alarm_actions = ["arn:aws:automate:${var.region}:ec2:reboot"]

  tags = local.tags
}

output "instance_id" {
  description = "ID of the EC2 instance."
  value       = aws_instance.this.id
}

output "instance_public_ip" {
  description = "Elastic IP (or public IP) of the instance."
  value       = var.create_eip ? aws_eip.this[0].public_ip : aws_instance.this.public_ip
}

output "instance_private_ip" {
  description = "Private IP of the instance."
  value       = aws_instance.this.private_ip
}

output "vpc_id" {
  description = "ID of the VPC used by the instance."
  value       = local.vpc_id
}

output "subnet_id" {
  description = "ID of the subnet used by the instance."
  value       = local.subnet_id
}

output "security_group_id" {
  description = "ID of the instance security group."
  value       = aws_security_group.this.id
}

output "iam_role_name" {
  description = "Name of the instance IAM role."
  value       = aws_iam_role.this.name
}

output "instance_profile_name" {
  description = "Name of the instance profile."
  value       = aws_iam_instance_profile.this.name
}

output "key_pair_name" {
  description = "Name of the SSH key pair."
  value       = aws_key_pair.this.key_name
}

output "status_check_alarm_arn" {
  description = "ARN of the status check reboot alarm."
  value       = aws_cloudwatch_metric_alarm.instance_status_check.arn
}

output "network_interface_eips" {
  description = "Elastic IPs attached to additional network interfaces."
  value       = { for k, v in aws_eip.network_interface : k => v.public_ip }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "source_region_2" {
  description = "Second source region"
  type        = string
  default     = "us-west-2"
}

variable "replica_region_1" {
  description = "First replica region"
  type        = string
  default     = "eu-west-1"
}

variable "replica_region_2" {
  description = "Second replica region"
  type        = string
  default     = "ap-southeast-2"
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Env = "dev"
    }
  }
}

provider "aws" {
  alias  = "source2"
  region = var.source_region_2

  default_tags {
    tags = {
      Env = "dev"
    }
  }
}

provider "aws" {
  alias  = "replica1"
  region = var.replica_region_1

  default_tags {
    tags = {
      Env = "dev"
    }
  }
}

provider "aws" {
  alias  = "replica2"
  region = var.replica_region_2

  default_tags {
    tags = {
      Env = "dev"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  source1_names = ["log1a.veerum", "log1b.veerum"]
  source2_names = ["log2a.veerum", "log2b.veerum"]
  all_sources   = concat(local.source1_names, local.source2_names)

  source1_buckets  = { for n in local.source1_names : n => "${n}-${local.account_id}" }
  source2_buckets  = { for n in local.source2_names : n => "${n}-${local.account_id}" }
  replica1_buckets = { for n in local.all_sources : n => "${n}-replica1-${local.account_id}" }
  replica2_buckets = { for n in local.all_sources : n => "${n}-replica2-${local.account_id}" }
}

# ---------------------------------------------------------------------------
# KMS keys (one customer-managed key per region)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "source1" {
  description             = "SSE-KMS key for source buckets in us-east-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "source1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "SSE-KMS key for source buckets in ${var.source_region_2}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "SSE-KMS key for replica buckets in ${var.replica_region_1}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "SSE-KMS key for replica buckets in ${var.replica_region_2}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

# ---------------------------------------------------------------------------
# Source buckets - us-east-1
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "source1" {
  for_each = local.source1_buckets
  bucket   = each.value
}

resource "aws_s3_bucket_ownership_controls" "source1" {
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "source1" {
  for_each                = aws_s3_bucket.source1
  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "source1" {
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id
  acl      = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.source1,
    aws_s3_bucket_public_access_block.source1,
  ]
}

resource "aws_s3_bucket_versioning" "source1" {
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source1" {
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source1.arn
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Source buckets - second source region
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "source2" {
  provider = aws.source2
  for_each = local.source2_buckets
  bucket   = each.value
}

resource "aws_s3_bucket_ownership_controls" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "source2" {
  provider                = aws.source2
  for_each                = aws_s3_bucket.source2
  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id
  acl      = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.source2,
    aws_s3_bucket_public_access_block.source2,
  ]
}

resource "aws_s3_bucket_versioning" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source2.arn
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Replica buckets - first replica region
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "replica1" {
  provider = aws.replica1
  for_each = local.replica1_buckets
  bucket   = each.value
}

resource "aws_s3_bucket_ownership_controls" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "replica1" {
  provider                = aws.replica1
  for_each                = aws_s3_bucket.replica1
  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id
  acl      = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.replica1,
    aws_s3_bucket_public_access_block.replica1,
  ]
}

resource "aws_s3_bucket_versioning" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica1.arn
    }
