  }
}

# ---------------------------------------------------------------------------
# Replica buckets - second replica region
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  for_each = local.replica2_buckets
  bucket   = each.value
}

resource "aws_s3_bucket_ownership_controls" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "replica2" {
  provider                = aws.replica2
  for_each                = aws_s3_bucket.replica2
  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id
  acl      = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.replica2,
    aws_s3_bucket_public_access_block.replica2,
  ]
}

resource "aws_s3_bucket_versioning" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica2.arn
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# IAM role for S3 replication
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-log-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume.json
}

locals {
  source_bucket_arns = concat(
    [for b in aws_s3_bucket.source1 : b.arn],
    [for b in aws_s3_bucket.source2 : b.arn],
  )

  replica_bucket_arns = concat(
    [for b in aws_s3_bucket.replica1 : b.arn],
    [for b in aws_s3_bucket.replica2 : b.arn],
  )
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketRead"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = local.source_bucket_arns
  }

  statement {
    sid    = "SourceObjectVersionRead"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = [for arn in local.source_bucket_arns : "${arn}/*"]
  }

  statement {
    sid    = "ReplicaWrite"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = [for arn in local.replica_bucket_arns : "${arn}/*"]
  }

  statement {
    sid       = "SourceKeyDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.source1.arn, aws_kms_key.source2.arn]
  }

  statement {
    sid       = "ReplicaKeyEncrypt"
    effect    = "Allow"
    actions   = ["kms:Encrypt"]
    resources = [aws_kms_key.replica1.arn, aws_kms_key.replica2.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name   = "s3-log-replication-policy"
  policy = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------------------------------------------------------------------
# Replication configurations
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "source1" {
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id
  role     = aws_iam_role.replication.arn

  rule {
    id       = "replicate-to-replica1"
    priority = 1
    status   = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    priority = 2
    status   = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
    aws_iam_role_policy_attachment.replication,
  ]
}

resource "aws_s3_bucket_replication_configuration" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id
  role     = aws_iam_role.replication.arn

  rule {
    id       = "replicate-to-replica1"
    priority = 1
    status   = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    priority = 2
    status   = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
    aws_iam_role_policy_attachment.replication,
  ]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "source_buckets" {
  value = concat(
    [for b in aws_s3_bucket.source1 : b.id],
    [for b in aws_s3_bucket.source2 : b.id],
  )
}

output "replica1_buckets" {
  value = [for b in aws_s3_bucket.replica1 : b.id]
}

output "replica2_buckets" {
  value = [for b in aws_s3_bucket.replica2 : b.id]
}

output "replication_role_arn" {
  value = aws_iam_role.replication.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = ">= 5.60.0"
      configuration_aliases = []
    }
  }
}

provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "Primary AWS region for GuardDuty and the findings export bucket."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "AWS region used for the cross-region replica of the findings export bucket."
  type        = string
  default     = "us-west-2"
}

variable "module_repository_url" {
  description = "Repository URL of this module, applied as a tag to the detector and all taggable resources."
  type        = string
  default     = "https://github.com/aws-ia/terraform-aws-guardduty"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "finding_publishing_frequency" {
  description = "Frequency of notifications sent for finding occurrences."
  type        = string
  default     = "FIFTEEN_MINUTES"

  validation {
    condition     = contains(["FIFTEEN_MINUTES", "ONE_HOUR", "SIX_HOURS"], var.finding_publishing_frequency)
    error_message = "finding_publishing_frequency must be FIFTEEN_MINUTES, ONE_HOUR, or SIX_HOURS."
  }
}

variable "ebs_snapshot_preservation" {
  description = "EBS snapshot preservation setting applied to malware scans after the detector is created."
  type        = string
  default     = "NO_RETENTION"

  validation {
    condition     = contains(["NO_RETENTION", "RETENTION_WITH_FINDING"], var.ebs_snapshot_preservation)
    error_message = "ebs_snapshot_preservation must be NO_RETENTION or RETENTION_WITH_FINDING."
  }
}

variable "filter_config" {
  description = "Optional list of GuardDuty findings filters."
  type = list(object({
    name        = string
    description = optional(string)
    rank        = number
    action      = string
    criterion = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(string)
      greater_than_or_equal = optional(string)
      less_than             = optional(string)
      less_than_or_equal    = optional(string)
    }))
  }))
  default = []
}

variable "ipset_config" {
  description = "Optional list of trusted IP sets. Each location must be an existing S3 object URL."
  type = list(object({
    name     = string
    format   = optional(string, "TXT")
    location = string
    activate = optional(bool, true)
  }))
  default = []
}

variable "threatintelset_config" {
  description = "Optional list of threat intelligence sets. Each location must be an existing S3 object URL."
  type = list(object({
    name     = string
    format   = optional(string, "TXT")
    location = string
    activate = optional(bool, true)
  }))
  default = []
}

variable "malware_protection_plan_config" {
  description = "Optional configuration for a GuardDuty Malware Protection plan for an S3 bucket. Null disables it."
  type = object({
    role_arn        = string
    bucket_name     = string
    object_prefixes = optional(list(string), [])
    tagging_status  = optional(string, "ENABLED")
  })
  default = null
}

variable "enable_s3_export" {
  description = "Whether to export GuardDuty findings to a versioned, access-logged, KMS-encrypted, cross-region-replicated S3 bucket."
  type        = bool
  default     = false
}

variable "export_bucket_name" {
  description = "Optional name for the findings export bucket. Defaults to a generated name."
  type        = string
  default     = null
}

variable "export_bucket_force_destroy" {
  description = "Allow destruction of the export, replica, and logging buckets even when they contain objects."
  type        = bool
  default     = false
}

variable "kms_deletion_window_in_days" {
  description = "Deletion window for the KMS keys created for findings export."
  type        = number
  default     = 30
}

################################################################################
# Data sources and locals
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_region" "replica" {
  provider = aws.replica
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  tags = merge(var.tags, {
    "terraform-module-source" = var.module_repository_url
  })

  create_export = var.enable_s3_export

  export_bucket_name  = coalesce(var.export_bucket_name, "guardduty-findings-${local.account_id}-${local.region}")
  replica_bucket_name = "${local.export_bucket_name}-replica"
  logs_bucket_name    = "${local.export_bucket_name}-access-logs"

  detector_features = toset([
    "S3_DATA_EVENTS",
    "RDS_LOGIN_EVENTS",
    "LAMBDA_NETWORK_LOGS",
    "EKS_AUDIT_LOGS",
    "EBS_MALWARE_PROTECTION",
  ])

  runtime_monitoring_additional_configuration = [
    "EKS_ADDON_MANAGEMENT",
    "ECS_FARGATE_AGENT_MANAGEMENT",
    "EC2_AGENT_MANAGEMENT",
  ]
}

################################################################################
# GuardDuty detector
################################################################################

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  tags = local.tags
}

resource "aws_guardduty_detector_feature" "this" {
  for_each = local.detector_features

  detector_id = aws_guardduty_detector.this.id
  name        = each.value
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  dynamic "additional_configuration" {
    for_each = local.runtime_monitoring_additional_configuration

    content {
      name   = additional_configuration.value
      status = "DISABLED"
    }
  }
}

resource "terraform_data" "malware_scan_settings" {
  triggers_replace = {
    detector_id               = aws_guardduty_detector.this.id
    ebs_snapshot_preservation = var.ebs_snapshot_preservation
    region                    = local.region
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.this.id} --ebs-snapshot-preservation ${var.ebs_snapshot_preservation} --region ${local.region}"
  }

  depends_on = [
    aws_guardduty_detector_feature.this,
  ]
}

################################################################################
# Findings filters
################################################################################

resource "aws_guardduty_filter" "this" {
  for_each = { for f in var.filter_config : f.name => f }

  detector_id = aws_guardduty_detector.this.id
  name        = each.value.name
  description = each.value.description
  rank        = each.value.rank
  action      = each.value.action

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criterion

      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = local.tags
}

################################################################################
# Trusted IP sets and threat intelligence sets
################################################################################

resource "aws_guardduty_ipset" "this" {
  for_each = { for s in var.ipset_config : s.name => s }

  detector_id = aws_guardduty_detector.this.id
  name        = each.value.name
  format      = each.value.format
  location    = each.value.location
  activate    = each.value.activate

  tags = local.tags
}

resource "aws_guardduty_threatintelset" "this" {
  for_each = { for s in var.threatintelset_config : s.name => s }

  detector_id = aws_guardduty_detector.this.id
  name        = each.value.name
  format      = each.value.format
  location    = each.value.location
  activate    = each.value.activate

  tags = local.tags
}

################################################################################
# Malware Protection plan for S3
################################################################################

resource "aws_guardduty_malware_protection_plan" "this" {
  count = var.malware_protection_plan_config == null ? 0 : 1

  role = var.malware_protection_plan_config.role_arn

  protected_resource {
    s3_bucket {
      bucket_name     = var.malware_protection_plan_config.bucket_name
      object_prefixes = var.malware_protection_plan_config.object_prefixes
    }
  }

  actions {
    tagging {
      status = var.malware_protection_plan_config.tagging_status
    }
  }

  tags = local.tags

  depends_on = [
    aws_guardduty_detector.this,
  ]
}

################################################################################
# Findings export - KMS keys
################################################################################

data "aws_iam_policy_document" "export_kms" {
  count = local.create_export ? 1 : 0

  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowGuardDutyToEncryptFindings"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.this.arn]
    }
  }
}

resource "aws_kms_key" "export" {
  count = local.create_export ? 1 : 0

  description             = "KMS key for GuardDuty findings export"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.export_kms[0].json

  tags = local.tags
}

resource "aws_kms_alias" "export" {
  count = local.create_export ? 1 : 0

  name          = "alias/guardduty-findings-export"
  target_key_id = aws_kms_key.export[0].key_id
}

data "aws_iam_policy_document" "replica_kms" {
  count = local.create_export ? 1 : 0

  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  description             = "KMS key for GuardDuty findings export replica"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms[0].json

  tags = local.tags
}

resource "aws_kms_alias" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  name          = "alias/guardduty-findings-export-replica"
  target_key_id = aws_kms_key.replica[0].key_id
}

################################################################################
# Findings export - access logs bucket
################################################################################

resource "aws_s3_bucket" "logs" {
  count = local.create_export ? 1 : 0

  bucket        = local.logs_bucket_name
  force_destroy = var.export_bucket_force_destroy

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = local.create_export ? 1 : 0

  bucket                  = aws_s3_bucket.logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server access log target buckets support only SSE-S3 default encryption.
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "logs" {
  count = local.create_export ? 1 : 0

  statement {
    sid       = "S3ServerAccessLogsPolicy"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.export[0].arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.logs[0].arn,
      "${aws_s3_bucket.logs[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id
  policy = data.aws_iam_policy_document.logs[0].json

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

################################################################################
# Findings export - primary bucket
################################################################################

resource "aws_s3_bucket" "export" {
  count = local.create_export ? 1 : 0

  bucket        = local.export_bucket_name
  force_destroy = var.export_bucket_force_destroy

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "export" {
  count = local.create_export ? 1 : 0

  bucket                  = aws_s3_bucket.export[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "export" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "export" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "export" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.export[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.export[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "export" {
  count = local.create_export ? 1 : 0

  bucket        = aws_s3_bucket.export[0].id
  target_bucket = aws_s3_bucket.logs[0].id
  target_prefix = "s3-access-logs/"

  depends_on = [aws_s3_bucket_policy.logs]
}

data "aws_iam_policy_document" "export" {
  count = local.create_export ? 1 : 0

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.export[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.this.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.export[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.this.arn]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.export[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }

  statement {
    sid       = "DenyIncorrectEncryptionHeader"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.export[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.export[0].arn]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.export[0].arn,
      "${aws_s3_bucket.export[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "export" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.export[0].id
  policy = data.aws_iam_policy_document.export[0].json

  depends_on = [aws_s3_bucket_public_access_block.export]
}

################################################################################
# Findings export - replica bucket
################################################################################

resource "aws_s3_bucket" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  bucket        = local.replica_bucket_name
  force_destroy = var.export_bucket_force_destroy

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica[0].arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "replica" {
  count = local.create_export ? 1 : 0

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.replica[0].arn,
      "${aws_s3_bucket.replica[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  count    = local.create_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id
  policy = data.aws_iam_policy_document.replica[0].json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

################################################################################
# Findings export - replication role and configuration
################################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_export ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_export ? 1 : 0

  name_prefix        = "guardduty-findings-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_export ? 1 : 0

  statement {
    sid    = "SourceBucket"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.export[0].arn]
  }

  statement {
    sid    = "SourceObjects"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.export[0].arn}/*"]
  }

  statement {
    sid    = "DestinationObjects"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }

  statement {
    sid       = "DecryptSource"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.export[0].arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "EncryptDestination"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.replica[0].arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.replica.name}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_export ? 1 : 0

  name   = "guardduty-findings-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "export" {
  count = local.create_export ? 1 : 0

  bucket = aws_s3_bucket.export[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-guardduty-findings"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica[0].arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.export,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication,
  ]
}

################################################################################
# Findings export - publishing destination
################################################################################

resource "aws_guardduty_publishing_destination" "this" {
  count = local.create_export ? 1 : 0

  detector_id      = aws_guardduty_detector.this.id
  destination_arn  = aws_s3_bucket.export[0].arn
  kms_key_arn      = aws_kms_key.export[0].arn
  destination_type = "S3"

  depends_on = [
    aws_s3_bucket_policy.export,
    aws_s3_bucket_server_side_encryption_configuration.export,
    aws_s3_bucket_logging.export,
    aws_s3_bucket_replication_configuration.export,
  ]
}

################################################################################
# Outputs
################################################################################

output "guardduty_detector_id" {
  description = "ID of the GuardDuty detector."
  value       = aws_guardduty_detector.this.id
}

output "guardduty_detector_arn" {
  description = "ARN of the GuardDuty detector."
  value       = aws_guardduty_detector.this.arn
}

output "guardduty_detector_features" {
  description = "Names of the detector features enabled by this configuration."
  value       = concat(sort(tolist(local.detector_features)), ["RUNTIME_MONITORING"])
}

output "guardduty_filter_ids" {
  description = "IDs of the GuardDuty findings filters."
  value       = { for k, v in aws_guardduty_filter.this : k => v.id }
}

output "guardduty_ipset_ids" {
  description = "IDs of the GuardDuty trusted IP sets."
  value       = { for k, v in aws_guardduty_ipset.this : k => v.id }
}

output "guardduty_threatintelset_ids" {
  description = "IDs of the GuardDuty threat intelligence sets."
  value       = { for k, v in aws_guardduty_threatintelset.this : k => v.id }
}

output "guardduty_malware_protection_plan_id" {
  description = "ID of the GuardDuty Malware Protection plan, if created."
  value       = one(aws_guardduty_malware_protection_plan.this[*].id)
}

output "guardduty_publishing_destination_id" {
  description = "ID of the GuardDuty publishing destination, if created."
  value       = one(aws_guardduty_publishing_destination.this[*].id)
}

output "findings_export_bucket_arn" {
  description = "ARN of the findings export bucket, if created."
  value       = one(aws_s3_bucket.export[*].arn)
}

output "findings_replica_bucket_arn" {
  description = "ARN of the findings replica bucket, if created."
  value       = one(aws_s3_bucket.replica[*].arn)
}

output "findings_logs_bucket_arn" {
  description = "ARN of the findings access logs bucket, if created."
  value       = one(aws_s3_bucket.logs[*].arn)
}

output "findings_export_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt exported findings, if created."
  value       = one(aws_kms_key.export[*].arn)
}

output "findings_replica_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt replicated findings, if created."
  value       = one(aws_kms_key.replica[*].arn)
}

output "findings_replication_role_arn" {
  description = "ARN of the IAM role used for cross-region replication, if created."
  value       = one(aws_iam_role.replication[*].arn)
}
